/*
 * Raspberry Pi 4 Model B - MLX91219 Current Sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2 (Pin 3)
 *   ADS1115 SCL -> GPIO3 (Pin 5)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   MLX91219 VOUT -> ADS1115 AIN0
 *   ADS1115 VDD -> 3.3V, GND -> GND
 *
 * Build: gcc -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* ADS1115 config bit fields */
#define ADS1115_CFG_OS_BEGIN   (1 << 15)
#define ADS1115_CFG_MUX_AIN0   (0x04 << 12)  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096 (0x01 << 9)    /* PGA = ±4.096V */
#define ADS1115_CFG_MODE_SS   (0x01 << 8)    /* Single-shot */
#define ADS1115_CFG_DR_128    (0x04 << 5)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x03 << 0)    /* Disable comparator */

/* MLX91219 sensor parameters */
#define MLX91219_SENSITIVITY  0.040f   /* 40 mV/A */
#define MLX91219_VZERO        2.5f     /* Zero-current output at mid-supply */

/* ADS1115 full-scale range for PGA ±4.096V */
#define ADS1115_VREF 4.096f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Conversion time for 128 SPS is ~8ms; use 10ms to be safe */
#define CONV_TIME_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register using i2cWriteI2CBlockData.
 * The ADS1115 expects MSB first, so we assemble the 16-bit value
 * as (reg | (high << 8)) and send it as a 2-byte block.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf, 3) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register using i2cReadI2CBlockData.
 * The ADS1115 sends MSB first, so we read 2 bytes and assemble them
 * correctly.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData from reg 0x%02X failed\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the raw ADC code.
 * Returns 0 on success, -1 on I2C error, -2 on sensor-absent (no conversion).
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out) {
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0) {
        return -1;
    }

    /* Wait for conversion to complete (128 SPS -> ~8ms; use 10ms) */
    gpioDelay(CONV_TIME_US);

    uint16_t cfg_readback;
    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg_readback) != 0) {
        return -1;
    }

    /* Check OS bit (bit 15) - if set, conversion is complete */
    if (!(cfg_readback & ADS1115_CFG_OS_BEGIN)) {
        fprintf(stderr, "Warning: ADS1115 conversion not complete (OS bit not set)\n");
        return -2;
    }

    uint16_t conversion;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conversion) != 0) {
        return -1;
    }

    *raw_out = (int16_t)conversion;
    return 0;
}

/*
 * Convert raw ADC code to current (amperes).
 * raw is a signed 16-bit value.
 * PGA = ±4.096V -> LSB = 4.096V / 32768 = 125 µV
 * current = (raw - MLX91219_VZERO) / MLX91219_SENSITIVITY * 1000
 */
static float raw_to_current(int16_t raw) {
    float voltage = (raw - MLX91219_VZERO) * ADS1115_VREF / 32768.0f;
    return (voltage / MLX91219_SENSITIVITY) * 1000.0f;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address 0x48 */
    g_i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Sensor via ADS1115\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t raw;
        int rc = ads1115_read_ain0(g_i2c_handle, &raw);

        if (rc == 0) {
            float current = raw_to_current(raw);
            printf("Current: %.3f A\n", current);
        } else if (rc == -2) {
            /* Sensor-absent / no conversion path */
            fprintf(stderr, "Warning: ADS1115 conversion not complete\n");
        } else {
            /* I2C bus error */
            fprintf(stderr, "Error: I2C read failure (rc=%d)\n", rc);
        }

        /* Sleep for the sample interval, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

