#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)
#define FLAME_DEBOUNCE_MS 50
#define TEMP_THRESHOLD 60.0
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_US 100000
#define ADC_CONV_TIME_US 9000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event = 0;
static volatile sig_atomic_t flame_event_pending = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    flame_event_pending = 1;
}

static int read_temperature(float *temp_out) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE);
    config[2] = 0x00;
    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config.\n");
        return -1;
    }
    gpioDelay(ADC_CONV_TIME_US);
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, &reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to select ADS1115 conversion register.\n");
        return -1;
    }
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion data.\n");
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    float voltage = raw * 4.096f / 32768.0f;
    *temp_out = (voltage / 3.3f) * 100.0f;
    return 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pull-up.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize buzzer state.\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        cleanup();
        return 1;
    }
    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register flame sensor ISR.\n");
        cleanup();
        return 1;
    }
    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    while (running) {
        if (flame_event_pending) {
            flame_event_pending = 0;
            if (gpioRead(FLAME_SENSOR_PIN) == 0) {
                flame_event = 1;
            }
        }
        if (flame_event) {
            gpioDelay(FLAME_DEBOUNCE_MS * 1000);
            if (gpioRead(FLAME_SENSOR_PIN) == 0) {
                flame_event = 0;
                printf("Flame detected!\n");
                log_event("Flame detected!");
            }
        }
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (temperature > TEMP_THRESHOLD) {
                printf("Temperature %.2f°C exceeds threshold %.2f°C!\n", temperature, TEMP_THRESHOLD);
                log_event("Temperature exceeds threshold!");
            } else {
                printf("Temperature: %.2f°C\n", temperature);
                log_event("Temperature reading.");
            }
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
            log_event("Error: Failed to read temperature.");
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

