        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring current sensor via MCP3008 on %s (SPI0 CE0, ch%d)\n",
           SPI_DEVICE, ADC_CHANNEL);
    printf("Threshold: %.2f A, Sensitivity: %.3f V/A\n", threshold, sensitivity);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = 0;

        if (mcp3008_read(ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s...\n",
                    SAMPLE_PERIOD_S);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /*
         * Sensor-absent / bus-error detection:
         *   0   -> all zeros (wiring fault or sensor disconnected)
         *   1023 -> all ones (wiring fault or sensor saturated)
         */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
