#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* Simulated 16-bit ADC reading for the CO element (0-65535) */
#define CO_RAW_MAX 65535.0f

/* Calibration parameters (replace with actual calibration data) */
#define CO_ZERO_PPM_RESISTANCE 10000.0f
#define CO_MAX_PPM_RESISTANCE 20000.0f
#define CO_MIN_PPM 0.0f
#define CO_MAX_PPM 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_co_raw(int handle, int *raw_out) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        return -1;
    }
    *raw_out = ((buf[0] << 8) | (buf[1] & 0xFF)) & 0xFFFF;
    return 0;
}

static float calculate_ppm(int raw) {
    if (raw <= CO_ZERO_PPM_RESISTANCE) {
        return CO_MIN_PPM;
    }
    if (raw >= CO_MAX_PPM_RESISTANCE) {
        return CO_MAX_PPM;
    }
    float ppm = CO_MIN_PPM + (float)(raw - CO_ZERO_PPM_RESISTANCE) *
                 (CO_MAX_PPM - CO_MIN_PPM) / (CO_MAX_PPM_RESISTANCE - CO_ZERO_PPM_RESISTANCE);
    return ppm;
}

static void log_data(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d (error: %d)\n",
                I2C_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CO sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw;
        if (read_co_raw(i2c_handle, &raw) != 0) {
            fprintf(stderr, "Error reading CO raw value (sensor absent or bus error)\n");
            log_data(-1.0f);
        } else {
            float ppm = calculate_ppm(raw);
            log_data(ppm);
            printf("CO: %.2f PPM (raw: %d)\n", ppm, raw);
        }
        sleep(SAMPLE_INTERVAL_SEC);
