// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x60
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define CO_THRESHOLD 25.0f
#define READ_INTERVAL 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int handle, float *co_level);
float calculate_co_ppm(int raw_data);
void log_data(float co_level);
void log_alert(float co_level);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
int read_sensor_data(int handle, float *co_level) {
    char buffer[4];
    int result = i2cReadDevice(handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine the two 16-bit ADC values (OX for CO, RED for NO2)
    int raw_data = (buffer[0] << 8) | buffer[1];
    *co_level = calculate_co_ppm(raw_data);
    return 0;
}

// Calculate CO level in PPM from raw ADC value
float calculate_co_ppm(int raw_data) {
    // Placeholder linear conversion (replace with actual calibration curve)
    // Assuming raw value is directly proportional to CO concentration
    float co_ppm = (float)raw_data * 0.1f;
    return co_ppm;
}

// Log data to file
void log_data(float co_level) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO_LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_level);
    fclose(fp);
}

// Log alert to file
void log_alert(float co_level) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file: %s\n", ALERT_LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold (%.2f PPM > %.2f PPM)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_level, CO_THRESHOLD);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air Quality Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float co_level;
        if (read_sensor_data(i2c_handle, &co_level) == 0) {
            log_data(co_level);
            if (co_level > CO_THRESHOLD) {
                log_alert(co_level);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_INTERVAL);
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("Air Quality Monitoring System stopped.\n");

    return 0;
}

