#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x48
#define SENSOR2_ADDR 0x49
#define REG_READ 0x00
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY -38.0
#define REFERENCE_PRESSURE 20e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int handle, float *out_level) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(handle, REG_READ, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading sensor 0x%02X: %d\n", handle, bytes);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_level = (raw * REFERENCE_PRESSURE) / 1000.0 + SENSITIVITY;
    return 0;
}

static float calculate_average(float l1, float l2) {
    return (l1 + l2) / 2.0f;
}

static void log_data(float avg_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    FILE *fp = fopen("audio_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s, %.2f dB\n", ts, avg_level);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h1 < 0 || h2 < 0) {
        fprintf(stderr, "I2C open failed: %d %d\n", h1, h2);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float l1 = ERROR_VALUE, l2 = ERROR_VALUE;
        if (read_sensor(h1, &l1) != 0) l1 = ERROR_VALUE;
        if (read_sensor(h2, &l2) != 0) l2 = ERROR_VALUE;

        float avg = calculate_average(l1, l2);
        log_data(avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    return 0;
}

