#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define LED_PIN 27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define ADC channels for the two microphones (MCP3008 supports 8 channels)
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define sampling parameters
#define SAMPLE_RATE 1000 // 1 ms per sample
#define WINDOW_SIZE 100 // 100 samples per microphone
#define THRESHOLD 0.7 // RMS threshold
#define LED_ON_TIME_MS 500 // LED on time in milliseconds
#define LOG_FILE "audio_events.csv"

// Global variables
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
double calculate_rms(int *data, int size);
void control_led(int state);
void log_event(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

// Initialize pigpio, SPI, and LED pin
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Open SPI channel (CE0)
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file for appending
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read ADC value from MCP3008 via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008 (3 bytes)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate RMS value from an array of samples
double calculate_rms(int *data, int size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < size; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    return sqrt(sum_of_squares / size);
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Log event to CSV file
void log_event(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file);
}

int main() {
    int mic1_data[WINDOW_SIZE];
    int mic2_data[WINDOW_SIZE];
    double mic1_rms, mic2_rms;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize hardware
    if (initialize() != 0) {
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Sample microphone 1
        for (int i = 0; i < WINDOW_SIZE; i++) {
            int adc_value = read_adc(MIC1_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading mic1 data at sample %d\n", i);
                continue;
            }
            mic1_data[i] = adc_value;
            gpioDelay(SAMPLE_RATE * 1000); // Convert ms to us
        }

        // Calculate RMS for microphone 1
        mic1_rms = calculate_rms(mic1_data, WINDOW_SIZE);

        // Sample microphone 2
        for (int i = 0; i < WINDOW_SIZE; i++) {
            int adc_value = read_adc(MIC2_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading mic2 data at sample %d\n", i);
                continue;
            }
            mic2_data[i] = adc_value;
            gpioDelay(SAMPLE_RATE * 1000); // Convert ms to us
        }

        // Calculate RMS for microphone 2
        mic2_rms = calculate_rms(mic2_data, WINDOW_SIZE);

        // Check threshold
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            printf("Threshold exceeded! Mic1 RMS: %.4f, Mic2 RMS: %.4f\n", mic1_rms, mic2_rms);
            control_led(1); // Turn on LED
            log_event(mic1_rms, mic2_rms);
            gpioDelay(LED_ON_TIME_MS * 1000); // Wait for LED_ON_TIME_MS milliseconds
            control_led(0); // Turn off LED
        }

        // Log event even if threshold not exceeded
        log_event(mic1_rms, mic2_rms);
    }

    // Cleanup
    cleanup();
    printf("Audio monitoring stopped.\n");

    return 0;
}

