#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_A0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_A0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)
#define OVERCURRENT_THRESHOLD 50.0
#define WARNING_LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_US 100000  // 10 Hz
#define ADC_VREF 4.096
#define ADC_MAX_COUNT 32767.0

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
int initialize_i2c(void);
int read_ads1115_current(void);
double convert_to_current(int16_t raw_value);
void update_buffer(double current_value);
double calculate_average_current(void);
void check_overcurrent(double average_current);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize I2C communication with ADS1115
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit ADC value from ADS1115 channel A0
int read_ads1115_current(void) {
    uint8_t config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    // Wait for conversion to complete (approx 8ms for 128 SPS)
    gpioDelay(10000);

    uint8_t reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register pointer\n");
        return -1;
    }

    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data\n");
        return -1;
    }

    int16_t raw_value = (int16_t)((data[0] << 8) | data[1]);
    return raw_value;
}

// Convert raw ADC value to current (A)
double convert_to_current(int16_t raw_value) {
    double voltage = (raw_value / ADC_MAX_COUNT) * ADC_VREF;
    double current = (voltage / 4.096) * 100.0;  // 0.5V to 4.5V maps to 0-100A
    return current;
}

// Update circular buffer with current reading
void update_buffer(double current_value) {
    current_buffer[buffer_index] = current_value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate the average current from the buffer
double calculate_average_current(void) {
    if (buffer_count == 0) {
        return 0.0;
    }
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

// Check if the average current exceeds the overcurrent threshold
void check_overcurrent(double average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(WARNING_LED_GPIO, 1);  // Turn on warning LED
        printf("Overcurrent detected! Average current: %.2f A\n", average_current);
    } else {
        gpioWrite(WARNING_LED_GPIO, 0);  // Turn off warning LED
    }
}

// Cleanup resources before exiting
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);
    gpioWrite(WARNING_LED_GPIO, 0);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t raw_value = read_ads1115_current();
        if (raw_value >= 0) {
            double current = convert_to_current(raw_value);
            update_buffer(current);
            double average_current = calculate_average_current();
            check_overcurrent(average_current);
        } else {
            fprintf(stderr, "Error reading current sensor. Retrying...\n");
        }

        gpioDelay(SAMPLE_RATE_US);
    }

    // Cleanup
    cleanup();
    printf("Overcurrent protection system stopped.\n");
    return 0;
}

