#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDR        0x29
#define TCS34725_ENABLE      0x00
#define TCS34725_ATIME       0x01
#define TCS34725_ID          0x12
#define TCS34725_CONTROL     0x0F
#define TCS34725_CDATA       0x14
#define TCS34725_RDATA       0x16
#define TCS34725_GDATA       0x18
#define TCS34725_BDATA       0x1A
#define TCS34725_ID_VALUE    0x44
#define I2C_BUS              1
#define LOG_FILE             "color_log.csv"
#define SAMPLE_INTERVAL_US   1000000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
    }
    *value = (uint8_t)rc;
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u, got=%d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int tcs34725_init(int handle) {
    uint8_t id = 0;
    if (i2c_read_reg(handle, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x%02X)\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_reg(handle, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg(handle, TCS34725_CONTROL, 0x01) < 0) return -1;
    if (i2c_write_reg(handle, TCS34725_ENABLE, 0x03) < 0) return -1;

    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    if (i2c_read_block(handle, TCS34725_CDATA, buf, sizeof(buf)) < 0) {
        return -1;
    }
    *clear = (uint16_t)((buf[1] << 8) | buf[0]);
    *red   = (uint16_t)((buf[3] << 8) | buf[2]);
    *green = (uint16_t)((buf[5] << 8) | buf[4]);
    *blue  = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%u,%u,%u\n", ts, clear, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TCS34725_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(g_log_file);
    }

    uint16_t clear, red, green, blue;
    int consecutive_errors = 0;

    while (g_running) {
        if (tcs34725_read_data(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_data(g_log_file, clear, red, green, blue);
            consecutive_errors = 0;
        } else {
            fprintf(stderr, "Warning: failed to read sensor data (attempt %d/%d)\n",
                    consecutive_errors + 1, MAX_CONSECUTIVE_ERRORS);
            if (++consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive errors, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

