#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90817_ADDR  0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MAX_READ_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit pressure value from the MLX90817                     */
/* Returns 0 on success (value stored in *out), -1 on error.         */
/* ------------------------------------------------------------------ */
static int read_pressure(uint16_t *out)
{
    int rc;

    rc = i2cReadWordData(g_i2c_handle, PRESSURE_REG);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X: pigpio code %d\n",
                PRESSURE_REG, rc);
        return -1;
    }

    /* pigpio returns data as (msb << 8) | lsb, which is already the
     * correct byte order for a 16-bit little-endian register on the
     * Pi, so no byte-swap is needed. */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit value to kPa                                  */
/* ------------------------------------------------------------------ */
static float raw_to_kPa(uint16_t raw)
{
    return ((float)raw / 65535.0f) * 500.0f;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row with an ISO 8601 UTC timestamp                 */
/* ------------------------------------------------------------------ */
static int log_data(float pressure_kPa)
{
    time_t now;
    struct tm tm_utc;
    char ts[32];

    now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r()");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        perror("fprintf()");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        perror("fflush()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t raw;
    float    pressure_kPa;
    int      consecutive_errors = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: pigpio code %d\n",
                I2C_BUS, MLX90817_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file once ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started. Logging to %s every 1 s.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        if (read_pressure(&raw) == 0) {
            consecutive_errors = 0;
            pressure_kPa = raw_to_kPa(raw);
            if (log_data(pressure_kPa) != 0) {
                fprintf(stderr, "Logging failed — continuing.\n");
            } else {
                printf("Pressure: %.2f kPa\n", pressure_kPa);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);

            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many consecutive read errors — "
                                "sensor may be absent or bus stuck.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

