#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_MUX_AIN1_GND 0x5000
#define ADS1115_CONFIG_PGA_2_3V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_MUX_AIN1_GND | ADS1115_CONFIG_PGA_2_3V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

#define WARNING_LED_PIN 17
#define PRESSURE_THRESHOLD 105.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int16_t read_ads1115_config(int handle) {
    char buf[2];
    if (i2cWriteByteData(handle, ADS1115_REG_CONFIG, 0) < 0) return -1;
    gpioDelay(1000);
    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONFIG, buf, 2) != 2) return -1;
    return (int16_t)((buf[0] << 8) | buf[1]);
}

int16_t read_ads1115_conversion(int handle) {
    char buf[2];
    if (i2cWriteByteData(handle, ADS1115_REG_CONVERSION, 0) < 0) return -1;
    gpioDelay(1000);
    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERSION, buf, 2) != 2) return -1;
    return (int16_t)((buf[0] << 8) | buf[1]);
}

int configure_ads1115(int handle) {
    int16_t cfg = ADS1115_CONFIG_DEFAULT;
    if (i2cWriteWordData(handle, ADS1115_REG_CONFIG, cfg) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

int read_ads1115_channel(int handle, uint8_t channel) {
    if (channel > 3) return -1;
    if (channel == 0) {
        return read_ads1115_conversion(handle);
    }
    if (channel == 1) {
        return read_ads1115_conversion(handle);
    }
    return -1;
}

float convert_to_pressure(int16_t adc_value) {
    float voltage = (adc_value / 32767.0) * 3.3;
    return (voltage / 5.0) * 400.0;
}

float convert_to_temperature(int16_t adc_value) {
    float voltage = (adc_value / 32767.0) * 3.3;
    return 0.0 + (voltage - 1.0) * 100.0;
}

void control_led(int state) {
    gpioWrite(WARNING_LED_PIN, state);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus for ADS1115\n");
        gpioTerminate();
        return 1;
    }

    if (configure_ads1115(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);
    gpioWrite(WARNING_LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int16_t config = read_ads1115_config(i2c_handle);
        if (config < 0) {
            fprintf(stderr, "Failed to read ADS1115 config\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int16_t adc0 = read_ads1115_channel(i2c_handle, 0);
        int16_t adc1 = read_ads1115_channel(i2c_handle, 1);

        if (adc0 < 0 || adc1 < 0) {
            fprintf(stderr, "Failed to read ADS1115 channels\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float pressure = convert_to_pressure(adc0);
        float temperature = convert_to_temperature(adc1);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            control_led(1);
        } else {
            control_led(0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    control_led(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

