#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL 0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED 1000000      /* 1 MHz */
#define SPI_FLAGS 0             /* Mode 0, active-low CE */
#define ADC_CHANNEL 0           /* MLX91209 on MCP3008 CH0 */
#define OVERCURRENT_THRESHOLD 10.0f
#define SHUTDOWN_GPIO 27
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define ADC_MAX_VALUE 1023.0f
#define VREF 3.3f
#define SENSOR_VCC 3.3f
#define SENSOR_ZERO_CURRENT_V (SENSOR_VCC / 2.0f)
#define SENSOR_SENSITIVITY 0.066f  /* 66 mV/A */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int read_adc(int channel);
static float adc_to_current(int adc_value);
static void log_current(float current);
static void cleanup(void);
static void signal_handler(int sig);

/* Read 10-bit value from MCP3008 single-ended channel */
static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] + 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Convert ADC value to current (A) */
static float adc_to_current(int adc_value) {
    float voltage = ((float)adc_value / ADC_MAX_VALUE) * VREF;
    float current = (voltage - SENSOR_ZERO_CURRENT_V) / SENSOR_SENSITIVITY;
    return current;
}

/* Log current with timestamp */
static void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file\n");
        }
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure shutdown GPIO is LOW before terminating */
    gpioWrite(SHUTDOWN_GPIO, 0);
    gpioTerminate();
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown GPIO */
    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SHUTDOWN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_GPIO, 0);

    /* Open log file */
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open current_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT DETECTED: %.2f A (threshold %.2f A)\n",
                    current, OVERCURRENT_THRESHOLD);
            gpioWrite(SHUTDOWN_GPIO, 1);
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

