            fprintf(stderr, "Failed to flush log file\n");
        }
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure shutdown GPIO is LOW before terminating */
    gpioWrite(SHUTDOWN_GPIO, 0);
    gpioTerminate();
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown GPIO */
    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SHUTDOWN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_GPIO, 0);

    /* Open log file */
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open current_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT DETECTED: %.2f A (threshold %.2f A)\n",
                    current, OVERCURRENT_THRESHOLD);
            gpioWrite(SHUTDOWN_GPIO, 1);
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

