#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */
#define ADC_CHANNEL 0        /* MCP3008 single-ended channel 0 */
#define VREF        3.3f
#define ADC_MAX     1023.0f
#define PPM_MAX     5000.0f
#define LEAK_THRESHOLD 1000.0f
#define LOG_FILE    "methane_log.txt"
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read 10-bit value from MCP3008 single-ended channel (0-7). Returns -1 on error. */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_ppm(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;
    return ((float)adc_value / (float)ADC_MAX) * PPM_MAX;
}

static void log_reading(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f PPM\n", ts, ppm);
    fclose(fp);
}

static void check_leak(float ppm) {
    if (ppm > LEAK_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeds threshold (%.2f PPM > %.2f PPM)!\n",
                ppm, LEAK_THRESHOLD);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Methane monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float ppm = adc_to_ppm(adc);
        log_reading(ppm);
        check_leak(ppm);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    printf("Methane monitoring stopped.\n");
    return 0;
}

