#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous mode
#define ADS1115_CONFIG_BASE 0x8000 // OS bit: start conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000 // MUX[14:12] = 100 for AIN0
#define ADS1115_CONFIG_PGA_4_096 0x0200 // PGA[11:9] = 001 for +/-4.096V
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000 // MODE[8] = 0 for continuous
#define ADS1115_CONFIG_DR_128 0x0080 // DR[7:5] = 100 for 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // Comparator queue disable

#define ADC_MAX_VALUE 32767.0 // 16-bit signed max for +/-4.096V
#define ADC_VREF 4.096 // Reference voltage for PGA=1

// Pressure sensor parameters (example values, adjust for your sensor)
#define PRESSURE_OFFSET_V 0.5
#define PRESSURE_SENSITIVITY_V_PER_KPA 0.1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_ads1115(int handle, int16_t *raw_value);
float convert_to_voltage(int16_t raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }

    // Configure ADS1115: write config register (16-bit)
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096 | ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_CQUE_NONE;
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int handle, int16_t *raw_value) {
    char reg = ADS1115_REG_CONVERSION;
    char read_buf[2];

    // Point to conversion register
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register pointer\n");
        return -1;
    }

    // Read 2 bytes
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data\n");
        return -1;
    }

    *raw_value = (int16_t)((read_buf[0] << 8) | read_buf[1]);
    return 0;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    return (float)raw_value * ADC_VREF / ADC_MAX_VALUE;
}

// Convert voltage to pressure (kPa)
float convert_to_pressure(float voltage) {
    return (voltage - PRESSURE_OFFSET_V) / PRESSURE_SENSITIVITY_V_PER_KPA;
}

// Log pressure data to file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
