#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define SSMTP_RECIPIENT "recipient@example.com"
#define SSMTP_SERVER "smtp.example.com"
#define SSMTP_PORT 587
#define SSMTP_USERNAME "username"
#define SSMTP_PASSWORD "password"

#define V_SUPPLY 5.0
#define R0 10000.0
#define BETA 3950.0
#define ADC_RESOLUTION 4095.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3208(int channel) {
    char tx[3] = {0x06, (char)((channel & 0x07) << 6), 0x00};
    char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x0F) << 8) | (rx[2] & 0xFF);
}

float adc_to_voltage(int adc_value) {
    return (adc_value / ADC_RESOLUTION) * V_SUPPLY;
}

float voltage_to_humidity(float voltage) {
    return (V_SUPPLY - voltage) / 0.0315;
}

float voltage_to_temperature(float voltage) {
    float r = (V_SUPPLY - voltage) / voltage * R0;
    if (r <= 0.0) return 0.0;
    float inv_r = 1.0 / r;
    float inv_t = 1.0 / BETA + inv_r;
    float t = -273.15 + 25.0 * (1.0 - inv_t);
    return t;
}

void send_email_alert(float humidity, float temperature) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2fC\" | ssmtp %s",
             humidity, temperature, SSMTP_RECIPIENT);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to execute ssmtp\n");
    }
    pclose(fp);
}

void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

void cleanup() {
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_humidity = read_mcp3208(MCP3208_CHANNEL);
        if (adc_humidity < 0) {
            fprintf(stderr, "ADC read failed\n");
            sleep(1);
            continue;
        }

        int adc_thermistor = read_mcp3208(MCP3208_CHANNEL - 1);
        if (adc_thermistor < 0) {
            fprintf(stderr, "ADC read failed\n");
            sleep(1);
            continue;
        }

        float voltage_humidity = adc_to_voltage(adc_humidity);
        float voltage_thermistor = adc_to_voltage(adc_thermistor);

        float humidity = voltage_to_humidity(voltage_humidity);
        float temperature = voltage_to_temperature(voltage_thermistor);

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

