#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */
#define CS_PIN      8        /* GPIO8 = CE0 */
#define ADC_CHANNELS 3
#define ADC_MAX     1023     /* 10-bit ADC */
#define LOG_FILE    "impact_log.txt"
#define SAMPLE_RATE 100      /* Hz */
#define G_THRESHOLD 2.0      /* g */
#define V_SUPPLY    3.3      /* V */
#define V_OFFSET    1.65     /* ADXL335 0g output voltage */
#define SENSITIVITY 0.3      /* ADXL335: 300 mV/g */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read one channel from MCP3008 via SPI (single-ended mode). */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then don't-care */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)(0x80 | (channel << 4)),
        0x00
    };
    unsigned char rx[3] = {0};

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        gpioWrite(CS_PIN, 1);
        return -1;
    }

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS\n");
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int x, int y, int z, double mag_g) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, mag_g) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to initialize CS pin state\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("ADXL335 impact logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(1000000 / SAMPLE_RATE);
            continue;
        }

        /* Validate 10-bit range */
        if (x < 0 || x > ADC_MAX || y < 0 || y > ADC_MAX || z < 0 || z > ADC_MAX) {
            fprintf(stderr, "ADC value out of range: X=%d Y=%d Z=%d\n", x, y, z);
            gpioDelay(1000000 / SAMPLE_RATE);
            continue;
        }

        double mag_g = (double)((x - V_OFFSET) / SENSITIVITY);
        if (log_data(log_file, x, y, z, mag_g) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        if (mag_g > G_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED: X=%d Y=%d Z=%d, Mag=%.3f g\n",
                    x, y, z, mag_g);
            fflush(log_file);
        }

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

