#define REG_FIFO_DATA  0xC1
#define REG_FIFO_DATA2 0xC2
#define REG_FIFO_DATA3 0xC3
#define REG_FIFO_DATA4 0xC4

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data in little-endian byte order */
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    /*
     * Probe the sensor by attempting a register read.  If the
     * sensor is present and initialized, i2cReadByteData returns >= 0.
     */
    uint8_t probe;
    if (i2c_read_byte(handle, REG_COMMAND, &probe) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at address 0x%02X\n",
                SI1172_ADDR);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw PPG samples and log as proxy HR/SpO2 values                */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, uint16_t *ir_raw, uint16_t *red_raw)
{
    /* Trigger a measurement by writing command register 0x00 (default) */
    if (i2c_write_byte(handle, REG_COMMAND, 0x00) != 0)
        return -1;

    /* Allow time for the measurement to complete (datasheet timing) */
    gpioDelay(5000);  /* 5 ms */

    /* Read 4 bytes of FIFO data starting at 0xC1 */
    uint8_t data[4];
    if (i2c_read_block_data(handle, REG_FIFO_DATA, (char *)data, 4) != 4) {
        fprintf(stderr, "[ERROR] Failed to read 4 bytes of FIFO data\n");
        return -1;
    }

