    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr,bpm,spo2,percent,error_flag\n");
        fflush(g_log_file);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Si1172 logging started.  Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        uint16_t ir_raw = 0, red_raw = 0;
        int hr = 0, spo2 = 0;
        int error_flag = 0;

        if (read_sensor_data(g_i2c_handle, &ir_raw, &red_raw) != 0) {
            error_flag = 1;
