/*
 * Raspberry Pi 4 Model B - SpiroQuant A+ ES1-005 Mass Flow Sensor Logger
 *
 * Hardware:
 *   - Raspberry Pi 4 (SPI0: CE0/GPIO8, SCLK/GPIO11, MOSI/GPIO10, MISO/GPIO9)
 *   - MCP3008 10-bit ADC on SPI0 (CE0) for reading the sensor's analog output
 *
 * The SpiroQuant A+ outputs an analog voltage proportional to flow rate.
 * Since the Raspberry Pi lacks an ADC, we read the ADC via SPI and convert
 * the 10-bit value to flow rate using a linear scaling formula.
 *
 * Build: gcc -Wall -Wextra -O2 -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:   sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_BAUD       1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1000000    /* 1 second in microseconds */
#define FLOW_MIN       0.0f
#define FLOW_MAX       5.0f
#define ADC_MAX        1023       /* 10-bit ADC */

/* Globals for signal handler cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 via SPI                              */
/* Returns 0-1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to flow rate (L/min)                              */
/* ------------------------------------------------------------------ */
static float adc_to_flow(int adc_value)
{
    /*
     * Linear mapping: 0V -> 0 L/min, 3.3V -> 5 L/min
     * 10-bit ADC: 0 -> 0, 1023 -> 5
     */
    return ((float)adc_value / (float)ADC_MAX) * FLOW_MAX;
}

/* ------------------------------------------------------------------ */
/* Log flow rate with timestamp to CSV file                            */
/* ------------------------------------------------------------------ */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d baud): %d\n",
                SPI_CHANNEL, SPI_BAUD, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_lpm\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging flow rate to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* Sensor-absent / fault detection: ADC at rail */
        if (adc_value == 0 || adc_value >= ADC_MAX) {
            fprintf(stderr, "Warning: ADC at rail (%d); sensor may be absent or disconnected\n",
                    adc_value);
        }

        float flow_rate = adc_to_flow(adc_value);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Warning: flow rate out of range (%.2f L/min); skipping log\n",
                    flow_rate);
        } else {
            if (log_flow_rate(g_log_file, flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

