    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging flow rate to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying next cycle\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        /* Sensor-absent / fault detection: ADC at rail */
        if (adc_value == 0 || adc_value >= ADC_MAX) {
            fprintf(stderr, "Warning: ADC at rail (%d); sensor may be absent or disconnected\n",
                    adc_value);
        }

        float flow_rate = adc_to_flow(adc_value);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Warning: flow rate out of range (%.2f L/min); skipping log\n",
                    flow_rate);
        } else {
            if (log_flow_rate(g_log_file, flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

