#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP_10125_ADDR 0x67
#define MEASURE_CMD_MSB 0x68
#define MEASURE_CMD_LSB 0x45
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buf[6];

    if (i2c_write_cmd(fd, MEASURE_CMD_MSB, MEASURE_CMD_LSB) < 0) {
        return -1;
    }

    usleep(10000); // 10ms conversion time

    if (i2c_read_bytes(fd, buf, 6) < 0) {
        return -1;
    }

    // Validate CRC (simple byte comparison with expected value 0xFF)
    if (buf[5] != 0xFF) {
        fprintf(stderr, "CRC mismatch on sensor data\n");
        return -1;
    }

    uint16_t raw_pressure = (buf[0] << 8) | buf[1];
    uint16_t raw_temp = (buf[3] << 8) | buf[4];

    // Official ICP-10125 calibration formulas
    float temp_offset = 0.5f;
    float pressure_offset = 0.0f;
    float temp_scale = 0.01f;
    float pressure_scale = 0.01f;

    data->temperature = (raw_temp - temp_offset) * temp_scale;
    data->pressure = (raw_pressure - pressure_offset) * pressure_scale;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(CSV_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open CSV file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->pressure);
    fflush(log_file);
    return 0;
}

static void display_data(const sensor_data_t *data) {
    printf("Timestamp: %s, Temperature: %.2f C, Pressure: %.2f Pa\n",
           "UNKNOWN", data->temperature, data->pressure);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("ICP-10125 Weather Station started. Press Ctrl+C to exit.\n");

    while (running) {
        sensor_data_t data;

        if (read_sensor_data(i2c_fd, &data) == 0) {
            log_data(&data);
            display_data(&data);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

