#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL_1 0
#define MCP3008_CHANNEL_2 1
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define GAIN 1.0f

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

int main(int argc, char *argv[]) {
    int gain = GAIN;
    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 100) {
            fprintf(stderr, "Error: Invalid gain value: %s\n", argv[1]);
            return 1;
        }
        gain = (float)val;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Sampling audio at %d Hz, gain: %.2f\n", SAMPLE_RATE, gain);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        int samples[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = read_mcp3008(MCP3008_CHANNEL_1 + i);
            if (val < 0) {
                error = 1;
                break;
            }
            samples[i] = val;
        }

        if (error) {
            fprintf(stderr, "Error: Sensor read failed, exiting.\n");
            break;
        }

        float diff[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            diff[i] = (float)samples[i] * gain;
        }

        for (int i = 0; i < SAMPLE_RATE; i++) {
            printf("%d,%.2f,%.2f\n", i, diff[0], diff[1]);
            gpioDelay(1000000 / SAMPLE_RATE);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nClean exit.\n");
    return 0;
}

