#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define BUZZER_PIN 18
#define FLAME_THRESHOLD 1.0
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", AMBIENT_TEMP_FILE, strerror(errno));
        return 25.0;
    }
    float temp = 25.0;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: invalid ambient temperature in %s\n", AMBIENT_TEMP_FILE);
        temp = 25.0;
    }
    fclose(fp);
    return temp;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(log_file->fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.3f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
        return 1;
    }

