    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        cleanup();
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            raw_adc = read_mcp3008(0);
            if (raw_adc >= 0) break;
            retries++;
            usleep(10000);
        }

        if (raw_adc < 0 || raw_adc > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", raw_adc);
            continue;
        }

        float voltage = (float)raw_adc * 3.3 / 1024.0;
        float temperature = read_ambient_temperature();
        int flame_detected = (compensate_voltage(voltage, temperature) > FLAME_THRESHOLD) ? 1 : 0;

        log_data(raw_adc, voltage, compensate_voltage(voltage, temperature), temperature, flame_detected);

        if (gpiod_line_set_value(buzzer_line, flame_detected ? 1 : 0) < 0) {
            perror("gpiod_line_set_value");
        }

        if (flame_detected) {
            printf("Flame detected! Voltage: %.3fV, Temp: %.2fC\n", voltage, temperature);
        } else {
            printf("No flame. Voltage: %.3fV, Temp: %.2fC\n", voltage, temperature);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

