#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */
#define ADC_CHANNEL 0
#define LED_GPIO    17
#define WATER_HIGH  75.0f
#define WATER_LOW   70.0f
#define LOG_FILE    "water_levels.json"
#define READ_INTERVAL_US 5000000 /* 5 seconds */
#define LOOP_DELAY_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Turn LED off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_percentage(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (float)adc_value / 1023.0f * 100.0f;
}

static void log_reading(float water_level)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    char timestamp[40];
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(g_log_fp, "  {\"timestamp\": \"%s\", \"water_level\": %.2f},\n",
                timestamp, water_level) < 0) {
        perror("fprintf to log file");
    } else {
        fflush(g_log_fp);
    }
}

static void control_led(float water_level)
{
    static int led_state = 0;

    if (water_level > WATER_HIGH && !led_state) {
        if (gpioWrite(LED_GPIO, 1) == 0) {
            led_state = 1;
            printf("Water level high (%.2f%%), LED ON\n", water_level);
        } else {
            fprintf(stderr, "Failed to set LED GPIO %d\n", LED_GPIO);
        }
    } else if (water_level < WATER_LOW && led_state) {
        if (gpioWrite(LED_GPIO, 0) == 0) {
            led_state = 0;
            printf("Water level low (%.2f%%), LED OFF\n", water_level);
        } else {
            fprintf(stderr, "Failed to set LED GPIO %d\n", LED_GPIO);
        }
    }
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file in append mode; write header if empty */
    g_log_fp = fopen(LOG_FILE, "a+");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "[\n");
        fflush(g_log_fp);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping cycle\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        float water_level = adc_to_percentage(adc_value);
        log_reading(water_level);
        control_led(water_level);

        printf("ADC: %4d  Water Level: %5.2f%%\n", adc_value, water_level);

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

