#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "your_email@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"
#define LOG_FILE "plant_data.txt"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_interval;
    char email_recipient[64];
    char msmtp_config_path[256];
} Config;

static Config config = {
    DEFAULT_SPI_CHANNEL,
    DEFAULT_ADC_CHANNEL,
    DEFAULT_MIN_RAW,
    DEFAULT_MAX_RAW,
    DEFAULT_MOISTURE_THRESHOLD,
    DEFAULT_LOGGING_INTERVAL,
    "your_email@example.com",
    DEFAULT_MSMTP_CONFIG
};

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_moisture(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Invalid calibration: max_raw %d <= min_raw %d\n", max_raw, min_raw);
        return -1;
    }
    if (raw_value < min_raw) raw_value = min_raw;
    if (raw_value > max_raw) raw_value = max_raw;
    return (int)(((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0f);
}

static int log_data(int moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, %d\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

static int send_email_alert(int moisture_percentage) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nSoil moisture level is critically low (raw ADC: %d, moisture: %d%%)\" | msmtp -t %s -f %s",
             moisture_percentage, raw_value, config.email_recipient, config.msmtp_config_path, config.email_recipient);

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("popen msmtp");
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("pclose msmtp");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:s:l:e:r:h")) != -1) {
        switch (opt) {
            case 'c': config.spi_channel = atoi(optarg); break;
            case 'a': config.adc_channel = atoi(optarg); break;
            case 'm': config.min_raw = atoi(optarg); break;
            case 's': config.max_raw = atoi(optarg); break;
            case 'l': config.logging_interval = atoi(optarg); break;
            case 'e': strncpy(config.email_recipient, optarg, sizeof(config.email_recipient) - 1); config.email_recipient[sizeof(config.email_recipient) - 1] = '\0'; break;
            case 'r': strncpy(config.msmtp_config_path, optarg, sizeof(config.msmtp_config_path) - 1); config.msmtp_config_path[sizeof(config.msmtp_config_path) - 1] = '\0'; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw] [-s max_raw] [-l logging_interval] [-e email_recipient] [-r msmtp_config]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(config.spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Plant monitoring started. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, config.logging_interval);

    while (!terminate) {
        int raw_value = read_mcp3008(config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "ADC read failed, retrying in %d seconds...\n", config.logging_interval);
            sleep(config.logging_interval);
            continue;
        }

        int moisture_percentage = calibrate_moisture(raw_value, config.min_raw, config.max_raw);
        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (moisture_percentage < config.moisture_threshold) {
            if (send_email_alert(moisture_percentage) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        for (int i = 0; i < config.logging_interval && !terminate; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Plant monitoring stopped.\n");
    return EXIT_SUCCESS;
}

