#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel 0
#define VREF 3.3            // Reference voltage
#define ADC_MAX 1023.0      // 10-bit ADC max value
#define SAMPLE_INTERVAL 1   // Seconds
#define LOG_FILE "pressure_log.txt"

// Sensor calibration parameters (example values)
#define MIN_PRESSURE 10.0   // kPa
#define MAX_PRESSURE 150.0  // kPa
#define MIN_VOLTAGE 0.5     // V
#define MAX_VOLTAGE 4.5     // V

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits (masked with 0x03)
    // rx_buffer[2] contains the eight least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * VREF / ADC_MAX;
}

// Function to convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    // Linear interpolation between MIN_PRESSURE and MAX_PRESSURE
    float pressure = MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
    return pressure;
}

// Function to log pressure data to a file
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel (Mode 0, 1 MHz)
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from the sensor
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on read error
        }

        // Check for sensor-absent conditions (0V or 3.3V)
        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: Sensor reading at extreme (%d). Check sensor connection.\n", adc_value);
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log the pressure reading
        log_pressure(pressure);

        // Wait for the specified interval
        time_sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

