#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define PUMP_GPIO   17
#define MOISTURE_LOW  300
#define MOISTURE_HIGH 600
#define SAMPLE_INTERVAL 5
#define BUFFER_SIZE 20

#define MCP3008_START 0x01
#define MCP3008_SINGLE_ENDED 0x80
#define MCP3008_CHANNEL_0 0x00

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int log_index = 0;
static int log_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { MCP3008_START, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = {0};

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void control_pump(int moisture_level) {
    static int pump_on = 0;
    if (moisture_level < MOISTURE_LOW && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = 1;
            printf("Pump ON (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to turn pump ON\n");
        }
    } else if (moisture_level > MOISTURE_HIGH && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = 0;
            printf("Pump OFF (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to turn pump OFF\n");
        }
    }
}

static void log_data(int moisture_level, int pump_state) {
    LogEntry *entry = &log_buffer[log_index];
    entry->timestamp = time(NULL);
    entry->moisture_level = moisture_level;
    entry->pump_state = pump_state;

    log_index = (log_index + 1) % BUFFER_SIZE;
    if (log_count < BUFFER_SIZE) {
        log_count++;
    }
}

static void print_log(void) {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < log_count; i++) {
        int idx = (log_index - log_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Moisture=%d, Pump=%s\n",
               time_str,
               log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n\n");
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Failed to read moisture level\n");
        return;
    }

    control_pump(moisture_level);
    log_data(moisture_level, gpioRead(PUMP_GPIO));
    print_log();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

