#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define LOG_FILE "health_log.txt"
#define SAMPLE_INTERVAL_US 1000000

/* MAX30102 register addresses */
#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0B
#define REG_LED2_PA 0x0C
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define MODE_SPO2 0x03
#define SPO2_CONFIG_100HZ 0x27
#define LED1_PA_24 0x24
#define LED2_PA_24 0x24

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int init_max30102(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_register(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("MAX30102 detected (Part ID: 0x%02X)\n", part_id);

    /* Reset the device */
    if (i2c_write_register(handle, REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000); /* 10ms delay for reset */

    /* Clear any pending interrupts */
    if (i2c_write_register(handle, REG_INTR_STATUS_1, 0x00) != 0) return -1;
    if (i2c_write_register(handle, REG_INTR_STATUS_2, 0x00) != 0) return -1;

    /* Configure FIFO: 3 samples per channel, 1 sample per channel */
    if (i2c_write_register(handle, REG_FIFO_CONFIG, 0x33) != 0) return -1;

    /* Set SpO2 mode */
    if (i2c_write_register(handle, REG_MODE_CONFIG, MODE_SPO2) != 0) return -1;

    /* Configure SpO2: 100Hz, 411us pulse width, 4096 ADC range */
    if (i2c_write_register(handle, REG_SPO2_CONFIG, SPO2_CONFIG_100HZ) != 0) return -1;

    /* Set LED pulse amplitudes */
    if (i2c_write_register(handle, REG_LED1_PA, LED1_PA_24) != 0) return -1;
    if (i2c_write_register(handle, REG_LED2_PA, LED2_PA_24) != 0) return -1;

    return 0;
}

static int read_fifo_data(int handle, uint8_t *red, uint8_t *ir) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, REG_FIFO_DATA, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }
    *red = (uint8_t)buffer[0] | ((uint8_t)buffer[1] << 8);
    *ir = (uint8_t)buffer[3] | ((uint8_t)buffer[4] << 8);
    return 0;
}

static float calculate_spo2(uint8_t ir1, uint8_t ir2) {
    if (ir1 == 0 || ir2 == 0) return 0.0f;
    float ratio = (float)ir1 / (float)ir2;
    float spo2 = 110.0f - 25.0f * ratio;
    if (spo2 < 0.0f) spo2 = 0.0f;
    if (spo2 > 100.0f) spo2 = 100.0f;
    return spo2;
}

static int detect_heart_rate(uint8_t *ir_data, int len, int *bpm) {
    if (len < 2) return -1;
    int peaks = 0;
    for (int i = 1; i < len - 1; i++) {
        if (ir_data[i] > ir_data[i - 1] && ir_data[i] > ir_data[i + 1]) {
            peaks++;
        }
    }
    if (peaks < 2) return -1;
    int period_us = (len - peaks) * 1000;
    *bpm = 60000 / period_us;
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102(i2c_handle) != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t red = 0, ir = 0;
    int ir_data_len = 0;
    int ir_peaks = 0;
    int ir_period_us = 0;
    int spo2 = 0.0f;
    int hr = 0;

    while (running) {
        if (read_fifo_data(i2c_handle, &red, &ir) == 0) {
            ir_data_len = ir_data_len + 2;
            if (ir_data_len >= 2) {
                ir_peaks = 0;
                ir_period_us = 0;
                detect_heart_rate(&ir, ir_data_len, &hr);
                if (hr > 0) {
                    ir_data_len = 0;
                }
            }
            spo2 = calculate_spo2(red, ir);
            if (spo2 < 95.0f) {
                char msg[128];
                snprintf(msg, sizeof(msg), "SpO2: %.2f%%", spo2);
                log_event(msg);
            }
            if (hr > 100) {
                char msg[128];
                snprintf(msg, sizeof(msg), "HR: %d BPM", hr);
                log_event(msg);
            }
        } else {
            log_event("Error reading sensor data");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

