#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define VREF        3.3
#define NUM_CHANNELS 3
#define LOG_INTERVAL_US 500000
#define CSV_FILENAME "analog_log.csv"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (char)((0x08 | channel) << 4);
    tx_buf[2] = 0x00;

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

static double calculate_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * VREF;
}

static void log_data(int channel, double voltage) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", CSV_FILENAME, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting MCP3008 data acquisition on SPI0 CE0, %d channels...\n", NUM_CHANNELS);

    while (!terminate) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                continue;
            }
            double voltage = calculate_voltage(adc_value);
            log_data(i, voltage);
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

