/*
 * Door proximity sensor for Raspberry Pi 5 (libgpiod + I2C)
 *
 * Hardware:
 *   - GP2Y0A21YK0F Sharp IR distance sensor -> ADS1115 A0
 *   - ADS1115 on /dev/i2c-1, address 0x48
 *   - 5V relay module IN on GPIO17 (active-high)
 *   - Magnetic reed switch on GPIO27 (active-low, pulled high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_sensor door_sensor.c -lgpiod
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define RELAY_LINE     17
#define REED_LINE      27
#define NUM_BASELINE_SAMPLES 10
#define THRESHOLD_PERCENT 80
#define POLL_MS        200
#define RELAY_ON_MS    3000
#define LOG_FILE       "/var/log/door_events.log"

/* ADS1115 config: single-shot, AIN0/GND, +/-4.096V, 128 SPS, continuous */
#define ADS1115_CFG_BASE 0x8000
#define ADS1115_CFG_MUX_AIN0 0x4000
#define ADS1115_CFG_PGA_4_096 0x0200
#define ADS1115_CFG_MODE_SINGLE 0x0100
#define ADS1115_CFG_DR_128 0x0080
#define ADS1115_CFG_CQUE_NONE 0x0003

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay = NULL;
static struct gpiod_line *g_reed = NULL;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    if (i2c_write16(fd, ADS1115_CONFIG, ADS1115_CFG_BASE) < 0) return -1;
    if (i2c_write16(fd, ADS1115_CONFIG, ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SINGLE |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE) < 0) return -1;
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t cfg;
    if (i2c_read16(fd, ADS1115_CONFIG, &cfg) < 0) return -1;
    if (!(cfg & ADS1115_CFG_MODE_SINGLE)) {
        fprintf(stderr, "ADS1115 not in single-shot mode\n");
        return -1;
    }
    /* Wait for conversion: ~8 ms at 128 SPS, poll up to 50 ms */
    for (int i = 0; i < 50; i++) {
        uint16_t cfg2;
        if (i2c_read16(fd, ADS1115_CONFIG, &cfg2) < 0) return -1;
        if (cfg2 & ADS1115_CFG_MODE_SINGLE) break;
        usleep(1000);
    }
    if (!(cfg2 & ADS1115_CFG_MODE_SINGLE)) return -1;
    uint16_t val;
    if (i2c_read16(fd, ADS1115_CONV, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

static int relay_set(int val) {
    if (gpiod_line_set_value(g_relay, val) < 0) {
        fprintf(stderr, "relay set failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int reed_read(void) {
    int v = gpiod_line_get_value(g_reed);
    if (v < 0) {
        fprintf(stderr, "reed read failed: %s\n", strerror(errno));
        return -1;
    }
    return v;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log open failed: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int init_i2c(void) {
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return -1;
    }
    g_relay = gpiod_chip_get_line(g_chip, RELAY_LINE);
    g_reed = gpiod_chip_get_line(g_chip, REED_LINE);
    if (!g_relay || !g_reed) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_relay, "door_sensor", 0) < 0) {
        fprintf(stderr, "relay request: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input_flags(g_reed, "door_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "reed request: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_relay) gpiod_line_set_value(g_relay, 0);
    if (g_reed) gpiod_line_release(g_reed);
    if (g_relay) gpiod_line_release(g_relay);
    if (g_chip) gpiod_chip_close(g_chip);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) return EXIT_FAILURE;
    if (init_gpio() < 0) { close(g_i2c_fd); return EXIT_FAILURE; }

    int baseline = 0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "baseline read %d failed\n", i);
            continue;
        }
        baseline += raw;
        usleep(50000);
    }
    if (baseline == 0) {
        fprintf(stderr, "baseline all zero, using 1\n");
        baseline = 1;
    }
    double avg = (double)baseline / NUM_BASELINE_SAMPLES;
    int threshold = (int)(avg * THRESHOLD_PERCENT / 100);
    printf("Baseline: %d, threshold: %d\n", baseline, threshold);

    while (g_running) {
        int16_t raw;
        if (ads1115_read(g_i2c_fd, &raw) < 0) {
            log_event("sensor read error");
            usleep(POLL_MS * 1000);
            continue;
        }
        double voltage = (double)raw / 32768.0 * 3.3;
        double dist = voltage / 0.75;
        if (dist < threshold) {
            printf("Distance %.2f cm < %.1f cm threshold, energizing relay\n", dist, threshold);
            if (relay_set(1) == 0) {
                log_event("relay energized");
                usleep(RELAY_ON_MS * 1000);
                if (relay_set(0) == 0) {
                    int reed = reed_read();
                    if (reed < 0) {
                        log_event("reed read error");
                    } else if (reed == 0) {
                        log_event("door opened");
                    } else {
                        log_event("door not opened");
                    }
                } else {
                    log_event("relay de-energize failed");
                }
            } else {
                log_event("relay energize failed");
            }
        }
        usleep(POLL_MS * 1000);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

