/*
 * soil_moisture_logger.c
 *
 * Reads three MCP3008 ADC channels (analog soil moisture sensors on channel 0)
 * via SPI0 on a Raspberry Pi 5 using libgpiod for manual CS control and
 * spidev for SPI communication. Logs to soil_moisture_log.csv every 5 s.
 *
 * Wiring (SPI0):
 *   MCP3008 #1 CS0 -> GPIO8  (manual CS0)
 *   MCP3008 #2 CS1 -> GPIO7  (manual CS1)
 *   MCP3008 #3 CS2 -> GPIO25 (manual CS2)
 *   MCP3008 DIN0 -> GPIO10 (MOSI)
 *   MCP3008 DOUT0 -> GPIO9  (MISO)
 *   MCP3008 CLK0  -> GPIO11 (SCLK)
 *   MCP3008 VDD   -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_moisture_logger soil_moisture_logger.c \
 *       -lgpiod -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <gpiod.h>

#define NUM_SENSORS      3
#define SPI_DEVICE       "/dev/spidev0.0"
#define SPI_SPEED_HZ     1000000U   /* 1 MHz */
#define SPI_MODE         SPI_MODE_0
#define SPI_BITS         8
#define LOG_FILE         "soil_moisture_log.csv"
#define SAMPLE_INTERVAL  5          /* seconds */

/* Manual CS lines (libgpiod line numbers) */
static const unsigned int cs_pins[NUM_SENSORS] = {8, 7, 25};
static const char *cs_names[NUM_SENSORS] = {"cs0", "cs1", "cs2"};

/* Globals for cleanup in signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_lines[NUM_SENSORS];
static int g_cs_requested[NUM_SENSORS] = {0};

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one MCP3008 channel (single-ended, channel 0-7).               */
/* Returns 0-1023 on success, -1 on error.                             */
/* MCP3008 single-ended read: 3-byte transfer, result in bits 9-2 of  */
/* byte 1 (lower 2 bits) and all 8 bits of byte 2.                      */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int fd, struct gpiod_line *cs_line)
{
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0) failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | 0x00) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);   /* release CS on error */
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1) failed: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int v1, int v2, int v3)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, v1, v2, v3) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int setup_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
static int setup_cs_lines(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip4");   /* RP1 on Pi 5 */
    if (!g_chip) {
        g_chip = gpiod_chip_open_by_name("gpiochip0"); /* older Pi 4/3 */
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        g_cs_lines[i] = gpiod_chip_get_line(g_chip, cs_pins[i]);
        if (!g_cs_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    cs_pins[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_request_output(g_cs_lines[i], "mcp3008-cs", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    cs_pins[i], strerror(errno));
            return -1;
        }
        g_cs_requested[i] = 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_cs_requested[i]) {
            gpiod_line_set_value(g_cs_lines[i], 1);   /* release CS */
            gpiod_line_release(g_cs_lines[i]);
            g_cs_requested[i] = 0;
        }
    }

    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_fp);
        if (sz == 0) {
            if (fprintf(g_log_fp, "timestamp,sensor1,sensor2,sensor3\n") < 0 ||
                fflush(g_log_fp) != 0) {
                fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
        }
    } else {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_spi_fd = setup_spi();
    if (g_spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_cs_lines() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int values[NUM_SENSORS];
        int read_ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(g_spi_fd, g_cs_lines[i]);
            if (v < 0) {
                read_ok = 0;
                values[i] = -1;
            } else {
                values[i] = v;
            }
        }

        if (read_ok) {
            if (log_data(g_log_fp, values[0], values[1], values[2]) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failure; skipping log entry.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

