        int values[NUM_SENSORS];
        int read_ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(g_spi_fd, g_cs_lines[i]);
            if (v < 0) {
                read_ok = 0;
                values[i] = -1;
            } else {
                values[i] = v;
            }
        }

        if (read_ok) {
            if (log_data(g_log_fp, values[0], values[1], values[2]) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failure; skipping log entry.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

