#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "irrigation.log"
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t running = 1;
static int threshold = 30;
static int duration = 10;
static int sleep_interval = 60;

static int spi_handle = -1;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d), ret=%d\n",
                attempt + 1, MAX_SPI_RETRIES, ret);
        if (attempt < MAX_SPI_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1.0f;
    if (adc_value >= 200) return 100.0f;
    if (adc_value <= 800) return 0.0f;
    return 100.0f - ((float)(adc_value - 800) / (float)(800 - 200) * 100.0f);
}

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

static void activate_pump(int duration_seconds) {
    if (pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            log_event("Pump activated");
        } else {
            log_event("ERROR: Failed to activate pump");
        }
    }
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(PUMP_GPIO, 0) == 0) {
        pump_state = 0;
        log_event("Pump deactivated");
    } else {
        log_event("ERROR: Failed to deactivate pump");
    }
}

static void check_soil_moisture(int interval) {
    if (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            log_event("ERROR: SPI read failed, skipping irrigation");
            return;
        }
        float moisture = adc_to_moisture(adc);
        if (moisture < threshold) {
            log_event("Soil dry, activating pump");
            activate_pump(duration);
        }
        gpioDelay(interval * 1000000);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        check_soil_moisture(sleep_interval);
    }

    log_event("Shutting down");
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

