#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define PCF8591_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out) {
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy read: the PCF8591 returns the result of the *previous* conversion,
     * so we discard this byte before reading the current sample. */
    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) < 0) {
        goto cleanup;
    }

    while (running) {
        uint8_t config = 0x00; /* single-ended, channel 0, analog output disabled */
        if (i2c_write_byte(fd, config) < 0) {
            goto cleanup;
        }

        /* Wait for the conversion to complete (PCF8591 needs ~100 us typical). */
        usleep(1000);

        uint8_t sample;
        if (i2c_read_byte(fd, &sample) < 0) {
            goto cleanup;
        }

        printf("AIN0: %3u\n", sample);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

