        printf("AIN0: %3u\n", sample);
        fflush(stdout);

        usleep(SAMPLE_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

