#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define ADC_CHANNEL    0
#define ADC_CONV_REG   0x00
#define ADC_CONFIG_REG 0x01
#define GPIO_PIN       27
#define BUFFER_SIZE    10
#define VCC            3.3f
#define ZERO_FIELD_V   2.5f
#define SENSITIVITY    0.0014f  /* mV/Gauss */
#define THRESHOLD_GAUSS 500.0f
#define SAMPLE_US      1000000  /* 1 Hz */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed: %d", i2c_handle);
        return -1;
    }
    /* ADS1115 config: AIN0 single-ended, +/-4.096 V, 128 SPS, continuous */
    uint16_t config = 0x8483;
    if (i2cWriteWordData(i2c_handle, ADC_CONFIG_REG, config) < 0) {
        syslog(LOG_ERR, "i2cWriteWordData config failed");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_adc_raw(int16_t *raw) {
    char reg = ADC_CONV_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "i2cWriteDevice reg select failed");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "i2cReadDevice failed");
        return -1;
    }
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static float convert_to_voltage(int16_t raw) {
    /* 16-bit signed, +/-4.096 V range */
    int16_t signed_raw = (int16_t)raw;
    float voltage = (float)signed_raw * 4.096f / 32768.0f;
    return voltage;
}

static float convert_to_gauss(float voltage) {
    return (voltage - ZERO_FIELD_V) / SENSITIVITY;
}

static void update_buffer(float gauss) {
    buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_rolling_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += buffer[i];
    return sum / (float)buffer_count;
}

static void trigger_shutdown(void) {
    if (gpioWrite(GPIO_PIN, 1) < 0) {
        syslog(LOG_ERR, "gpioWrite HIGH failed");
        return;
    }
    syslog(LOG_INFO, "Motor shutdown triggered (GPIO27 HIGH)");
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting Hall sensor monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started (ADC channel %d, GPIO27, threshold %.1f Gauss)", ADC_CHANNEL, THRESHOLD_GAUSS);

    while (running) {
        int16_t raw = 0;
        if (read_adc_raw(&raw) < 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = convert_to_voltage(raw);
        if (voltage < 0.0f || voltage > VCC) {
            syslog(LOG_ERR, "Voltage out of range: %.3f V", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float gauss = convert_to_gauss(voltage);
        update_buffer(gauss);
        float avg = calculate_rolling_average();

        syslog(LOG_INFO, "Voltage: %.3f V, Gauss: %.3f, Avg: %.3f", voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            trigger_shutdown();
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

