#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define PUMP_GPIO   18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10
#define READ_INTERVAL 60
#define LOG_FILE "watering_events.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static void log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture Level: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    } else {
        fprintf(fp, "[timestamp error] - Moisture Level: %d\n", moisture_level);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize pump GPIO state\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Soil Moisture Monitoring and Pump Control started.\n");

    while (running) {
        int moisture_level = read_mcp3008(0);

        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level. Retrying in %d seconds.\n", READ_INTERVAL);
            sleep(READ_INTERVAL);
            continue;
        }

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d. Activating pump.\n", moisture_level);
            if (control_pump(1) != 0) {
                fprintf(stderr, "Pump activation failed.\n");
            } else {
                log_event(moisture_level);
                sleep(WATERING_DURATION);
                if (control_pump(0) != 0) {
                    fprintf(stderr, "Pump deactivation failed.\n");
                }
            }
        } else {
            printf("Moisture level: %d. No action needed.\n", moisture_level);
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

