#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define BLINK_DURATION_US 1000000  /* 1 s */

/* ADS1115 config: single-shot, AIN0, PGA=4.096V, 128 SPS, single-shot */
#define ADS1115_CONFIG_BASE 0x8183  /* MUX=100 (AIN0), PGA=001 (4.096V), MODE=1 (single-shot), DR=100 (128 SPS), COMP_QUE=11 (disable comparator) */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_raw(void) {
    char cfg[3];
    char conv[2];
    int16_t raw;

    /* Write config: pointer to conversion register, then 2 bytes of config */
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    cfg[2] = ADS1115_CONFIG_BASE & 0xFF;

    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: I2C write to config register failed\n");
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Point to conversion register, then read 2 bytes */
    cfg[0] = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, cfg, 1) < 0) {
        fprintf(stderr, "Error: I2C write to conversion register failed\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, conv, 2) < 0) {
        fprintf(stderr, "Error: I2C read from conversion register failed\n");
        return -1;
    }

    raw = (int16_t)((conv[0] << 8) | (conv[1] & 0xFF));
    return raw;
}

static double calculate_magnetic_field(int16_t raw) {
    /* ADS1115 PGA = 4.096V -> LSB = 4.096V / 32768 = 0.000125 V */
    double voltage = (double)raw * 0.000125;
    /* SS49E sensitivity: 0.001 V/Gauss (1 mV/Gauss) */
    return voltage / 0.001;
}

static void blink_led(void) {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(BLINK_DURATION_US);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(BLINK_DURATION_US);
}

int main(int argc, char *argv[]) {
    double threshold = 100.0;

    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Error: Threshold must be positive\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.2f Gauss)...\n", threshold);

    while (running) {
        int16_t raw = read_ads1115_raw();
        if (raw < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double field = calculate_magnetic_field(raw);
        printf("Magnetic Field: %.2f Gauss\n", field);

        if (field > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

