#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define HYSTERESIS 5.0
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "soil_moisture_rpi4"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define SAMPLE_INTERVAL 60
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static MQTTClient client = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc) {
    if (adc < 0 || adc > 1023) return -1.0f;
    return 100.0f - ((float)adc / 1023.0f) * 100.0f;
}

static void mqtt_connect_callback(void *context, char *topic, int result) {
