#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_FILE "sensor_data.csv"
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, then null byte */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int log_data(FILE *fp, float v0, float v1, float v2) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, v0, v1, v2) < 0) {
        fprintf(stderr, "fprintf() failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, baud %d): %d\n",
                SPI_CHANNEL, SPI_BAUD, spi_handle);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Logging MCP3008 channels 0-2 to %s every 5 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (running) {
        int vals[NUM_CHANNELS];
        int ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            vals[i] = read_mcp3008(i);
            if (vals[i] < 0) {
                fprintf(stderr, "Read failed on channel %d\n", i);
                ok = 0;
                break;
            }
        }

        if (!ok) {
            break;
        }

        float v[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            v[i] = (float)vals[i] * VREF / 1024.0f;
        }

        if (log_data(fp, v[0], v[1], v[2]) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int s = 0; s < 50 && running; s++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");

    if (fclose(fp) != 0) {
        perror("fclose");
    }
    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "spiClose failed\n");
    }
    gpioTerminate();

    return 0;
}

