    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f,%.2f,%d\n", ts, sound, light, err) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) return 1;
    if (init_spi() != 0) { close(i2c_fd); return 1; }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        close(i2c_fd); close(spi_fd);
        return 1;
    }

    while (running) {
        int err = 0;
        float sound = 0.0f, light = 0.0f;
        int adc = read_adc(0);
        if (adc < 0) err = 1;
        if (read_bh1750(&light) != 0) err = 1;

        if (log_data(sound, light, err) != 0) {
            fprintf(stderr, "log write failed\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

