#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define NUM_SENSORS 3
#define PWM_FREQ 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calculate_valve_position(int adc_sum, int num_sensors) {
    if (num_sensors <= 0) return 0;
    int avg = adc_sum / num_sensors;
    int duty = (int)(((float)avg / 1023.0f) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

static void set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > PWM_RANGE) position = PWM_RANGE;
    gpioPWM(VALVE_GPIO, position);
}

static void log_data(int s1, int s2, int s3, int avg, int pos) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, S1=%d, S2=%d, S3=%d, Avg=%d, ValvePos=%d\n",
            ts, s1, s2, s3, avg, pos);
    fflush(log_file);
}

static void cleanup(void) {
    set_valve_position(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Irrigation controller started. Press Ctrl+C to stop.\n");

    while (running) {
        int sum = 0;
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(i);
            if (v < 0) {
                fprintf(stderr, "Sensor %d read failed\n", i);
                continue;
            }
            sum += v;
            valid++;
        }

        if (valid == 0) {
            fprintf(stderr, "All sensors failed, skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int avg = sum / valid;
        int pos = calculate_valve_position(avg, valid);

        set_valve_position(pos);
        log_data(0, 1, 2, avg, pos);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("Shutdown complete.\n");
    return 0;
}

