        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float read_distance(void) {
    struct timespec start, end;
    long elapsed_ns;

    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("Failed to set Trig low");
        return -1.0f;
    }
    usleep(2);

    if (gpiod_line_set_value(trig_line, 1) < 0) {
        perror("Failed to set Trig high");
        return -1.0f;
    }
    usleep(10);

    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("Failed to set Trig low");
        return -1.0f;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
            if (elapsed_ns > ECHO_TIMEOUT_NS) {
                return -1.0f;
            }
            return (float)elapsed_ns / 1000000000.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (end.tv_sec - start.tv_sec > 0.1) {
            return -1.0f;
        }
    }
}

float map_distance_to_frequency(float distance) {
    if (distance < calibration_data.min_distance) distance = calibration_data.min_distance;
    if (distance > calibration_data.max_distance) distance = calibration_data.max_distance;

    float freq = calibration_data.min_frequency +
        (distance - calibration_data.min_distance) *
        (calibration_data.max_frequency - calibration_data.min_frequency) /
        (calibration_data.max_distance - calibration_data.min_distance);

    if (freq < calibration_data.min_frequency) freq = calibration_data.min_frequency;
    if (freq > calibration_data.max_frequency) freq = calibration_data.max_frequency;

    return freq;
}

int set_pwm_frequency(int frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Frequency %d out of range [%d, %d]\n", frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }

    int duty = (int)((float)frequency / MAX_FREQUENCY * PWM_DUTY_MAX);
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    int period_ns = 10000000 / frequency;
    int duty_ns = period_ns * duty / PWM_DUTY_MAX;

    FILE *fp = fopen("/sys/class/pwm/pwmchip0/pwm0/period", "w");
    if (!fp) {
        perror("Failed to write period");
        return -1;
    }
    fprintf(fp, "%d", period_ns);
    fclose(fp);

    fp = fopen("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "w");
    if (!fp) {
        perror("Failed to write duty_cycle");
        return -1;
    }
    fprintf(fp, "%d", duty_ns);
    fclose(fp);

    return 0;
}

int set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_DUTY_MAX) duty_cycle = PWM_DUTY_MAX;

    int period_ns = 10000000 / PWM_PERIOD_NS;
    int duty_ns = period_ns * duty_cycle / PWM_DUTY_MAX;

    FILE *fp = fopen("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "w");
    if (!fp) {
        perror("Failed to write duty_cycle");
        return -1;
    }
    fprintf(fp, "%d", duty_ns);
    fclose(fp);

    return 0;
}

int read_ldr(void) {
    int adc_value = spi_read_adc(LDR_ADC_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read LDR ADC value\n");
        return -1;
    }
    return adc_value;
}

void cleanup(void) {
    if (pwm_enabled) {
        set_pwm_duty_cycle(0);
        close(pwm_opened);
        pwm_enabled = 0;
    }
    if (pwm_exported) {
        unlink("/sys/class/pwm/pwmchip0/pwm0/period");
        unlink("/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
        unlink("/sys/class/pwm/pwmchip0/pwm0/enable");
        pwm_exported = 0;
    }
    if (echo_line) gpiod_line_release(echo_line);
    if (trig_line) gpiod_line_release(trig_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

int load_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found: %s\n", filename);
        return -1;
    }

    if (fscanf(fp, "%f %f %f %f", &calibration_data.min_distance, &calibration_data.max_distance, &calibration_data.min_frequency, &calibration_data.max_frequency) != 4) {
        fprintf(stderr, "Invalid calibration data format\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration data loaded: min=%.2f, max=%.2f, min_freq=%.2f, max_freq=%.2f\n",
           calibration_data.min_distance, calibration_data.max_distance,
           calibration_data.min_frequency, calibration_data.max_frequency);
    return 0;
}

int save_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("Failed to open calibration file for writing");
        return -1;
    }

    fprintf(fp, "%f %f %f %f\n", calibration_data.min_distance, calibration_data.max_distance,
            calibration_data.min_frequency, calibration_data.max_frequency);

    fclose(fp);
    printf("Calibration data saved to %s\n", filename);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        close(spi_fd);
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "theremin-trig", 0) < 0) {
        perror("Failed to request Trig line as output");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "theremin-echo") < 0) {
        perror("Failed to request Echo line as input");
        cleanup();
        return 1;
    }

    if (pwm_exported) {
        unlink("/sys/class/pwm/pwmchip0/pwm0/enable");
        pwm_exported = 0;
    }

    if (pwm_exported) {
        pwm_opened = open("/sys/class/pwm/pwmchip0/pwm0/enable", O_WRONLY);
        if (pwm_opened < 0) {
            perror("Failed to open enable file");
            pwm_exported = 0;
            pwm_opened = -1;
        } else {
            pwm_enabled = 1;
        }
    }

    if (!pwm_exported) {
        FILE *fp = fopen("/sys/class/pwm/pwmchip0/pwm0/period", "w");
        if (fp) {
            fprintf(fp, "10000000");
            fclose(fp);
            pwm_exported = 1;
        } else {
            perror("Failed to export PWM");
        }
    }

    if (!pwm_exported || !pwm_opened) {
        fprintf(stderr, "PWM not available or not exported\n");
        cleanup();
        return 1;
    }

    if (load_calibration_data("theremin_config.txt") < 0) {
        fprintf(stderr, "Using default calibration values\n");
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, holding last frequency\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float frequency = map_distance_to_frequency(distance);
        int duty = (int)((float)frequency / MAX_FREQUENCY * PWM_DUTY_MAX);
        if (duty < 0) duty = 0;
        if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

        if (set_pwm_frequency(frequency) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
        }

        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            fprintf(stderr, "Error reading LDR, holding last duty\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (set_pwm_duty_cycle(ldr_value) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting...\n");
    cleanup();
    return 0;
}

