#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY 1 // seconds
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_aqi(int adc_value);
void control_fan(float aqi);
void log_data(float aqi);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read from MCP3008 ADC (single-ended, channel 0-7)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // MCP3008 SPI protocol: start bit (0x01), single-ended mode (0x08), channel select (0x00-0x07)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode + channel
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value from response bytes 1 and 2
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate AQI from ADC value (linear mapping: 0-500)
float calculate_aqi(int adc_value) {
    // Linear mapping: 0-1023 ADC -> 0-500 AQI
    return (float)adc_value / 1023.0 * 500.0;
}

// Function to control the ventilation fan
void control_fan(float aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to a file
void log_data(float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %.2f\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed\n");
        return -1;
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    spiClose(spi_handle);
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        // Retry loop for SPI read
        while (retries < SPI_RETRIES && adc_value < 0) {
            adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error: SPI read failed, retrying (%d/%d)...\n", retries + 1, SPI_RETRIES);
                retries++;
                sleep(SPI_RETRY_DELAY);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: SPI read failed after %d retries, re-initializing SPI...\n", SPI_RETRIES);
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Error: SPI re-initialization failed, exiting\n");
                break;
            }
            sleep(SPI_RETRY_DELAY); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Calculate AQI
        float aqi = calculate_aqi(adc_value);

        // Control fan
        control_fan(aqi);

        // Log data
        log_data(aqi);

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

