#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// GPIO pin definitions
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI definitions
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC definitions
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
void set_motor_speed(int enable_pin, int direction_pin, int speed);
void move_motor(int enable_pin, int direction_pin, int speed, int duration_ms);
void cleanup();
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to set motor speed and direction
void set_motor_speed(int enable_pin, int direction_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > MAX_SPEED) speed = MAX_SPEED;

    // Set PWM duty cycle for speed (0-255)
    gpioPWM(enable_pin, speed);

    // Set direction (1 = forward, 0 = backward)
    gpioWrite(direction_pin, (speed > 0) ? 1 : 0);
}

// Function to move motor with acceleration/deceleration
void move_motor(int enable_pin, int direction_pin, int speed, int duration_ms) {
    int current_speed = speed;
    int increment = (speed > MIN_SPEED) ? (MAX_SPEED - speed) / duration_ms : (speed < MAX_SPEED) ? (speed - MIN_SPEED) / duration_ms : 0;

    for (int i = 0; i < duration_ms && !terminate; i += increment) {
        set_motor_speed(enable_pin, direction_pin, current_speed);
        time_sleep(i / 1000.0);
        current_speed += increment;
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);
    gpioWrite(MOTOR1_ENABLE, 0);
    gpioWrite(MOTOR2_ENABLE, 0);
    gpioTerminate();
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
