        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, (int)(speed_factor1 * 100.0f));
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, (int)(speed_factor2 * 100.0f));

