#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_US 10000
#define DEBOUNCE_MS 10
#define CALIBRATION_TIME_S 5
#define NOISE_THRESHOLD 0.1f

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calibrate_ambient(void) {
    float sum = 0.0f;
    int valid = 0;
    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_TIME_S);
    for (int i = 0; i < CALIBRATION_TIME_S * 100 && running; i++) {
        int val = read_mcp3008(0);
        if (val >= 0) {
            sum += (float)val;
            valid++;
        }
        gpioDelay(1000000);
    }
    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid ADC samples\n");
        return -1.0f;
    }
    return sum / valid;
}

static void control_led(float level) {
    static int led_state = 0;
    static uint32_t last_toggle = 0;

    if (level > (NOISE_THRESHOLD * 1023.0f)) {
        uint32_t now = gpioTick();
        if (now - last_toggle > DEBOUNCE_MS * 1000) {
            led_state = !led_state;
            if (gpioWrite(LED_PIN, led_state) == 0) {
                last_toggle = now;
            } else {
                fprintf(stderr, "Failed to write LED pin\n");
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float level = (float)val / 1023.0f;
        printf("Sound level: %.2f\n", level);
        control_led(level);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

