#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel for AWM720P
#define VOLTAGE_MIN 0.5   // Sensor output at 0 SLPM
#define VOLTAGE_MAX 4.5   // Sensor output at 200 SLPM
#define AIRFLOW_MAX 200.0 // Maximum airflow in SLPM
#define SAMPLE_INTERVAL_MS 100 // Sampling interval in milliseconds
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_airflow(float airflow);
void log_error(const char *message);
void signal_handler(int signal);
void timer_callback(void *user_data);

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid ADC channel");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message for MCP3008
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 3) {
        log_error("SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    // Linear interpolation: 0.5V at 0 SLPM, 4.5V at 200 SLPM
    float airflow = (voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) * AIRFLOW_MAX;
    return airflow;
}

// Function to log airflow data to file
void log_airflow(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Airflow: %.2f SLPM\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Timer callback function (runs every 100ms)
void timer_callback(void *user_data) {
    int adc_value = read_adc(ADC_CHANNEL);
    if (adc_value >= 0) {
        float voltage = (float)adc_value / 1023.0 * 3.3; // Convert ADC value to voltage
        float airflow = voltage_to_airflow(voltage);
        log_airflow(airflow);
    } else {
        log_error("ADC read failed");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI_MODE0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback (runs every 100ms)
    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, timer_callback) != 0) {
        fprintf(stderr, "Failed to set up timer\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Keep the program running until a signal is received
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, NULL); // Disable timer
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

