#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP_NAME  "gpiochip0"
#define CS_PIN          8
#define SPI_SPEED_HZ    1000000
#define SAMPLE_PERIOD_NS 1000000  /* 1 ms -> 1000 Hz */
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int init_gpio(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    struct gpiod_line *cs = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return fd;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0..1023 on success, -1 on error.
 */
static int read_mcp3008(int spi_fd, struct gpiod_line *cs)
{
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | 0x00) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    /* Manually control CS: drive low before transfer, high after */
    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("gpiod_line_set_value(low)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("gpiod_line_set_value(high)");
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *log, long long ts_ns, int adc)
{
    if (fprintf(log, "%lld|%d\n", ts_ns, adc) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_line *cs = NULL;
    FILE *log = NULL;
    int rc = EXIT_FAILURE;

    if (setup_signals() < 0)
        goto cleanup;

    spi_fd = init_spi();
    if (spi_fd < 0)
        goto cleanup;

    cs = gpiod_chip_get_line(GPIO_CHIP_NAME, CS_PIN);
    if (!cs)
        goto cleanup;

    if (gpiod_line_request_output(cs, "mcp3008-cs", 1) < 0)
        goto cleanup;

    log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next);

    while (g_running) {
        int adc = read_mcp3008(spi_fd, cs);
        if (adc < 0) {
            fprintf(stderr, "SPI read error\n");
            goto cleanup;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        long long ts = (long long)now.tv_sec * 1000000000LL + (long long)(now.tv_nsec);

        if (log_data(log, ts, adc) < 0) {
            fprintf(stderr, "Log write error\n");
            goto cleanup;
        }

        /* Sleep until the next sample deadline (approximate) */
        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000LL) {
            next.tv_sec++;
            next.tv_nsec -= 1000000000LL;
        }
        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000LL) {
            next.tv_sec++;
            next.tv_nsec -= 1000000000LL;
        }

        struct timespec req = { .tv_sec = next.tv_sec,
                                .tv_nsec = next.tv_nsec };
        while (nanosleep(&req, &req) < 0 && errno == EINTR && g_running)
            ;
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (log) {
        fclose(log);
        log = NULL;
    }
    if (cs)
        gpiod_line_release(cs);
    if (spi_fd >= 0)
        close(spi_fd);
    return rc;
}

