#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// ADXL335 Configuration
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // 1.5V at 0g

// MCP3008 Configuration
#define MCP3008_CS_PIN 8
#define MCP3008_MOSI_PIN 10
#define MCP3008_MISO_PIN 9
#define MCP3008_SCLK_PIN 11

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Kalman Filter Parameters
#define Q 0.001 // Process noise covariance
#define R 0.01 // Measurement noise covariance
#define PREDICTIVE_GAIN 0.99 // Predictive gain
#define UPDATE_GAIN 0.1 // Update gain

// Global Variables
static volatile int running = 1;
static int spi_handle = -1;
static double Qx = 0, Qy = 0, Qz = 0;
static double Px = 0, Py = 0, Pz = 0;
static double Rx = 0, Ry = 0, Rz = 0;

// Function Prototypes
int read_mcp3008(int channel);
double convert_adc_to_voltage(int adc_value);
double convert_voltage_to_acceleration(double voltage);
void kalman_filter(double new_measurement, double *state, double *covariance);
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    gpioWrite(MCP3008_CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // De-assert CS

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
double convert_adc_to_voltage(int adc_value) {
    return (double)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to acceleration (g)
double convert_voltage_to_acceleration(double voltage) {
    return (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
}

// Kalman Filter implementation
void kalman_filter(double new_measurement, double *state, double *covariance) {
    // Prediction step
