#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define VCC 3.3f
#define V_QUIESCENT (VCC / 2.0f)
#define SENSITIVITY 0.025f
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define MIN_MAGNETIC_FIELD -100.0f
#define MAX_MAGNETIC_FIELD 100.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line, int *value) {
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    *value = ret;
    return 0;
}

static float calculate_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * VCC;
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

static int log_data(float sensor1, float sensor2, float sensor3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%.3f,%.3f,%.3f\n", sensor1, sensor2, sensor3);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    line3 = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "drv5055_sensor1") < 0 ||
        gpiod_line_request_input(line2, "drv5055_sensor2") < 0 ||
        gpiod_line_request_input(line3, "drv5055_sensor3") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value, sensor2_value, sensor3_value;

        if (read_sensor(line1, &sensor1_value) < 0 ||
            read_sensor(line2, &sensor2_value) < 0 ||
            read_sensor(line3, &sensor3_value) < 0) {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float sensor1_magnetic_field = calculate_magnetic_field(sensor1_value);
        float sensor2_magnetic_field = calculate_magnetic_field(sensor2_value);
        float sensor3_magnetic_field = calculate_magnetic_field(sensor3_value);

        if (log_data(sensor1_magnetic_field, sensor2_magnetic_field, sensor3_magnetic_field) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        if (sensor1_magnetic_field < MIN_MAGNETIC_FIELD || sensor1_magnetic_field > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field out of range (Sensor 1: %.3f mT)\n", sensor1_magnetic_field);
        }
        if (sensor2_magnetic_field < MIN_MAGNETIC_FIELD || sensor2_magnetic_field > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field out of range (Sensor 2: %.3f mT)\n", sensor2_magnetic_field);
        }
        if (sensor3_magnetic_field < MIN_MAGNETIC_FIELD || sensor3_magnetic_field > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: Magnetic field out of range (Sensor 3: %.3f mT)\n", sensor3_magnetic_field);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

