#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define LOG_FILE "watering.log"

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (ret != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }
    while (keep_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "SPI read error\n");
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char buf[64];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(fp, "%s, ERROR: SPI read failed\n", buf);
            fflush(fp);
            sleep(60);
            continue;
        }
        float moisture = (adc / 1023.0f) * 100.0f;
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char buf[64];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
        if (moisture < MOISTURE_THRESHOLD) {
            gpioWrite(PUMP_GPIO, 1);
            fprintf(fp, "%s, Moisture: %.2f%%, Pump ON\n", buf, moisture);
            fflush(fp);
        } else {
            gpioWrite(PUMP_GPIO, 0);
            fprintf(fp, "%s, Moisture: %.2f%%, Pump OFF\n", buf, moisture);
            fflush(fp);
        }
        sleep(60);
    }
    gpioWrite(PUMP_GPIO, 0);
    fclose(fp);
    gpioTerminate();
    return 0;
}

