#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define LED_GPIO 17
#define MAX_PAYLOAD_SIZE 256
#define MAX_RECONNECT_DELAY 60
#define BACKOFF_BASE 1

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        } else {
            printf("Connected to MQTT broker and subscribed to %s\n", MQTT_TOPIC);
        }
    } else {
        log_error("MQTT connect failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        log_error("Unexpected MQTT disconnect");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen <= 0) {
        log_error("Empty MQTT message received");
        return;
    }
    char payload[MAX_PAYLOAD_SIZE];
    int copy_len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload + (int)sizeof(payload) - copy_len, message->payload, copy_len);
    payload[(int)sizeof(payload) - copy_len] = '\0';
    char *endptr = NULL;
    cJSON *root = cJSON_Parse(payload);
    if (!root) {
        log_error("JSON parse error");
        return;
    }
    if (!cJSON_IsBoolean(root->child)) {
        log_error("Invalid JSON: missing or non-boolean 'led_state'");
        cJSON_Delete(root);
        return;
    }
    int led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state")->valueint;
    if (gpioWrite(LED_GPIO, led_state) != 0) {
        log_error("Failed to write to GPIO");
    }
    cJSON_Delete(root);
}

static void on_subscribe(struct mosquitto *m, void *userdata, int mid, int qos_count, const int *granted_qos) {
    (void)m; (void)userdata; (void)mid; (void)granted_qos;
    if (qos_count > 0) {
        printf("Subscribed to topic %s with QoS %d\n", MQTT_TOPIC, qos_count);
    } else {
        printf("Subscribed to topic %s\n", MQTT_TOPIC);
    }
}

static void reconnect_handler(struct mosquitto *m, void *userdata) {
    (void)m; (void)userdata;
    int delay = BACKOFF_BASE;
    while (running && mosquitto_reconnect(m, NULL, delay) == MOSQ_ERR_SUCCESS) {
        delay = (delay * 2 > MAX_RECONNECT_DELAY) ? MAX_RECONNECT_DELAY : delay * 2;
        sleep(delay);
    }
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (pigpio_initialized) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to set signal handlers");
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_subscribe_callback_set(mosq, on_subscribe);
    mosquitto_reconnect_callback_set(mosq, reconnect_handler);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        cleanup();
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        cleanup();
        return 1;
    }
    pigpio_initialized = 1;
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("LED control started. GPIO%d, MQTT %s:%d\n", LED_GPIO, MQTT_BROKER, MQTT_PORT);

    while (running) {
        rc = mosquitto_loop_start(mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop start failed");
            sleep(1);
            continue;
        }
        while (running) {
            rc = mosquitto_loop_run(mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("MQTT loop run failed");
                break;
            }
            if (!running) break;
        }
        if (rc != MOSQ_ERR_SUCCESS && running) {
            log_error("MQTT loop stop failed");
        }
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

