    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0x00) != 0) return -1;
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    return 0;
}

static int read_raw(int handle, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0) return -1;
    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double compensate_temp(int32_t raw, const bmp280_calib_t *c, int32_t *t_fine) {
    int32_t var1 = ((((raw >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    int32_t var2 = (((((raw >> 4) - ((int32_t)c->dig_T1)) * ((raw >> 4) - ((int32_t)c->dig_T1))) >> 12) * ((int32_t)c->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    int32_t T = (*t_fine * 5 + 128) >> 8;
    return T / 100.0;
}

static double compensate_press(int32_t raw, const bmp280_calib_t *c, int32_t t_fine) {
    int64_t var1 = ((int64_t)t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)c->dig_P6;
    var2 = var2 + ((var1 * (int64_t)c->dig_P5) << 17);
    var2 = var2 + (((int64_t)c->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)c->dig_P3) >> 8) + ((var1 * (int64_t)c->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)c->dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    int64_t p = 1048576 - raw;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)c->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)c->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)c->dig_P7) << 4);
    return (double)p / 256.0;
}

static double calc_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_PRESSURE, 0.1903));
}

static void log_reading(double altitude) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Altitude: %.2f m\n", ts, altitude);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_init(i2c_handle, &cal) != 0) {
        fprintf(stderr, "Error: BMP280 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int32_t raw_t, raw_p;
        if (read_raw(i2c_handle, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Error: I2C read failed\n");
            break;
        }
        int32_t t_fine;
        double temp = compensate_temp(raw_t, &cal, &t_fine);
        double press = compensate_press(raw_p, &cal, t_fine);
        double alt = calc_altitude(press);
        log_reading(alt);
        printf("Altitude: %.2f m\n", alt);
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

