#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3f
#define LM35_SCALE 0.01f
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL_US 5000000

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_temperature(int adc_value) {
    return (float)adc_value * LM35_SCALE;
}

static void buffer_init(float *buffer, int size) {
    memset(buffer, 0, size * sizeof(float));
}

static void buffer_add(float *buffer, int *index, float value) {
    buffer[*index] = value;
    *index = (*index + 1) % size;
}

static int buffer_write_to_file(const char *filename, float *buffer, int size) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    int written = fwrite(buffer, sizeof(float), size, fp);
    if (written != size) {
        fprintf(stderr, "Error writing to file: wrote %d of %d values\n", written, size);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature_buffer[BUFFER_SIZE];
    buffer_init(temperature_buffer, BUFFER_SIZE);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float temperature = adc_to_temperature(adc_value);
            buffer_add(temperature_buffer, 0, temperature);
            printf("Temperature: %.2f °C\n", temperature);

            if (buffer_write_to_file(LOG_FILE, temperature_buffer, BUFFER_SIZE) != 0) {
                fprintf(stderr, "Failed to write buffer to file\n");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

