#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SPI_BUS "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(*fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }
    return 0;
}

static int init_spi(int *fd) {
    *fd = open(SPI_BUS, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening SPI bus %s: %s\n", SPI_BUS, strerror(errno));
        return -1;
    }
    unsigned int speed = 1000000;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    unsigned char cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to BH1750: %s\n", strerror(errno));
        return -1;
    }
    usleep(180000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(float lux, int sound_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Light: %.2f, Sound: %d\n", timestamp, lux, sound_level);
    fclose(fp);
    return 0;
}

int main(void) {
    int i2c_fd = -1, spi_fd = -1;
    float lux = 0.0f;
    int sound_level = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c(&i2c_fd) < 0) {
        return 1;
    }
    if (init_spi(&spi_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Error reading light sensor, skipping sample.\n");
        } else {
            sound_level = read_mcp3008(spi_fd, 0);
            if (sound_level < 0) {
                fprintf(stderr, "Error reading sound sensor, skipping sample.\n");
            } else {
                if (log_data(lux, sound_level) < 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

