#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP4725_ADDR 0x62
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000

static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int write_mcp4725(uint16_t value) {
    char buf[2];
    buf[0] = (value >> 8) & 0xFF;
    buf[1] = value & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write to MCP4725 failed\n");
        return -1;
    }
    return 0;
}

static float adc_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0f) * 3.3f;
    return (voltage - 0.5f) * 100.0f;
}

static float voltage_to_dac(float voltage) {
    return (voltage / 3.3f) * 1023.0f;
}

static void log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %.2f V\n",
            timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC, retrying in 1s...\n");
            gpioDelay(1000000);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);
        float dac_voltage = voltage_to_dac(temperature);

        if (write_mcp4725((uint16_t)dac_voltage) != 0) {
            fprintf(stderr, "Failed to write DAC, retrying in 1s...\n");
            gpioDelay(1000000);
            continue;
        }

        log_data(adc_value, temperature, dac_voltage);
        printf("ADC: %d, Temperature: %.2f C, DAC: %.2f V\n", adc_value, temperature, dac_voltage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    write_mcp4725(0);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

