#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "soil_data.txt"
#define NUM_SENSORS 3
#define SLEEP_INTERVAL 60

int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void log_data(int sensor_index, float moisture_level);
void signal_handler(int signal);

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01;
    tx_buffer[1] = (0x08 | channel) << 4;
    tx_buffer[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (result = %d)\n", channel, result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d\n", adc_value);
        return -1.0;
    }
    return (1.0 - (float)adc_value / 1023.0) * 100.0;
}

void log_data(int sensor_index, float moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d, Moisture: %.2f%%\n", timestamp, sensor_index, moisture_level);
    fflush(log_file);
}

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_values[NUM_SENSORS];
        float moisture_levels[NUM_SENSORS];

        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                moisture_levels[i] = -1.0;
            } else {
                moisture_levels[i] = adc_to_moisture(sensor_values[i]);
            }
        }

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (moisture_levels[i] < 0) {
                fprintf(stderr, "Error: Invalid moisture reading for sensor %d\n", i);
            } else {
                log_data(i, moisture_levels[i]);
            }
        }

        gpioDelay(SLEEP_INTERVAL * 1000000);
    }

    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Soil Moisture Monitoring Stopped.\n");
    return 0;
}

