#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor driver pins (L298N-compatible numbering) */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Rain sensor threshold (ADC value) */
#define RAIN_THRESHOLD 5

/* Motor PWM range and speed */
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_SPEED 150

/* Polling interval */
#define POLL_INTERVAL_US 1000000  /* 1 second */

/* Global resources for signal-safe cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; do not call non-async-signal-safe  */
/* functions from here.                                              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1 on   */
/* error.                                                            */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)(0x08 | channel) << 4, 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to rain level (0-10). Higher ADC = drier = rain   */
/* level 0.                                                        */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 10 - (int)(((float)adc_value / 1023.0f) * 10.0f);
}

/* ------------------------------------------------------------------ */
/* Log a timestamped rain reading to the log file.                     */
/* ------------------------------------------------------------------ */
static void log_rain_level(int rain_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s Rain Level: %d\n", timestamp, rain_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

/* ------------------------------------------------------------------ */
/* Drive the motor forward (close window) for duration_ms.             */
/* ------------------------------------------------------------------ */
static void close_window(int duration_ms)
{
    if (gpioPWM(MOTOR_ENA, MOTOR_PWM_SPEED) < 0) {
        fprintf(stderr, "Failed to set PWM on ENA\n");
        return;
    }
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioDelay(duration_ms * 1000);  /* gpioDelay takes microseconds */
    gpioPWM(MOTOR_ENA, 0);
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
}

/* ------------------------------------------------------------------ */
/* Drive the motor backward (open window) for duration_ms.             */
/* ------------------------------------------------------------------ */
static void open_window(int duration_ms)
{
    if (gpioPWM(MOTOR_ENA, MOTOR_PWM_SPEED) < 0) {
        fprintf(stderr, "Failed to set PWM on ENA\n");
        return;
    }
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioDelay(duration_ms * 1000);
    gpioPWM(MOTOR_ENA, 0);
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and initial speed */
    if (gpioSetPWMrange(MOTOR_ENA, MOTOR_PWM_RANGE) < 0 ||
        gpioPWM(MOTOR_ENA, MOTOR_PWM_SPEED) < 0) {
        fprintf(stderr, "Failed to set PWM range or initial speed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open rain_log.txt for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start with window open (motor off) */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, 0);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int rain_level = adc_to_rain_level(adc_value);
        log_rain_level(rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            printf("Rain detected (level %d)! Closing window...\n", rain_level);
            close_window(3000);  /* 3 seconds */
        } else {
            printf("Rain level reduced to %d. Window stays open.\n", rain_level);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

