#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_PERIOD_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    localtime_r(&now, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] ", buf);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_GPIO %d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_GPIO %d low.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Clap detector running. MIC=GPIO%d, LED=GPIO%d. Threshold=%d. Ctrl+C to exit.\n",
           MIC_GPIO, LED_GPIO, THRESHOLD);

    bool last_trigger = false;
    uint32_t last_trigger_tick = 0;

    while (running) {
        int adc_value = gpioRead(MIC_GPIO);
        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read MIC_GPIO %d.\n", MIC_GPIO);
            break;
        }

        uint32_t now_tick = gpioTick();

        if (adc_value > THRESHOLD) {
            if (now_tick - last_trigger_tick > DEBOUNCE_MS * 1000) {
                last_trigger = true;
                last_trigger_tick = now_tick;

                if (gpioWrite(LED_GPIO, 1) == 0) {
                    print_timestamp();
                    printf("Clap detected!\n");
                    fflush(stdout);
                    gpioDelay(LED_ON_MS * 1000);
                    gpioWrite(LED_GPIO, 0);
                }
            }
        } else {
            last_trigger = false;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

