#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio"
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD 200
#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW 0.0
#define A 26.0
#define B -6.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", pin);
    return (access(GPIO_PATH "/export", W_OK | X_OK) == 0) ? 0 : -1;
}

static int gpio_unexport(int pin) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", pin);
    return (access(GPIO_PATH "/unexport", W_OK | X_OK) == 0) ? 0 : -1;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "%s/gpio%d/direction", GPIO_PATH, pin);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    if (fprintf(fp, "%s", dir) < 0) { fclose(fp); return -1; }
    fclose(fp);
    return 0;
}

static int gpio_set_value(int pin, int val) {
    char path[64];
    snprintf(path, sizeof(path), "%s/gpio%d/value", GPIO_PATH, pin);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    if (fprintf(fp, "%d", val) < 0) { fclose(fp); return -1; }
    fclose(fp);
    return 0;
}

static int read_gpio(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "%s/gpio%d/value", GPIO_PATH, pin);
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;
    int val = -1;
    if (fscanf(fp, "%d", &val) != 1) { fclose(fp); return -1; }
    fclose(fp);
    return val;
}

static double voltage_to_distance(double voltage) {
    return (voltage - VOLTAGE_LOW) / (VOLTAGE_HIGH - VOLTAGE_LOW) * (A + B);
}

static void log_distance(double distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f\n", ts, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    while (running) {
        int val = read_gpio(GPIO_PIN);
        if (val < 0) {
            fprintf(stderr, "GPIO read error, retrying in 1s\n");
            sleep(1);
            continue;
        }

        double voltage = (val == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
        double distance = voltage_to_distance(voltage);

        log_distance(distance);
        printf("Distance: %.2f mm\n", distance);

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    return 0;
}

