#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define LED_GPIO 21
#define VCC 3.3
#define ADC_RESOLUTION 1023.0
#define THRESHOLD 10.0
#define SENSITIVITY_MV_PER_MT 1.65
#define QUIESCENT_OUTPUT_V 1.65
#define LOG_FILE "magnetic_log.txt"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return (adc_value / ADC_RESOLUTION) * VCC;
}

static float voltage_to_field(float voltage) {
    float field = (voltage - QUIESCENT_OUTPUT_V) * 1000.0f / SENSITIVITY_MV_PER_MT;
    if (field < 0.0f) field = 0.0f;
    return field;
}

static void log_data(float field) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Field: %.2f mT\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, field);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);
    signal(SIGINT, signal_handler);
    printf("Monitoring magnetic field (threshold %.1f mT)...\n", THRESHOLD);
    while (!terminate) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            gpioDelay(100000);
            continue;
        }
        float voltage = adc_to_voltage(adc);
        float field = voltage_to_field(voltage);
        log_data(field);
        gpioWrite(LED_GPIO, field > THRESHOLD ? 1 : 0);
        gpioDelay(100000);
    }
    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

