#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "current_log.txt"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define VREF 3.3
#define SENSITIVITY 0.1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_line *line = NULL;
static struct gpiod_chip *chip = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line, "current_monitor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    if (spi_fd < 0) {
        fprintf(stderr, "SPI device not initialized\n");
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float convert_to_current(int adc_value) {
    float voltage = (float)adc_value * VREF / ADC_MAX_VALUE;
    float current = voltage / SENSITIVITY;
    return current;
}

int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, current) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(log_file);
    return 0;
}

void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            sleep(1);
            continue;
        }

        float current = convert_to_current(adc_value);

        if (log_data(current) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        sleep(1);
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

