#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W - MLX91211 Current Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V (pin 2 or 4)
 *   MCP3008 VREF -> Pi 5V
 *   MCP3008 AGND -> Pi GND
 *   MCP3008 DGND -> Pi GND
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MLX91211 is ratiometric: 2.5V at 0A, 5.0V at full-scale +50A.
 * Current = (V - 2.5) * (50.0 / 2.5)
 */

#define SPI_CHANNEL    0          /* CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 reference voltage */
#define VDD            5.0        /* MLX91211 supply voltage */
#define IFS            50.0       /* Full-scale current (A) */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.     */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
