#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define NUM_SAMPLES 5
#define SAMPLE_DELAY_MS 2
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip (gpiochip0 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    /* Get lines for the two sensors */
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("gpiod_chip_get_line(SENSOR1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("gpiod_chip_get_line(SENSOR2)");
        goto cleanup;
    }

    /* Request both lines as inputs */
    if (gpiod_line_request_input(line1, "b5w-db01-s1") < 0) {
        perror("gpiod_line_request_input(SENSOR1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-db01-s2") < 0) {
        perror("gpiod_line_request_input(SENSOR2)");
        goto cleanup;
    }

    printf("Monitoring Omron B5W-DB01 sensors on GPIO%d and GPIO%d.\n",
           SENSOR1_GPIO, SENSOR2_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int s1_state = -1, s2_state = -1;
        int s1_samples[NUM_SAMPLES];
        int s2_samples[NUM_SAMPLES];

        /* Read sensor 1 with debouncing */
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val = gpiod_line_get_value(line1);
            if (val < 0) {
                perror("gpiod_line_get_value(SENSOR1)");
                goto cleanup;
            }
            s1_samples[i] = val;
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        /* Majority vote for sensor 1 */
        int s1_majority = 0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            if (s1_samples[i] == 0) s1_majority++;
        }
        s1_state = (s1_majority > (NUM_SAMPLES / 2)) ? 0 : 1;

        /* Read sensor 2 with debouncing */
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val = gpiod_line_get_value(line2);
            if (val < 0) {
                perror("gpiod_line_get_value(SENSOR2)");
                goto cleanup;
            }
            s2_samples[i] = val;
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        /* Majority vote for sensor 2 */
        int s2_majority = 0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            if (s2_samples[i] == 0) s2_majority++;
        }
        s2_state = (s2_majority > (NUM_SAMPLES / 2)) ? 0 : 1;

        /* Log results */
        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1_state == 0 ? "Object Present" : "No Object",
               s2_state == 0 ? "Object Present" : "No Object");

        if (s1_state == 0 && s2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

