#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_PIN          17
#define IMAGE_WIDTH      1280
#define IMAGE_HEIGHT     720
#define IMAGE_QUALITY    85
#define DEBOUNCE_MS      200
#define POLL_INTERVAL_US 50000
#define CAPTURE_DIR      "/home/pi/security_cam"
#define MAX_FILENAME_LEN 256

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat(%s): %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s): %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork(): %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep our log clean */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);
        execlp("libcamera-still", "libcamera-still",
               "-o", filename,
               "--width", "1280",
               "--height", "720",
               "--quality", "85",
               (char *)NULL);
        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execlp(libcamera-still): %s", strerror(errno));
        _exit(127);
    }

    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running)
                return -1;
            continue;
        }
        syslog(LOG_ERR, "waitpid(): %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (exit %d)", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

static int generate_filename(char *buf, size_t buflen)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return -1;
    }

    if (strftime(buf, buflen, "%Y%m%d_%H%M%S.jpg", &timeinfo) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return -1;
    }
    return 0;
}

int main(void)
{
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    syslog(LOG_INFO, "Motion detector started on BCM GPIO%d", PIR_PIN);

    int last_state = gpioRead(PIR_PIN);
    if (last_state < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed", PIR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_PIN);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000);
            current_state = gpioRead(PIR_PIN);
            if (current_state < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_PIN);
                break;
            }
            if (current_state != last_state) {
                last_state = current_state;
                syslog(LOG_INFO, "Motion detected (state %d)", current_state);
                if (capture_image(CAPTURE_DIR "/motion_detected.jpg") != 0) {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    syslog(LOG_INFO, "Motion detector stopped");
    closelog();
    return EXIT_SUCCESS;
}

