#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char *buffer, int width, int height) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    memcpy(buffer, buffer->data, width * height);
    return 0;
}

static int save_pgm(const char *filename, const unsigned char *buffer, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    if (fwrite(buffer, 1, width * height, fp) != (size_t)(width * height)) {
        fprintf(stderr, "Failed to write %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", device, strerror(errno));
        return 1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device);
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Warning: device did not accept %dx%d, got %dx%d\n",
                IMAGE_WIDTH, IMAGE_HEIGHT, fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (buf.length < (unsigned int)(IMAGE_WIDTH * IMAGE_HEIGHT)) {
        fprintf(stderr, "Warning: buffer too small (%u bytes), using anyway\n", buf.length);
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int ret = 0;
    while (keep_running) {
        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            fprintf(stderr, "select timeout (no frame in %d s)\n", CAPTURE_TIMEOUT_SEC);
            continue;
        }

        if (capture_frame(fd, (unsigned char *)buffer, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
            break;
        }

        if (save_pgm("image_0001.pgm", buffer, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
            break;
        }

        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++((size_t)(buf.index % NUM_BUFFERS)));
        printf("Saved image: %s\n", filename);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            break;
        }
    }

    if (munmap(buffer, buf.length) < 0) {
        fprintf(stderr, "munmap failed: %s\n", strerror(errno));
    }

    if (close(fd) < 0) {
        fprintf(stderr, "close failed: %s\n", strerror(errno));
    }

    printf("Exiting cleanly.\n");
    return 0;
}

