#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define OUTPUT_FILE "image.jpg"
#define NUM_BUFFERS 4
#define FRAME_TIMEOUT_MS 1000

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int xioctl2(int fd, unsigned long request, void *arg, void *ret) {
    int r;
    do {
        r = xioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    if (r == -1) return -1;
    if (ret) *ret = r;
    return 0;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int pix_fmt = V4L2_PIX_FMT_MJPEG;
    unsigned int width = IMAGE_WIDTH;
    unsigned int height = IMAGE_HEIGHT;
    unsigned int i;

    *fd = open(DEVICE_NAME, O_RDWR, 0);
    if (*fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pix_fmt;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(*fd);
            return -1;
        }

        if (buf.length < (unsigned int)(width * height)) {
            fprintf(stderr, "Insufficient buffer size\n");
            close(*fd);
            return -1;
        }

        if (xioctl(*fd, VIDIOC_MMAP, &buf) < 0) {
            perror("VIDIOC_MMAP");
            close(*fd);
            return -1;
        }

        if (munmap((void *)buf.m.offset, buf.length) < 0) {
            perror("munmap");
            close(*fd);
            return -1;
        }
    }

    if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("VIDIOC_STREAMON");
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_image(int fd, const char *filename) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = FRAME_TIMEOUT_MS / 1000;
    tv.tv_usec = (FRAME_TIMEOUT_MS % 1000) * 1000;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Frame has no data\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen(" OUTPUT_FILE ")");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    size_t written = fwrite(buf.m.offset, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Short write to %s\n", filename);
        fclose(fp);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(" OUTPUT_FILE ")");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    xioctl(fd, VIDIOC_QBUF, &buf);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_camera(&fd) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    if (capture_image(fd, OUTPUT_FILE) < 0) {
        fprintf(stderr, "Image capture failed\n");
        ret = EXIT_FAILURE;
    } else {
        printf("Image captured and saved as %s\n", OUTPUT_FILE);
        ret = EXIT_SUCCESS;
    }

    if (fd >= 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &buf);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buf.index >= 0 && buf.index < req.count) {
                xioctl(fd, VIDIOC_QBUF, &buf);
            }
        }
        close(fd);
    }

    return ret;
}

