#include <gpiod.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define UP_BUTTON_GPIO 6
#define DOWN_BUTTON_GPIO 7
#define LEFT_BUTTON_GPIO 8
#define RIGHT_BUTTON_GPIO 9

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_MID_PULSE_WIDTH 1500
#define SERVO_MIN_DUTY 50
#define SERVO_MAX_DUTY 100
#define SERVO_MID_DUTY 75
#define STEP_SIZE 5
#define POLL_INTERVAL_US 50000
#define PWM_PERIOD_US 20000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(struct gpiod_line *line, int duty) {
    if (duty < SERVO_MIN_DUTY) duty = SERVO_MIN_DUTY;
    if (duty > SERVO_MAX_DUTY) duty = SERVO_MAX_DUTY;
    int pulse_width = (int)((long)(duty * SERVO_MAX_PULSE_WIDTH) / SERVO_MAX_DUTY);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "set_value(1) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(pulse_width * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "set_value(0) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep((PWM_PERIOD_US - pulse_width * 1000) * 1000);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *up_line = NULL, *down_line = NULL;
    struct gpiod_line *left_line = NULL, *right_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_GPIO);
    tilt_line = gpiod_chip_get_line(chip, TILT_GPIO);
    up_line = gpiod_chip_get_line(chip, UP_BUTTON_GPIO);
    down_line = gpiod_chip_get_line(chip, DOWN_BUTTON_GPIO);
    left_line = gpiod_chip_get_line(chip, LEFT_BUTTON_GPIO);
    right_line = gpiod_chip_get_line(chip, RIGHT_BUTTON_GPIO);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan-servo", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "tilt-servo", 0) < 0 ||
        gpiod_line_request_input_flags(up_line, "up-button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(down_line, "down-button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(left_line, "left-button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(right_line, "right-button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    int pan_pos = SERVO_MID_PULSE_WIDTH;
    int tilt_pos = SERVO_MID_PULSE_WIDTH;

    while (running) {
        int up_val = gpiod_line_get_value(up_line);
        int down_val = gpiod_line_get_value(down_line);
        int left_val = gpiod_line_get_value(left_line);
        int right_val = gpiod_line_get_value(right_line);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read button values: %s\n", strerror(errno));
            break;
        }

        if (up_val == 0) {
            tilt_pos += STEP_SIZE;
            if (tilt_pos > 125) tilt_pos = 125;
            if (tilt_pos < 25) tilt_pos = 25;
            if (set_servo_pulse(tilt_line, tilt_pos) < 0) break;
        } else if (down_val == 0) {
            tilt_pos -= STEP_SIZE;
            if (tilt_pos < 25) tilt_pos = 25;
            if (tilt_pos > 125) tilt_pos = 125;
            if (set_servo_pulse(tilt_line, tilt_pos) < 0) break;
        }
        if (left_val == 0) {
            pan_pos += STEP_SIZE;
            if (pan_pos > 125) pan_pos = 125;
            if (pan_pos < 25) pan_pos = 25;
            if (set_servo_pulse(pan_line, pan_pos) < 0) break;
        } else if (right_val == 0) {
            pan_pos -= STEP_SIZE;
            if (pan_pos < 25) pan_pos = 25;
            if (pan_pos > 125) pan_pos = 125;
            if (set_servo_pulse(pan_line, pan_pos) < 0) break;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (up_line) gpiod_line_release(up_line);
    if (down_line) gpiod_line_release(down_line);
    if (left_line) gpiod_line_release(left_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

