#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define KERNEL_RADIUS 2
#define NUM_BUFFERS 4
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        goto fail;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto fail;
    }

    buf.length = fmt.fmt.pix.length;
    buf.flags = V4L2_BUF_FLAG_READ;

    if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto fail;
    }

    if (xioctl(*fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("VIDIOC_STREAMON");
        goto fail;
    }

    return 0;

fail:
    close(*fd);
    *fd = -1;
    return -1;
}

static int capture_frame(int fd, void **buffer) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    *buffer = mmap(NULL, fmt.fmt.pix.length, PROT_READ, MAP_SHARED, fd, buf.index);
    if (*buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    memcpy(buffer, *buffer, fmt.fmt.pix.length);
    *buffer = buffer;
    return 0;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int w, int h) {
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int y0 = yuyv[i * 2 + j * 2];
            int u = yuyv[i * 2 + (j * 2 + 1)];
            int y1 = yuyv[i * 2 + (j * 2 + 2)];
            int v = yuyv[i * 2 + (j * 2 + 3)];

            int c0 = (y0 + y1) / 2;
            int c1 = (u - 16, v - 128);
            int r = (c0 + c1) / 2;
            int g = (c0 - c1) / 2;
            int b = (c0 + c1) / 2;

            rgb[i * 3 + j * 3] = (unsigned char)(r + 128);
            rgb[i * 3 + j * 3 + 1] = (unsigned char)(g + 128);
            rgb[i * 3 + j * 3 + 2] = (unsigned char)(b + 128);
        }
    }
