    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int sum = 0;
            for (int k = -KERNEL_RADIUS; k <= KERNEL_RADIUS; k++) {
                for (int l = -KERNEL_RADIUS; l <= KERNEL_RADIUS; l++) {
                    int x = j + k;
                    int y = i + l;
                    if (x >= 0 && x < w && y >= 0 && y < h) {
                        sum += rgb[y * 3 + x * 3];
                    }
                }
            }
            blurred[i * w + j] = (unsigned char)(sum / (4 * (KERNEL_RADIUS + 1) * (KERNEL_RADIUS + 1)));
