#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_FRAMESIZES 32
#define MAX_FRAMEINTERVALS 32

static int enumerate_sizes(int fd, struct v4l2_frmsizeenum *sizes, int *num_sizes) {
    struct v4l2_frmsizeenum fs;
    int ret, i;

    for (i = 0; i < *num_sizes; i++) {
        ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs);
        if (ret < 0) {
            if (errno == EINVAL) return 0; /* end of enumeration */
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
            return -1;
        }
        sizes[i] = fs;
        i++;
    }
    *num_sizes = i;
    return 0;
}

static int enumerate_intervals(int fd, struct v4l2_frmivalenum *intervals, int *num_intervals) {
    struct v4l2_frmivalenum fi;
    int ret, i;

    for (i = 0; i < *num_intervals; i++) {
        ret = ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fi);
        if (ret < 0) {
            if (errno == EINVAL) return 0; /* end of enumeration */
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
            return -1;
        }
        intervals[i] = fi;
        i++;
    }
    *num_intervals = i;
    return 0;
}

static int is_autofocus_supported(int fd) {
    struct v4l2_queryctrlquery q;
    memset(&q, 0, sizeof(q));
    q.id = V4L2_CID_FOCUS_AUTO;
    q.type = V4L2_QUERYCTL_TUNE;
    q.value = 0;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &q) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCTRL (focus auto) failed: %s\n", strerror(errno));
        return -1;
    }
    return (q.flags & V4L2_QUERYCTL_FLAG_ACTIVE) != 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum sizes[MAX_FRAMESIZES];
    int num_sizes = 0;
    struct v4l2_frmivalenum intervals[MAX_FRAMEINTERVALS];
    int num_intervals = 0;
    int autofocus = -1;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Camera: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus Info: %s\n", cap.bus_info);

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Video Capture: %s\n", cap.capabilities & V4L2_CAP_VIDEO_CAPTURE);
    } else {
        printf("Video Capture: NOT SUPPORTED\n");
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Frame Sizes: ");
        if (enumerate_sizes(fd, sizes, &num_sizes) < 0) {
            close(fd);
            return 1;
        }
        for (int i = 0; i < num_sizes; i++) {
            printf("%d x %d\n", sizes[i].width, sizes[i].height);
        }
        printf("Frame Intervals: ");
        if (enumerate_intervals(fd, intervals, &num_intervals) < 0) {
            close(fd);
            return 1;
        }
        for (int i = 0; i < num_intervals; i++) {
            printf("%d/%d\n", intervals[i].denom, intervals[i].num);
        }
    } else {
        printf("Frame Sizes: NOT SUPPORTED\n");
        printf("Frame Intervals: NOT SUPPORTED\n");
    }

    if (is_autofocus_supported(fd) == 0) {
        printf("Autofocus: SUPPORTED\n");
        autofocus = 0;
    } else {
        printf("Autofocus: NOT SUPPORTED\n");
        autofocus = -1;
    }

    printf("Summary: %s\n", cap.card);
    printf("  Capture: %s\n", cap.capabilities & V4L2_CAP_VIDEO_CAPTURE ? "YES" : "NO");
    printf("  Frame Sizes: %d x %d, %d x %d, ... (list truncated)\n",
           sizes[0].width, sizes[0].height,
           sizes[1].width, sizes[1].height);
    printf("  Frame Intervals: %d/%d, %d/%d, ... (list truncated)\n",
           intervals[0].denom, intervals[0].num,
           intervals[1].denom, intervals[1].num);
    printf("  Autofocus: %s\n", autofocus ? "SUPPORTED" : "NOT SUPPORTED");

    close(fd);
    return 0;
}

