#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define CAPTURE_DIR "motion_captures"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define SERVER_IP "localhost"
#define SERVER_PORT 8080

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o '%s' --width %d --height %d --quality %d",
             filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing libcamera-still: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", WIFEXITED(result) ? WEXITSTATUS(result) : -1);
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion, int gpio_pin) {
    char json[512];
    int ret = snprintf(json, sizeof(json),
                       "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"gpio_pin\":%d}",
                       filename, timestamp, motion, gpio_pin);
    if (ret < 0 || (size_t)ret >= sizeof(json)) {
        fprintf(stderr, "JSON buffer too small\n");
        return -1;
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_IP ":" SERVER_PORT);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "HTTP request failed (code=%ld)\n", http_code);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Sending data to %s:%d\n",
           PIR_GPIO, server_ip, server_port);

    while (running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (motion) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];
            struct timespec ts;
            char filename[64];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (!timeinfo) {
                fprintf(stderr, "localtime() failed\n");
                gpioDelay(DEBOUNCE_SEC * 1000000);
                continue;
            }
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

            if (capture_image(filename) == 0) {
                char json[512];
                int ret = snprintf(json, sizeof(json),
                                   "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"gpio_pin\":%d}",
                                   filename, timestamp, motion, PIR_GPIO);
                if (ret < 0 || (size_t)ret >= sizeof(json)) {
                    fprintf(stderr, "JSON buffer too small\n");
                } else {
                    if (send_data(filename, timestamp, motion, PIR_GPIO) != 0) {
                        fprintf(stderr, "Failed to send data for %s\n", filename);
                    }
                }
            } else {
                fprintf(stderr, "Failed to capture image for %s\n", filename);
            }

            gpioDelay(DEBOUNCE_SEC * 1000000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
}

