#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN          17
#define GPIO_CHIP_NAME   "gpiochip0"
#define IMAGE_DIR        "/home/pi/images"
#define LOG_FILE         "/home/pi/motion_capture.log"
#define DEBOUNCE_MS      50
#define POLL_TIMEOUT_MS  1000
#define CAPTURE_TIMEOUT  2000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int capture_image(const char *filename)
{
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
                       filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "libcamera-still killed by signal %d\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "motion-capture") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on line %d: %s\n",
                PIR_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Motion detection started on BCM GPIO%d. Press Ctrl+C to exit.\n", PIR_PIN);

    while (program_running) {
        struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
        int ev = gpiod_line_event_wait(pir_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_wait error: %s\n", strerror(errno));
            break;
        }
        if (ev == 0) continue; /* timeout, no event */

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        /* Debounce: wait for a second falling edge or a timeout */
        struct timespec debounce = { 0, DEBOUNCE_MS * 1000000L };
        int waited = 0;
        while (program_running && waited < POLL_TIMEOUT_MS) {
            int r = gpiod_line_event_wait(pir_line, &debounce);
            if (r < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "Debounce wait error: %s\n", strerror(errno));
                break;
            }
            if (r == 0) break; /* timeout, not a second edge */
            waited += r;
        }

        if (!program_running) break;

        char filename[256];
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            char ts_str[32];
            strftime(ts_str, sizeof(ts_str), "%Y%m%d_%H%M%S", &tm);
            snprintf(filename, sizeof(filename), "%s/%s_%s.jpg", IMAGE_DIR, ts_str, tm.tm_mday < 10 ? "0" : "");
        } else {
            snprintf(filename, sizeof(filename), "%s/unknown_%s.jpg", IMAGE_DIR, "unknown");
        }

        printf("Motion detected on GPIO%d, capturing %s\n", PIR_PIN, filename);

        if (capture_image(filename) == 0) {
            log_event("Image captured and saved.");
        } else {
            log_event("Failed to capture image.");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    printf("Exiting.\n");
    return ret;
}

