#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_X 100
#define CROP_Y 50
#define OUTPUT_FILE "cropped.yuv"
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int xselect(int fd, fd_set *readfds, fd_set *writefds, fd_set *exceptfds,
                   struct timeval *timeout, int *errorfds) {
    int r;
    do {
        r = select(fd, readfds, writefds, exceptfds, timeout);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char *buffer, int width, int height) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    if (buf.index >= buf.n_buffers) {
        fprintf(stderr, "No buffer available\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    if (xioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    fd_set rfds;
    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    struct timeval tv = { .tv_sec = CAPTURE_TIMEOUT_SEC, .tv_usec = 0 };
    int ret = xselect(fd, &rfds, NULL, NULL, &tv, NULL);
    if (ret == -1) {
        perror("select()");
        return -1;
    }
    if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused < (unsigned long)width * height) {
        fprintf(stderr, "Short frame: %u bytes\n", buf.bytesused);
        return -1;
    }

    memcpy(buffer, buf.mapped, buf.bytesused);
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF (re-queue)");
        return -1;
    }

    return 0;
}

static int save_yuv(const unsigned char *data, int width, int height) {
    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("fopen(OUTPUT_FILE)");
        return -1;
    }
    size_t written = fwrite(data, 1, width * height * 2, fp);
    if (written != (size_t)(width * height * 2)) {
        fprintf(stderr, "Short write: %zu of %d\n", written, width * height * 2);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose(OUTPUT_FILE)");
        return -1;
    }
    return 0;
}

static int crop_yuyv(const unsigned char *src, int src_w, int src_h,
                      unsigned char *dst, int dst_w, int dst_h) {
    if (dst_w * dst_h * 2 > dst_w * src_h * 2) {
        fprintf(stderr, "Destination too large for source\n");
        return -1;
    }

    int src_x = CROP_X;
    int src_y = CROP_Y;
    int dst_x = 0;
    int dst_y = 0;

    for (int y = 0; y < dst_h; y++) {
        for (int x = 0; x < dst_w; x++) {
            int src_row = src_y + y;
            int src_col = src_x + x;

            if (src_row < 0 || src_row >= src_h || src_col < 0 || src_col >= src_w) {
                dst[dst_y * dst_w + dst_x] = 0;
                dst_x++;
                continue;
            }

            if (dst_w * dst_h * 2 > dst_w * src_h * 2) {
                dst[dst_y * dst_w + dst_x] = 0;
                dst_x++;
                continue;
            }

            /* YUYV: 2 bytes = Y0 U Y1 V */
            unsigned char y0 = src[src_row * src_w + src_col];
            unsigned char u = src[src_row * src_w + src_col + 1];
            unsigned char y1 = src[src_row * src_w + src_col + 2];
            unsigned char v = src[src_row * src_w + src_col + 3];

            /* Crop YUYV: keep Y0, U, Y1, V */
            dst[dst_y * dst_w + dst_x] = y0;
            dst[dst_y * dst_w + dst_x + 1] = u;
            dst[dst_y * dst_w + dst_x + 2] = y1;
            dst[dst_y * dst_w + dst_x + 3] = v;
            dst_x++;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Warning: driver negotiated %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    if (buf.index >= req.count) {
        fprintf(stderr, "No buffer available\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set rfds;
    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    struct timeval tv = { .tv_sec = 0, .tv_usec = 0 };
    int ret = xselect(fd, &rfds, NULL, NULL, &tv, NULL);
    if (ret == -1) {
        perror("select()");
        goto cleanup;
    }
    if (ret == 0) {
        fprintf(stderr, "No buffer available after select\n");
        goto cleanup;
    }

    unsigned char *frame = malloc((size_t)fmt.fmt.pix.sizeimage);
    if (!frame) {
        perror("malloc()");
        goto cleanup;
    }

    if (capture_frame(fd, frame, fmt.fmt.pix.width, fmt.fmt.pix.height) < 0) {
        fprintf(stderr, "Failed to capture frame\n");
        goto cleanup;
    }

    if (crop_yuyv(frame, fmt.fmt.pix.width, fmt.fmt.pix.height,
                  frame + (size_t)fmt.fmt.pix.sizeimage / 2,
                  CROP_WIDTH, CROP_HEIGHT) < 0) {
        fprintf(stderr, "Crop failed\n");
        goto cleanup;
    }

    if (save_yuv(frame, fmt.fmt.pix.width, fmt.fmt.pix.height) < 0) {
        fprintf(stderr, "Failed to save cropped frame\n");
        goto cleanup;
    }

    printf("Cropped frame saved as %s (%dx%d)\n", OUTPUT_FILE, CROP_WIDTH, CROP_HEIGHT);

cleanup:
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF (cleanup)");
    }
    if (xioctl(fd, VIDIOC_STREAMOFF, &buf) < 0) {
        perror("VIDIOC_STREAMOFF");
    }
    free(frame);
    close(fd);
    return (g_stop) ? EXIT_FAILURE : EXIT_SUCCESS;
}

