#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

int init_i2c(void) {
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X).\n", LCD_I2C_ADDR);
        return -1;
    }
    return 0;
}

void lcd_send_nibble(unsigned char nibble) {
    unsigned char data[4] = {0x00, 0x00, 0x00, 0x00};
    data[3] = nibble;
    i2cWriteDevice(i2c_handle, (char *)data, 4);
}

void lcd_send_byte(unsigned char val, int is_data) {
    unsigned char hi = (val & 0xF0) | 0x0C;
    unsigned char lo = ((val << 4) & 0xF0) | 0x0C;
    lcd_send_nibble(hi);
    lcd_send_nibble(lo);
}

void lcd_send_command(unsigned char cmd) {
    lcd_send_byte(cmd, 0);
}

void lcd_send_data(unsigned char data) {
    lcd_send_byte(data, 1);
}

void lcd_clear(void) {
    lcd_send_command(0x01);
    gpioDelay(2000);
}

void lcd_set_cursor(int col, int row) {
    unsigned char addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_command(0x80);
    lcd_send_nibble(addr);
}

void lcd_print(const char *str) {
    while (*str) {
        lcd_send_data((unsigned char)*str++);
    }
}

void lcd_print_number(int num) {
    char buf[4];
    buf[0] = num / 1000;
    buf[1] = (num / 100) % 10;
    buf[2] = (num / 10) % 10;
    buf[3] = num % 10;
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(buf);
}

void lcd_update(void) {
    gpioDelay(2000);
}

double calculate_flow_rate(int pulses, double elapsed_time) {
    return (pulses / PULSES_PER_LITER) * (elapsed_time / 3600.0);
}

void log_data(double flow_rate, double total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Flow Rate: %.2f L/min, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
}

void update_lcd(double flow_rate, double total_volume) {
    char timestamp[80];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Flow Rate: ");
    lcd_print_number(flow_rate);
    lcd_print(" L/min");
    lcd_print(" Total Volume: ");
    lcd_print_number(total_volume);
    lcd_update();
}

void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pulses = 0;
    double total_volume = 0.0;
    double last_time = 0.0;
    int lcd_update_count = 0;

    while (running) {
        int level = gpioRead(FLOW_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: Failed to read GPIO17.\n");
            gpioDelay(1000000);
            continue;
        }

        if (level == 1) {
            pulses++;
        }

        double current_time = time_time();
        double elapsed_time = current_time - last_time;
        last_time = current_time;

        double flow_rate = calculate_flow_rate(pulses, elapsed_time);
        total_volume += flow_rate;
        pulses = 0;

        log_data(flow_rate, total_volume);

        if (lcd_update_count < 10) {
            lcd_update_count++;
            update_lcd(flow_rate, total_volume);
        } else {
            lcd_update_count = 0;
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_print("Sensor Error");
            lcd_print("Check Connection");
            lcd_update();
        }

        gpioDelay(1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

