/*
 * Raspberry Pi 4 Model B — Anemometer + Wind Vane Logger
 *
 * Hardware:
 *   - Anemometer pulse output on GPIO17 (rising edge, 5 V tolerant)
 *   - MCP3008 10-bit ADC on SPI0 (CE0), channel 0 for wind vane
 *   - 16x2 LCD via PCF8574 I2C backpack at 0x27 on I2C bus 1
 *
 * Build:  gcc -O2 -Wall -o wind_logger wind_logger.c -lpigpio -lrt
 * Run:    sudo ./wind_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define ANEMOMETER_GPIO          17
#define I2C_BUS                 1
#define I2C_ADDR                 0x27
#define SPI_CHANNEL              0
#define SPI_SPEED                1000000          /* 1 MHz */
#define SPI_FLAGS                0                /* mode 0, CE0 */
#define LCD_WIDTH                16
#define LCD_LINE1               0
#define LCD_LINE2               1
#define SAMPLE_PERIOD_US        500000           /* 500 ms */
#define MAX_CONSECUTIVE_ERRORS   10

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static volatile bool         g_pulse_pending = false;
static int                   g_spi_handle = -1;
static int                   g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata);
static int  read_mcp3008(int channel, int *out_value);
static int  lcd_write_nibble(uint8_t nibble, uint8_t rs);
static int  lcd_send_command(uint8_t cmd);
static int  lcd_send_data(uint8_t data);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN);

    /* --- Interrupt on rising edge --- */
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO%d.\n", ANEMOMETER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- I2C setup (PCF8574 I2C backpack) --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- SPI setup (MCP3008) --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- LCD init via I2C --- */
    if (lcd_write_nibble(0x03, 0x00) != 0) {
        fprintf(stderr, "Error: LCD init failed (I2C).\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (lcd_send_command(0x28) != 0) {
        fprintf(stderr, "Error: LCD clear failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (lcd_send_command(0x0C) != 0) {
        fprintf(stderr, "Error: LCD home failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Anemometer & Wind Vane Logger running.\n");
    printf("Pulse on GPIO%d, MCP3008 ch0, LCD @ 0x%02X, SPI ch%d, %d Hz.\n",
           ANEMOMETER_GPIO, I2C_ADDR, SPI_CHANNEL, SPI_SPEED);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "Warning: MCP3008 read failed (sensor absent or bus error).\n");
        }

        /* --- Compute wind speed (pulses * 0.5 m/s) --- */
        double wind_speed = (double)pulses * 0.5;

        /* --- Compute wind direction (0-359 degrees) --- */
        int direction = (int)((adc / 1023.0) * 360.0);

        /* --- Display on LCD --- */
        char line1[LCD_WIDTH + 1];
        char line2[LCD_WIDTH + 1];

        if (wind_speed > 0.0) {
            snprintf(line1, sizeof(line1), "Wind Spd: %6.2f m/s", wind_speed);
            snprintf(line2, sizeof(line2), "Dir: %3d deg", direction);
        } else {
            snprintf(line1, sizeof(line1), "Wind Spd: 0.00 m/s");
            snprintf(line2, sizeof(line2), "Dir: ---");
        }

