}

/* ----------------------------- MCP3008 read ------------------------------- */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI handle invalid in read_mcp3008.\n");
        return -1;
    }

    /* MCP3008 single-ended read: 3 bytes — start bit, config, dummy */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
