{
    if (lcd_write_nibble(data & 0xF0, 1) != 0) return -1;
    if (lcd_write_nibble((data << 4) & 0xF0, 1) != 0) return -1;
    if (lcd_write_nibble((data << 8) & 0xF0, 1) != 0) return -1;
    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
