    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Anemometer & Wind Vane Logger running.\n");
    printf("Pulse on GPIO%d, MCP3008 ch0, LCD @ 0x%02X, SPI ch%d, %d Hz.\n",
           ANEMOMETER_GPIO, I2C_ADDR, SPI_CHANNEL, SPI_SPEED);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "Warning: MCP3008 read failed (sensor absent or bus error).\n");
        }

        /* --- Compute wind speed (pulses * 0.5 m/s) --- */
        double wind_speed = (double)pulses * 0.5;

        /* --- Compute wind direction (0-359 degrees) --- */
        int direction = (int)((adc / 1023.0) * 360.0);

        /* --- Display on LCD --- */
        char line1[LCD_WIDTH + 1];
        char line2[LCD_WIDTH + 1];

        if (wind_speed > 0.0) {
            snprintf(line1, sizeof(line1), "Wind Spd: %6.2f m/s", wind_speed);
            snprintf(line2, sizeof(line2), "Dir: %3d deg", direction);
        } else {
            snprintf(line1, sizeof(line1), "Wind Spd: 0.00 m/s");
            snprintf(line2, sizeof(line2), "Dir: ---");
        }

        if (lcd_send_command(0x01) != 0) {
            fprintf(stderr, "Warning: LCD clear failed.\n");
        }
        if (lcd_send_data((uint8_t)line1[LCD_WIDTH]) != 0) {
            fprintf(stderr, "Warning: LCD data1 failed.\n");
        }
        if (lcd_send_data((uint8_t)line2[LCD_WIDTH]) != 0) {
            fprintf(stderr, "Warning: LCD data2 failed.\n");
        }

        /* --- Print to console --- */
        printf("[%u] Wind Speed: %6.2f m/s | Direction: %3d deg | Pulses: %u\n",
               pulses, wind_speed, direction, pulses);

        /* --- Sleep 500 ms --- */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ----------------------------- Pulse callback ----------------------------- */
