#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

/* BCM GPIO numbers */
static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = { .tv_sec = 0, .tv_nsec = (long)us * 1000L };
    nanosleep(&ts, NULL);
}

static void clear_matrix(struct gpiod_line *row_lines, struct gpiod_line *col_lines) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_set_value(row_lines[i], 0);
        gpiod_line_set_value(col_lines[i], 1);
    }
}

static void display_row(struct gpiod_line *row_lines, struct gpiod_line *col_lines, int row, int val) {
    gpiod_line_set_value(row_lines[row], val);
    gpiod_line_set_value(col_lines[row], val);
}

static void display_pattern(struct gpiod_line *row_lines, struct gpiod_line *col_lines, int pattern) {
    for (int i = 0; i < NUM_ROWS; i++) {
        display_row(row_lines, col_lines, i, pattern[i]);
    }
}

static void wave_left_to_right(struct gpiod_line *row_lines, struct gpiod_line *col_lines) {
    for (int i = 0; i < NUM_ROWS; i++) {
        int val = (i % 2 == 0) ? 1 : 0;
        display_row(row_lines, col_lines, i, val);
    }
}

static void wave_right_to_left(struct gpiod_line *row_lines, struct gpiod_line *col_lines) {
    for (int i = 0; i < NUM_ROWS; i++) {
        int val = (i % 2 == 0) ? 0 : 1;
        display_row(row_lines, col_lines, i, val);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *row_lines[NUM_ROWS];
    struct gpiod_line *col_lines[NUM_COLS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = NULL;
        col_lines[i] = NULL;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Request row lines as outputs, initially low */
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            goto cleanup;
        }
    }

    /* Request column lines as outputs, initially high (off for common anode) */
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            goto cleanup;
        }
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Wave-like animation on 8x8 LED matrix. Press Ctrl+C to exit.\n");

    while (running) {
        /* Wave left-to-right */
        printf("Wave left-to-right...\n");
        wave_left_to_right(row_lines, col_lines);
        sleep_us(SCAN_DELAY_US);

        if (!running) break;

        /* Wave right-to-left */
        printf("Wave right-to-left...\n");
        wave_right_to_left(row_lines, col_lines);
        sleep_us(SCAN_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Turn off all LEDs and release lines */
    clear_matrix(row_lines, col_lines);
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) gpiod_line_release(row_lines[i]);
        if (col_lines[i]) gpiod_line_release(col_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);

    return ret;
}

