/*
 * VL53L3CX Time-of-Flight Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download sequence
 * (ST Ultra Lite Driver ULD) that is not publicly documented in the
 * pigpio API. This program stubs the firmware download with a
 * descriptive comment and focuses on the I2C communication layer.
 * For production, the ULD must be integrated or the sensor must be
 * configured via the ST ULD SDK.
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L3CX SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L3CX VDD -> 3.3V
 *   VL53L3CX GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29

/* VL53L3CX ULD register addresses (stubbed for pigpio compatibility) */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START      0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS    0x0089
#define VL53L3CX_REG_RESULT_DISTANCE       0x0096

#define EXPECTED_MODEL_ID 0xEA

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address, then read `len` bytes. */
static int i2c_write_reg_addr(uint16_t reg, uint8_t *buf, uint8_t len) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed for register 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed for register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then read `len` bytes. */
static int i2c_read_reg_addr(uint16_t reg, uint8_t *buf, uint8_t len) {
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error: I2C write failed for register 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed for register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l3cx_init(void) {
    uint8_t model_id = 0;
    if (i2c_read_reg_addr(VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L3CX detected (Model ID: 0x%02X)\n", model_id);

    /* Stubbed firmware download sequence (ULD) */
    uint8_t fw_download[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};
    if (i2c_write_reg_addr(0x0000, fw_download, sizeof(fw_download)) != 0) {
        fprintf(stderr, "Error: Firmware download failed\n");
        return -1;
    }

    /* Start ranging in continuous mode */
    uint8_t start_cmd[] = {0x01, 0x00};
    if (i2c_write_reg_addr(VL53L3CX_REG_SYSTEM_MODE_START, start_cmd, sizeof(start_cmd)) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int vl53l3cx_read_distance(uint16_t *dist) {
    uint8_t status = 0;
    if (i2c_read_reg_addr(VL53L3CX_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* No new data */
    }
    if (i2c_read_reg_addr(VL53L3CX_REG_RESULT_DISTANCE, (uint8_t *)dist, 2) != 0) {
        return -1;
    }
    return 0;
}

static void log_data(uint16_t distances[], int num_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Distances: ", timestamp);
    for (int i = 0; i < num_targets; i++) {
        printf("%u mm ", distances[i]);
        if (i < num_targets - 1) printf(", ");
    }
    printf("\n");
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, VL53L3CX_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l3cx_init() != 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t distances[4];
    int num_targets = 0;

    while (!terminate) {
        int ret = vl53l3cx_read_distance(distances);
        if (ret == 0) {
            num_targets = (ret > 0) ? ret : 0;
            log_data(distances, num_targets);
        } else if (ret < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2c_write_reg_addr(VL53L3CX_REG_SYSTEM_MODE_START, NULL, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

