#define SI1145_REG_IRQ_MODE3 0x12
#define SI1145_REG_IRQ_MODE4 0x13
#define SI1145_REG_IRQ_MODE5 0x14
#define SI1145_REG_IRQ_MODE6 0x15
#define SI1145_REG_IRQ_MODE7 0x16
#define SI1145_REG_IRQ_STATUS 0x21
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_VIS_DATA2 0x24
#define SI1145_REG_ALS_IR_DATA0 0x25
#define SI1145_REG_ALS_IR_DATA1 0x26
#define SI1145_REG_ALS_IR_DATA2 0x27
#define SI1145_REG_ALS_VIS_DATA3 0x28
#define SI1145_REG_ALS_VIS_DATA4 0x29
#define SI1145_REG_ALS_VIS_DATA5 0x2A
#define SI1145_REG_ALS_IR_DATA3 0x2B
#define SI1145_REG_ALS_IR_DATA4 0x2C
#define SI1145_REG_ALS_IR_DATA5 0x2D
#define SI1145_REG_COMMAND 0x18

#define SI1145_PART_ID      0x45
#define SI1145_HW_KEY_VAL   0x17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (read_reg(SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X).\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_ENABLE, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE1, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE2, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE3, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE4, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE5, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE6, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE7, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, 0x01) != 0) return -1;

    return 0;
}

static int read_si1145_data(int *prox, int *light) {
    uint8_t vis_lsb = 0, vis_msb = 0, vis_h = 0, ir_lsb = 0, ir_msb = 0, ir_h = 0;
    uint8_t vis3_lsb = 0, vis3_msb = 0, vis3_h = 0, ir3_lsb = 0, ir3_msb = 0, ir3_h = 0;

    if (read_reg(SI1145_REG_ALS_VIS_DATA0, &vis_lsb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA1, &vis_msb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA2, &vis_h) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_IR_DATA0, &ir_lsb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_IR_DATA1, &ir_msb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_IR_DATA2, &ir_h) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA3, &vis3_lsb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA4, &vis3_msb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_VIS_DATA5, &vis3_h) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_IR_DATA3, &ir3_lsb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_IR_DATA4, &ir3_msb) != 0) return -1;
    if (read_reg(SI1145_REG_ALS_IR_DATA5, &ir3_h) != 0) return -1;

    *light = ((uint16_t)vis_h << 8) | (uint16_t)vis_msb | vis_lsb;
    *light &= 0x3FFF;

    *prox = ((uint16_t)ir_h << 8) | (uint16_t)ir_msb | ir_lsb;
    *prox &= 0x3FFF;

    return 0;
}

static void log_data(int prox, int light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, prox, light);
    fflush(g_log_file);
}

static void cleanup(void) {
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen("biometric_log.txt", "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int prox, light;
        if (read_si1145_data(&prox, &light) == 0) {
            log_data(prox, light);
            printf("Proximity: %d, Ambient Light: %d\n", prox, light);
        } else {
            fprintf(stderr, "Read failed, continuing...\n");
        }
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

