#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  4
#define LED_PIN     17
#define LOG_FILE    "proximity.log"
#define POLL_MS     100
#define BLINK_MS    100

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s Object detected\n", ts);
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor = NULL;
    struct gpiod_line *led = NULL;
    int prev_val = 1;  /* assume no object at startup (HIGH) */
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip on Raspberry Pi 5 (gpiochip4) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(gpiochip4): %s\n", strerror(errno));
        /* Fallback: try gpiochip0 (RPi 4 default) */
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "gpiod_chip_open_by_name(gpiochip0): %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor, "e18-d50nk") < 0) {
        fprintf(stderr, "gpiod_line_request_input(sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "e18-d50nk", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(led): %s\n", strerror(errno));
        goto cleanup;
    }

