#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_CFG 0x08
#define SI1145_REG_CH_LIST 0x4F
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x18

#define SI1145_PART_ID     0x45
#define SI1145_HW_KEY_VAL  0x17

#define LOG_FILE "biometric_data.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int si1145_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_read_word(int handle, uint8_t reg, uint16_t *value) {
    uint8_t lo, hi;
    if (si1145_read_reg(handle, reg, &lo) != 0) return -1;
    if (si1145_read_reg(handle, reg + 1, &hi) != 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1145_init(int handle) {
    uint8_t part_id;
    if (si1145_read_reg(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0) return -1;

    if (si1145_write_reg(handle, SI1145_REG_MEAS_CFG, 0x00) != 0) return -1;

    if (si1145_write_reg(handle, SI1145_REG_CH_LIST, 0x07) != 0) return -1;

    return 0;
}

static int si1145_trigger_and_read(int handle, uint16_t *prox, uint16_t *ambient) {
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, 0x06) != 0) return -1;
    gpioDelay(2000);

    if (si1145_write_reg(handle, SI1145_REG_COMMAND, 0x07) != 0) return -1;
    gpioDelay(2000);

    if (si1145_read_word(handle, SI1145_REG_PS1_DATA0, prox) != 0) return -1;
    if (si1145_read_word(handle, SI1145_REG_ALS_VIS_DATA0, ambient) != 0) return -1;

    return 0;
}

static void log_data(FILE *fp, uint16_t prox, uint16_t ambient) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u,%u\n", timestamp, prox, ambient);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        uint16_t prox, ambient;
        if (si1145_trigger_and_read(g_i2c_handle, &prox, &ambient) == 0) {
            log_data(g_log_file, prox, ambient);
        } else {
            fprintf(stderr, "Sensor read error - continuing\n");
        }
        sleep(1);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_file) fclose(g_log_file);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

