/*
 * Plant Watering Reminder using HC-SR04 Ultrasonic Sensor
 * Board: Raspberry Pi Zero W
 * Library: libgpiod (modern GPIO API)
 *
 * Wiring:
 *   HC-SR04 TRIGGER -> GPIO 17 (BCM, output)
 *   HC-SR04 ECHO    -> GPIO 27 (BCM, input, via 1k/2k voltage divider for 5V->3.3V)
 *   HC-SR04 VCC     -> 5V (external supply recommended)
 *   HC-SR04 GND     -> GND
 *
 * Build: gcc -O2 -Wall -o plant_water plant_water.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define LOG_FILE         "distance_log.txt"
#define POLL_INTERVAL_S  60
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define ECHO_RISE_TIMEOUT_US 100000
#define SPEED_OF_SOUND_CM_PER_S 34300.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_message(FILE *log_fp, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (log_fp)
        fprintf(log_fp, "%s %s\n", ts, msg);
    else
        fprintf(stderr, "%s %s\n", ts, msg);
}

static void log_distance(FILE *log_fp, float distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM)
        fprintf(log_fp, "%s Distance out of range: %.2f cm\n", ts, distance_cm);
    else
        fprintf(log_fp, "%s Distance: %.2f cm\n", ts, distance_cm);
}

static void log_error(FILE *log_fp, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (log_fp)
        fprintf(log_fp, "%s ERROR: %s\n", ts, msg);
    else
        fprintf(stderr, "%s ERROR: %s\n", ts, msg);
}

/*
 * Measure distance using libgpiod edge events.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo)
{
    struct timespec start, end;
    long elapsed_us;
    int ret;

    /* Ensure trigger is low */
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        log_error(NULL, "Failed to set trigger low");
        return -1.0f;
    }
    usleep(5);

    /* Send 10 us trigger pulse */
    ret = gpiod_line_set_value(trigger, 1);
    if (ret < 0) {
        log_error(NULL, "Failed to set trigger high");
        return -1.0f;
    }
    usleep(TRIGGER_PULSE_US);
    ret = gpiod_line_set_value(trigger, 0);
    if (ret < 0) {
        log_error(NULL, "Failed to set trigger low");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout 100 ms) */
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (program_running) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            log_error(NULL, "Failed to read echo pin");
            return -1.0f;
        }
        if (ret == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                     (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > ECHO_RISE_TIMEOUT_US) {
            log_error(NULL, "Echo rising edge timeout");
            return -1.0f;
        }
    }

    /* Wait for echo falling edge (timeout 30 ms) */
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (program_running) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            log_error(NULL, "Failed to read echo pin");
            return -1.0f;
        }
        if (ret == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                     (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            log_error(NULL, "Echo falling edge timeout");
            return -1.0f;
        }
    }

    /* Calculate pulse duration in seconds */
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (program_running) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            log_error(NULL, "Failed to read echo pin");
            return -1.0f;
        }
        if (ret == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000L +
                     (end.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            log_error(NULL, "Echo falling edge timeout");
            return -1.0f;
        }
    }

    float pulse_s = (float)elapsed_us / 1000000.0f;

    /* distance = (pulse * speed) / 2 */
    float distance = (pulse_s * SPEED_OF_SOUND_CM_PER_S) / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        log_error(NULL, "Distance out of valid range");
        return -1.0f;
    }

    return distance;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
