#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_ADDR 0x39
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_PROX 0x9C
#define APDS9960_RED_L 0x96
#define APDS9960_GREEN_L 0x98
#define APDS9960_BLUE_L 0x9A
#define APDS9960_ID_VALUE 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define I2C_BUS 1
#define SAMPLE_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
    }
    return value;
}

static int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
    }
    return result;
}

static int initialize_sensor(int handle) {
    int id = i2c_read_register(handle, APDS9960_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }
    if (id != APDS9960_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x%02X)\n", id, APDS9960_ID_VALUE);
        return -1;
    }

    if (i2c_write_register(handle, APDS9960_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_register(handle, APDS9960_ATIME, 0xDB) < 0) return -1;
    if (i2c_write_register(handle, APDS9960_WTIME, 0xF6) < 0) return -1;
    if (i2c_write_register(handle, APDS9960_PPULSE, 0x87) < 0) return -1;
    if (i2c_write_register(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_register(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_proximity(int handle) {
    int prox = i2c_read_register(handle, APDS9960_PROX);
    if (prox < 0) {
        fprintf(stderr, "Error reading proximity: %d\n", prox);
        return -1;
    }
    return prox;
}

static int read_color(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int r = i2c_read_register(handle, APDS9960_RED_L);
    int g = i2c_read_register(handle, APDS9960_GREEN_L);
    int b = i2c_read_register(handle, APDS9960_BLUE_L);
    if (r < 0 || g < 0 || b < 0) {
        fprintf(stderr, "Error reading color channels\n");
        return -1;
    }
    *red = (uint16_t)r;
    *green = (uint16_t)g;
    *blue = (uint16_t)b;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%d\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    int proximity;

    while (!terminate) {
        proximity = read_proximity(i2c_handle);
        if (proximity < 0) {
            fprintf(stderr, "Proximity read error, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1;
                continue;
            }
            if (initialize_sensor(i2c_handle) < 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                terminate = 1;
                continue;
            }
            continue;
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            if (read_color(i2c_handle, &red, &green, &blue) == 0) {
                log_data(red, green, blue, proximity);
            } else {
                fprintf(stderr, "Error reading color data\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

