#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A
#define CSV_FILE       "heartrate.csv"

#define REG_PART_ID     0x00
#define REG_MEAS_RATE0 0x08
#define REG_PS_DATA0   0x24
#define REG_PS_DATA1   0x25
#define REG_COMMAND    0x47

#define CMD_RESET       0x01
#define CMD_START       0x11

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    union i2c_smbus_data data;
    data.byte = val;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_WRITE,
        .command = reg,
        .size = I2C_SMBUS_BYTE_DATA,
        .data = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out) {
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_READ,
        .command = reg,
        .size = I2C_SMBUS_BYTE_DATA,
        .data = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_read_byte(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = data.byte;
    return 0;
}

static int si1182_init(int fd) {
    uint8_t part_id = 0;
    if (i2c_read_byte(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    if (i2c_write_byte(fd, REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Failed to set MEAS_RATE0.\n");
        return -1;
    }

    if (i2c_write_byte(fd, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Failed to reset sensor.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_write_byte(fd, REG_COMMAND, CMD_START) < 0) {
        fprintf(stderr, "Failed to start measurement.\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_byte(fd, REG_PS_DATA0, &lo) < 0) return -1;
    if (i2c_read_byte(fd, REG_PS_DATA1, &hi) < 0) return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int calculate_bpm(uint16_t prox) {
    /* Placeholder: proximity signal is a proxy for light reflection rate.
     * A higher value indicates a higher heart rate. */
    int bpm = (int)((prox * 100) / 65535);
    if (bpm > 200) bpm = 200;
    if (bpm < 40)  bpm = 40;
    return bpm;
}

static void log_data(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d\n", ts, bpm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging heart rate to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (g_running) {
        uint16_t prox = 0;
        if (read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample.\n");
        } else {
            int bpm = calculate_bpm(prox);
            log_data(g_csv, bpm);
        }
        usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

