#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define TRIGGER_PIN 17
#define LOG_FILE "distance_log.txt"

#define REG_SYSRANGE_START 0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

#define EXPECTED_INT_STATUS 0x01
#define MAX_RANGE_TIMEOUT_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    }
    *value = (uint8_t)rc;
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): got %d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t id;
    if (i2c_read_byte(handle, 0x00, &id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }
    if (id != 0xEA) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0xEA)\n", id);
        return -1;
    }

    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status;
    uint8_t buf[14];

    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0) return -1;
    gpioDelay(1000);

    for (int i = 0; i < MAX_RANGE_TIMEOUT_MS; i++) {
        if (i2c_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) return -1;
        if (status & EXPECTED_INT_STATUS) break;
        gpioDelay(1000);
    }

    if (!(status & EXPECTED_INT_STATUS)) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, buf, 14) < 0) return -1;

    *distance_mm = (buf[10] << 8) | buf[11];
    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L0X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L0X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(TRIGGER_PIN) == 0) {
            gpioDelay(1000);
            if (gpioRead(TRIGGER_PIN) == 0) {
                uint16_t distance_mm;
                if (vl53l0x_read_distance(i2c_handle, &distance_mm) == 0) {
                    log_distance(log_file, distance_mm);
                } else {
                    fprintf(stderr, "Measurement failed\n");
                }
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

