#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

/* ICU-20201 Register Map */
#define REG_WHO_AM_I 0x00
#define REG_DISTANCE 0x40
#define REG_CONFIG 0x41
#define REG_INT_CFG 0x42
#define REG_INT_EN 0x43
#define REG_INT_STATUS 0x44

#define WHO_AM_I_EXPECTED 0x01

static int i2c_handle = -1;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t lo, hi;
    if (read_register(handle, REG_DISTANCE, &lo) < 0) return -1;
    if (read_register(handle, REG_DISTANCE + 1, &hi) < 0) return -1;
    *distance = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int configure_sensor(int handle) {
    uint8_t who_am_i;
    if (read_register(handle, REG_WHO_AM_I, &who_am_i) < 0) return -1;
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_EXPECTED, who_am_i);
        return -1;
    }
    if (write_register(handle, REG_CONFIG, 0x00) < 0) return -1;
    if (write_register(handle, REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(handle, REG_INT_EN, 0x01) < 0) return -1;
    return 0;
}

static void log_data(uint16_t distance, int threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, Threshold: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance, threshold);
    fclose(fp);
}

static void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ICU20201_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor configuration failed. Check wiring and sensor presence.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurements. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    while (running) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error reading distance. Retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_data(distance, threshold);
        control_led(LED_GPIO, (distance < threshold) ? 1 : 0);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

