#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x50
#define NUM_SAMPLES    10
#define DISTANCE_THRESHOLD_MM 1000
#define LOG_FILE       "intrusion_log.txt"
#define MEAS_DELAY_MS  10
#define CYCLE_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_sensor_distance(int fd, int *distance_out) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t data[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_data(fd, data, sizeof(data)) < 0)
        return -1;

    if (data[0] != 0x50) {
        fprintf(stderr, "Sensor not responding (header mismatch: 0x%02X)\n", data[0]);
        return -1;
    }

    uint16_t raw = ((uint16_t)data[11] << 8) | data[12];
    *distance_out = (int)raw;
    return 0;
}

static void log_intrusion(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Intrusion detected! Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int total = 0;
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int dist;
            if (read_sensor_distance(g_i2c_fd, &dist) == 0) {
                total += dist;
                valid++;
            } else {
                fprintf(stderr, "Read failed at sample %d\n", i);
            }
            usleep(CYCLE_DELAY_MS * 1000);
        }

        if (valid == 0) {
            fprintf(stderr, "No valid samples in this cycle.\n");
        } else {
            int avg = (valid > 0) ? (total / valid) : 0;
            if (avg < DISTANCE_THRESHOLD_MM) {
                log_intrusion(g_log_fp, avg);
                printf("Intrusion detected! Average distance: %d mm\n", avg);
            }
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

