                printf("Intrusion detected! Average distance: %d mm\n", avg);
            }
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

