/*
 * VL53L0X Time-of-Flight distance reader for Raspberry Pi 3 Model B+
 * Uses pigpio (modern API, no wiringPi).
 *
 * Wiring:
 *   VL53L0X SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   VL53L0X SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   VL53L0X VDD  -> 3.3 V
 *   VL53L0X GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o vl53l0x_reader vl53l0x_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l0x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- VL53L0X constants (from datasheet) ---- */
#define VL53L0X_ADDR          0x29
#define I2C_BUS               1

#define REG_SYSRANGE_START    0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define REG_MODEL_ID           0xC0

#define EXPECTED_MODEL_ID      0xEE

#define POLL_TIMEOUT_MS        100
#define LOOP_DELAY_MS          500

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address.                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l0x_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit register address.                        */
/* Returns 0 on success and stores result in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers.     */
/* Returns 0 on success and stores value in *out; -1 on error.           */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;

    if (vl53l0x_read_reg(handle, reg, &lo) != 0)
        return -1;

    if (vl53l0x_read_reg(handle, reg + 1, &hi) != 0)
        return -1;

    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L0X: verify model ID and clear any latched       */
/* interrupt.                                                        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    if (vl53l0x_read_reg(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "Unexpected model ID: 0x%02X (expected 0x%02X). "
                "Wrong sensor or wrong address.\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);

    /* Clear any latched interrupt so subsequent polls are reliable. */
    if (vl53l0x_write_reg(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Failed to clear interrupt latch.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Perform one single-shot ranging measurement.                        */
/* Returns 0 on success and stores distance in mm in *distance; -1 on   */
/* error.                                                              */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_distance(int handle, uint16_t *distance)
{
    /* Start a single-shot ranging measurement. */
    if (vl53l0x_write_reg(handle, REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        return -1;
    }

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until data ready. */
    uint8_t status = 0;
    int elapsed = 0;
    const int poll_step = 5;  /* 5 ms */

    do {
        if (vl53l0x_read_reg(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;

        if (status & 0x01)
            break;

        gpioDelay(poll_step * 1000);  /* microseconds */
        elapsed += poll_step;
    } while (elapsed < POLL_TIMEOUT_MS);

    if (!(status & 0x01)) {
        fprintf(stderr, "Ranging timeout (no data within %d ms).\n",
                POLL_TIMEOUT_MS);
        return -1;
    }

    /* Read 16-bit distance from RESULT_RANGE_STATUS. */
    uint16_t raw = 0;
    if (vl53l0x_read_reg16(handle, REG_RESULT_RANGE_STATUS, &raw) != 0) {
        fprintf(stderr, "Failed to read distance register.\n");
        return -1;
    }

    /* Clear the interrupt so the next measurement can signal. */
    if (vl53l0x_write_reg(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt after read.\n");
    }

    *distance = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    localtime_r(&now, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s ", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l0x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialisation failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting VL53L0X distance readings (Ctrl+C to stop)...\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance = 0;

        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read error; continuing.\n");
        }

        gpioDelay(LOOP_DELAY_MS * 1000);  /* microseconds */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

