static int si1182_data_ready(int handle)
{
    int irq = si1182_read_reg(handle, SI1182_REG_IRQ);
    if (irq < 0)
        return -1;
    return (irq & SI1182_IRQ_PROX_DATA_READY) ? 1 : 0;
}

static int si1182_read_proximity(int handle, uint16_t *prox)
{
    int lsb = si1182_read_reg(handle, SI1182_REG_DATA);
    if (lsb < 0)
        return -1;

    int msb = si1182_read_reg(handle, SI1182_REG_DATA_MSB);
    if (msb < 0)
        return -1;

    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n",
                SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: try a dummy read to confirm sensor is present */
    int dummy = i2cReadByteData(g_i2c_handle, SI1182_REG_IRQ);
    if (dummy < 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X (NACK or bus error)\n",
                SI1182_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Si1182 proximity sensor reading started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int ready = si1182_data_ready(g_i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Error checking data-ready status\n");
            break;
        }
        if (ready) {
            uint16_t prox;
            if (si1182_read_proximity(g_i2c_handle, &prox) == 0) {
                printf("Proximity: %u\n", prox);
            } else {
                fprintf(stderr, "Error reading proximity data\n");
                break;
            }
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

