#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DIST_REG       0x00
#define DIST_FACTOR    0.125f   /* mm per count */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg16_be(int fd, uint8_t reg, uint16_t *out)
{
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr  = MLX75030_ADDR;
    msgs[0].flags = 0;            /* write */
    msgs[0].len   = 1;
    msgs[0].buf   = &reg;

    msgs[1].addr  = MLX75030_ADDR;
    msgs[1].flags = I2C_M_RD;     /* read */
    msgs[1].len   = 2;
    msgs[1].buf   = NULL;         /* no data payload */

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "ioctl(I2C_RDWR): %s\n", strerror(errno));
        return -1;
    }

    *out = (uint16_t)msgs[1].buf[0] | ((uint16_t)msgs[1].buf[1] << 8);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signals() != 0)
        goto out;

    fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        goto out;

    /* Quick presence check: read the distance register. */
    uint16_t raw;
    if (i2c_read_reg16_be(fd, DIST_REG, &raw) != 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        goto out;
    }

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16_be(fd, DIST_REG, &raw) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            /* Retry next cycle; do not exit. */
            continue;
        }

        float distance_mm = (float)raw * DIST_FACTOR;
        printf("Distance: %.2f mm\n", distance_mm);
        fflush(stdout);

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

out:
    if (fd >= 0)
        close(fd);
    return rc;
}

