/*
 * OPT3101 Time-of-Flight Distance Sensor Reader
 * Board: Raspberry Pi Zero W
 * Library: pigpio (I2C)
 * Bus: I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * Address: 0x44
 *
 * Reads channel 0 distance, ambient light, and error flags every 500 ms.
 * Logs to console and exits cleanly on SIGINT.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_I2C_ADDR 0x44
#define I2C_BUS 1

/* OPT3101 register addresses (16-bit, big-endian on the bus) */
#define REG_RESULT_DIST     0x00
#define REG_RESULT_AMBIENT  0x02
#define REG_RESULT_ERROR    0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then read `len` bytes back       */
/* ------------------------------------------------------------------ */
static int read_i2c_block(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register value                            */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (read_i2c_block(handle, reg, buf, 2) != 0) {
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read OPT3101 channel 0 distance, ambient light, and error flags   */
/* ------------------------------------------------------------------ */
static int read_opt3101_data(int handle, uint16_t *distance,
                             uint16_t *ambient_light,
                             uint16_t *error_flags)
{
    if (read_reg16(handle, REG_RESULT_DIST, distance) != 0) {
        return -1;
    }
    if (read_reg16(handle, REG_RESULT_AMBIENT, ambient_light) != 0) {
        return -1;
    }
    if (read_reg16(handle, REG_RESULT_ERROR, error_flags) != 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to the console                                              */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t distance, uint16_t ambient_light,
                     uint16_t error_flags)
{
    printf("Distance: %u mm, Ambient Light: %u, Error Flags: 0x%04X\n",
           distance, ambient_light, error_flags);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the OPT3101 address */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3101_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X "
                        "(pigpio error %d).\n", OPT3101_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("OPT3101 distance sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main acquisition loop */
    while (g_running) {
        uint16_t distance = 0, ambient_light = 0, error_flags = 0;

        if (read_opt3101_data(g_i2c_handle, &distance, &ambient_light, &error_flags) == 0) {
            log_data(distance, ambient_light, error_flags);
        } else {
            fprintf(stderr, "Error: Failed to read OPT3101 data.\n");
            /* Brief pause before retrying to avoid log flooding */
            gpioDelay(100000); /* 100 ms */
        }

        /* Sleep 500 ms (pigpio delay is microseconds) */
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

