/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained; NOT wiringPi)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm series resistor (5V->3.3V level shift)
 *   HC-SR04 VCC  -> 5V (NOT 3.3V; HC-SR04 module is 5V tolerant)
 *   HC-SR04 GND  -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms echo timeout (max range) */
#define LOOP_DELAY_US    1000000     /* 1 second between readings      */

/* HC-SR04 operating limits */
#define MIN_PULSE_US     0
#define MAX_PULSE_US     38000       /* ~38 ms round-trip at 2 m range */
#define MAX_DISTANCE_CM  400.0       /* HC-SR04 rated max range      */

/* ------------------------------------------------------------------ */
/* Shared state between signal handler and main loop                   */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_start_tick = 0;
static volatile uint32_t     g_end_tick   = 0;
static volatile bool        g_echo_rising = false;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04: 10 us HIGH pulse on TRIG                      */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIG HIGH\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG LOW\n");
        return;
    }
}

/* ------------------------------------------------------------------ */
/* Wait for ECHO rising edge with timeout                             */
/* ------------------------------------------------------------------ */
static bool wait_rising(void)
{
    uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (g_running) {
        if (gpioRead(ECHO_PIN) == 1) {
            g_echo_rising = true;
            return true;
        }
        if (gpioTick() >= deadline) {
            return false;                 /* timeout */
        }
        gpioDelay(100);                  /* 100 us poll interval */
    }
    return false;                        /* interrupted by signal */
}

/* ------------------------------------------------------------------ */
/* Wait for ECHO falling edge with timeout                             */
/* ------------------------------------------------------------------ */
static bool wait_falling(void)
{
    uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (g_running) {
        if (gpioRead(ECHO_PIN) == 0) {
            g_end_tick = gpioTick();
            return true;
        }
        if (gpioTick() >= deadline) {
            return false;                 /* timeout */
        }
        gpioDelay(100);
    }
    return false;                        /* interrupted by signal */
}

/* ------------------------------------------------------------------ */
/* Compute distance in cm from pulse width (microseconds)              */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t pulse_us)
{
    if (pulse_us <= 0) {
        return -1.0;                       /* invalid reading */
    }
    return (double)pulse_us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped distance reading to the console                    */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
