#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define RANGE_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define MAGIC_WORD_SIZE 8
#define RAW_DATA_SIZE (MAGIC_WORD_SIZE + NUM_RANGE_BINS * 2)
#define LOG_FILE "intrusion_log.csv"

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_frame(int fd, uint8_t *buf, size_t buf_size) {
    size_t total_read = 0;
    while (total_read < buf_size && running) {
        ssize_t n = read(fd, buf + total_read, buf_size - total_read);
        if (n < 0) {
            if (running) perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }
        total_read += n;
    }
    return total_read;
}

static int parse_range_profile(const uint8_t *buf, float *range_profile) {
    if (buf[0] != 0x02 || buf[1] != 0x01 ||
        buf[2] != 0x04 || buf[3] != 0x03 ||
        buf[4] != 0x06 || buf[5] != 0x05 ||
        buf[6] != 0x08 || buf[7] != 0x07) {
        fprintf(stderr, "Invalid magic word: 0x%02X%02X%02X%02X%02X%02X%02X%02X\n",
                buf[0], buf[1], buf[2], buf[3], buf[4], buf[5], buf[6], buf[7]);
        return -1;
    }

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        uint16_t raw = (uint16_t)((buf[MAGIC_WORD_SIZE + i * 2] << 8) | buf[MAGIC_WORD_SIZE + i * 2 + 1]);
        range_profile[i] = (float)raw * RANGE_RESOLUTION;
    }
    return 0;
}

static void log_intrusion(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s,%.3f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(2000000);
    gpioWrite(gpio_pin, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance (m)\n");
    }

    uint8_t frame_buf[RAW_DATA_SIZE];
    float range_profile[NUM_RANGE_BINS];

    while (running) {
        int bytes_read = read_uart_frame(uart_fd, frame_buf, sizeof(frame_buf));
        if (bytes_read < 0) {
            break;
        }
        if (bytes_read == 0) {
            continue;
        }

        if (parse_range_profile(frame_buf, range_profile) == 0) {
            for (int i = 0; i < NUM_RANGE_BINS; i++) {
                if (range_profile[i] > RANGE_THRESHOLD) {
                    log_intrusion(range_profile[i]);
                    trigger_alert(GPIO_LED);
                    break;
                }
            }
        }
    }

    if (uart_fd >= 0) close(uart_fd);
    if (log_file) fclose(log_file);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();

    return 0;
}

