#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DISTANCE_REG_H 0x31
#define DISTANCE_REG_L 0x32
#define ALERT_GPIO     17
#define DISTANCE_THRESHOLD 10.0f
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance)
{
    int hi = i2cReadByteData(g_i2c_handle, DISTANCE_REG_H);
    if (hi < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", DISTANCE_REG_H, hi);
        return -1;
    }

    int lo = i2cReadByteData(g_i2c_handle, DISTANCE_REG_L);
    if (lo < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", DISTANCE_REG_L, lo);
        return -1;
    }

    uint16_t raw = ((uint16_t)hi << 8) | (uint16_t)lo;
    *distance = (float)raw / 10.0f;
    return 0;
}

static void log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    fclose(fp);
}

static void trigger_alert(float distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        printf("Alert triggered! Distance: %.2f cm\n", distance);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe sensor presence by reading the high byte of the distance register */
    int probe = i2cReadByteData(g_i2c_handle, DISTANCE_REG_H);
    if (probe < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X on bus %d\n",
                I2C_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting distance monitoring (threshold %.1f cm)...\n",
           (double)DISTANCE_THRESHOLD);

    while (g_running) {
        float distance;

        if (read_distance(&distance) == 0) {
            log_distance(distance);
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Read failed; continuing...\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

