#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define LOG_FILE       "distance_log.csv"

#define REG_MODEL_ID            0x010F
#define REG_SOFT_RESET          0x0000
#define REG_SYSTEM_MODE_START   0x007
#define REG_SYSRANGE_START      0x000
#define REG_RESULT_INT_STATUS   0x013
#define REG_RESULT_RANGE_STATUS 0x078
#define REG_SYSTEM_INT_CLEAR    0x014

#define EXPECTED_MODEL_ID       0xEA
#define SOFT_RESET_VALUE       0x00
#define MODE_START_CONTINUOUS  0x01
#define RANGE_READY_TIMEOUT_MS 100
#define POLL_DELAY_US           100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) return -1;
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_reg16_be(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    if (i2c_write_reg8(handle, REG_SOFT_RESET, SOFT_RESET_VALUE) < 0) {
        fprintf(stderr, "Error: failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(2000);

    if (i2c_write_reg8(handle, REG_SYSTEM_MODE_START, MODE_START_CONTINUOUS) < 0) {
        fprintf(stderr, "Error: failed to start continuous ranging.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_wait_ready(int handle) {
    uint8_t status = 0;
    int elapsed = 0;
    while (elapsed < RANGE_READY_TIMEOUT_MS) {
        if (i2c_read_reg8(handle, REG_RESULT_INT_STATUS, &status) < 0) {
            fprintf(stderr, "Error: failed to read interrupt status.\n");
            return -1;
        }
        if (status & 0x01) return 0;
        gpioDelay(POLL_DELAY_US);
        elapsed += 1000;
    }
    fprintf(stderr, "Warning: VL53L1X range-ready timeout.\n");
    return -1;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_read_reg16_be(handle, REG_RESULT_RANGE_STATUS, distance_mm) < 0) {
        fprintf(stderr, "Error: failed to read distance register.\n");
        return -1;
    }
    return 0;
}

static int log_distance(FILE *fp, uint16_t distance_mm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static const char *get_parking_guidance(uint16_t distance_mm) {
    if (distance_mm < 300) return "STOP";
    if (distance_mm < 600) return "APPROACH";
    if (distance_mm < 1200) return "SLOW";
    return "CLEAR";
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (vl53l1x_wait_ready(g_i2c_handle) < 0) {
            fprintf(stderr, "Warning: range-ready timeout, skipping cycle.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t distance_mm = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) < 0) {
            fprintf(stderr, "Warning: read failed, skipping cycle.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_distance(g_log_file, distance_mm) < 0) {
            fprintf(stderr, "Warning: log write failed.\n");
        }

        const char *guidance = get_parking_guidance(distance_mm);
        printf("Distance: %u mm, Guidance: %s\n", distance_mm, guidance);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

