#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH201_ADDR     0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_DIST_MSB  0x00
#define CH201_REG_DIST_LSB  0x01
#define CH201_REG_CTRL      0x02

/* CTRL register bits */
#define CTRL_MEASURE_BIT   0x01
#define CTRL_INT_MASK      0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, buf, 3) == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%04X failed (attempt %d/%d)\n",
                reg, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
            fprintf(stderr, "I2C write (reg select 0x%04X) failed (attempt %d/%d)\n",
                    reg, attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(handle, (char *)buf, len) == (int)len)
            return 0;
        fprintf(stderr, "I2C read from reg 0x%04X failed (attempt %d/%d)\n",
                reg, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 sensor                                                         */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    /* Clear any stale interrupt flags */
    if (i2c_write_reg16(handle, CH201_REG_CTRL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear CH201 CTRL register\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t buf[2];

    if (i2c_read_reg16(handle, CH201_REG_DIST_MSB, buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ch201_start_measurement(int handle)
{
    return i2c_write_reg16(handle, CH201_REG_CTRL, CTRL_MEASURE_BIT);
}

static int ch201_stop_measurement(int handle)
{
    return i2c_write_reg16(handle, CH201_REG_CTRL, 0x00);
}

/* ------------------------------------------------------------------ */
/* LED blink control                                                    */
/* ------------------------------------------------------------------ */
static void set_led(int on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

static void blink_led(int frequency_hz)
{
    int half_period_us = (frequency_hz > 0) ? 500000 / frequency_hz : 1000000;
    int cycles = (SAMPLE_US < half_period_us) ? SAMPLE_US / half_period_us : 1;

    for (int i = 0; i < cycles && g_running; i++) {
        set_led(1);
        gpioDelay(half_period_us / 2);
        set_led(0);
        gpioDelay(half_period_us / 2);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_led(0);

    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (err=%d)\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH201 initialized at 0x%02X. Sampling every %d ms. Ctrl+C to exit.\n",
           CH201_ADDR, SAMPLE_US / 1000);

    while (g_running) {
        uint16_t distance = 0;
        if (ch201_read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Distance read failed; continuing.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map distance to blink frequency (50 mm -> 10 Hz, 500 mm -> 1 Hz) */
        float freq = 10.0f + (float)distance * (10.0f - 1.0f) / 450.0f;

        if (freq < 1.0f) freq = 1.0f;
        if (freq > 10.0f) freq = 10.0f;

        printf("Distance: %u mm  Blink: %.1f Hz\n", distance, freq);

        blink_led((int)freq);
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    set_led(0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

