#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x60
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, MLX75030_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(float *distance_cm) {
    char cmd = 0x01;
    char buf[2];
    int ret;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ret = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (ret < 0) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, ret);
            gpioDelay(1000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        ret = i2cReadDevice(i2c_handle, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, ret);
            gpioDelay(1000);
            continue;
        }

        if (ret != 2) {
            fprintf(stderr, "Unexpected byte count: %d (attempt %d/%d)\n", ret, attempt + 1, MAX_RETRIES);
            gpioDelay(1000);
            continue;
        }

        unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
        *distance_cm = (float)raw / 100.0f;
        return 0;
    }

    return -1;
}

static int log_data(float distance_cm) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float distance_cm;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
