static int init_vl53l1x(int handle) {
    if (write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (write_reg16(handle, REG_I2C_SLAVE__DEVICE_ADDR, VL53L1X_ADDR) < 0) return -1;

    if (write_reg16(handle, REG_SYSTEM__MODE_START, 0x40) < 0) return -1;
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t status = 0;
    if (read_reg16(handle, REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 1; /* not ready yet */

    uint8_t dist = 0;
    if (read_reg16(handle, REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &dist) < 0) return -1;
    *distance = (int)dist;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X initialized. Polling every %d ms. Press Ctrl+C to exit.\n", POLL_DELAY_US / 1000);

    int distance = -1;
    while (running) {
        int rc = read_distance(i2c_handle, &distance);
        if (rc == 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error (rc=%d). Re-initializing sensor...\n", rc);
            if (init_vl53l1x(i2c_handle) < 0) {
                fprintf(stderr, "Re-init failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

