#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      -90.0
#define MAX_ANGLE      90.0
#define ECHO_TIMEOUT_US 50000   /* 50 ms */
#define LOOP_DELAY_US   200000  /* 200 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output\n", SERVO_PIN);
        return -1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* 1 ms settle */

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); /* 10 us pulse */
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Measure distance in cm. Returns >= 0 on success, -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    trigger_sensor();

    /* Wait for echo rising edge */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo stuck low (timeout)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo stuck high (timeout)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
        return -1.0;
    }

    return distance;
}

static float map_distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    float frac = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    return MIN_ANGLE + frac * (MAX_ANGLE - MIN_ANGLE);
}

static void set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulse_us = (int)(angle * 2000.0 / 180.0 + 500.0);
    gpioServo(SERVO_PIN, pulse_us);
}

static void log_data(float distance, float angle)
{
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        perror("Error opening sensor_data.log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %.2f deg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance, angle);
    } else {
        fprintf(fp, "Distance: %.2f cm, Angle: %.2f deg\n", distance, angle);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: sensor read failed, skipping cycle\n");
        } else {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
            printf("Distance: %.2f cm, Angle: %.2f deg\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioServo(SERVO_PIN, 0); /* Stop servo pulses */
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

