    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "I2C read error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }
    if (i2c_write_reg8(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg8(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg8(handle, 0x0080, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0089, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, 0x008A, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, 0x008B, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x008C, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, 0x008D, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, 0x008E, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x008F, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0090, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0091, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0092, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0093, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0094, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0095, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0096, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0097, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, 0x0089, 0x02) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t ready = 0;
    if (i2c_read_reg8(handle, REG_DATA_READY, &ready) != 0) return -1;
    if (!(ready & 0x01)) {
        return 1;
    }
    if (i2c_read_reg16(handle, REG_DISTANCE_HI, distance) != 0) return -1;
    return 0;
}

static void log_distance(uint16_t distance) {
    struct msg_msg msg;
    msg.mtype = 1;
    msg.mtext[0] = (char *)&distance;
    msg.mtext[1] = 0;
    if (mq_send(mq_fd, (const char *)&msg, sizeof(msg), 0) != 0) {
        fprintf(stderr, "Failed to send message: %s\n", strerror(errno));
    }
}

static void buzzer_on(void) {
    gpioWrite(BUZZER_GPIO, 1);
}

static void buzzer_off(void) {
    gpioWrite(BUZZER_GPIO, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (mq_fd >= 0) {
        mq_close(mq_fd);
        mq_fd = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    mq_fd = mq_open(MSG_QUEUE_NAME, O_CREAT | O_RDWR, 0666, 0);
    if (mq_fd == (mqd_t)-1) {
        fprintf(stderr, "Failed to open message queue: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);
        if (ret == 0) {
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_on();
            } else {
                buzzer_off();
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

