#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define BUZZER_THRESHOLD 30.0
#define POLL_DELAY_US   100000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_state = 0;  /* 0=idle, 1=rising seen, 2=falling seen */

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * We compute the delta correctly across the wrap.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        end_tick = tick;
        echo_state = 2;
    }
}

/*
 * Compute distance in cm from pulse width in microseconds.
 * Returns -1.0 on timeout or invalid reading.
 */
static double calculate_distance(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) {
        return -1.0;
    }
    double time_s = (double)pulse_width_us / 1000000.0;
    return (time_s * SPEED_OF_SOUND) / 2.0;
}

static void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void display_distance(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Invalid reading: %.2f cm (out of range)\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_state = 0;
        start_tick = 0;
        end_tick   = 0;

        /* Send 10 us trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        /* Wait for echo or timeout (max ~1 s) */
        uint32_t wait_start = gpioTick();
        while (running && echo_state != 2) {
            if ((gpioTick() - wait_start) > 1000000) {
                echo_state = 0;
                break;
            }
            gpioDelay(100);
        }

        if (echo_state == 0) {
            fprintf(stderr, "Warning: no echo received (sensor absent or wiring fault).\n");
        } else if (echo_state == 2) {
            uint32_t pulse_width = end_tick - start_tick;
            double distance = calculate_distance(pulse_width);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Warning: distance %.2f cm out of valid range.\n", distance);
            } else {
                display_distance(distance);
                control_buzzer(distance);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

