#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mqtts5.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "gate_controller"

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0001
#define VL53L1X_REG_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;
static struct mosquitto *mosq = NULL;

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, event);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_reg(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int vl53l1x_read_reg(uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int vl53l1x_init(void) {
    if (vl53l1x_write_reg(VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write_reg(VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    uint8_t id;
    if (vl53l1x_read_reg(VL53L1X_REG_SYSTEM_MODE, &id) < 0) return -1;
    if (id != 0x00) {
        fprintf(stderr, "VL53L1X not detected (ID=0x%02X)\n", id);
        return -1;
    }

    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_MODE, 0x01) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t status;
    if (vl53l1x_read_reg(VL53L1X_REG_RANGE_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 1;

    uint8_t data[2];
    if (vl53l1x_read_reg(VL53L1X_REG_RESULT_DISTANCE, data) < 0) return -1;
    *distance = (data[0] << 8) | data[1];

    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static void gate_control(int open) {
    if (gpioServo(SERVO_PIN, 1500) < 0) return;
    if (open) {
        gpioServo(SERVO_PIN, 1000);
        log_event("Gate opened");
    } else {
        gpioServo(SERVO_PIN, 2000);
        log_event("Gate closed");
    }
}

static void mqtt_messageArrived(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[256];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        if (strncmp(payload, "force_open", 9) == 0) {
            log_event("Received force_open");
            gate_control(1);
        } else if (strncmp(payload, "force_close", 10) == 0) {
            log_event("Received force_close");
            gate_control(0);
        } else if (strncmp(payload, "status_request", 12) == 0) {
            char response[128];
            snprintf(response, sizeof(response), "status: gate %s", gate_control(0) ? "closed" : "open");
            log_event("Sent status: gate closed");
            int rc = mosquitto_publish(m, NULL, NULL, "/status", strlen(response), response, 0, false);
            if (rc != MOSQ_ERR_SUCCESS) {
                fprintf(stderr, "Publish failed: %s\n", mosquitto_strerror(rc));
            }
        }
    }
}

static void mqtt_connect(struct mosquitto *m, void *userdata, int result) {
    (void)m; (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_event("Connected to MQTT broker");
        mosquitto_subscribe(m, NULL, "gate_controller", 0);
        mosquitto_connect_callback_set(m, mqtt_messageArrived);
    } else {
        fprintf(stderr, "MQTT connect failed: %s\n", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        fprintf(stderr, "MQTT disconnect: %s\n", mosquitto_strerror(rc));
    }
}

static void mqtt_error(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    fprintf(stderr, "MQTT error: %s\n", mosquitto_strerror(rc));
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        log_event("I2C open failed");
        cleanup();
        return 1;
    }

    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        log_event("VL53L1X init failed");
        cleanup();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        log_event("Failed to set servo pin mode");
        cleanup();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "mosquitto_new failed\n");
        log_event("mosquitto_new failed");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect);
    mosquitto_error_callback_set(mosq, mqtt_error);

    mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    while (mosquitto_loop(mosq) == MOSQ_ERR_CONN_LOST) {
        fprintf(stderr, "Reconnecting...\n");
        mosquitto_reconnect(mosq);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    int gate_state = 0;
    while (running) {
        uint16_t distance;
        int rc = vl53l1x_read_distance(&distance);
        if (rc == 0) {
            int obj = (distance < DISTANCE_THRESHOLD) ? 1 : 0;
            if (obj != gate_state) {
                gate_state = obj;
                gate_control(obj);
                log_event(gate_state ? "Object detected, gate opened" : "Path clear, gate closed");
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error\n");
            log_event("I2C read error");
        }
        gpioDelay(100000);
