/*
 * HC-SR04 Ultrasonic Distance Measurement
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM 23, output)
 *   ECHO -> GPIO 24 (physical pin 18, BCM 24, input, pull-down)
 *   VCC  -> 5V (physical pin 2 or 4)
 *   GND  -> GND (physical pin 6)
 *
 * NOTE: The HC-SR04 ECHO output is 5V.  A voltage divider (e.g., 1k/2k)
 *       or logic-level converter is REQUIRED on the ECHO line to keep
 *       the signal within the Pi's 3.3V GPIO tolerance.
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIG_PIN      23
#define ECHO_PIN      24

#define TRIG_PULSE_US 10          /* 10 us trigger pulse            */
#define MEASURE_PERIOD_US 200000  /* 200 ms between measurements     */
#define ECHO_TIMEOUT_US  60000    /* 60 ms max echo wait            */
#define MIN_PULSE_US    100       /* reject noise / no-object reads  */
#define MAX_PULSE_US    30000     /* reject out-of-range reads      */

#define SPEED_CM_PER_US 0.0343    /* 343 m/s = 0.0343 cm/us          */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback: fires on every edge of ECHO_PIN              */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        static uint32_t rising_tick = 0;
        rising_tick = tick;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        static uint32_t falling_tick = 0;
        falling_tick = tick;
    }
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "TIME_ERROR");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "TIME_ERROR");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                               */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    /* Reset edge tick counters */
    rising_tick = 0;
    falling_tick = 0;

    /* Issue 10 us trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(TRIG, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIG, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo with timeout */
    uint32_t waited = 0;
    while (g_running) {
        uint32_t now = gpioTick();
        if (now - rising_tick > ECHO_TIMEOUT_US) {
            break;  /* timeout */
        }
        gpioDelay(100);  /* 100 us poll interval */
        waited += 100;
        if (waited >= MEASURE_PERIOD_US) {
            break;  /* normal cycle elapsed */
        }
    }

    if (!g_running) {
        return -1.0f;
    }

    if (falling_tick == 0) {
        return -1.0f;  /* no echo received */
    }

    uint32_t pulse_us = falling_tick - rising_tick;
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        return -1.0f;  /* out of plausible range */
    }

    float distance_cm = (float)pulse_us * SPEED_CM_PER_US / 2.0f;
    return distance_cm;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (distance < 0.0f) {
        fprintf(stderr, "[%s] WARNING: invalid distance (%.2f cm)\n",
                ts, distance);
        if (g_log_file) {
            fprintf(g_log_file, "%s, WARNING, invalid distance\n", ts);
            fflush(g_log_file);
        }
    } else {
        printf("[%s] Distance: %.2f cm\n", ts, distance);
        if (g_log_file) {
            fprintf(g_log_file, "%s, OK, %.2f cm\n", ts, distance);
            fflush(g_log_file);
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIG) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIG, 0) init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open distance_log.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(ECHO) failed\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d | ECHO: GPIO %d\n", TRIG_PIN, ECHO_PIN);
    printf("  Logging to distance_log.txt.  Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            log_distance(distance);
        } else {
            log_distance(distance);
        }

        /* Sleep 200 ms between measurements */
        gpioDelay(MEASURE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

