    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIG) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIG, 0) init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open distance_log.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(ECHO) failed\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d | ECHO: GPIO %d\n", TRIG_PIN, ECHO_PIN);
    printf("  Logging to distance_log.txt.  Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            log_distance(distance);
        } else {
            log_distance(distance);
        }

        /* Sleep 200 ms between measurements */
        gpioDelay(MEASURE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

