#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define DISTANCE_THRESHOLD_OPEN 50
#define DISTANCE_THRESHOLD_CLOSE 60
#define LOG_FILE "parking_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_RANGE_STATUS_OBJECT_DETECTED 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L1X\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0x%02X)\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(10000);

    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t status = 0;
    if (read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: Failed to read range status\n");
        return -1;
    }
    if (status & VL53L1X_RANGE_STATUS_OBJECT_DETECTED) {
        uint8_t dist_buf[2];
        if (read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
            fprintf(stderr, "Error: Failed to read distance\n");
            return -1;
        }
        *distance = (dist_buf[0] << 8) | dist_buf[1];
        return 0;
    }
    return -1;
}

static void log_event(const char *event, int distance) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s - Distance: %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file);
}

static void open_gate(int distance) {
    if (distance < 0) return;
    if (distance < DISTANCE_THRESHOLD_OPEN) {
        gpioServo(SERVO_PIN, 1500);
        log_event("Gate OPEN", distance);
    }
}

static void close_gate(int distance) {
    if (distance < 0) return;
    if (distance > DISTANCE_THRESHOLD_CLOSE) {
        gpioServo(SERVO_PIN, 750);
        log_event("Gate CLOSE", distance);
    }
}

static void cleanup() {
    if (i2c_handle >= 0) {
        write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", VL53L1X_ADDR);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 1000);
    gpioSetPWMrange(SERVO_PIN, 2000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_open = 0;
    int last_distance = -1;

    while (running) {
        int distance = -1;
        if (read_distance(i2c_handle, &distance) == 0) {
            if (distance < 0) {
                gpioServo(SERVO_PIN, 1500);
                log_event("Sensor Error", -1);
            } else {
                if (last_distance >= 0 && last_distance != distance) {
                    if (distance < 0) {
                        gpioServo(SERVO_PIN, 1500);
                        log_event("Sensor Error", -1);
                    } else {
                        open_gate(distance);
                    }
                }
                last_distance = distance;
            }
        } else {
            gpioServo(SERVO_PIN, 1500);
            log_event("Sensor Read Error", -1);
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

