#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_DELAY_US 500000
#define LOG_FILE "gate_events.log"

#define REG_SOFT_RESET 0x0003
#define REG_SYSTEM_MODE 0x0001
#define REG_RANGE_CONFIG_A 0x000F
#define REG_RANGE_CONFIG_B 0x0010
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0089
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], buf + 1, 2);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr[0], addr + 1, 1) < 0) return -1;
    return i2cReadI2CBlockData(handle, addr[0], (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    if (write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000);

    if (write_reg16(handle, REG_SYSTEM_MODE, 0x00) < 0) return -1;
    if (write_reg16(handle, REG_RANGE_CONFIG_A, 0x01) < 0) return -1;
    if (write_reg16(handle, REG_RANGE_CONFIG_B, 0x00) < 0) return -1;

    if (write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    if (write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    if (write_reg16(handle, REG_SYSTEM_MODE, 0x02) < 0) return -1;
    return 0;
}

static int read_distance(int handle, int *distance_mm) {
    uint8_t status_buf[1];
    uint8_t dist_buf[2];

    if (write_reg16(handle, REG_RESULT_INTERRUPT_STATUS, 0x01) < 0) return -1;
    gpioDelay(1000);

    if (read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, status_buf, 1) < 0) return -1;
    if ((status_buf[0] & 0x01) == 0) {
        *distance_mm = -1;
        return 0;
    }

    if (read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;
    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];

    if (write_reg16(handle, REG_RESULT_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    return 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %s\n",
            utc->tm_year + 1900, utc->tm_mon + 1, utc->tm_mday,
            utc->tm_hour, utc->tm_min, utc->tm_sec, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance;
        if (read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Error reading distance from VL53L1X\n");
            log_event("ERROR: I2C read failure");
        } else if (distance >= 0 && distance <= DISTANCE_THRESHOLD_MM) {
            if (gpioWrite(GATE_OPEN_PIN, 1) < 0) {
                fprintf(stderr, "Error writing HIGH to gate open pin\n");
                log_event("ERROR: Failed to open gate");
            } else {
                log_event("Gate opened");
            }
        } else {
            if (gpioWrite(GATE_CLOSE_PIN, 1) < 0) {
                fprintf(stderr, "Error writing HIGH to gate close pin\n");
                log_event("ERROR: Failed to close gate");
            } else {
                log_event("Gate closed");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

