#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define MOTOR_FORWARD  17
#define MOTOR_BACKWARD 18
#define TRIGGER_PIN    24

#define THRESHOLD_LOW  100   /* mm */
#define THRESHOLD_HIGH 300   /* mm */

#define REG_SOFT_RESET       0x0000
#define REG_START_MEASUREMENT 0x0000
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_DISTANCE_MSB      0x0096
#define REG_DISTANCE_LSB      0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    char data_buf[1];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int retries = 0;
    int delay_ms = 10;

    while (retries < 10) {
        if (vl53l1x_read_byte(handle, REG_RESULT_RANGE_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read range status.\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        gpioDelay(delay_ms * 1000);
        delay_ms *= 2;
        retries++;
    }

    if (retries >= 10) {
        fprintf(stderr, "Error: Timeout waiting for measurement.\n");
        return -1;
    }

    uint16_t dist = 0;
    if (vl53l1x_read_word(handle, REG_DISTANCE_MSB, &dist) < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }
    *distance = dist;
    return 0;
}

static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
}

static void trigger_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();
    if (current_tick - last_tick > 100000) { /* 100 ms */
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
            motor_stop();
        }
        last_tick = current_tick;
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    motor_stop();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d.\n", VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for GPIO %d.\n", TRIGGER_PIN);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("System ready. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

