/*
 * Proximity-based interactive art installation using MPR121 capacitive touch sensor.
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (modern Linux GPIO character-device API)
 * I2C:    /dev/i2c-1, MPR121 at address 0x5A
 * LEDs:   GPIO 17, 18, 27, 22 (BCM numbering)
 *
 * Build:  gcc -O2 -Wall -o art_installation art_installation.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5A

#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG0     0x5E
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_SOFTRESET      0x80
#define MPR121_AUTO_CONFIG0   0x5A
#define MPR121_AUTO_CONFIG1   0x5B
#define MPR121_AUTO_CONFIG2   0x5C
#define MPR121_AUTO_CONFIG3   0x5D

#define NUM_ELECTRODES 12
#define POLL_DELAY_MS   50

/* BCM GPIO numbers for the four LEDs */
static const unsigned int led_pins[NUM_ELECTRODES] = {17, 18, 27, 22};

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_lines[NUM_ELECTRODES];
static FILE *g_log = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *val);
static int  mpr121_init(int fd);
static int  mpr121_read_touch(int fd, uint16_t *touch_status);
static void led_pattern(uint16_t touch_status);
static void log_event(uint16_t touch_status);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 init -------------------------------- */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(1000);  /* allow reset to complete */

    /* Verify sensor presence by reading back the touch status register */
    uint8_t dummy;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &dummy) < 0)
        return -1;

    /* Baseline filtering */
    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;

    /* Auto-configuration thresholds */
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG1, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG2, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG3, 0xB4) < 0) return -1;

    /* Stop mode (ELECONFIG0 = 0x00) */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x00) < 0) return -1;

    /* Enable all 12 electrodes, run mode (ELECONFIG0 = 0x0C) */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

/* ----------------------------- Read touch status ------------------------- */
static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- LED pattern -------------------------------- */
static void led_pattern(uint16_t touch_status)
{
    uint8_t pattern = 0;

    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (touch_status & (1u << i)) {
            pattern |= (uint8_t)(1u << led_pins[i]);
        }
    }

    /* Drive all four LEDs simultaneously */
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (gpiod_line_set_value(g_lines[i], (pattern >> i) & 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %u: %s\n", led_pins[i], strerror(errno));
        }
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(uint16_t touch_status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (touch_status == 0) {
        printf("[%s] No electrodes touched. LEDs: OFF\n", timestamp);
    } else {
        printf("[%s] Electrodes: ", timestamp);
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1u << i))
                printf("ELE%d", i + 1);
            else
                printf("ELE%d", i + 1);
        }
        printf("\n");
        fflush(stdout);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Turn off all LEDs */
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (g_lines[i]) {
            gpiod_line_set_value(g_lines[i], 0);
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
        }
    }

    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Open log file */
    g_log = fopen("art_installation.log", "a");
    if (!g_log) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(g_log);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED lines */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ELECTRODES; i++) {
        g_lines[i] = gpiod_chip_get_line(g_chip, led_pins[i]);
        if (!g_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(g_lines[i], "mpr121_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Art installation running. Press Ctrl+C to exit.\n");
    printf("I2C: %s @ 0x%02X | LEDs: GPIO %u, %u, %u, %u\n",
           I2C_BUS, MPR121_ADDR, led_pins[0], led_pins[1], led_pins[2], led_pins[3]);

    /* Main loop */
    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch(g_i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status; retrying...\n");
            usleep(POLL_DELAY_MS * 1000);
            continue;
