#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define SOUND_SPEED 34300.0
#define TIMEOUT_US  30000
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define LOOP_DELAY_US    1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_reading(float distance) {
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s, %.2f cm\n", ts, distance);
    fclose(fp);
}

static void log_error(const char *msg) {
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s, ERROR: %s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static float measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo) {
    struct timespec ts_start, ts_now;
    long elapsed_us;
    int val;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1.0;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trigger, 1) < 0) {
        log_error("Failed to set trigger high");
        return -1.0;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_error("Failed to read echo line");
            return -1.0;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            log_error("Timeout waiting for echo rising edge");
            return -1.0;
        }
    } while (val == 0);

    /* Measure echo pulse width (timeout) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            log_error("Failed to read echo line");
            return -1.0;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                     (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            log_error("Timeout waiting for echo falling edge");
            return -1.0;
        }
    } while (val == 1);

    long pulse_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                    (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
    float distance = (pulse_us * SOUND_SPEED) / 2000000.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_error("Distance out of valid range");
        return -1.0;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        log_error("Failed to get trigger line");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        log_error("Failed to get echo line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        log_error("Failed to request trigger line as output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        log_error("Failed to request echo line as input");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    while (program_running) {
        float distance = measure_distance(trigger, echo);
        if (distance >= 0.0) {
            log_reading(distance);
        }
        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

