#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN      17
#define ECHO_PIN      18
#define TRIGGER_PULSE_US 10
#define LOG_FILE      "distance_log.txt"
#define SAMPLE_PERIOD_S 1.0

/* Speed of sound at 20 C: 343 m/s = 343000 cm/s = 343000000 us/m */
#define SOUND_SPEED_CM_S 34300.0
#define SOUND_SPEED_US_PER_M 34300.0

/* Sanity bounds for echo pulse width (us) */
#define MIN_PULSE_US  58   /* ~1 cm */
#define MAX_PULSE_US  25000 /* ~4 m */

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                            */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile int      g_echo_seen   = 0;
static volatile int      g_echo_valid   = 0;
static volatile int      g_running      = 1;
static FILE             *g_log_fp      = NULL;

/* ------------------------------------------------------------------ */
/* ISR callback: fires on EITHER_EDGE of the echo pin                   */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_pulse_start = tick;
        g_echo_seen   = 0;
        g_echo_valid  = 0;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_pulse_end   = tick;
        g_echo_seen   = 1;
        g_echo_valid  = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Compute elapsed microseconds with 32-bit tick wraparound-safe        */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04 and measure distance (m)                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int measure_distance(float *distance)
{
    /* Fire 10 us trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1;
    }

    /* Wait for echo callback to fire (poll up to 1 s) */
    uint32_t start_wait = gpioTick();
    while (!g_echo_seen && g_running) {
        if ((gpioTick() - start_wait) >= 1000000) {
            fprintf(stderr, "Error: echo callback timeout\n");
            return -1;
        }
        gpioDelay(100);
    }

    if (!g_echo_seen) {
        fprintf(stderr, "Error: no echo received on GPIO%d\n", ECHO_PIN);
        return -1;
    }

    /* Validate pulse width */
    uint32_t pulse_us = tick_diff(g_pulse_start, g_pulse_end);
    if (pulse_us == 0 || pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse width %u us\n", pulse_us);
        return -1;
    }

    /* distance = pulse_us * speed_of_sound / 2  (round trip) */
    *distance = (float)pulse_us * SOUND_SPEED_US_PER_M / 2.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                         */
/* ------------------------------------------------------------------ */
static int log_distance(float distance)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Distance: %.2f m\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on EITHER_EDGE */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx(ECHO) failed\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, logging to '%s'.\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float distance = 0.0f;

        if (measure_distance(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: failed to log distance\n");
            }
        } else {
            fprintf(stderr, "Warning: measurement failed, skipping log entry\n");
        }

        /* Sleep for the remainder of the sample period */
        time_t sleep_start = time(NULL);
        while (g_running && (time(NULL) - sleep_start < SAMPLE_PERIOD_S)) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    /* Disable ISR */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    /* Close log file */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

