#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define SHUTDOWN_REG 0x0018
#define START_REG 0x0020
#define TRIGGER_PIN_REG 0x0000
#define TRIGGER_PIN_VAL 0x00

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to write register 0x%04X", reg);
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        syslog(LOG_ERR, "Failed to write register address 0x%04X", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        syslog(LOG_ERR, "Failed to read %d bytes from register 0x%04X", len, reg);
        return -1;
    }
    return 0;
}

static int init_sensor(int handle) {
    if (write_reg16(handle, SHUTDOWN_REG, 0x00) != 0) return -1;
    if (write_reg16(handle, START_REG, 0x01) != 0) return -1;
    if (write_reg16(handle, TRIGGER_PIN_REG, TRIGGER_PIN_VAL) != 0) return -1;
    return 0;
}

static int read_distance(int handle, uint16_t *distance, uint8_t *status) {
    uint8_t dist_buf[2];
    uint8_t status_buf[1];
    if (read_reg16(handle, DISTANCE_REG, dist_buf, 2) != 0) return -1;
    if (read_reg16(handle, STATUS_REG, status_buf, 1) != 0) return -1;
    *distance = (dist_buf[0] << 8) | dist_buf[1];
    *status = status_buf[0];
    return 0;
}

static void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s, Distance: %u mm, Status: 0x%02X", timestamp, distance, status);
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, signal_handler);
