#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GATE_GPIO      24
#define DISTANCE_THRESHOLD_CM  20.0f
#define POLL_DELAY_US  100000
#define LOG_FILE       "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_MODEL_ID            0x010F
#define REG_SYSRANGE_START      0x0015
#define REG_RANGE_CONFIG        0x0021
#define REG_RESULT_DISTANCE     0x0089
#define EXPECTED_MODEL_ID       0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_sensor(int handle)
{
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) != 1) {
        log_event("Error: failed to read model ID");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: unexpected model ID 0x%02X (expected 0x%02X)", model_id, EXPECTED_MODEL_ID);
        log_event(msg);
        return -1;
    }
    if (i2c_write_reg16(handle, REG_RANGE_CONFIG, 0x00) != 0) {
        log_event("Error: failed to set ranging mode");
        return -1;
    }
    if (i2c_write_reg16(handle, REG_SYSRANGE_START, 0x01) != 0) {
        log_event("Error: failed to start ranging");
        return -1;
    }
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm)
{
    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, buf, 2) != 2) {
        log_event("Error: failed to read distance register");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void control_gate(int gpio, float distance_cm)
{
    static int gate_open = 0;
    if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
        if (gpioWrite(gpio, 1) == 0) {
            gate_open = 1;
            log_event("Gate opened");
        } else {
            log_event("Error: failed to open gate");
        }
    } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_open) {
        if (gpioWrite(gpio, 0) == 0) {
            gate_open = 0;
            log_event("Gate closed");
        } else {
            log_event("Error: failed to close gate");
        }
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_event("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GATE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GATE_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting GPIO %d low\n", GATE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        float distance = 0.0f;
        if (read_distance_cm(g_i2c_handle, &distance) == 0) {
            control_gate(GATE_GPIO, distance);
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.1f cm", distance);
            log_event(msg);
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

