#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_S 34300.0
#define MIN_DISTANCE_CM     2.0
#define MAX_DISTANCE_CM     400.0
#define MIN_ANGLE           0
#define MAX_ANGLE           180
#define SERVO_MIN_PW_US     500
#define SERVO_MAX_PW_US     2500
#define SERVO_DEFAULT_PW_US 1500
#define TRIGGER_PULSE_US    10
#define ECHO_TIMEOUT_US     30000
#define SAMPLE_INTERVAL_US  100000
#define MOVING_AVG_SIZE     5
#define LOG_FILE_NAME       "distance_log.csv"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* Shared between callback and main thread */
static volatile uint32_t g_pulse_start = 0;
static volatile uint32_t g_pulse_end   = 0;
static volatile int      g_pulse_ready = 0;
static volatile double    g_distance    = 0.0;
static volatile int      g_valid       = 0;

static double distance_buffer[MOVING_AVG_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_pulse_start = tick;
        g_pulse_ready = 0;
    } else if (level == 0) {
        g_pulse_end = tick;
        g_pulse_ready = 1;
    }
}

static double calculate_moving_average(void)
{
    double sum = 0.0;
    int count = (buffer_count < MOVING_AVG_SIZE) ? buffer_count : MOVING_AVG_SIZE;
    for (int i = 0; i < count; i++) {
        sum += distance_buffer[i];
    }
    return sum / count;
}

static double map_distance_to_angle(double distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double normalized = (distance - MIN_DISTANCE_CM) /
                        (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    double angle = (normalized * (MAX_ANGLE - MIN_ANGLE)) + MIN_ANGLE;
    return angle;
}

static int map_angle_to_pulsewidth(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    double normalized = (angle - MIN_ANGLE) /
                        (MAX_ANGLE - MIN_ANGLE);
    int pw = (int)(SERVO_MIN_PW_US +
                   (normalized * (SERVO_MAX_PW_US - SERVO_MIN_PW_US)));
    if (pw < SERVO_MIN_PW_US) pw = SERVO_MIN_PW_US;
    if (pw > SERVO_MAX_PW_US) pw = SERVO_MAX_PW_US;
    return pw;
}

static int set_servo_angle(int angle)
{
    int pw = map_angle_to_pulsewidth(angle);
    if (gpioServo(SERVO_PIN, pw) < 0) {
        fprintf(stderr, "gpioServo failed for angle %d\n", angle);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
        fflush(g_log_file);
    }
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_file, "Timestamp,Distance_cm,Servo_Angle_Deg\n") < 0) {
        fprintf(stderr, "Error writing CSV header\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(g_log_file);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set echo alert callback\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
