#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define THRESHOLD_MM 200
#define BUFFER_SIZE 10
#define POLL_DELAY_US 50000

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ID     0x0001
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_SYSTEM_CONFIG           0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG     0x0080
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0044
#define VL53L1X_REG_GPIO_HV_MUX_CTRL        0x0030
#define VL53L1X_REG_GPIO_TIO_HV_STATUS       0x0030
#define VL53L1X_REG_SYSTEM_RANGE_START      0x0000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    uint8_t id;
    if (read_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read device ID\n");
        return -1;
    }
    if (id != 0xEACC) {
        fprintf(stderr, "Error: Unexpected device ID 0x%02X (expected 0xEACC)\n", id);
        return -1;
    }

    /* Recommended STMicroelectronics sequence */
    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);

    if (write_reg16(handle, VL53L1X_REG_SYSTEM_CONFIG, 0x01) < 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x01) < 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_GPIO_HV_MUX_CTRL, 0x00) < 0) return -1;
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;

    /* Enable signal rate check */
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) return -1;

    /* Start ranging */
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) return -1;

    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    if (read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) return -1;
    if (!(status & 0x01)) {
        return 1; /* Not ready yet */
    }

    uint8_t dist_buf[2];
    if (read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void update_circular_buffer(int *buffer, int size, int new_value) {
    buffer[interrupt_count] = new_value;
    interrupt_count = (interrupt_count + 1) % size;
}

static void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    control_led(GPIO_LED, 0);

    int circular_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int interrupt_count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance;
        int read_result = read_distance(i2c_handle, &distance);

        if (read_result == 0) {
            update_circular_buffer(circular_buffer, BUFFER_SIZE, distance);
            int below_threshold = (distance < THRESHOLD_MM);

            control_led(GPIO_LED, below_threshold);
            if (below_threshold) {
                printf("Warning: Object detected at %u mm\n", distance);
            }
        } else if (read_result < 0) {
            fprintf(stderr, "Error reading distance: %d\n", read_result);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_led(GPIO_LED, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

