#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY  200.0
#define MAX_FREQUENCY  2000.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   200.0
#define PWM_DUTY       128  /* 50% of 255 */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS  200
#define LOOP_DELAY_US    100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Measure distance using HC-SR04 via pigpio hardware-timed GPIO. */
static double measure_distance(void) {
    /* Ensure trigger starts low. */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse. */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout). */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_MS * 1000) {
            fprintf(stderr, "Error: Echo rising-edge timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout). */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_MS * 1000) {
            fprintf(stderr, "Error: Echo falling-edge timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    /* distance = (pulse_width * speed_of_sound) / 2 */
    double distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;

    return distance;
}

/* Map distance to frequency using a logarithmic scale. */
static double distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0.0; /* Silence out-of-range */
    }
    double ratio = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    double frequency = MIN_FREQUENCY * exp(ratio * M_PI);
    return frequency;
}

int main(void) {
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes. */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low. */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range (50 Hz resolution). */
    if (gpioSetPWMfrequency(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, 255) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with a known frequency. */
    double current_frequency = 440.0;
    if (gpioSetPWMfrequency(PWM_PIN, current_frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0.0) {
            /* Error already printed in measure_distance. */
            gpioPWM(PWM_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double frequency = distance_to_frequency(distance);
        if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
            gpioPWM(PWM_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }
        if (gpioPWM(PWM_PIN, PWM_DUTY) < 0) {
            fprintf(stderr, "Error: gpioPWM failed\n");
            gpioPWM(PWM_PIN, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release pigpio. */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

