/*
 * Theremin-like instrument on Raspberry Pi 3 Model B+
 * Piezo buzzer: GPIO18 (PWM0)
 * HC-SR04 ultrasonic sensor: trigger=GPIO23, echo=GPIO24
 *
 * Distance (5-50 cm) maps to frequency (200-2000 Hz).
 * Uses pigpio gpioHardwarePWM for smooth, continuous tone generation.
 *
 * Build: gcc -Wall -O2 -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_FREQ_HZ      200
#define MAX_FREQ_HZ      2000
#define MIN_DIST_CM      5.0f
#define MAX_DIST_CM      50.0f
#define MIN_DIST_CM_READ 5.0f
#define MAX_DIST_CM_READ 50.0f
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  100000   /* 100 ms */
#define LOOP_DELAY_US    10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure echo pulse width in microseconds using gpioDelay.
 * Returns pulse width in us, or -1 on timeout / error.
 */
static long measure_echo_pulse_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo pin did not go high (timeout).\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo pin did not go low (timeout).\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float read_distance_cm(void)
{
    /* Ensure trigger is low before starting */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    long pulse_us = measure_echo_pulse_us();
    if (pulse_us < 0)
        return -1.0f;

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    /* speed_of_sound = 343 m/s = 0.0343 cm/us */
    return (float)pulse_us * 0.0343f / 2.0f;
}

static int calculate_frequency(float distance_cm)
{
    if (distance_cm < MIN_DIST_CM_READ) distance_cm = MIN_DIST_CM_READ;
    if (distance_cm > MAX_DIST_CM_READ) distance_cm = MAX_DIST_CM_READ;

    float frac = (distance_cm - MIN_DIST_CM_READ) /
                 (MAX_DIST_CM_READ - MIN_DIST_CM_READ);

    int freq = MIN_FREQ_HZ + (int)((float)(MAX_FREQ_HZ - MIN_FREQ_HZ) *
                                  frac);

    if (freq < MIN_FREQ_HZ) freq = MIN_FREQ_HZ;
    if (freq > MAX_FREQ_HZ) freq = MAX_FREQ_HZ;

    return freq;
}

static void set_buzzer_frequency(int freq_hz)
{
    if (freq_hz < 0) {
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        return;
    }

    /* pigpio gpioHardwarePWM: duty 0-255, frequency in Hz */
    if (gpioHardwarePWM(BUZZER_PIN, freq_hz, 0) < 0) {
        fprintf(stderr, "Warning: gpioHardwarePWM failed for freq %d Hz.\n", freq_hz);
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
    }
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
