#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  50000   /* 50 ms timeout for echo pulse */
#define TRIGGER_US  10      /* 10 us trigger pulse */
#define MIN_DIST_CM 2.0
#define MAX_DIST_CM 400.0
#define SOUND_SPEED_CM_PER_US 29.1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static double measure_distance(void) {
    /* Send 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) >= TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_start) >= TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    double distance = (double)pulse_width / 2.0 / SOUND_SPEED_CM_PER_US;

    if (distance < MIN_DIST_CM || distance > MAX_DIST_CM) {
        return -1.0;
    }
    return distance;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10.0) {
                printf("Too close!\n");
            }
        }
        fflush(stdout);

        /* Sleep 500 ms; gpioDelay is microseconds */
        gpioDelay(500000);
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

