#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define READ_INTERVAL_MS 100

/* ICU-20201 register addresses (16-bit, big-endian on bus) */
#define REG_MEASURE_TRIGGER 0x00
#define REG_RANGE_SELECT 0x02
#define REG_CONTINUOUS_MODE 0x01
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_reg(uint16_t reg, uint8_t value) {
    char tx[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    char rx[3] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI write failed for reg 0x%04X (ret=%d)\n", reg, ret);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint16_t reg, uint8_t *value) {
    char tx[3] = { (char)(reg >> 8), (char)(reg & 0xFF), 0x00 };
    char rx[3] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI read failed for reg 0x%04X (ret=%d)\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[2];
    return 0;
}

static int init_sensor(void) {
    /* Start continuous measurement mode */
    if (spi_write_reg(REG_CONTINUOUS_MODE, 0x01) != 0) return -1;
    /* Set range to 5 m (0x00) */
    if (spi_write_reg(REG_RANGE_SELECT, 0x00) != 0) return -1;
    /* Trigger first measurement */
    if (spi_write_reg(REG_MEASURE_TRIGGER, 0x01) != 0) return -1;
    return 0;
}

static int read_distance(uint16_t *distance_mm) {
    uint8_t low, high;
    if (spi_read_reg(REG_DISTANCE_LOW, &low) != 0) return -1;
    if (spi_read_reg(REG_DISTANCE_HIGH, &high) != 0) return -1;
    *distance_mm = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_distance(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(CS_PIN, 1);

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance readings. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t distance_mm;
        if (read_distance(&distance_mm) == 0) {
            log_distance(distance_mm);
            if (distance_mm > 200 && distance_mm < 5000) {
                printf("Distance: %u mm\n", distance_mm);
            } else {
                fprintf(stderr, "Invalid distance reading: %u mm\n", distance_mm);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

