#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR        0x60
#define SI1175_ALS_VIS_DATA0 0x22
#define SI1175_ALS_VIS_DATA1 0x23
#define LOG_FILE           "proximity_log.csv"
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int read_als_visible(int fd, uint16_t *out) {
    uint8_t lo, hi;
    if (i2c_read_byte(fd, SI1175_ALS_VIS_DATA0, &lo) == -1) return -1;
    if (i2c_read_byte(fd, SI1175_ALS_VIS_DATA1, &hi) == -1) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t als) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, (unsigned)als) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) == EOF) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1) {
        goto cleanup;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (fprintf(fp, "timestamp,als_visible\n") < 0) {
        fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
        goto cleanup;
    }
    if (fflush(fp) == EOF) {
        fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Si1175 ALS reader started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        uint16_t als = 0;
        if (read_als_visible(fd, &als) == -1) {
            fprintf(stderr, "ALS read failed; continuing.\n");
        } else {
            if (log_data(fp, als) == -1) {
                fprintf(stderr, "Log write failed; continuing.\n");
            } else {
                printf("ALS: %u\n", (unsigned)als);
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) == EOF) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            rc = EXIT_FAILURE;
        }
    }
    if (fd >= 0) {
        if (close(fd) == -1) {
            fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
            rc = EXIT_FAILURE;
        }
    }
    return rc;
}

