#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1120_ADDR 0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_ALS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_COMMAND 0x30
#define SI1120_CMD_RESET 0x01
#define SI1120_EXPECTED_PART_ID 0x41
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
    }
    *value = (uint8_t)rc;
    return rc;
}

static int read_reg16(uint8_t reg_low, uint8_t reg_high, uint16_t *value) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_high, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1120(void) {
    uint8_t part_id;
    if (read_reg(SI1120_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != SI1120_EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x%02X)\n", part_id, SI1120_EXPECTED_PART_ID);
        return -1;
    }
    if (write_reg(SI1120_REG_COMMAND, SI1120_CMD_RESET) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *prox) {
    if (read_reg16(SI1120_REG_ALS_DATA0, SI1120_REG_ALS_DATA1, als) < 0) return -1;
    if (read_reg16(SI1120_REG_PS1_DATA0, SI1120_REG_PS1_DATA1, prox) < 0) return -1;
    return 0;
}

static void log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, SI1120_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (init_si1120() < 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Si1120 logging started. Press Ctrl+C to stop.\n");
    while (!terminate) {
        uint16_t als = 0, prox = 0;
        int retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_sensor_data(&als, &prox) == 0) break;
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(RETRY_DELAY_US);
        }
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
            continue;
        }
        log_data(als, prox);
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

