#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

/* Si1145 register addresses */
#define SI1145_REG_PART_ID       0x00
#define SI1145_REG_HW_KEY        0x07
#define SI1145_REG_MEAS_RATE     0x06
#define SI1145_REG_IRQ_ENABLE    0x0F
#define SI1145_REG_ALS_VIS_ADC_COUNTER 0x21
#define SI1145_REG_PS_ADC_MISC   0x0C
#define SI1145_REG_PS_LED21      0x0C
#define SI1145_REG_PS_LED3       0x0F
#define SI1145_REG_PS_ADC_GAIN   0x0D
#define SI1145_REG_PS1_DATA0     0x16
#define SI1145_REG_PS1_DATA1     0x17
#define SI1145_REG_COMMAND       0x80

/* Commands */
#define SI1145_CMD_RESET         0x01
#define SI1145_CMD_PS_FORCE      0x03

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int read_register(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
    }
    return rc;
}

static int init_si1145(int handle) {
    /* Reset */
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    /* Hardware key */
    if (write_register(handle, SI1145_REG_HW_KEY, 0x03) < 0) return -1;

    /* Measurement rate: 2 ms (0x02) */
    if (write_register(handle, SI1145_REG_MEAS_RATE, 0x02) < 0) return -1;

    /* Disable interrupts */
    if (write_register(handle, SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;

    /* ALS visible IR ADC counter: 1 */
    if (write_register(handle, SI1145_REG_ALS_VIS_ADC_COUNTER, 0x00) < 0) return -1;

    /* PS ADC misc: small IR */
    if (write_register(handle, SI1145_REG_PS_ADC_MISC, 0x03) < 0) return -1;

    /* PS LED1: 180 mA */
    if (write_register(handle, SI1145_REG_PS_LED21, 0x0F) < 0) return -1;

    /* PS LED3: 180 mA */
    if (write_register(handle, SI1145_REG_PS_LED3, 0x0F) < 0) return -1;

    /* PS ADC gain: 7.7x */
    if (write_register(handle, SI1145_REG_PS_ADC_GAIN, 0x07) < 0) return -1;

    /* Force proximity measurement */
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;

    return 0;
}

static int read_proximity(int handle) {
    int lo = read_register(handle, SI1145_REG_PS1_DATA0);
    if (lo < 0) return -1;
    int hi = read_register(handle, SI1145_REG_PS1_DATA1);
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

static void log_data(int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %d\n", timestamp, proximity);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, msg);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int proximity = read_proximity(i2c_handle);
        if (proximity >= 0) {
            log_data(proximity);
        } else {
            log_error("Failed to read proximity data");
        }
        gpioDelay(100000); /* 100 ms */
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

