#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TIMEOUT_US 30000
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define SERVO_MID_US 1500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_MIN_DISTANCE 200.0
#define SERVO_MAX_DISTANCE 110.0
#define SERVO_MIN_DISTANCE 20.0
#define UPDATE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    trigger_sensor();

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }

    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }

    end_tick = gpioTick();

    double pulse_width = (double)(end_tick - start_tick);
    return (pulse_width * SPEED_OF_SOUND_CM_PER_US) / 2.0;
}

static int set_servo_angle(double distance) {
    if (distance < SERVO_MIN_DISTANCE) distance = SERVO_MIN_DISTANCE;
    if (distance > SERVO_MAX_DISTANCE) distance = SERVO_MAX_DISTANCE;

    int pulse_width = SERVO_MIN_US + (int)((distance - SERVO_MIN_DISTANCE) *
                                            (SERVO_MAX_US - SERVO_MIN_US) /
                                            (SERVO_MAX_DISTANCE - SERVO_MIN_DISTANCE));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioServo(SERVO_PIN, SERVO_MIN_US);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: sensor read failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);

        if (set_servo_angle(distance) != 0) {
            fprintf(stderr, "Warning: servo set failed\n");
        }

        gpioDelay(UPDATE_INTERVAL_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

