#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define SERVO_MIN_PULSEWIDTH 500
#define SERVO_MAX_PULSEWIDTH 2500
#define TIMEOUT_US 50000
#define SOUND_SPEED 0.0343
#define MIN_DISTANCE_CM 20.0
#define MAX_DISTANCE_CM 200.0

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

float measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout++ > TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > TIMEOUT_US) return -1.0;
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    float distance = (pulse_duration * SOUND_SPEED) / 2.0;
    return distance;
}

int angle_from_distance(float distance) {
    if (distance < MIN_DISTANCE_CM) return MIN_ANGLE;
    if (distance > MAX_DISTANCE_CM) return MAX_ANGLE;
    float fraction = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(fraction * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
}

void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Invalid angle %d (must be %d-%d)\n", angle, MIN_ANGLE, MAX_ANGLE);
        return;
    }
    int pulsewidth = SERVO_MIN_PULSEWIDTH + (int)((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));
    gpioServo(SERVO_PIN, pulsewidth);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(500000);

    signal(SIGINT, handle_sigint);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor timeout\n");
        } else {
            int angle = angle_from_distance(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %d\n", distance, angle);
        }
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

