#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x01
#define SI7005_REG_HUM 0x02
#define SI7005_REG_CONFIG 0x03
#define SI7005_CONFIG_VAL 0x00
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %d\n", reg, rc);
        return -1;
    }
    gpioDelay(10000);
    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int write_register(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, SI7005_REG_CONFIG, SI7005_CONFIG_VAL) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_sensor(int handle, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_hum;
    if (read_register(handle, SI7005_REG_TEMP, &raw_temp) != 0) {
        return -1;
    }
    if (read_register(handle, SI7005_REG_HUM, &raw_hum) != 0) {
        return -1;
    }
    *temperature = (175.72f * (float)raw_temp) / 65536.0f - 46.85f;
    *humidity = (125.0f * (float)raw_hum) / 65536.0f - 6.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;
    while (running) {
        if (read_sensor(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Read failed, attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
                break;
            }
            if (initialize_sensor(i2c_handle) != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

