#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

/* Scaling factors for default ranges */
#define ACCEL_SCALE 16384.0f  /* ±2 g  -> 16384 LSB/g */
#define GYRO_SCALE  131.0f    /* ±250 deg/s -> 131 LSB/dps */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an MPU-6050 register; returns 0 on success, -1 on error. */
static int mpu_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* Read one byte from an MPU-6050 register; returns 0 on success, -1 on error. */
static int mpu_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read a block of bytes starting at `reg`; returns 0 on success, -1 on error. */
static int mpu_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, want=%u, got=%d): %s\n",
                reg, len, rc, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* Initialise the MPU-6050: verify identity, reset, wait, configure sample rate, ranges. */
static int mpu6050_init(int handle)
{
    uint8_t whoami = 0;

    /* --- Verify device identity --- */
    if (mpu_read_byte(handle, MPU6050_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (whoami != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    printf("MPU-6050 detected (WHO_AM_I = 0x%02X)\n", whoami);

    /* --- Reset the device --- */
    if (mpu_write_byte(handle, MPU6050_PWR_MGMT_1, 0x80) != 0)
        return -1;
    gpioDelay(100000); /* 100 ms reset settling time */

    /* --- Wake up: clear sleep bit (bit 6) --- */
    if (mpu_write_byte(handle, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms for oscillator to stabilise */

    /* --- Set sample rate divider to 7 -> 1 kHz / (1 + 7) = 125 Hz --- */
    if (mpu_write_byte(handle, MPU6050_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* --- Configure accelerometer: ±2 g range (AFS_SEL = 0) --- */
    if (mpu_write_byte(handle, MPU6050_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    /* --- Configure gyroscope: ±250 deg/s range (FS_SEL = 0) --- */
    if (mpu_write_byte(handle, MPU6050_GYRO_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* Read 14 bytes of sensor data and parse big-endian int16 values. */
static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];

    if (mpu_read_block(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main(void)
{
    int handle = -1;

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the MPU-6050 default address --- */
    handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus 1, addr 0x%02X): %s\n",
                MPU6050_ADDR, pigpio_error(handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise the sensor --- */
    if (mpu6050_init(handle) != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 initialised. Reading at 125 Hz (Ctrl+C to stop)...\n");

    /* --- Main acquisition loop --- */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_sensor_data(handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Sensor read error; continuing...\n");
        }

        gpioDelay(100000); /* 100 ms -> 10 Hz output */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

