#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define SHT40_CMD_HIGHREP 0xFD
#define SHT40_MEAS_MS     10
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht40_read(int handle, float *temp, float *hum) {
    uint8_t cmd = SHT40_CMD_HIGHREP;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "SHT40: failed to send measurement command\n");
        return -1;
    }

    gpioDelay(SHT40_MEAS_MS * 1000);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "SHT40: failed to read 6 bytes from sensor\n");
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "SHT40: temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "SHT40: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum  = -6.0f  + 125.0f * (float)h_raw / 65535.0f;

    if (*hum < 0.0f)   *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SHT40_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, hum;
        if (sht40_read(handle, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; re-opening I2C bus.\n");
            i2cClose(handle);
            handle = i2cOpen(1, SHT40_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus: %d\n", handle);
                break;
            }
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

