#define I2C_DEVICE "/dev/i2c-1"
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    if (i2c_write_byte(fd, reg) < 0) {
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int fd, uint8_t reg, float *temp) {
    uint16_t raw;
    if (i2c_read_word(fd, reg, &raw) < 0) {
        return -1;
    }
    *temp = (175.0f * raw / 65535.0f) - 46.85f;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Ambient_C,Object_C\n");
        fflush(log_file);
    }

    printf("MLX90614 monitoring started. Press Ctrl+C to stop.\n");

    while (running) {
        float ambient = NAN, object = NAN;
        int err = 0;

        if (read_temperature(i2c_fd, AMBIENT_TEMP_REG, &ambient) < 0) {
            fprintf(stderr, "Error reading ambient temperature.\n");
            err = 1;
        }
        if (read_temperature(i2c_fd, OBJECT_TEMP_REG, &object) < 0) {
            fprintf(stderr, "Error reading object temperature.\n");
            err = 1;
        }

        if (!isnan(ambient) && !isnan(object)) {
            if (log_temperature(ambient, object) < 0) {
                fprintf(stderr, "Error logging temperature.\n");
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        } else {
            fprintf(stderr, "Sensor read error; skipping log entry.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

