#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define STS30_ADDR 0x4A
#define I2C_BUS 1
#define SAMPLE_INTERVAL_SEC 5
#define ERROR_LOG_FILE "error_log.txt"
#define DATA_LOG_FILE "enclosure_temp_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *data_log_fp = NULL;
static FILE *error_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (error_log_fp) {
        fprintf(error_log_fp, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
        fflush(error_log_fp);
    }
    fprintf(stderr, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
}

static int read_sts30(int handle, float *temp_out) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[3];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        log_error("I2C write failed");
        return -1;
    }

    gpioDelay(20000); /* 20 ms conversion time */

    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        log_error("I2C read failed");
        return -1;
    }
    if (rc != 3) {
        log_error("I2C read short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_out = -45.0f + 175.0f * ((float)raw / 65536.0f);
    return 0;
}

static void log_data(float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(data_log_fp, "%s, %.2f\n", ts, temp);
    fflush(data_log_fp);
}

int main(void) {
    int i2c_handle;
    float temperature;
    int init_ok = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    init_ok = 1;

    data_log_fp = fopen(DATA_LOG_FILE, "a");
    if (!data_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", DATA_LOG_FILE, strerror(errno));
        goto cleanup;
    }

    error_log_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", ERROR_LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (running) {
        i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
        if (i2c_handle < 0) {
            log_error("Failed to open I2C device");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_sts30(i2c_handle, &temperature) == 0) {
            log_data(temperature);
        } else {
            log_error("STS30 read failed");
        }

        i2cClose(i2c_handle);
        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    if (data_log_fp) fclose(data_log_fp);
    if (error_log_fp) fclose(error_log_fp);
    if (init_ok) gpioTerminate();
    return EXIT_SUCCESS;
}

