#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("I2C read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_hum  = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
    *humidity    = 100.0f * (float)raw_hum / 65535.0f;

    return 0;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Smart Greenhouse Monitor started. Logging to %s every %d seconds.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_SEC);

    while (running) {
        if (i2c_write_cmd(i2c_fd, 0xFD) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            sleep(MEASUREMENT_INTERVAL_SEC);
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        float temperature, humidity;
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        for (int i = 0; i < MEASUREMENT_INTERVAL_SEC && running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

