#define SDP31_ADDR     0x28
#define MEASURE_CMD    0x21 0x96
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES    3
#define RETRY_DELAY_US 1000
#define LOG_FILE       "airflow.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SDP31_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int send_measurement_command(void) {
    uint8_t cmd[2] = { MEASURE_CMD[0], MEASURE_CMD[1] };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int16_t *pressure_raw, int16_t *temperature_raw) {
    uint8_t buf[6];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %d\n", rc);
        return -1;
    }
    *pressure_raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature_raw = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static void convert_data(int16_t pressure_raw, int16_t temperature_raw,
                         float *pressure_pa, float *temperature_c) {
    *pressure_pa = (float)pressure_raw / 60.0f;
    *temperature_c = (float)temperature_raw / 200.0f;
}

static int log_data(float pressure_pa, float temperature_c) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    int16_t pressure_raw = 0, temperature_raw = 0;
    float pressure_pa = 0.0f, temperature_c = 0.0f;

    while (g_running) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (send_measurement_command() != 0) {
                gpioDelay(RETRY_DELAY_US);
                continue;
            }
            gpioDelay(1000);

            if (read_sensor_data(&pressure_raw, &temperature_raw) == 0) {
                success = 1;
                break;
            }
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
        }

        if (success) {
            convert_data(pressure_raw, temperature_raw,
                         &pressure_pa, &temperature_c);
            if (log_data(pressure_pa, temperature_c) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; continuing\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

