#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define MEASURE_CMD    0x362F
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP8xx */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_bytes: read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    uint8_t buf[9];

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;

    usleep(45000); /* 45 ms conversion time */

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRC for each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale-factor word\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 200.0f - 45.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log, 0, SEEK_END);
    if (ftell(g_log) == 0)
        fprintf(g_log, "timestamp,pressure_pa,temperature_c\n");

    printf("SDP800 airflow monitor started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        float pressure, temperature;

        if (read_sdp800(g_i2c_fd, &pressure, &temperature) == 0) {
            log_data(g_log, pressure, temperature);
            printf("P=%.2f Pa  T=%.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    if (g_log) fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

