#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD_HIGH_REP 0x2C06
#define CONVERSION_DELAY_US 15000
#define SAMPLE_INTERVAL_S 5
#define ERROR_LOG_FILE "error_log.txt"
#define DATA_LOG_FILE "enclosure_temp_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void log_data(float temperature) {
    FILE *fp = fopen(DATA_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening data log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fclose(fp);
}

static int read_temperature(float *temperature) {
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD_HIGH_REP >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD_HIGH_REP & 0xFF)
    };
    uint8_t buf[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        log_error("Failed to write measurement command to I2C device");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        log_error("Failed to read 3 bytes from I2C device");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC checksum mismatch on temperature data");
        return -1;
