#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000  /* 5 seconds */
#define MEASUREMENT_DELAY_US 1000000 /* 1 second */

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT           0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_DATA_READY                0xE4B8

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* CRC-8: polynomial 0x31, init 0xFF (Sensirion standard) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_data_ready(uint16_t *ready) {
    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice (data-ready) failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "Error: short read for data-ready (got %d bytes)\n", rc);
        return -1;
    }
    uint8_t crc = crc8(buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "Error: data-ready CRC mismatch (calc=0x%02X, got=0x%02X)\n", crc, buf[2]);
        return -1;
    }
    *ready = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice (measurement) failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "Error: short read for measurement data (got %d bytes)\n", rc);
        return -1;
    }
    /* CRC check for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        uint8_t crc = crc8(&buf[i * 3], 2);
        if (crc != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: measurement CRC mismatch at word %d (calc=0x%02X, got=0x%02X)\n",
                    i, crc, buf[i * 3 + 2]);
            return -1;
        }
    }
    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t hum_raw  = ((uint16_t)buf[6] << 8) | buf[7];
    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum  = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static int log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d) on bus %d addr 0x%02X\n", i2c_handle, I2C_BUS, SCD40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after ~1 second */
    gpioDelay(MEASUREMENT_DELAY_US);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (!terminate) {
        uint16_t ready = 0;
        if (read_data_ready(&ready) != 0) {
            fprintf(stderr, "Warning: data-ready poll failed, retrying\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (ready == 0) {
            uint16_t co2;
            float temp, hum;
            if (read_measurement(&co2, &temp, &hum) == 0) {
                if (log_data(co2, temp, hum) != 0) {
                    fprintf(stderr, "Warning: log write failed\n");
                }
            } else {
                fprintf(stderr, "Warning: measurement read failed\n");
            }
        } else {
            fprintf(stderr, "Warning: data not ready yet (0x%04X), skipping\n", ready);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful shutdown */
    if (send_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    }
    gpioDelay(100000); /* allow command to take effect */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

