#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_SEC 5

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

static sensor_data_t co2_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_scd40(void) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF),
        (uint8_t)(CMD_START_PERIODIC_MEASUREMENT & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start periodic measurement command\n");
        return -1;
    }
    return 0;
}

static int stop_scd40(void) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF),
        (uint8_t)(CMD_STOP_PERIODIC_MEASUREMENT & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send stop periodic measurement command\n");
        return -1;
    }
    return 0;
}

static int read_scd40_data(sensor_data_t *data) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_READ_MEASUREMENT >> 8) & 0xFF),
        (uint8_t)(CMD_READ_MEASUREMENT & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send read measurement command\n");
        return -1;
    }

    gpioDelay(2000);

    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SCD40\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on humidity word\n");
        return -1;
    }

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];

    data->co2 = co2_raw;
    data->temperature = -45.0f + 175.0f * ((float)temp_raw / 65535.0f);
    data->humidity = 100.0f * ((float)hum_raw / 65535.0f);

    return 0;
}

static void add_to_buffer(uint16_t co2, float temperature, float humidity) {
    co2_buffer[buffer_index].co2 = co2;
    co2_buffer[buffer_index].temperature = temperature;
    co2_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- CO2 Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Index: %2d, CO2: %5u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               idx, co2_buffer[idx].co2,
               co2_buffer[idx].temperature, co2_buffer[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, SCD40_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_scd40() != 0) {
        fprintf(stderr, "Error: SCD40 initialisation failed (sensor absent or bus error)\n");
        stop_scd40();
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", LED_GPIO);
        stop_scd40();
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("SCD40 CO2 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sensor_data_t data;
        if (read_scd40_data(&data) == 0) {
            printf("CO2: %5u ppm, Temp: %.2f C, Hum: %.2f %%\n",
                   data.co2, data.temperature, data.humidity);

            add_to_buffer(data.co2, data.temperature, data.humidity);

            if (data.co2 > CO2_THRESHOLD)
                gpioWrite(LED_GPIO, 1);
            else
                gpioWrite(LED_GPIO, 0);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying next cycle\n");
        }

        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    stop_scd40();
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    print_buffer();
    return EXIT_SUCCESS;
}

