#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define MAX_CONSECUTIVE_ERRORS 3
#define TIMEOUT_US 50000            /* 50 ms edge wait timeout */
#define MIN_TEMP_C -40.0
#define MAX_TEMP_C 150.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Busy-wait for a rising edge on the GPIO pin.
 * Returns the elapsed microsecond count since the last edge, or -1 on timeout.
 */
static long wait_for_rising_edge(void) {
    uint32_t start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;
        }
    }
    return (long)(gpioTick() - start_tick);
}

/*
 * Busy-wait for a falling edge on the GPIO pin.
 * Returns the elapsed microsecond count since the last edge, or -1 on timeout.
 */
static long wait_for_falling_edge(void) {
    uint32_t start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1;
        }
    }
    return (long)(gpioTick() - start_tick);
}

/*
 * Read temperature from TMP05.
 * Returns 0 on success, -1 on timeout or division-by-zero.
 */
static int read_temperature(double *temperature) {
    long th_us = 0, tl_us = 0;

    /* Wait for rising edge (start of new cycle) */
    th_us = wait_for_rising_edge();
    if (th_us < 0) {
        fprintf(stderr, "Timeout waiting for rising edge (sensor absent or stuck high?)\n");
        return -1;
    }

    /* Wait for falling edge (end of cycle) */
    tl_us = wait_for_falling_edge();
    if (tl_us < 0) {
        fprintf(stderr, "Timeout waiting for falling edge (sensor absent or stuck low?)\n");
        return -1;
    }

    if (tl_us == 0) {
        fprintf(stderr, "Error: TL is zero (division by zero)\n");
        return -1;
    }

    /* Temperature = 4215 - (2143 * TH / TL) */
    double temp = 4215.0 - (2143.0 * (double)th_us / (double)tl_us);

    if (temp < MIN_TEMP_C || temp > MAX_TEMP_C) {
        fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", temp);
        return -1;
    }

    *temperature = temp;
    return 0;
}

static void log_temperature(double temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static void log_sensor_failure(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
    fflush(log_file);
}

int main(void) {
    double temperature;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "--- TMP05 temperature monitoring started ---\n");
    fflush(log_file);

    while (running) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Failed to read temperature (consecutive error %d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_sensor_failure();
                fprintf(stderr, "Max consecutive errors reached. Logging sensor failure and exiting.\n");
                break;
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    if (log_file != NULL) {
        fprintf(log_file, "--- TMP05 temperature monitoring stopped ---\n");
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

