#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2400
#define I2C_BUS 1
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 15000
#define OFFSET_PERIOD_SEC 3600
#define OFFSET_SCALE_TEMP 2.0
#define OFFSET_SCALE_HUM 5.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static SensorData read_sensor_data(void) {
    SensorData data = {NAN, NAN};
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(1000000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(1000000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(1000000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(1000000);
            continue;
        }

        uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t hum_raw = ((uint16_t)buf[3] << 8) | buf[4];

        data.temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        data.humidity = 100.0f * (float)hum_raw / 65535.0f;

        return data;
    }

    fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
    return data;
}

static SensorData simulate_offset(SensorData data) {
    time_t now = time(NULL);
    time_t offset_time = now - OFFSET_PERIOD_SEC;
    float temp_offset = OFFSET_SCALE_TEMP * (offset_time / (float)OFFSET_PERIOD_SEC);
    float hum_offset = OFFSET_SCALE_HUM * (offset_time / (float)OFFSET_PERIOD_SEC);

    data.temperature += temp_offset;
    data.humidity += hum_offset;

    if (data.temperature < -40.0f) data.temperature = -40.0f;
    if (data.temperature > 125.0f) data.temperature = 125.0f;
    if (data.humidity < 0.0f) data.humidity = 0.0f;
    if (data.humidity > 100.0f) data.humidity = 100.0f;

    return data;
}

static void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "# Greenhouse monitor started\n");
    fflush(log_file);

    while (running) {
        SensorData raw_data = read_sensor_data();
        SensorData logged_data = simulate_offset(raw_data);
        log_data(logged_data);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

