#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define READ_INTERVAL_SEC  5
#define MEAS_TIMEOUT_MS    100
#define RESET_CMD          0xFE
#define RESET_CMD_LEN      1
#define RESET_CMD_ARG      0x00
#define NO_HOLD_TEMP_CMD   0xF3
#define NO_HOLD_HUM_CMD    0xF5
#define PAIR_TEMP_CMD      0xE0
#define CRC8_POLY          0x31
#define CRC8_INIT          0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLY;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_write_cmd_arg(int fd, uint8_t cmd, uint8_t arg) {
    uint8_t buf[2] = {cmd, arg};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_cmd_arg: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_bytes: read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, float *out) {
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    struct timespec ts = {0, 1000000L}; /* 1 ms */
    nanosleep(&ts, NULL);

    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        uint8_t buf[3];
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;
        if (crc8(buf, 2) == buf[2]) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *out = (float)raw;
            return 0;
        }
        struct timespec sleep_ts = {0, 100000L}; /* 100 us */
        nanosleep(&sleep_ts, NULL);
    }
    fprintf(stderr, "read_measurement: timeout for cmd 0x%02X\n", cmd);
    return -1;
}

static int read_humidity(int fd, float *out) {
    if (i2c_write_cmd_arg(fd, NO_HOLD_HUM_CMD, RESET_CMD_ARG) < 0)
        return -1;
    if (i2c_write_cmd_arg(fd, NO_HOLD_HUM_CMD, RESET_CMD_ARG) < 0)
        return -1;
    if (read_measurement(fd, NO_HOLD_HUM_CMD, out) < 0)
        return -1;
    return 0;
}

static int read_temperature(int fd, float *out) {
    if (i2c_write_cmd_arg(fd, NO_HOLD_TEMP_CMD, RESET_CMD_ARG) < 0)
        return -1;
    if (i2c_write_cmd_arg(fd, NO_HOLD_TEMP_CMD, RESET_CMD_ARG) < 0)
        return -1;
    if (read_measurement(fd, NO_HOLD_TEMP_CMD, out) < 0)
        return -1;
    return 0;
}

static int reset_sensor(int fd) {
    return i2c_write_cmd(fd, RESET_CMD);
}

static int log_data(float temp, float hum, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si7021 greenhouse monitor started on %s (addr 0x%02X).\n", I2C_BUS, SI7021_ADDR);

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int ok = 0;

        if (read_humidity(g_i2c_fd, &hum) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            if (reset_sensor(g_i2c_fd) < 0) {
                fprintf(stderr, "Sensor reset failed.\n");
            }
            continue;
        }
        if (read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (reset_sensor(g_i2c_fd) < 0) {
                fprintf(stderr, "Sensor reset failed.\n");
            }
            continue;
        }
        ok = 1;

        if (log_data(temp, hum, "OK") < 0) {
            fprintf(stderr, "Logging failed.\n");
        } else {
            printf("T=%.2f C  H=%.2f %%\n", temp, hum);
        }

        for (int s = 0; s < READ_INTERVAL_SEC && g_running; s++)
            sleep(1);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

