    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si7021 greenhouse monitor started on %s (addr 0x%02X).\n", I2C_BUS, SI7021_ADDR);

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int ok = 0;

        if (read_humidity(g_i2c_fd, &hum) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            if (reset_sensor(g_i2c_fd) < 0) {
                fprintf(stderr, "Sensor reset failed.\n");
            }
            continue;
        }
        if (read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (reset_sensor(g_i2c_fd) < 0) {
                fprintf(stderr, "Sensor reset failed.\n");
            }
            continue;
        }
        ok = 1;

        if (log_data(temp, hum, "OK") < 0) {
            fprintf(stderr, "Logging failed.\n");
        } else {
            printf("T=%.2f C  H=%.2f %%\n", temp, hum);
        }

        for (int s = 0; s < READ_INTERVAL_SEC && g_running; s++)
            sleep(1);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

