#define TEMP_OUT_L 0x2B
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, int32_t *pressure) {
    uint8_t buf[3];
    if (read_block(handle, PRESS_OUT_XL, buf, 3) < 0) return -1;
    int32_t raw = ((int32_t)buf[2] << 16) | ((int32_t)buf[1] << 8) | buf[0];
    if (raw & 0x00800000) raw |= 0xFF000000;
    *pressure = raw;
    return 0;
}

static int read_temperature(int handle, int16_t *temperature) {
    uint8_t buf[2];
    if (read_block(handle, TEMP_OUT_L, buf, 2) < 0) return -1;
    *temperature = (int16_t)(((uint16_t)buf[1] << 8) | buf[0]);
    return 0;
}

static void log_data(FILE *fp, int32_t pressure, int16_t temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
