                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_temperature(i2c_handle, &temperature) < 0) {
            time_t t = time(NULL);
            struct tm tm;
            localtime_r(&t, &tm);
            fprintf(stderr, "%04d-%02d-%02d %02d:%02d:%02d, Error reading temperature\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        log_data(log_file, pressure, temperature);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

