#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  1.0   /* seconds */

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

static int init_circular_buffer(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++)
        cb->buffer[i] = 0.0f;
    return 0;
}

static float read_temperature(void)
{
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1000.0f;
    }

    /* pigpio returns bytes in little-endian order; STLM75 sends MSB first */
    uint16_t swapped = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));
    int16_t  value   = (int16_t)swapped;
    value >>= 7;                       /* right-justify 9-bit data */
    return (float)value / 2.0f;
}

static void update_circular_buffer(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void control_led(float avg_temp)
{
    gpioWrite(LED_GPIO, (avg_temp > TEMP_THRESHOLD) ? 1 : 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    CircularBuffer temp_buffer;
    if (init_circular_buffer(&temp_buffer) != 0) {
        fprintf(stderr, "Failed to initialise circular buffer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();
        if (temperature < -999.0f) {
            fprintf(stderr, "Skipping sample due to read error\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        update_circular_buffer(&temp_buffer, temperature);
        float avg_temp = 0.0f;
        if (temp_buffer.count > 0)
            avg_temp = temp_buffer.buffer[0] / temp_buffer.count;

        control_led(avg_temp);
        printf("Temperature: %.2f C, Average: %.2f C, LED: %s\n",
               temperature, avg_temp,
               (avg_temp > TEMP_THRESHOLD) ? "ON" : "OFF");

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

