#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200
#define CO2_THRESHOLD_OFF 0
#define CO2_THRESHOLD_LOW_OFF 800
#define CO2_THRESHOLD_LOW_LOW 1199
#define CO2_THRESHOLD_HIGH_HIGH 1200

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write command 0x%04X failed\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_read_data(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read %d bytes failed\n", len);
        return -1;
    }
    return 0;
}

static int scd30_init(void) {
    if (scd30_write_command(0x0202) != 0) return -1;
    gpioDelay(10000);
    if (scd30_write_command(0x0300) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int scd30_read_data(sensor_data_t *data) {
    uint8_t buf[18];
    if (scd30_read_data(buf, sizeof(buf)) != 0) return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature data\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on humidity data\n");
        return -1;
    }

    int co2_raw = (buf[0] << 8) | buf[1];
    int temp_raw = (buf[3] << 8) | buf[4];
    int hum_raw = (buf[6] << 8) | buf[7];

    data->co2 = co2_raw;
    data->temperature = temp_raw / 100.0f;
    data->humidity = hum_raw / 100.0f;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", ts, data->co2, data->temperature, data->humidity);
    fflush(log_file);
}

static void control_ventilation(int co2) {
    if (co2 < CO2_THRESHOLD_LOW_OFF) {
        printf("CO2: %d ppm - OFF\n", co2);
    } else if (co2 < CO2_THRESHOLD_LOW_LOW) {
        printf("CO2: %d ppm - LOW\n", co2);
    } else {
        printf("CO2: %d ppm - HIGH\n", co2);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_write_command(0x0202);
        gpioDelay(10000);
        scd30_write_command(0x0300);
        gpioDelay(10000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr 0x%02X)\n", SCD30_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (scd30_init() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("SCD30 monitoring started. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        sensor_data_t data;
        if (scd30_read_data(&data) == 0) {
            log_data(&data);
            control_ventilation(data.co2);
        } else {
            fprintf(stderr, "Warning: sensor read failed, retrying next cycle\n");
        }
        sleep(MEASUREMENT_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

