#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <string.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x2F
#define READ_LEN 9
#define DEFAULT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int i2c_bus;
    int i2c_address;
    int interval_ms;
    int max_retries;
} config_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device on bus %d, addr 0x%02X (pigpio error %d).\n",
                bus, addr, handle);
        return -1;
    }
    return handle;
}

static int start_sdp32(int handle) {
    char cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send start-measurement command to SDP32 (pigpio error %d).\n", result);
        return -1;
    }
    return 0;
}

static int read_sdp32(int handle, int16_t *pressure_raw, int16_t *temperature_raw, int16_t *scale_factor) {
    char buffer[READ_LEN];
    int result = i2cReadDevice(handle, buffer, READ_LEN);
    if (result != READ_LEN) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SDP32 (got %d bytes, pigpio error %d).\n",
                result, result);
        return -1;
    }

    if (crc8((uint8_t *)buffer, 2) != (uint8_t)buffer[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8((uint8_t *)buffer + 3, 2) != (uint8_t)buffer[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8((uint8_t *)buffer + 6, 2) != (uint8_t)buffer[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    *pressure_raw = (int16_t)(((uint8_t)buffer[0] << 8) | (uint8_t)buffer[1]);
    *temperature_raw = (int16_t)(((uint8_t)buffer[3] << 8) | (uint8_t)buffer[4]);
    *scale_factor = (int16_t)(((uint8_t)buffer[6] << 8) | (uint8_t)buffer[7]);
    return 0;
}

static void log_data(int16_t pressure_raw, int16_t temperature_raw, int16_t scale_factor, int interval_ms) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    float pressure_pa = (float)pressure_raw / (float)scale_factor;
    float temperature_c = (float)temperature_raw / 200.0f;

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure_pa, temperature_c);
    fflush(stdout);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = SDP32_ADDR,
        .interval_ms = DEFAULT_INTERVAL_MS,
        .max_retries = MAX_RETRIES
    };

    int opt;
    while ((opt = getopt(argc, argv, "i:m:r:")) != -1) {
        switch (opt) {
            case 'i':
                config.i2c_bus = atoi(optarg);
                break;
            case 'm':
                config.i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'r':
                config.max_retries = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-i i2c_bus] [-m i2c_address] [-r max_retries]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (config.max_retries <= 0) {
        fprintf(stderr, "Error: max_retries must be positive.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = initialize_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (start_sdp32(i2c_handle) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_failures = 0;
    while (!terminate) {
        int16_t pressure_raw = 0, temperature_raw = 0, scale_factor = 0;
        int success = 0;

        for (int attempt = 0; attempt < config.max_retries && !terminate; attempt++) {
            if (read_sdp32(i2c_handle, &pressure_raw, &temperature_raw, &scale_factor) == 0) {
                success = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (success) {
            log_data(pressure_raw, temperature_raw, scale_factor, config.interval_ms);
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: Failed to read SDP32 after %d attempts. Sensor may be disconnected.\n",
                    consecutive_failures);
            if (consecutive_failures >= config.max_retries) {
                fprintf(stderr, "Error: Max consecutive failures reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(config.interval_ms * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

