#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_CONFIG_T14  0x0800  /* bit 12 = 1 -> 14-bit T+RH, 14-bit resolution */
#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_INTERVAL_S   5
#define CONV_DELAY_MS       20     /* 14-bit conversion takes ~12 ms; 20 ms is safe */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_byte: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_bytes: write reg pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read the data bytes */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_bytes: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_init(int fd)
{
    /* Configure: 14-bit T+RH, 14-bit resolution, no heater, no interrupt */
    if (i2c_write_byte(fd, HDC1000_CONFIG_REG, HDC1000_CONFIG_T14) != 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint8_t data[4];

    /* Trigger a 14-bit T+RH conversion by writing the temperature register pointer */
    if (i2c_write_byte(fd, HDC1000_TEMP_REG, 0x00) != 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    /* Read 4 bytes: 2 temperature + 2 humidity */
    if (i2c_read_bytes(fd, HDC1000_TEMP_REG, data, sizeof(data)) != 0)
        return -1;

    uint16_t raw_temp = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_hum  = (uint16_t)((data[2] << 8) | data[3]);

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor may be absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at address 0x%02X. Sampling every %d s.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read HDC1000 data.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

