#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int handle, float *pressure) {
    char cmd[2] = {0x36, 0x08};
    char buf[3];
    int16_t raw;

    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x36 0x08)\n");
        return -1;
    }

    gpioDelay(10000);

    if (i2cReadDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw;
    return 0;
}

int main(void) {
    float pressure;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, MLX90833_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 pressure sensor reader started (bus %d, addr 0x%02X).\n",
           I2C_BUS, MLX90833_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_pressure(i2c_handle, &pressure) == 0) {
                success = 1;
                break;
            }
            gpioDelay(100000);
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to read pressure after %d attempts.\n", MAX_RETRIES);
            continue;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        if (timeinfo == NULL) {
            fprintf(stderr, "Error: localtime failed\n");
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(stdout);

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

