#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x60
#define PRESSURE_MSB   0xAA
#define PRESSURE_LSB   0xAB
#define SCALE_FACTOR   0.1f
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error (0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure)
{
    uint8_t msb = 0, lsb = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, PRESSURE_MSB) == 0 &&
            i2c_read_byte(fd, PRESSURE_MSB, &msb) == 0 &&
            i2c_write_byte(fd, PRESSURE_LSB) == 0 &&
            i2c_read_byte(fd, PRESSURE_LSB, &lsb) == 0) {
            uint16_t raw = ((uint16_t)msb << 8) | lsb;
            *pressure = (float)raw * SCALE_FACTOR;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES)
            usleep(10000);
    }
    return -1;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    fflush(stdout);

    while (g_running) {
        float pressure;
        if (read_pressure(g_fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("%s - Pressure: %.2f kPa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting cleanly.\n");
    if (g_fd >= 0)
        close(g_fd);
    return EXIT_SUCCESS;
}

