#define READ_INTERVAL  1.0
#define I2C_RETRY_COUNT 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_pressure(int handle, float *pressure_out) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * SCALE_FACTOR;
