    while (g_running) {
        rc = read_pressure(g_i2c_handle, &pressure);
        if (rc != 0) {
            fprintf(stderr, "I2C read error; re-initializing bus...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            sleep(I2C_RETRY_COUNT);
            g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "I2C re-open failed: %s\n", strerror(errno));
                break;
            }
            continue;
        }

        log_pressure(g_log_file, pressure);
        check_pressure_range(pressure);

        time_sleep(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

