#include <sys/stat.h>
#include <pigpio.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    uint8_t cmd = 0x00;
    uint8_t data[4];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 4) != 4) {
        fprintf(stderr, "Error reading 4 bytes from I2C device.\n");
        return -1;
    }

    if (data[3] & 0x80) {
        fprintf(stderr, "Sensor status bits indicate error (data[3]=0x%02X).\n", data[3]);
        return -1;
    }

    uint16_t raw_temperature = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_humidity = ((uint16_t)data[2] << 8) | data[3];

    *temperature = (float)raw_temperature * 165.0f / 16383.0f - 40.0f;
    *humidity = (float)raw_humidity * 100.0f / 16383.0f;

    return 0;
}

static int check_log_file_size(const char *path, off_t *size) {
    struct stat st;
    if (stat(path, &st) != 0) {
        perror("stat");
        return -1;
    }
    *size = st.st_size;
    return 0;
}

