#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define SENT_TIMEOUT_US 1000000
#define SENT_TICKS_PER_US (1000000 / TICK_US)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s, ERROR: %s\n", ts, msg);
}

static void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
        fclose(fp);
    } else {
        log_error("Failed to open pressure_log.txt");
    }
}

static int read_sent_nibble(int *ticks) {
    int count = 0;
    uint32_t start = gpioTick();
    while (count < 32 && running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) return -1;
        if (level != 0) count++;
        if (gpioTick() - start > SENT_TIMEOUT_US) return -2;
    }
    if (count < 32) return -3;
    *ticks = count;
    return 0;
}

static int read_sent_word(int *ticks) {
    int r1 = read_sent_nibble(ticks);
    if (r1 < 0) return r1;
    int r2 = read_sent_nibble(ticks + 1);
    if (r2 < 0) return r2;
    return r1 + r2;
}

static int read_sent_frame(int *ticks) {
    int status = 0;
    int raw = 0;
    int checksum = 0;

    if (read_sent_nibble(&ticks[0]) < 0) return -1;
    if (read_sent_nibble(&ticks[1]) < 0) return -2;
    if (read_sent_nibble(&ticks[2]) < 0) return -3;
    if (read_sent_nibble(&ticks[3]) < 0) return -4;

    status = ticks[0];
    raw = ticks[1] + (ticks[2] << 4);
    checksum = ticks[3] + (ticks[4] << 4);

    if (checksum < 0 || checksum > 15) return -5;
    if (status < 0 || status > 15) return -6;
    if (raw < 0 || raw > 1023) return -7;
    if (checksum != (status + raw) & 0F) return -8;
    *ticks = ticks[1] + ticks[2] + ticks[3] + ticks[4];
