#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_ID 0x01
#define TMP117_ID 0x0117
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp_c) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, TMP117_REG_TEMP, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (rc=%d)\n", rc);
        return -1;
    }
    int16_t raw = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *temp_c = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temp_c) {
    if (fwrite(&temp_c, sizeof(float), 1, log_file) != 1) {
        perror("fwrite failed");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X (rc=%d)\n", TMP117_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int id = i2cReadByteData(i2c_handle, TMP117_REG_ID);
    if (id != TMP117_ID) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%02X, expected 0x%04X\n", id, TMP117_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temp_c;
        if (read_temperature(&temp_c) == 0) {
            if (log_temperature(temp_c) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

