#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD  5
#define LOG_FILE       "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void circular_buffer_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void circular_buffer_add(CircularBuffer *cb, float temperature) {
    time(&cb->buffer[cb->head].timestamp);
    cb->buffer[cb->head].temperature = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int rc = i2cReadI2CBlockData(g_i2c_handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: rc=%d\n", rc);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static void log_buffer_to_file(const CircularBuffer *cb) {
    if (g_log_file == NULL) {
