#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHTC3_ADDR        0x70
#define SHTC3_CMD_MEASURE  0x7866  /* normal power, clock stretching disabled */
#define SHTC3_MEASURE_MS   12      /* max conversion time for 1.8 V supply */
#define LOG_FILE          "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5
#define I2C_BUS           1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t shtc3_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_reading(float temp, float rh) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, rh);
    fclose(fp);
    return 0;
}

static int read_shtc3(int handle, float *temp, float *rh) {
    uint8_t cmd[2] = { (uint8_t)(SHTC3_CMD_MEASURE >> 8), (uint8_t)(SHTC3_CMD_MEASURE & 0xFF) };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }

    gpioDelay(SHTC3_MEASURE_MS * 1000);  /* microseconds */

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (shtc3_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (shtc3_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    float t = 175.0f * (float)t_raw / 65535.0f - 45.0f;
    float rh = 100.0f * (float)h_raw / 65535.0f;

    if (t < -40.0f || t > 125.0f || rh < 0.0f || rh > 100.0f) {
        fprintf(stderr, "Out-of-range: T=%.2f C, RH=%.2f %%\n", t, rh);
        return -1;
    }

    *temp = t;
    *rh   = rh;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHTC3 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp, rh;
        if (read_shtc3(g_i2c_handle, &temp, &rh) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, rh);
            if (log_reading(temp, rh) != 0) {
                fprintf(stderr, "Warning: failed to log reading\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

