#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7202(int handle, float *field_gauss, float *temp_celsius) {
    char buf[2];
    int result;

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Si7202: expected 2 bytes, got %d\n", result);
        return -1;
    }

    int raw_value = (buf[0] << 8) | buf[1];
    *field_gauss = raw_value * 0.1f;
    *temp_celsius = raw_value * 0.01f - 25.0f;
    return 0;
}

static int log_data(FILE *fp, float field_gauss, float temp_celsius) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (isnan(field_gauss) || isnan(temp_celsius)) {
        fprintf(fp, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, field_gauss, temp_celsius);
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float field_gauss, temp_celsius;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SI7202_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
        fflush(log_file);
    }

    printf("Si7202 sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_si7202(i2c_handle, &field_gauss, &temp_celsius) == 0) {
            printf("Field: %.2f Gauss, Temp: %.2f C\n", field_gauss, temp_celsius);
            log_data(log_file, field_gauss, temp_celsius);
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values.\n");
        }
        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

