static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_bit(int gpio, uint32_t *out) {
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) < 0) return -1;
    uint32_t high_start = gpioTick();
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -1;
    uint32_t high_end = gpioTick();
    *out = (high_end - high_start) / 2;
    return 0;
}

static int read_dht11(int gpio, float *temperature, float *humidity) {
    uint32_t data[DHT11_BIT_COUNT];
    int status = 0;

    /* Start signal: pull low for >= 18 ms, then high for 40 us */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, 0) < 0) return -1;
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(gpio, 1) < 0) return -1;
    gpioDelay(DHT11_START_HIGH_US);

    /* Switch to input */
    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;

    /* Sensor response: 80 us low + 80 us high */
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) < 0) return -1;

    /* Read 40 data bits */
    for (int i = 0; i < DHT11_BIT_COUNT; i++) {
        if (read_bit(gpio, &data[i]) < 0) return -1;
        if (data[i] > DHT11_BIT_THRESHOLD_HIGH_US) {
            data[i] = 1;
        }
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        log_error(1, "Checksum mismatch");
        return -1;
    }

    /* Humidity: 16-bit, integer part in byte 0 */
    uint16_t raw_h = (uint16_t)((data[0] << 8) | data[1]);
    *humidity = (float)raw_h / 10.0f;

    /* Temperature: 16-bit, integer part in byte 2 */
    uint16_t raw_t = (uint16_t)((data[2] << 8) | data[3]);
    *temperature = (float)raw_t / 10.0f;

    return 0;
}

static void log_reading(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(g_log_file, "%s: Temperature: %.1f C, Humidity: %.1f %%\n", ts, temperature, humidity);
    fflush(g_log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_log_file = fopen("dht11_readings.txt", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("DHT11 sensor reader started");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int ret = read_dht11(DHT11_GPIO, &temperature, &humidity);

        if (ret == 0) {
            log_reading(temperature, humidity);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            log_error(ret, "Failed to read DHT11 sensor");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < DHT11_SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    log_message("DHT11 sensor reader stopped");
    fclose(g_log_file);
    gpioTerminate();
    return 0;
}

