#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT31_ADDR 0x44
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW  0x06
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEASURE_DELAY_US 20000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d: %d\n",
                SHT31_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(sensor_data_t *data) {
    uint8_t cmd[2] = { MEASURE_CMD_HIGH, MEASURE_CMD_LOW };
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            continue;
        }

        uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t hum_raw  = ((uint16_t)buf[3] << 8) | buf[4];

        data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        data->humidity    = 100.0f * (float)hum_raw / 65535.0f;
        return 0;
    }

    fprintf(stderr, "Sensor read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char timestamp[32];

            if (localtime_r(&now, &tm_info) == NULL) {
                fprintf(stderr, "localtime_r failed\n");
            } else {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
                fprintf(log_file, "%s,ERROR,read_failed\n", timestamp);
                fflush(log_file);
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

