#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define ADPD105_REG_DEVID 0x00
#define ADPD105_REG_RED_LSB 0x64
#define ADPD105_REG_GREEN_LSB 0x66
#define ADPD105_REG_BLUE_LSB 0x68
#define ADPD105_DEVID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register16(handle, ADPD105_REG_RED_LSB, red) < 0) return -1;
    if (read_register16(handle, ADPD105_REG_GREEN_LSB, green) < 0) return -1;
    if (read_register16(handle, ADPD105_REG_BLUE_LSB, blue) < 0) return -1;
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;
    float x = (r - g) / (g - b);
    float y = (r - b) / (g - b);
    float cct = 449.0f * powf(298.15f / (powf(y, 1.0f / 3.0f) + powf(x, 1.0f / 3.0f)), 3.0f) - 300.0f;
    if (cct < 0.0f) cct = 0.0f;
    if (cct > 6500.0f) cct = 6500.0f;
    return cct;
}

static int log_data(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, cct) < 0) return -1;
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    uint16_t red1, green1, blue1, red2, green2, blue2;
    float cct1, cct2, average_cct;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (err=%d)\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X (err=%d)\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    int devid1 = i2cReadByteData(i2c_handle1, ADPD105_REG_DEVID);
    if (devid1 != ADPD105_DEVID) {
        fprintf(stderr, "Error: Sensor 1 (0x%02X) DEVID mismatch: got 0x%02X, expected 0x%02X\n", SENSOR1_ADDR, devid1, ADPD105_DEVID);
        cleanup();
        return 1;
    }

    int devid2 = i2cReadByteData(i2c_handle2, ADPD105_REG_DEVID);
    if (devid2 != ADPD105_DEVID) {
        fprintf(stderr, "Error: Sensor 2 (0x%02X) DEVID mismatch: got 0x%02X, expected 0x%02X\n", SENSOR2_ADDR, devid2, ADPD105_DEVID);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    printf("Starting ADPD105 CCT logging (bus %d, 0x%02X, 0x%02X)...\n", I2C_BUS, SENSOR1_ADDR, SENSOR2_ADDR);

    while (running) {
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 1 data\n");
        } else if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 2 data\n");
        } else {
            cct1 = calculate_cct(red1, green1, blue1);
            cct2 = calculate_cct(red2, green2, blue2);
            average_cct = (cct1 + cct2) / 2.0f;
            if (log_data(average_cct) < 0) {
                fprintf(stderr, "Error: Failed to write to log file\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

