#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMP_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_pressure(int handle, float *pressure_kPa) {
    uint16_t raw;
    if (read_register16(handle, PRESSURE_REG, &raw) != 0) {
        return -1;
    }
    *pressure_kPa = ((float)raw - 0.0f) * (800.0f - 0.0f) / 32768.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature_C) {
    uint16_t raw;
    if (read_register16(handle, TEMP_REG, &raw) != 0) {
        return -1;
    }
    *temperature_C = (float)raw * 0.01f - 40.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tire Pressure Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float pressure, temperature;
        int pressure_ok = read_pressure(i2c_handle, &pressure);
        int temp_ok = read_temperature(i2c_handle, &temperature);

        if (pressure_ok == 0 && temp_ok == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            if (pressure_ok != 0) {
                log_error(log_file, "Failed to read pressure register");
            }
            if (temp_ok != 0) {
                log_error(log_file, "Failed to read temperature register");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

