#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define STTS2004_ADDR   0x4A
#define STTS2004_TEMP_REG 0x00
#define LED_GPIO        17
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define POLL_INTERVAL_SEC  1
#define MAX_I2C_RETRIES   3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (out == NULL)
        return -1;

    for (int attempt = 0; attempt < MAX_I2C_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            usleep(10000);
            continue;
        }

        uint8_t buf[2];
        ssize_t n = read(fd, buf, 2);
        if (n != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): got %zd bytes, %s\n",
                    reg, attempt + 1, n, n < 0 ? strerror(errno) : "short read");
            usleep(10000);
            continue;
        }

        *out = ((uint16_t)buf[0] << 8) | buf[1];
        return 0;
    }

    return -1;
}

static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, STTS2004_TEMP_REG, &raw) != 0) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_I2C_RETRIES);
        return -1;
    }

    *temp_c = (float)((int16_t)raw) * 0.0625f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "stts2004-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int ret = EXIT_SUCCESS;

    while (g_running) {
        float temp_c;
        if (read_temperature(i2c_fd, &temp_c) != 0) {
            ret = EXIT_FAILURE;
            break;
        }

        int led_val = (temp_c > TEMP_THRESHOLD_HIGH) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_val) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        printf("Temperature: %.2f °C, LED: %s\n",
               temp_c, led_val ? "ON" : "OFF");
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return ret;
}

