#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define CMD_MEASURE_RH_NOH 0xF5
#define CMD_MEASURE_TEMP_NOH 0xF3
#define CMD_READ_TEMP     0xE0
#define MEASURE_DELAY_US  20000   /* 20 ms for no-hold measurement */
#define SAMPLE_INTERVAL  60      /* seconds */
#define MAX_RETRIES      3
#define LOG_FILE         "environment.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7021 (no register addressing). */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read 2 bytes of data from the Si7021 (no register addressing). */
static int si7021_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %d bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* Read temperature from the Si7021 after a previous RH measurement. */
static int read_temperature(int handle, float *temperature)
{
    uint8_t buf[2];
    if (si7021_read_bytes(handle, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* Read humidity from the Si7021 after a previous RH measurement. */
static int read_humidity(int handle, float *humidity)
{
    uint8_t buf[2];
    if (si7021_read_bytes(handle, buf, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *humidity = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

/* Read temperature and humidity from the Si7021 in one measurement cycle. */
static int read_sensor(int handle, float *temperature, float *humidity)
{
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NOH) < 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint8_t buf[4];
    if (si7021_read_bytes(handle, buf, 4) < 0)
        return -1;

    uint16_t raw_rh = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp = ((uint16_t)buf[2] << 8) | buf[3];

    *humidity = (125.0f * (float)raw_rh / 65536.0f) - 6.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    *temperature = (175.72f * (float)raw_temp / 65536.0f) - 46.85f;

    return 0;
}

static void log_data(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(stdout);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s,ERROR,%s\n", timestamp, msg);
    fflush(fp);

    fprintf(stderr, "%s,ERROR,%s\n", timestamp, msg);
    fflush(stderr);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading the electronic ID (0x84 0x00 0x00 0x00). */
    uint8_t id[8];
    if (si7021_read_bytes(g_i2c_handle, id, 8) < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X — check wiring and address.\n",
                SI7021_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] Si7021 detected (electronic ID verified).\n");

    while (g_running) {
        float temperature, humidity;

        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor(g_i2c_handle, &temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] read_sensor attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (ok) {
            log_data(temperature, humidity);
        } else {
            log_error("Sensor read failed after retries");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\n[INFO] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

