#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define HDC1080_REG_TEMP 0x00
#define HDC1080_REG_HUM 0x01
#define HDC1080_REG_CONFIG 0x02
#define HDC1080_CONFIG_14BIT 0x0B
#define CONVERSION_DELAY_US 20000
#define LOG_FILE "enviro_log.txt"
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(void) {
    if (i2cWriteByteData(i2c_handle, HDC1080_REG_CONFIG, HDC1080_CONFIG_14BIT) < 0) {
        fprintf(stderr, "Error: Failed to write HDC1080 config register\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read(float *temperature, float *humidity) {
    char buf[4];
    int rc;

    rc = i2cWriteByte(i2c_handle, HDC1080_REG_TEMP);
    if (rc < 0) {
        fprintf(stderr, "Error: Failed to set temperature register pointer\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    rc = i2cReadDevice(i2c_handle, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "Error: Failed to read 4 bytes from HDC1080 (got %d)\n", rc);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_hum = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (handle=%d)\n", HDC1080_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init() < 0) {
        fprintf(stderr, "Error: HDC1080 sensor not detected or init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HDC1080 initialized. Logging every %d seconds. Press Ctrl+C to exit.\n", POLL_INTERVAL_S);

    while (running) {
        if (hdc1080_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) < 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

