#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_INTERVAL_SEC 60
#define READ_INTERVAL_SEC 5
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_DIR "/var/log/scd40_error.log"

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t log_thread_active = 0;
static pthread_t log_thread_id;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_DIR "/scd40_error.log", "a");
    if (!fp) {
        perror("Error opening error log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed for command 0x%04X (rc=%d)", cmd, rc);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed (rc=%d)", rc);
        log_error(msg);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        char msg[128];
        snprintf(msg, sizeof(msg), "CRC error in CO2 data");
        log_error(msg);
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        char msg[128];
        snprintf(msg, sizeof(msg), "CRC error in temperature data");
        log_error(msg);
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        char msg[128];
        snprintf(msg, sizeof(msg), "CRC error in humidity data");
        log_error(msg);
        return -1;
    }

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];

    *co2 = co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static void log_data(const circular_buffer_t *cb) {
    FILE *fp = fopen(LOG_DIR "/scd40_data.csv", "w");
    if (!fp) {
        log_error("Failed to open CSV file for writing");
        return;
    }
    fprintf(fp, "timestamp,co2_ppm,temperature_c,humidity_pct\n");
    pthread_mutex_lock(&cb->mutex);
    int start = (cb->count == BUFFER_SIZE) ? cb->tail : cb->head;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&cb->data[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, cb->data[idx].co2, cb->data[idx].temperature, cb->data[idx].humidity);
    }
    fclose(fp);
    pthread_mutex_unlock(&cb->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!log_thread_active) {
            log_thread_active = 1;
            pthread_create(&log_thread_id, NULL, log_data, &buffer);
        }
    }
    pthread_exit(NULL);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    log_thread_active = 0;
    pthread_join(log_thread_id, NULL);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(CMD_START_PERIODIC) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    sleep(1);

    while (running) {
        uint16_t co2;
        float temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            buffer_add(&buffer, data);
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (send_command(CMD_STOP_PERIODIC) != 0) {
        log_error("Failed to stop periodic measurement");
    }
    pthread_mutex_lock(&buffer.mutex);
    log_data(&buffer);
    pthread_mutex_unlock(&buffer.mutex);
    pthread_mutex_destroy(&buffer.mutex);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

