#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_CHIP       "gpiochip4"
#define LED_OFFSET     17
#define PRESSURE_THRESHOLD 95000.0f
#define POLL_INTERVAL_US 1000000
#define MEAS_DELAY_US   20000
#define HIGH_ACC_CMD    0x4011

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as per InvenSense datasheet */
static uint8_t icp_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n) {
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)r;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t *c0, uint16_t *c1,
                            uint16_t *c2, uint16_t *c3) {
    uint8_t reg = 0x66;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to set OTP register pointer: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[8];
    if (i2c_read_n(fd, buf, 8) < 0) return -1;
    *c0 = (uint16_t)((buf[0] << 8) | buf[1]);
    *c1 = (uint16_t)((buf[2] << 8) | buf[3]);
    *c2 = (uint16_t)((buf[4] << 8) | buf[5]);
    *c3 = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int read_measurement(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, HIGH_ACC_CMD) < 0) return -1;
    usleep(MEAS_DELAY_US);
    uint8_t buf[6];
    if (i2c_read_n(fd, buf, 6) < 0) return -1;
    if (icp_crc8(buf, 2) != buf[2] || icp_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)buf[0] << 8) | buf[1];
    uint32_t raw_t = ((uint32_t)buf[3] << 8) | buf[4];
    *pressure = (float)raw_p / 256.0f;
    *temperature = (float)raw_t / 256.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t c0, c1, c2, c3;
    if (read_calibration(fd, &c0, &c1, &c2, &c3) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", LED_CHIP, strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_OFFSET);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "icp10125_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n", LED_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("ICP-10125 monitoring started (addr 0x%02X). Press Ctrl+C to exit.\n", ICP10125_ADDR);

    while (running) {
        float pressure, temperature;
        if (read_measurement(fd, &pressure, &temperature) < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        int led_val = 0;
        if (pressure < PRESSURE_THRESHOLD) {
            led_val = 1;
            printf("Pressure below threshold (%.0f Pa). LED warning active.\n", PRESSURE_THRESHOLD);
        } else {
            led_val = 0;
        }

        if (gpiod_line_set_value(led, led_val) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        }

        /* Blink at 1 Hz under normal, 5 Hz when warning */
        if (led_val) {
            usleep(500000);
            usleep(500000);
        } else {
            usleep(500000);
            usleep(500000);
            usleep(500000);
            usleep(500000);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

