        /* Blink at 1 Hz under normal, 5 Hz when warning */
        if (led_val) {
            usleep(500000);
            usleep(500000);
        } else {
            usleep(500000);
            usleep(500000);
            usleep(500000);
            usleep(500000);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

