#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS        1
#define MLX90614_ADDR  0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO        18
#define TEMP_HYSTERESIS 30.0
#define TEMP_HYSTERESIS_LOW 28.0
#define LOG_FILE        "temperature_log.txt"
#define READ_INTERVAL_S 2
#define MAX_RETRIES     3
#define RETRY_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature_raw(int handle, uint8_t reg, float *out_celsius) {
    int raw = -1;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadWordData(handle, reg);
        if (rc >= 0) {
            raw = rc;
            break;
        }
        fprintf(stderr, "Warning: I2C read failed (reg 0x%02X, attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    if (raw < 0) {
        fprintf(stderr, "Error: Failed to read temperature from register 0x%02X after %d attempts.\n",
                reg, MAX_RETRIES);
        return -1;
    }
    *out_celsius = (float)raw * 0.02f - 273.15f;
    return 0;
}

static int control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_HYSTERESIS && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (object T=%.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Error: Failed to turn fan ON (GPIO %d)\n", FAN_GPIO);
        }
    } else if (object_temp < TEMP_HYSTERESIS_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (object T=%.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Error: Failed to turn fan OFF (GPIO %d)\n", FAN_GPIO);
        }
    }
    return 0;
}

static int log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    } else {
        fprintf(stderr, "Warning: localtime_r failed\n");
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (rc=%d).\n",
                I2C_BUS, MLX90614_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90614 temperature monitor started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float ambient = -273.15f;
        float object = -273.15f;

        if (read_temperature_raw(g_i2c_handle, AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Skipping cycle: ambient read failed.\n");
        } else if (read_temperature_raw(g_i2c_handle, OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Skipping cycle: object read failed.\n");
        } else {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            control_fan(object);
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Warning: failed to log temperatures.\n");
            }
        }

        for (int i = 0; i < READ_INTERVAL_S && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

