#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static int i2c_handle = -1;
static int server_fd = -1;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = MEASURE_CMD;
    unsigned char data[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(10000);
            continue;
        }

        unsigned int raw_temperature = (data[0] << 8) | data[1];
        unsigned int raw_humidity = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    return -1;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

int setup() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_error("Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_error("setsockopt failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        log_error("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup() {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set signal handlers");
        return 1;
    }

    if (setup() != 0) {
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        float temperature, humidity;
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            char html[256];
            snprintf(html, sizeof(html),
                     "HTTP/1.1 200 OK\r\n"
                     "Content-Type: text/html\r\n"
                     "Connection: close\r\n"
                     "\r\n"
                     "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body>"
                     "<h1>SHT40 Sensor Data</h1>"
                     "<p>Temperature: %.2f &deg;C</p>"
                     "<p>Humidity: %.2f %%</p>"
                     "</body></html>",
                     temperature, humidity);

            if (send(server_fd, html, strlen(html), 0) < 0) {
                log_error("Failed to send HTTP response");
            }
        } else {
            log_error("Failed to read SHT40 sensor after retries");
        }

        sleep(1);
    }

    cleanup();
    printf("Server shut down cleanly.\n");
    return 0;
}

