#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temp_c) {
    char buf[2];
    int ret = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((uint16_t)buf[0] << 8 | (uint8_t)buf[1]);
    raw >>= 4;
    *temp_c = (float)raw * 0.0625f;
    return 0;
}

static int log_temperature(const char *filename, float temp_c) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
