#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define HDC2010_REG_TEMP_L  0x00
#define HDC2010_REG_TEMP_H  0x01
#define HDC2010_REG_HUM_L   0x02
#define HDC2010_REG_HUM_H   0x03
#define HDC2010_REG_CONFIG  0x0F
#define HDC2010_REG_MEAS_CFG 0x0E

#define MEAS_CFG_ONE_SHOT   0x01
#define MEAS_CFG_TEMP_HUM   0x00
#define MEAS_CFG_TEMP_ONLY   0x10
#define MEAS_CFG_HUM_ONLY    0x20
#define MEAS_CFG_OFF         0x00

#define I2C_BUS             1
#define POLL_TIMEOUT_MS     500
#define SAMPLE_INTERVAL_S   5
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int hdc2010_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

static int hdc2010_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int hdc2010_read_word(int handle, uint8_t reg_l, uint16_t *out)
{
    uint8_t lo, hi;
    if (hdc2010_read_reg(handle, reg_l, &lo) != 0)
        return -1;
    if (hdc2010_read_reg(handle, reg_l + 1, &hi) != 0)
        return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int hdc2010_trigger_measurement(int handle)
{
    if (hdc2010_write_reg(handle, HDC2010_REG_MEAS_CFG, MEAS_CFG_ONE_SHOT) != 0)
        return -1;
    return 0;
}

static int hdc2010_wait_for_data(int handle)
{
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t cfg;
        if (hdc2010_read_reg(handle, HDC2010_REG_CONFIG, &cfg) != 0)
            return -1;
        if ((cfg & MEAS_CFG_ONE_SHOT) == 0)
            return 0;
        gpioDelay(1000);
    }
    fprintf(stderr, "Timeout waiting for measurement (CONFIG=0x%02X)\n", cfg);
    return -1;
}

