        return -1;
    if (hdc2010_read_word(handle, HDC2010_REG_HUM_L, &raw_hum) != 0)
        return -1;

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum / 65536.0f) * 100.0f;

    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Warning: humidity out of range: %.2f%%\n", *humidity);
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n",
                I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HDC2010 sensor reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, HDC2010_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;
        int rc = hdc2010_read(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed (rc=%d). Attempting recovery...\n", rc);
            if (g_i2c_handle >= 0) {
                i2cClose(g_i2c_handle);
                g_i2c_handle = -1;
            }
            gpioDelay(1000000);
            g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Recovery failed: pigpio rc=%d\n", g_i2c_handle);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

