/*
 * PID-controlled reflow oven for Raspberry Pi 3 Model B+
 * MAX6675 thermocouple over SPI0 (CE0/CE1), solid-state relay on GPIO17
 * Reads a target temperature profile from profile.txt and logs to reflow_log.csv
 *
 * Build: gcc -O2 -Wall -o reflow reflow.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define RELAY_GPIO_LINE 17
#define GPIO_CHIP_NAME  "gpiochip0"

#define TARGET_TEMP_FILE "profile.txt"
#define LOG_FILE         "reflow_log.csv"

#define SAMPLE_INTERVAL_US 1000000  /* 1 second */
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay_line = NULL;

/* PID state */
static float Kp = 1.0f;
static float Ki = 0.01f;
static float Kd = 0.01f;
static float integral = 0.0f;
static float prev_error = 0.0f;
static float last_valid_temp = 0.0f;
static time_t last_valid_time = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_relay_line = gpiod_chip_get_line(g_chip, RELAY_GPIO_LINE);
    if (!g_relay_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", RELAY_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_relay_line, "reflow-oven", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", RELAY_GPIO_LINE, strerror(errno));
        g_relay_line = NULL; gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    return 0;
}

static int read_max6675(uint16_t *raw_temp) {
    uint8_t tx[2] = {0x01, 0x00};
    uint8_t rx[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static float calculate_temperature(uint16_t raw) {
    if (raw & 0x0002) {
        fprintf(stderr, "MAX6675 open-circuit flag set\n");
        return -273.15f;
    }
    int16_t temp = (int16_t)(raw >> 4);
    return (float)temp * 0.25f;
}

static void control_relay(float pid_output) {
    if (g_relay_line) {
        int duty = (int)(pid_output * 255.0f);
        if (duty < 0) duty = 0;
        if (duty > 255) duty = 255;

        if (gpiod_line_set_value(g_relay_line, duty) < 0) {
            fprintf(stderr, "Error setting relay GPIO value: %s\n", strerror(errno));
        }
    }
}

static void log_data(float temperature) {
    if (!g_log_fp) return;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(g_log_fp, "%s,%.2f\n", ts, temperature);
    fflush(g_log_fp);
}

static void load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s. Using default profile.\n", filename, strerror(errno));
        return;
    }

    char line[256];
    float target_temp = 0.0f;
    time_t target_time = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *t = strtok(line, ",\r\n");
        if (!t) continue;
        char *s = strtok(NULL, ",\r\n");
        if (!s) continue;

        char *endptr;
        float time = strtof(s, &endptr);
        if (*endptr != '\0' || time <= 0.0f) continue;

        char *temp_end;
        float target = strtof(t, &temp_end);
        if (*temp_end != '\0' || target <= 0.0f) continue;

        if (target_time == 0) {
            target_time = time;
        } else if (difftime(time, target_time) < 60.0f) {
            fprintf(stderr, "Profile out of order at %s\n", t);
            continue;
        }

        target_temp = target;
    }

    fclose(fp);
    printf("Profile loaded: time=%.2f, target=%.2f\n", target_time, target_temp);
}

static void cleanup(void) {
    if (g_relay_line) {
        gpiod_line_set_value(g_relay_line, 0);
        gpiod_line_release(g_relay_line);
        g_relay_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) return 1;
    if (gpio_init() < 0) {
        close(g_spi_fd); g_spi_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature(C)\n");
        fflush(g_log_fp);
    }

    load_profile(TARGET_TEMP_FILE);

    printf("Starting reflow cycle. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_max6675(&raw) == 0) {
                success = 1;
                break;
            }
            retries++;
            usleep(10000);
        }

        if (!success) {
            fprintf(stderr, "MAX6675 read failed after %d retries. Continuing.\n", MAX_RETRIES);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = calculate_temperature(raw);
        time_t now = time(NULL);

        if (difftime(now, last_valid_time) >= 5.0f) {
            last_valid_time = now;
            last_valid_temp = temperature;
        }

        float error = temperature - last_valid_temp;
        integral += error;
        if (integral > 255.0f) integral = 255.0f;
        if (integral < 0.0f) integral = 0.0f;

        float derivative = error - prev_error;
        float output = Kp * error + Ki * integral + Kd * derivative;

        control_relay(output);
        log_data(temperature);

        prev_error = error;
        printf("T=%.2f C  Err=%.2f C  PID=%.2f\n", temperature, error, output);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

