#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>

#define HEATER_RELAY_PIN 17
#define HEATER_PWM_PIN 18
#define TEMP_SENSOR_PATH "/sys/bus/w1/devices/28-000005b5e1e4/w1_slave"
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static double setpoint = 20.0;
static double Kp = 1.0, Ki = 0.1, Kd = 0.01;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(double *temp_out) {
    FILE *fp = fopen(TEMP_SENSOR_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_SENSOR_PATH, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading temperature sensor: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (!strstr(line1, "YES")) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    char *t = strstr(line2, "t=");
    if (!t) {
        fprintf(stderr, "Temperature value not found\n");
        return -1;
    }
    long raw = strtol(t + 2, NULL, 10);
    *temp_out = (double)raw / 1000.0;
    return 0;
}

static void control_heater(double temp, double setpoint, double *pid_out) {
    double error = setpoint - temp;
    double integral = 0.0;
    double prev_error = 0.0;

    integral += error;
    *pid_out = Kp * error + Ki * integral + Kd * (error - prev_error);

    if (*pid_out < 0) *pid_out = 0;
    if (*pid_out > 100) *pid_out = 100;

    int pwm_val = (int)(*pid_out);
    if (gpiod_line_set_value(pwm_line, pwm_val) < 0) {
        fprintf(stderr, "Error setting PWM value: %s\n", strerror(errno));
    }
}

static void log_data(double temp, double setpoint, double pid_out, int pwm_val) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temp: %.2f, Setpoint: %.2f, PID: %.2f, PWM: %d\n",
            timestamp, temp, setpoint, pid_out, pwm_val);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        fprintf(stderr, "  setpoint: temperature in Celsius\n");
        fprintf(stderr, "  Kp, Ki, Kd: PID gains\n");
        return EXIT_FAILURE;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    if (setpoint <= 0 || Kp <= 0 || Ki <= 0 || Kd <= 0) {
        fprintf(stderr, "Invalid parameters. Setpoint must be positive, gains must be non-zero.\n");
        return EXIT_FAILURE;
