        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, HEATER_RELAY_PIN);
    pwm_line = gpiod_chip_get_line(chip, HEATER_PWM_PIN);
    if (!relay_line || !pwm_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "heater-relay", 0) < 0) {
        fprintf(stderr, "Error requesting relay line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pwm_line, "heater-pwm", 0) < 0) {
        fprintf(stderr, "Error requesting PWM line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse heater controller started. Setpoint: %.2f C, Kp: %.2f, Ki: %.2f, Kd: %.2f\n",
           setpoint, Kp, Ki, Kd);

    while (running) {
        double temp;
        if (read_temperature(&temp) == 0) {
            double pid_out;
            control_heater(temp, setpoint, &pid_out);
            log_data(temp, setpoint, pid_out, 0);
            printf("Temp: %.2f C, PID: %.2f, PWM: 0\n", temp, pid_out);
        } else {
