#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define AHT20_ADDR 0x38
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define HUMIDITY_THRESHOLD_HIGH 60.0f
#define HUMIDITY_THRESHOLD_LOW 55.0f
#define POLL_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb, uint8_t xlsb) {
    uint8_t buf[3] = {msb, lsb, xlsb};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 3) == 3) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) return -1;
    usleep(15000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    if (i2c_write_cmd(fd, 0xAC, 0x33, 0x00) < 0) return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_data(fd, data, 6) < 0) return -1;

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 not calibrated or busy\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)data[1] << 12) |
                   ((uint32_t)data[2] << 4) |
                   ((uint32_t)data[3] >> 4);

    *humidity = ((float)raw / 1048576.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay, "dehumidifier", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int ret = 0;
    while (running) {
        float humidity;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);
            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    perror("gpiod_line_set_value HIGH");
                }
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    perror("gpiod_line_set_value LOW");
                }
            }
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return ret;
}

