#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL_SEC 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    syslog(LOG_INFO, "I2C bus opened and HTU21D sensor 0x%02X selected", HTU21D_ADDR);
    return fd;
}

static int i2c_read_humidity(int fd, float *humidity) {
    unsigned char cmd = 0x2E; /* Start relative humidity measurement */
    unsigned char buf[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &cmd, 1) != 1) {
            syslog(LOG_ERR, "I2C write failed (cmd 0x%02X): %s", cmd, strerror(errno));
            retries++;
            usleep(100000);
            continue;
        }

        usleep(20000); /* 20 ms measurement wait */

        if (read(fd, buf, 4) != 4) {
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            retries++;
            usleep(100000);
            continue;
        }

        if (buf[3] != (buf[0] + buf[1] + buf[2] & 0xFF)) {
            syslog(LOG_ERR, "CRC mismatch on humidity data");
            retries++;
            usleep(100000);
            continue;
        }

        unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
        *humidity = (float)raw / 10.0f;
        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

static int http_post(const char *json) {
    struct sockaddr_in server_addr;
    char response[1024];
    char request[1024];
    int retry_count = 0;

    while (retry_count < MAX_RETRIES) {
        sock_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (sock_fd < 0) {
            syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
            retry_count++;
            sleep(1);
            continue;
        }

        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(80);

        if (gethostbyname("api.example.com") == NULL) {
            syslog(LOG_ERR, "DNS resolution failed for api.example.com");
            close(sock_fd);
            sock_fd = -1;
            retry_count++;
            sleep(1);
            continue;
        }

        if (inet_pton(AF_INET, "api.example.com", &server_addr) <= 0) {
            syslog(LOG_ERR, "Invalid address/addr family");
            close(sock_fd);
            sock_fd = -1;
            retry_count++;
            sleep(1);
            continue;
        }

        if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            syslog(LOG_ERR, "Connection to %s failed: %s", API_ENDPOINT, strerror(errno));
            close(sock_fd);
            sock_fd = -1;
            retry_count++;
            sleep(1);
            continue;
        }

        snprintf(request, sizeof(request),
                 "POST %s HTTP/1.1\r\n"
                 "Host: api.example.com\r\n"
                 "Content-Type: application/json\r\n"
                 "Content-Length: %zu\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "%s",
                 API_ENDPOINT, strlen(json), json);

