#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define SAMPLE_INTERVAL_US 2000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static bmp280_calib_t calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    return (bytes == (int)len) ? 0 : -1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_calibration(int handle) {
    uint8_t buf[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, buf, sizeof(buf)) != 0) return -1;
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)calib.dig_P3) >> 8) + ((var1 * (int64_t)calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)calib.dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (uint32_t)p;
}

static int read_raw_data(int handle, int32_t *raw_T, int32_t *raw_P) {
    uint8_t buf[6];
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    gpioDelay(10000);
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0) return -1;
    *raw_P = (int32_t)(((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4));
    *raw_T = (int32_t)(((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | ((uint32_t)buf[5] >> 4));
    return 0;
}

static void log_breach(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Pressure breach: %.2f hPa\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    uint8_t chip_id = 0;
    int retry = 0;
    do {
        if (i2c_read_block(i2c_handle, BMP280_REG_CHIP_ID, &chip_id, 1) == 0 && chip_id == BMP280_CHIP_ID) {
            break;
        }
        fprintf(stderr, "Chip ID mismatch (got 0x%02X, expected 0x%02X). Retrying...\n", chip_id, BMP280_CHIP_ID);
        gpioDelay(100000);
        retry++;
    } while (retry < MAX_RETRIES);

    if (retry == MAX_RETRIES) {
        fprintf(stderr, "BMP280 not detected after %d retries.\n", MAX_RETRIES);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int32_t raw_T, raw_P;
        if (read_raw_data(i2c_handle, &raw_T, &raw_P) != 0) {
            fprintf(stderr, "I2C read error. Re-initialising bus...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C. Retrying in 2 s...\n");
                gpioDelay(SAMPLE_INTERVAL_US);
                continue;
            }
            uint8_t id = 0;
            do {
                if (i2c_read_block(i2c_handle, BMP280_REG_CHIP_ID, &id, 1) == 0 && id == BMP280_CHIP_ID) break;
                gpioDelay(100000);
            } while (retry < MAX_RETRIES);
            if (retry == MAX_RETRIES) {
                fprintf(stderr, "BMP280 not detected after re-init. Exiting.\n");
                terminate = 1;
                break;
            }
            if (read_calibration(i2c_handle) != 0) {
                fprintf(stderr, "Failed to re-read calibration. Exiting.\n");
                terminate = 1;
                break;
            }
            continue;
        }

        int32_t temp = compensate_temperature(raw_T);
        uint32_t press = compensate_pressure(raw_P);
        float pressure = (float)press / 100.0f;

        if (pressure > PRESSURE_THRESHOLD_HIGH) {
            log_breach(pressure);
        } else if (pressure < PRESSURE_THRESHOLD_LOW) {
            log_breach(pressure);
        }

        printf("Pressure: %.2f hPa\n", pressure);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

