    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (uint32_t)p;
}

static int read_raw_data(int handle, int32_t *raw_T, int32_t *raw_P) {
    uint8_t buf[6];
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) return -1;
    gpioDelay(10000);
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, buf, 6) != 0) return -1;
    *raw_P = (int32_t)(((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4));
    *raw_T = (int32_t)(((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | ((uint32_t)buf[5] >> 4));
    return 0;
}

static void log_breach(float pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Pressure breach: %.2f hPa\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    uint8_t chip_id = 0;
    int retry = 0;
    do {
        if (i2c_read_block(i2c_handle, BMP280_REG_CHIP_ID, &chip_id, 1) == 0 && chip_id == BMP280_CHIP_ID) {
            break;
        }
        fprintf(stderr, "Chip ID mismatch (got 0x%02X, expected 0x%02X). Retrying...\n", chip_id, BMP280_CHIP_ID);
        gpioDelay(100000);
        retry++;
    } while (retry < MAX_RETRIES);

    if (retry == MAX_RETRIES) {
        fprintf(stderr, "BMP280 not detected after %d retries.\n", MAX_RETRIES);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int32_t raw_T, raw_P;
        if (read_raw_data(i2c_handle, &raw_T, &raw_P) != 0) {
            fprintf(stderr, "I2C read error. Re-initialising bus...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C. Retrying in 2 s...\n");
                gpioDelay(SAMPLE_INTERVAL_US);
                continue;
            }
            uint8_t id = 0;
            do {
                if (i2c_read_block(i2c_handle, BMP280_REG_CHIP_ID, &id, 1) == 0 && id == BMP280_CHIP_ID) break;
                gpioDelay(100000);
            } while (retry < MAX_RETRIES);
            if (retry == MAX_RETRIES) {
                fprintf(stderr, "BMP280 not detected after re-init. Exiting.\n");
                terminate = 1;
                break;
            }
            if (read_calibration(i2c_handle) != 0) {
                fprintf(stderr, "Failed to re-read calibration. Exiting.\n");
                terminate = 1;
                break;
            }
            continue;
        }

        int32_t temp = compensate_temperature(raw_T);
        uint32_t press = compensate_pressure(raw_P);
        float pressure = (float)press / 100.0f;

        if (pressure > PRESSURE_THRESHOLD_HIGH) {
            log_breach(pressure);
        } else if (pressure < PRESSURE_THRESHOLD_LOW) {
            log_breach(pressure);
        }

        printf("Pressure: %.2f hPa\n", pressure);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

