#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_PIN 17
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define LOG_FILE_PREFIX "sensor_data_"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint8_t cmd[2] = {0x00, 0x00};
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);
    uint8_t buf[2];
    if (i2c_read(fd, buf, 2) < 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw * 0.0078125f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    if (i2c_write(fd, init_cmd, 3) < 0) return -1;
    usleep(15000);
    uint8_t cmd[3] = {0xAC, 0x33, 0x00};
    if (i2c_write(fd, cmd, 3) < 0) return -1;
    usleep(20000);
    uint8_t buf[7];
    if (i2c_read(fd, buf, 7) < 0) return -1;
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }
    uint32_t raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
    *hum = (float)raw * 0.1f;
    return 0;
}

static int read_pir(struct gpiod_line *line, int *motion) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
        return -1;
    }
    *motion = val;
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm);
}

static int create_log_file(const char *prefix) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char filename[64];
    strftime(filename, sizeof(filename), "%Y-%m-%d_%H%M.log", tm);
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to create log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set TMP117 as slave: %s\n", strerror(errno));
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set AHT20 as slave: %s\n", strerror(errno));
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Starting sensor logging...\n");

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        char ts[32];
        char filename[64];
        char line[256];

        get_timestamp(ts, sizeof(ts));

        if (create_log_file(filename) < 0) {
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_temperature(i2c_fd, &temp) == 0) break;
            retries++;
            if (retries < MAX_RETRIES) usleep(RETRY_DELAY_MS * 1000);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_humidity(i2c_fd, &hum) == 0) break;
            retries++;
            if (retries < MAX_RETRIES) usleep(RETRY_DELAY_MS * 1000);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (read_pir(pir_line, &motion) < 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
        }

        snprintf(line, sizeof(line), "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
        FILE *fp = fopen(filename, "a");
        if (!fp) {
            fprintf(stderr, "Failed to open log file %s: %s\n", filename, strerror(errno));
        } else {
            if (fputs(line, fp) == EOF) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            }
            fclose(fp);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

