#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

static int motor_forward(struct gpiod_line *en, struct gpiod_line *in1,
                          struct gpiod_line *in2)
{
    if (gpiod_line_set_value(in1, 1) < 0) {
        log_event("ERROR: failed to set IN1 high");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_event("ERROR: failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(en, 1) < 0) {
        log_event("ERROR: failed to enable motor");
        return -1;
    }
    return 0;
}

static int motor_stop(struct gpiod_line *en, struct gpiod_line *in1,
                       struct gpiod_line *in2)
{
    if (gpiod_line_set_value(in1, 0) < 0) {
        log_event("ERROR: failed to set IN1 low");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_event("ERROR: failed to set IN2 low");
        return -1;
    }
    if (gpiod_line_set_value(en, 0) < 0) {
        log_event("ERROR: failed to disable motor");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *en_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        log_event("ERROR: cannot open GPIO chip");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    en_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain_line || !en_line || !in1_line || !in2_line) {
        log_event("ERROR: cannot get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        log_event("ERROR: cannot request rain sensor line as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(en_line, "motor_en", 0) < 0) {
        log_event("ERROR: cannot request enable line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        log_event("ERROR: cannot request IN1 line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        log_event("ERROR: cannot request IN2 line as output");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started (GPIO17, active-low).");

    while (program_running) {
        int val = gpiod_line_get_value(rain_line);
