                    break;
                }
                if (motor_stop(en_line, in1_line, in2_line) < 0) {
                    log_event("ERROR: motor stop failed");
                } else {
                    log_event("Motor stopped.");
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_event("Shutting down...");
    ret = EXIT_SUCCESS;

