#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_FLAGS       0
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_PERIOD   1.0

#define TEMP_MIN        25.0f
#define TEMP_MAX        60.0f
#define TEMP_STEP       5.0f
#define PWM_MIN         0
#define PWM_MAX         255
#define PWM_STEP        5

typedef struct {
    float temperature;
    int   pwm_duty;
} TemperatureData;

typedef struct {
    TemperatureData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static CircularBuffer g_buffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, float temp, int duty) {
    cb->data[cb->head].temperature = temp;
    cb->data[cb->head].pwm_duty    = duty;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void buffer_print(const CircularBuffer *cb) {
    printf("\n--- Temperature Log (%d entries) ---\n", cb->count);
    int start = (cb->count < BUFFER_SIZE) ? 0 : cb->head;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        time_t t = cb->data[idx].temperature;
        struct tm tmv;
        localtime_r(&t, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("[%s] Temp: %.2f C  PWM: %d/%d\n",
               ts, cb->data[idx].temperature, cb->data[idx].pwm_duty, PWM_RANGE);
    }
    printf("--- End Log ---\n\n");
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", FAN_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d\n", FAN_GPIO);
        return -1;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * MAX31855 32-bit register (MSB first):
 *   D[31:18]  Thermocouple temperature, 14-bit signed, 0.25 C/LSB
 *   D[17]     Reserved
 *   D[16]     Fault bit
 *   D[15:4]   Internal cold-junction temp, 12-bit signed, 0.0625 C/LSB
 *   D[3]      SCG (short to GND)
 *   D[2]      SCV (short to VCC)
 *   D[1]      OC  (open circuit)
 *   D[0]      reserved
 */
static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(g_spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", SPI_CHANNEL);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (raw & 0x00000002) fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (raw & 0x00000004) fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -2;
    }

    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) thermocouple_raw |= 0xC000;  /* sign-extend */

    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int set_fan_speed(float temp) {
    int duty = 0;

    if (temp < TEMP_MIN) duty = PWM_MIN;
    else if (temp < TEMP_MIN + TEMP_STEP) {
        duty = (int)((temp - TEMP_MIN) / TEMP_STEP * PWM_MIN);
    } else if (temp < TEMP_MIN + 2 * TEMP_STEP) {
        duty = (int)((temp - TEMP_MIN) / TEMP_STEP * PWM_MIN + PWM_STEP);
    } else if (temp < TEMP_MAX) {
        duty = (int)((temp - TEMP_MIN - TEMP_STEP) / (TEMP_MAX - TEMP_MIN) * PWM_MAX);
    } else {
        duty = PWM_MAX;
    }

    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO%d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (init_gpio() != 0) return 1;
    if (init_spi() != 0) { cleanup(); return 1; }

    buffer_init(&g_buffer);

    while (g_running) {
        float temperature;
        int rc = read_max31855(&temperature);

        if (rc == 0) {
            if (set_fan_speed(temperature) != 0) {
                fprintf(stderr, "Warning: fan control failed this cycle\n");
            }
            int duty = gpioGetPWMdutycycle(FAN_GPIO);
            if (duty >= 0) {
                TemperatureData td;
                td.temperature = temperature;
                td.pwm_duty    = duty;
                buffer_add(&g_buffer, temperature, duty);
            }
        } else if (rc == -2) {
            fprintf(stderr, "MAX31855 fault — skipping fan update\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    buffer_print(&g_buffer);
    cleanup();
    return 0;
}

