#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define INTERRUPT_GPIO 2
#define LOG_FILE "altitude_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    return i2cWriteDevice(handle, (char *)buf, 2);
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, 22) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static double compute_temperature(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return ((b5 + 8) >> 4) / 10.0;
}

static double compute_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2;
    b3 /= 4;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (double)p;
}

static int log_data(double temp, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, pressure) < 0) return -1;
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    bmp180_cal_t cal;
    if (read_calibration(i2c_handle, &cal) != 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(INTERRUPT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "GPIO mode set failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "GPIO pull-up failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, log_data, NULL) != 0) {
        fprintf(stderr, "ISR setup failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("Logging started. Press Ctrl+C to stop.\n");
    while (running) {
        gpioDelay(1000000);
        if (!running) break;
        int32_t ut, up;
        if (read_raw_temp(i2c_handle, &ut) != 0 || read_raw_pressure(i2c_handle, &up) != 0) {
            fprintf(stderr, "Sensor read error\n");
            continue;
        }
        double temp = compute_temperature(ut, &cal);
        double press = compute_pressure(up, ut, &cal);
        if (log_data(temp, press) != 0) {
            fprintf(stderr, "Log write failed\n");
        }
    }
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

