#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5
#define GPIO_CHIP "gpiochip4"
#define CS_LINE 8

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_RTD_FAULT_REG 0x03

#define RTD_A 0.0039083
#define RTD_B -0.0000005775
#define RTD_C 0.000000000004183
#define RTD_R0 100.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg, value};
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }
    return 0;
}

static int max31865_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg, 0x00};
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int max31865_init(int fd) {
    if (max31865_write_reg(fd, MAX31865_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    if (max31865_write_reg(fd, MAX31865_CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_rtd(int fd, float *temperature) {
    uint8_t rtd_msb, rtd_lsb, rtd_fault;

    if (max31865_read_reg(fd, MAX31865_RTD_MSB_REG, &rtd_msb) < 0) {
        fprintf(stderr, "Error reading RTD MSB: %s\n", strerror(errno));
        return -1;
    }
    if (max31865_read_reg(fd, MAX31865_RTD_LSB_REG, &rtd_lsb) < 0) {
        fprintf(stderr, "Error reading RTD LSB: %s\n", strerror(errno));
        return -1;
    }
    if (max31865_read_reg(fd, MAX31865_RTD_FAULT_REG, &rtd_fault) < 0) {
        fprintf(stderr, "Error reading fault register: %s\n", strerror(errno));
        return -1;
    }

    if (rtd_fault & 0x01) {
        fprintf(stderr, "RTD fault detected: %02X\n", rtd_fault);
        return -1;
    }

    int16_t rtd_raw = (int16_t)((rtd_msb << 8) | rtd_lsb);
    float rtd_resistance = (rtd_raw * 43000.0) / 32768.0;
    float temperature = (rtd_resistance - RTD_R0) / RTD_A;

    if (temperature < -100.0 || temperature > 1000.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1;
    }

    *temperature = temperature;
    return 0;
}

static void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    if (max31865_init(spi_fd) < 0) {
        fprintf(stderr, "Failed to initialize MAX31865\n");
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    printf("RTD monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_rtd(spi_fd, &temperature) == 0) {
            log_data(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read RTD data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return 0;
}

