#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 50000
#define CONVERSION_DELAY_US 5000

#define OVERSAMPLING 0
#define OSS (OVERSAMPLING << 6)

typedef struct {
    time_t timestamp;
    int pressure;
} PressureData;

typedef struct {
    PressureData buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer pressure_buffer;
static volatile sig_atomic_t running = 1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((data[0] << 8) | data[1]);
    ac2 = (int16_t)((data[2] << 8) | data[3]);
    ac3 = (int16_t)((data[4] << 8) | data[5]);
    ac4 = (uint16_t)((data[6] << 8) | data[7]);
    ac5 = (uint16_t)((data[8] << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1 = (int16_t)((data[12] << 8) | data[13]);
    b2 = (int16_t)((data[14] << 8) | data[15]);
    mb = (int16_t)((data[16] << 8) | data[17]);
    mc = (int16_t)((data[18] << 8) | data[19]);
    md = (int16_t)((data[20] << 8) | data[21]);
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error: Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd = (OSS << 6) | 0x34;
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, cmd) < 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)(data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - OSS);
    return 0;
}

static int calculate_pressure(int32_t ut, int32_t up, int32_t *pressure) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *pressure = (b5 + 8) >> 4;
    return 0;
}

static void add_to_buffer(CircularBuffer *buf, time_t ts, int pressure) {
    buf->buffer[buf->head].timestamp = ts;
    buf->buffer[buf->head].pressure = pressure;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static double calculate_rolling_average(const CircularBuffer *buf, int pressure) {
    if (buf->count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        sum += buf->buffer[idx].pressure;
    }
    return sum / buf->count;
}

static void trigger_alert(int pressure) {
    double avg = calculate_rolling_average(&pressure_buffer, pressure);
    if (fabs(pressure - avg) > 5.0) {
        gpioWrite(ALERT_GPIO, 1);
        printf("Alert: Pressure deviation (%.2f hPa) detected!\n", pressure - avg);
