    if (read_calibration(i2c_handle, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("bmp180_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int32_t ut, up;
        if (read_raw_temp(i2c_handle, &ut) != 0) {
            fprintf(stderr, "I2C read error for temperature\n");
            break;
        }
        if (read_raw_pressure(i2c_handle, &up) != 0) {
            fprintf(stderr, "I2C read error for pressure\n");
            break;
        }
        int32_t b5 = compute_b5(ut, &cal);
        float temp = calculate_temperature(b5, &cal);
        float pressure = calculate_pressure(up, b5, &cal);
        log_data(temp, pressure);
        gpioDelay(500000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nCleanup complete.\n");
    return 0;
}

