    cal->dig_T1 = (uint16_t)(buf[1]  << 8 | buf[0]);
    cal->dig_T2 = (int16_t)(buf[3]  << 8 | buf[2]);
    cal->dig_T3 = (int16_t)(buf[5]  << 8 | buf[4]);
    cal->dig_P1 = (uint16_t)(buf[7]  << 8 | buf[6]);
    cal->dig_P2 = (int16_t)(buf[9]  << 8 | buf[8]);
    cal->dig_P3 = (int16_t)(buf[11] << 8 | buf[10]);
    cal->dig_P4 = (int16_t)(buf[13] << 8 | buf[12]);
    cal->dig_P5 = (int16_t)(buf[15] << 8 | buf[14]);
    cal->dig_P6 = (int16_t)(buf[17] << 8 | buf[16]);
    cal->dig_P7 = (int16_t)(buf[19] << 8 | buf[18]);
    cal->dig_P8 = (int16_t)(buf[21] << 8 | buf[20]);
    cal->dig_P9 = (int16_t)(buf[23] << 8 | buf[22]);
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t status;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status, 1) != 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(1000);
    }
    if ((status & 0x08) != 0) {
        fprintf(stderr, "BMP280: measurement timeout\n");
        return -1;
    }
    uint8_t buf[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, buf, 6) != 0) return -1;
    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static double bmp280_compensate_press(int32_t raw_p, const bmp280_calib_t *cal, int32_t t_fine) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (double)p / 256.0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t chip_id;
    if (i2c_read_reg(fd, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "BMP280: failed to read chip ID\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280: unexpected chip ID 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "BMP280: reset write failed\n");
        return -1;
    }
    usleep(2000);
    if (bmp280_read_calibration(fd, cal) != 0) {
        fprintf(stderr, "BMP280: calibration read failed\n");
        return -1;
    }
    /* ctrl_meas: osrs_t=001, osrs_p=001 -> 0x25 */
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, CTRL_MEAS_VAL) != 0) {
        fprintf(stderr, "BMP280: ctrl_meas write failed\n");
        return -1;
    }
    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal, double *temp_c, double *press_hpa) {
    int32_t raw_t, raw_p;
    if (bmp280_read_raw(fd, &raw_t, &raw_p) != 0) return -1;
    int32_t t_fine;
    *temp_c = bmp280_compensate_temp(raw_t, cal, &t_fine);
    *press_hpa = bmp280_compensate_press(raw_p, cal, t_fine);
    return 0;
}

static void log_data(double temp_c, double press_hpa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp_c, press_hpa);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BMP280_ADDR_DEFAULT, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd, &((bmp280_calib_t *)NULL)) != 0) {
        fprintf(stderr, "BMP280 init failed at 0x%02X\n", BMP280_ADDR_DEFAULT);
        close(fd);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X\n", BMP280_ADDR_DEFAULT);

    while (g_running) {
        bmp280_calib_t cal;
        if (bmp280_init(fd, &cal) != 0) {
            fprintf(stderr, "Re-init failed; continuing\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        double temp_c, press_hpa;
        if (bmp280_read(fd, &cal, &temp_c, &press_hpa) == 0) {
            log_data(temp_c, press_hpa);
            printf("T: %.2f °C  P: %.2f hPa\n", temp_c, press_hpa);
        } else {
            fprintf(stderr, "Read failed; continuing\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

