#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <pthread.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL_US 1000000

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static CircularBuffer temp_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "lm75-temp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out) {
    uint8_t reg = TEMP_REG;
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing temperature register address: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 5;
    *temp_out = (float)raw / 256.0f;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_init() < 0) return 1;
    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    if (pthread_mutex_init(&temp_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Error initializing mutex: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float temperature;
    while (running) {
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&temp_buffer, temperature);
            float avg = calculate_average(&temp_buffer);
            int led_state = (avg > TEMP_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Error setting LED state: %s\n", strerror(errno));
            }
            printf("Temperature: %.2f°C, Average: %.2f°C, LED: %s\n",
                   temperature, avg, led_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C.\n");
            if (i2c_fd >= 0) close(i2c_fd);
            i2c_fd = -1;
            if (i2c_init() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return 0;
}

