#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define DEFAULT_TARGET 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define MAX_TEMP 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "temperature.log"

#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775

typedef struct {
    double target;
    double kp;
    double ki;
    double kd;
} PIDParams;

typedef struct {
    double current_temperature;
    double previous_error;
    double integral;
} PIDState;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static PIDParams pid_params;
static PIDState pid_state;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, PIDParams *params) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s'. Using defaults.\n", filename);
        params->target = DEFAULT_TARGET;
        params->kp = DEFAULT_KP;
        params->ki = DEFAULT_KI;
        params->kd = DEFAULT_KD;
        return -1;
    }
    char buffer[256];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Warning: Could not read config file '%s'. Using defaults.\n", filename);
        params->target = DEFAULT_TARGET;
        params->kp = DEFAULT_KP;
        params->ki = DEFAULT_KI;
        params->kd = DEFAULT_KD;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    char *t = strstr(buffer, "\"target\"");
    if (t) t += 4;
    char *kp = strstr(buffer, "\"kp\"");
    if (kp) t = kp + 3;
    char *ki = strstr(buffer, "\"ki\"");
    if (ki) t = ki + 3;
    char *kd = strstr(buffer, "\"kd\"");
    if (kd) t = kd + 3;
    if (!t) return -1;
    char *endptr;
    params->target = strtof(t, &endptr);
    params->kp = strtof(kp, &endptr);
    params->ki = strtof(ki, &endptr);
    params->kd = strtof(kd, &endptr);
    if (params->target < 0 || params->target > 100) {
        fprintf(stderr, "Warning: Target temperature out of range. Setting to default.\n");
        params->target = DEFAULT_TARGET;
    }
    return 0;
}

static int read_max31865(int handle, double *temperature) {
    char tx[2] = {0x80, 0xC1};
    char rx[3] = {0};
    if (spiXfer(handle, tx, rx, 3) != 3) {
        log_message("SPI transfer failed");
        return -1;
    }
    uint8_t rtd_msb = (rx[0] >> 7) & 0x07;
    uint8_t rtd_lsb = rx[1] & 0x07;
    uint8_t fault = rx[2] & 0x01;
    if (fault) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MAX31865 fault: %s", fault ? "fault detected" : "none");
        log_message(msg);
        return -1;
    }
    uint16_t rtd_code = ((uint16_t)(rtd_msb << 8) | rtd_lsb) & 0x7FFF;
    if (rtd_code == 0) {
        log_message("Invalid RTD code (0)");
        return -1;
    }
    double rtd_resistance = (rtd_code / 32768.0) * R_REF;
    if (rtd_resistance <= 0.0) {
        log_message("Invalid resistance calculation");
        return -1;
    }
    double t = (rtd_resistance - R0) / (A + B * t);
