#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define DEFAULT_TARGET 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define MAX_TEMP 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "temperature.log"

#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775

typedef struct {
    double target;
    double kp;
    double ki;
    double kd;
} PIDParams;

typedef struct {
    double current_temperature;
    double previous_error;
    double integral;
} PIDState;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;
static PIDParams pid_params;
static PIDState pid_state;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, PIDParams *params) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s'. Using defaults.\n", filename);
        params->target = DEFAULT_TARGET;
        params->kp = DEFAULT_KP;
        params->ki = DEFAULT_KI;
        params->kd = DEFAULT_KD;
        return -1;
    }
    char buffer[256];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Warning: Could not read config file '%s'. Using defaults.\n", filename);
        params->target = DEFAULT_TARGET;
        params->kp = DEFAULT_KP;
        params->ki = DEFAULT_KI;
        params->kd = DEFAULT_KD;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    char *t = strstr(buffer, "\"target\"");
    if (t) t += 4;
    char *kp = strstr(buffer, "\"kp\"");
    if (kp) t = kp + 3;
    char *ki = strstr(buffer, "\"ki\"");
    if (ki) t = ki + 3;
    char *kd = strstr(buffer, "\"kd\"");
    if (kd) t = kd + 3;
    if (!t) return -1;
    char *endptr;
    params->target = strtof(t, &endptr);
    params->kp = strtof(kp, &endptr);
    params->ki = strtof(ki, &endptr);
    params->kd = strtof(kd, &endptr);
