#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define MAX_RETRIES 3
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration_data(int fd) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAC, &ac2) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAE, &ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB0, &ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB2, &ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB4, &ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);
    int msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    usleep(5000);
    int msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> 8;
    return 0;
}

static int compute_b5(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    if (b5_out) *b5_out = b5;
    return 0;
}

static int compute_temperature(int32_t ut, int32_t b5, float *temp_out) {
    int32_t x1 = ((b5 + 8) >> 4) * (int32_t)ac6;
    int32_t x2 = ((int32_t)ac5 * (b5 + 8) >> 15);
    int32_t b6 = x1 + x2;
    int32_t t = 0;
    if (b6 < 0) t = (b6 * 5 + 128) >> 8;
    else t = (b6 * 5 + 128) >> 8;
    *temp_out = (float)t / 100.0f;
    return 0;
}

static int compute_pressure(int32_t up, int32_t b5, float *press_out) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    uint32_t x1p = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2p = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3p = ((x1p + x2p) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (x3p + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0) p = (b7 * 2 + 1) >> 1;
    else p = (b7 / 5) * 100;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *press_out = (float)(p + ((x1 + x2 + 3791) >> 4));
    return 0;
}

static int log_breach(float temp, float press) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Temp: %.2f C, Pressure: %.2f hPa\n", ts, temp, press);
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (read_calibration_data(i2c_fd) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 at 0x%02X on %s. Press Ctrl+C to exit.\n", BMP180_ADDR, I2C_BUS);

    while (running) {
        int32_t ut, up, b5;
        int ut_ok = 0, up_ok = 0;

        for (int r = 0; r < MAX_RETRIES; r++) {
            if (read_raw_temperature(i2c_fd, &ut) == 0) ut_ok = 1; else break;
            if (read_raw_pressure(i2c_fd, &up) == 0) up_ok = 1; else break;
            usleep(100000);
        }

        if (!ut_ok || !up_ok) {
            fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
            continue;
        }

        int32_t b5;
        if (compute_b5(ut, &b5) < 0) {
            fprintf(stderr, "compute_b5 failed\n");
            continue;
        }

        float temp, press;
        if (compute_temperature(ut, b5, &temp) < 0 || compute_pressure(up, b5, &press) < 0) {
            fprintf(stderr, "Compute failed\n");
            continue;
        }

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            log_breach(temp, press);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

