}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (read_calibration_data(i2c_fd) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 at 0x%02X on %s. Press Ctrl+C to exit.\n", BMP180_ADDR, I2C_BUS);

    while (running) {
        int32_t ut, up, b5;
        int ut_ok = 0, up_ok = 0;

        for (int r = 0; r < MAX_RETRIES; r++) {
            if (read_raw_temperature(i2c_fd, &ut) == 0) ut_ok = 1; else break;
            if (read_raw_pressure(i2c_fd, &up) == 0) up_ok = 1; else break;
            usleep(100000);
        }

        if (!ut_ok || !up_ok) {
            fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
            continue;
        }

        int32_t b5;
        if (compute_b5(ut, &b5) < 0) {
            fprintf(stderr, "compute_b5 failed\n");
            continue;
        }

        float temp, press;
        if (compute_temperature(ut, b5, &temp) < 0 || compute_pressure(up, b5, &press) < 0) {
            fprintf(stderr, "Compute failed\n");
            continue;
        }

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            log_breach(temp, press);
        }

        sleep(1);
    }

