#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_LEN          22
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define FAN_GPIO                18
#define TEMP_THRESHOLD          30.0f
#define BUFFER_SIZE             60
#define SAMPLE_PERIOD_US        500000
#define I2C_BUS                 1

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int  buffer_index = 0;
static int  buffer_count = 0;
static int  i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    uint8_t data[BMP180_CAL_LEN];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, (char *)data, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((data[0]  << 8) | data[1]);
    ac2 = (int16_t)((data[2]  << 8) | data[3]);
    ac3 = (int16_t)((data[4]  << 8) | data[5]);
    ac4 = (uint16_t)((data[6]  << 8) | data[7]);
    ac5 = (uint16_t)((data[8]  << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1  = (int16_t)((data[12] << 8) | data[13]);
    b2  = (int16_t)((data[14] << 8) | data[15]);
    mb  = (int16_t)((data[16] << 8) | data[17]);
    mc  = (int16_t)((data[18] << 8) | data[19]);
    md  = (int16_t)((data[20] << 8) | data[21]);
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t msb, lsb;
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)&msb, 1) != 1) {
        fprintf(stderr, "Error: failed to read temperature MSB\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)&lsb, 1) != 1) {
        fprintf(stderr, "Error: failed to read temperature LSB\n");
        return -1;
    }
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS0) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t msb, lsb, xlsb;
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)&msb, 1) != 1) {
        fprintf(stderr, "Error: failed to read pressure MSB\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB + 1, (char *)&lsb, 1) != 1) {
        fprintf(stderr, "Error: failed to read pressure LSB\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB + 2, (char *)&xlsb, 1) != 1) {
        fprintf(stderr, "Error: failed to read pressure XLSB\n");
        return -1;
    }
    *up = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb;
    return 0;
}

static float calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return (float)((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;
    uint32_t x1p = ((uint32_t)ac3 * b6) >> 13;
    uint32_t x2p = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3p = (x1p + x2p + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (x3p + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0) {
        return;
    }
    if (read_raw_pressure(&up) != 0) {
        return;
    }
    float temp = calculate_temperature(ut);
    float pres = calculate_pressure(up, ut);
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temp;
    buffer[buffer_index].pressure = pres;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)buffer[buffer_index].timestamp, temp, pres);
    if (temp > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }
}

static void cleanup(void) {
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        cleanup();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set timer\n");
        cleanup();
        return 1;
    }
    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

