#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO       17
#define SPI_CHANNEL       0
#define SPI_SPEED         2000000
#define SPI_FLAGS         0
#define TARGET_TEMP       25.0
#define MAX_DUTY_CYCLE    80.0
#define PWM_RANGE         255
#define PWM_FREQ          1000
#define LOG_FILE          "heater_log.csv"
#define SAMPLE_PERIOD_US  100000
#define MAX_READ_ERRORS   10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double temp, double duty) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, duty);
    fflush(log_file);
}

static int read_max31855(int handle, double *temp) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret = spiXfer(handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: ");
        if (raw & 0x00000004) fprintf(stderr, "open circuit ");
        if (raw & 0x00000002) fprintf(stderr, "short to GND ");
        if (raw & 0x00000001) fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -2;
    }
    int16_t therm = (int16_t)((raw >> 18) & 0x3FFF);
    if (therm & 0x2000) therm |= 0xC000;
    *temp = therm * 0.25;
    return 0;
}

static double calculate_duty(double target, double integral, double dt) {
    double error = target - (double)dt;
    double derivative = 0.0;
    if (error != 0.0) derivative = (error - (double)dt) / dt;
    double kp = 1.0, ki = 0.1, kd = 0.01;
    double new_integral = integral + (dt * ki * error);
    double duty = kp * error + kd * derivative + ki * new_integral;
    if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;
    if (duty < 0.0) duty = 0.0;
    return duty;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "# timestamp,temperature_c,duty_cycle_pct\n");

    double integral = 0.0;
    double dt = 1.0;
    int consecutive_errors = 0;

    while (running) {
        double temp = 0.0;
        int rc = read_max31855(spi_handle, &temp);
        if (rc == 0) {
            consecutive_errors = 0;
            double duty = calculate_duty(TARGET_TEMP, integral, dt);
            if (duty > 0.0) {
                gpioPWM(HEATER_GPIO, (int)duty);
                log_data(temp, duty);
            }
            integral += dt * duty;
            if (integral > 100.0) integral = 100.0;
            if (integral < 0.0) integral = 0.0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many errors, shutting down\n");
                break;
            }
            gpioPWM(HEATER_GPIO, 0);
            log_data(0.0, 0.0);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

