    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "# timestamp,temperature_c,duty_cycle_pct\n");

    double integral = 0.0;
    double dt = 1.0;
    int consecutive_errors = 0;

    while (running) {
        double temp = 0.0;
        int rc = read_max31855(spi_handle, &temp);
        if (rc == 0) {
            consecutive_errors = 0;
            double duty = calculate_duty(TARGET_TEMP, integral, dt);
            if (duty > 0.0) {
                gpioPWM(HEATER_GPIO, (int)duty);
                log_data(temp, duty);
            }
            integral += dt * duty;
            if (integral > 100.0) integral = 100.0;
            if (integral < 0.0) integral = 0.0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many errors, shutting down\n");
                break;
            }
            gpioPWM(HEATER_GPIO, 0);
            log_data(0.0, 0.0);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

