#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27
#define COMMON_PIN 3

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_THRESHOLD_BLUE  40000
#define TEMP_THRESHOLD_GREEN 60000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen(" TEMP_FILE ")");
        return -1;
    }

    int millideg;
    if (fscanf(fp, "%d", &millideg) != 1) {
        fprintf(stderr, "fscanf failed reading temperature\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "ferror reading temperature\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(" TEMP_FILE ")");
        return -1;
    }

    return millideg;
}

static void set_led_color(int r, int g, int b)
{
    /* Common-anode: duty 255 = off, duty 0 = fully on.
     * Invert so that higher brightness maps to lower duty. */
    gpioPWM(RED_PIN,   255 - r);
    gpioPWM(GREEN_PIN, 255 - g);
    gpioPWM(BLUE_PIN,  255 - b);
}

static void turn_off_led(void)
{
    gpioPWM(RED_PIN,   255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN,  255);
}

static void cleanup(void)
{
    turn_off_led();
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0 ||
        gpioSetMode(COMMON_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Common-anode: drive high to turn off (LED off when all cathodes are high). */
    gpioWrite(RED_PIN,   1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN,  1);
    gpioWrite(COMMON_PIN, 1);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp_m = read_cpu_temp();
        if (temp_m < 0) {
            fprintf(stderr, "Skipping update cycle due to temperature read error.\n");
        } else {
            int r, g, b;

            if (temp_m < TEMP_THRESHOLD_BLUE) {
                r = 0; g = 0; b = 255;
            } else if (temp_m < TEMP_THRESHOLD_GREEN) {
                r = 0; g = 255; b = 0;
            } else {
                r = 255; g = 0; b = 0;
            }

            set_led_color(r, g, b);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp_m, r, g, b);
        }

        /* Sleep 0.5 s in 0.05 s slices so signals are caught promptly. */
        for (int i = 0; i < 10 && g_running; i++) {
            time_sleep(0.05);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

