#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int send_start_signal(int gpio) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000); // 2 ms low
    gpioWrite(gpio, 1);
    gpioDelay(30);   // 30 us high
    gpioSetMode(gpio, PI_INPUT);
    return 0;
}

static int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int timeout = 1000; // 1 ms timeout per bit

    while (timeout-- > 0) {
        gpioSetMode(gpio, PI_OUTPUT);
        gpioWrite(gpio, 0);
        gpioDelay(40);
        gpioSetMode(gpio, PI_INPUT);
        gpioDelay(80);

        if (gpioRead(gpio) == 0) {
            data[bit_idx] <<= 1;
            if (gpioRead(gpio) == 1) {
                data[bit_idx] |= 1;
            }
            bit_idx++;
            if (bit_idx == 40) break;
        }
        gpioDelay(40);
    }

    if (bit_idx != 40) {
        fprintf(stderr, "DHT22: timeout or incomplete read\n");
        return -1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }
    return 0;
}

static int post_data(float temperature, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "libcurl init failed\n");
        return -1;
    }

    char json_data[256];
    snprintf(json_data, sizeof(json_data),
             "{\"temperature\":%.1f,\"humidity\":%.1f}",
             temperature, humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Failed to set headers\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (http_code != 200) {
        fprintf(stderr, "HTTP POST failed with code %ld\n", http_code);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    float temperature, humidity;
    int success = 0;

    while (running) {
        if (send_start_signal(DHT22_GPIO) != 0) {
            fprintf(stderr, "Failed to send start signal\n");
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            retries++;
            fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", retries, MAX_RETRIES);
            sleep(1);
        }

        if (success) {
            retries = 0;
            while (retries < MAX_RETRIES && running) {
                if (post_data(temperature, humidity) == 0) {
                    printf("Data posted successfully\n");
                    break;
                }
                retries++;
                fprintf(stderr, "Data POST failed (attempt %d/%d)\n", retries, MAX_RETRIES);
                sleep(1);
            }
        } else {
            fprintf(stderr, "DHT22 sensor not responding after %d retries\n", MAX_RETRIES);
        }

        sleep(READ_INTERVAL_SEC);
    }

    gpioTerminate();
    return 0;
}

