#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_LEN          22
#define BMP180_OSS              3
#define BMP180_CONV_DELAY_US    (26 * 1000)  /* 26 ms for OSS=3 */
#define DEBOUNCE_US             200000      /* 200 ms debounce */
#define LOG_FILE                "pressure_log.txt"
#define INTERRUPT_GPIO          4
#define SAMPLE_INTERVAL_US      2000000     /* 2 s */

static volatile sig_atomic_t logging_enabled = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* BMP180 calibration coefficients */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ---- prototypes ---- */
static int  bmp180_read_calibration(void);
static int  bmp180_read_raw(int16_t *ut, int32_t *up);
static int  bmp180_read_pressure(double *pressure_hpa);
static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);

/* ---- BMP180 calibration ---- */
static int bmp180_read_calibration(void) {
    uint8_t buf[BMP180_CAL_LEN];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, (char *)buf, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (ac1 == 0 && ac6 == 0) {
        fprintf(stderr, "Error: BMP180 calibration data invalid (sensor absent?)\n");
        return -1;
    }
    return 0;
}

/* ---- raw temperature and pressure reads ---- */
static int bmp180_read_raw(int16_t *ut, int32_t *up) {
    uint8_t cmd = 0x2E;  /* read raw temp */
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, cmd) < 0) {
        fprintf(stderr, "Error: failed to write temp command\n");
        return -1;
    }
    gpioDelay(5000);      /* 4.5 ms max conversion */
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: failed to read raw data\n");
        return -1;
    }
    *ut = (int16_t)((msb << 8) | lsb);
    *up = ((int32_t)(msb << 8) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

