#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_LEN          22
#define BMP180_OSS              3
#define BMP180_CONV_DELAY_US    (26 * 1000)  /* 26 ms for OSS=3 */
#define DEBOUNCE_US             200000      /* 200 ms debounce */
#define LOG_FILE                "pressure_log.txt"
#define INTERRUPT_GPIO          4
#define SAMPLE_INTERVAL_US      2000000     /* 2 s */

