#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 10
#define DHT22_START_LOW_US 1000
#define DHT22_START_HIGH_US 30
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(int pin, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_state = 1;
    int counter = 0;
    int timeout = 0;

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(DHT22_START_LOW_US);
    gpioWrite(pin, 1);
    gpioDelay(DHT22_START_HIGH_US);
    gpioSetMode(pin, PI_INPUT);

    timeout = 0;
    while (gpioRead(pin) == 1) {
        if (++timeout > DHT22_TIMEOUT_US) return -1;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(pin) == 0) {
        if (++timeout > DHT22_TIMEOUT_US) return -1;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(pin) == 1) {
        if (++timeout > DHT22_TIMEOUT_US) return -1;
        gpioDelay(1);
    }

    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(pin) == last_state) {
            if (++timeout > DHT22_TIMEOUT_US) return -1;
            gpioDelay(1);
        }
        last_state = gpioRead(pin);

        if (i < 4) {
            data[bit_idx / 8] <<= 1;
            if (timeout > (DHT22_TIMEOUT_US / 2)) {
                data[bit_idx / 8] |= 1;
            }
            counter++;
            if (counter == 32) {
                bit_idx++;
            }
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2;
    }

    unsigned int raw_humidity = (data[0] << 8) | data[1];
    *humidity = (float)raw_humidity / 10.0f;
    return 0;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json_data[128];
    snprintf(json_data, sizeof(json_data), "{\"humidity\":%.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (http_code < 200 || http_code >= 300) {
        syslog(LOG_ERR, "HTTP POST failed: %ld", http_code);
        return -1;
    }

    syslog(LOG_INFO, "Humidity: %.1f%% posted to %s", humidity, server_url);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 monitor (pin %d, server %s)", DHT22_PIN, server_url);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    int ret = EXIT_SUCCESS;

    while (running) {
        float humidity = 0.0f;
        int rc = -1;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            rc = read_dht22(DHT22_PIN, &humidity);
            if (rc == 0) break;
            syslog(LOG_WARNING, "DHT22 read failed (attempt %d/%d)", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(2);
            }
        }

        if (rc != 0) {
            syslog(LOG_ERR, "DHT22 sensor read failed after %d attempts", MAX_RETRIES);
        } else {
            syslog(LOG_INFO, "DHT22 humidity: %.1f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity to server");
            }
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    gpioTerminate();
    curl_global_cleanup();
    syslog(LOG_INFO, "Exiting gracefully");
    closelog();
    return ret;
}

