#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <stdbool.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define MAX_TEMP 65

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void) {
    int fd = open(TEMP_FILE, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[16];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';

    long millideg = strtol(buf, NULL, 10);
    if (millideg < 0 || millideg > 200000) {
        fprintf(stderr, "Invalid temperature value: %s\n", buf);
        close(fd);
        return -1;
    }
    close(fd);
    return (int)millideg;
}

static int write_fan(int state) {
    int fd = open(FAN_STATE_FILE, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    char buf[8];
    int len = snprintf(buf, sizeof(buf), "%d", state);
    if (len < 0 || (size_t)len >= sizeof(buf)) {
        fprintf(stderr, "Error formatting fan state\n");
        close(fd);
        return -1;
    }

    ssize_t w = write(fd, buf, len);
    if (w < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_FILE, strerror(errno));
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int set_fan_speed(int temp, int *current_state) {
    int target_state;

    if (temp < 45000) {
        target_state = 0;
    } else if (temp < 55000) {
        target_state = 1;
    } else if (temp < 65000) {
        target_state = 2;
    } else {
        target_state = 3;
    }

    if (target_state < 0 || target_state > 3) {
        fprintf(stderr, "Invalid fan state: %d\n", target_state);
        return -1;
    }

    if (*current_state != target_state) {
        if (write_fan(target_state) == 0) {
            *current_state = target_state;
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp) {
                fprintf(fp, "%s Fan speed set to %d\n", ts, target_state);
                fclose(fp);
            } else {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Failed to set fan speed to %d\n", target_state);
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    int current_fan_speed = 0;
    if (set_fan_speed(read_cpu_temp(), &current_fan_speed) != 0) {
        fprintf(stderr, "Initial fan speed setup failed\n");
        return 1;
    }

    printf("Fan control started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (set_fan_speed(temp, &current_fan_speed) != 0) {
            fprintf(stderr, "Fan speed set failed\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (write_fan(0) != 0) {
        fprintf(stderr, "Warning: failed to stop fan on shutdown\n");
    }
    printf("Fan stopped. Exiting.\n");
    return 0;
}

