#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define LOG_FILE "heater_log.txt"
#define TARGET_TEMP 50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define PWM_RANGE 100
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MIN 0
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

typedef struct {
    double Kp, Ki, Kd;
    double integral, previous_error;
    double target;
} PIDController;

static PIDController pid = {KP, KI, KD, 0.0, 0.0, TARGET_TEMP};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void log_data(double temp, int duty, double pid_out) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] Temp: %.2f C, Duty: %d, PID: %.2f\n", ts, temp, duty, pid_out);
    fflush(log_file);
}

static int read_max31855(int handle, double *temp) {
    char buf[4];
    int ret = spiRead(handle, buf, 4);
    if (ret != 4) {
        log_message("SPI read failed");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);
    if (raw & 0x00010000) {
        if (raw & 0x00000004) log_message("Thermocouple open circuit");
        if (raw & 0x00000002) log_message("Thermocouple short to GND");
        if (raw & 0x00000001) log_message("Thermocouple short to VCC");
        return -2;
    }
    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    *temp = thermocouple_temp * 0.25;
    return 0;
}

static int set_heater_pwm(int gpio, int duty) {
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    if (gpioPWM(gpio, duty) < 0) {
        log_message("gpioPWM failed");
        return -1;
    }
    return 0;
}

static double pid_calculate(double current_temp, double target_temp) {
    double error = target_temp - current_temp;
    pid.integral += error;
    double derivative = error - pid.previous_error;
    double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    pid.previous_error = error;
    return output;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        log_message("Shutting down");
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    log_message("Starting heater control");
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        log_message("SPI open failed");
        cleanup();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    double current_temp;
    while (running) {
        int rc = read_max31855(spi_handle, &current_temp);
        if (rc == 0) {
            if (current_temp > MAX_TEMP || current_temp < MIN_TEMP) {
                log_message("Failsafe: out of range, disabling heater");
                set_heater_pwm(HEATER_GPIO, 0);
                current_temp = TARGET_TEMP;
            }
            double pid_out = pid_calculate(current_temp, TARGET_TEMP);
            int duty = (int)pid_out;
            if (duty < 0) duty = 0;
            if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
            if (set_heater_pwm(HEATER_GPIO, duty) != 0) {
                log_message("Heater disable due to PWM failure");
                set_heater_pwm(HEATER_GPIO, 0);
            }
            log_data(current_temp, duty, pid_out);
        } else if (rc == -2) {
            log_message("Thermocouple fault, disabling heater");
            set_heater_pwm(HEATER_GPIO, 0);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

