#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x08
#define NUM_SENSORS 2
#define LOG_FILE "flow_log.txt"
#define RETRY_COUNT 3
#define POLL_INTERVAL_US 1000000

static int i2c_handles[NUM_SENSORS];
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write error (handle %d), retries left: %d\n", handle, retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "I2C read error (handle %d), retries left: %d\n", handle, retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch (handle %d), retries left: %d\n", handle, retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate from handle %d after %d retries\n", handle, RETRY_COUNT);
    return -1;
}

static int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", SENSOR_ADDR);
            for (int j = 0; j < i; j++) i2cClose(i2c_handles[j]);
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float flow_rates[NUM_SENSORS];
        int errors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_flow_rate(i2c_handles[i], &flow_rates[i]) != 0) {
                errors++;
            }
        }

        if (errors == 0) {
            if (log_flow_rates(flow_rates[0], flow_rates[1]) != 0) {
                fprintf(stderr, "Failed to log flow rates\n");
            }
        } else {
            fprintf(stderr, "Sensor read errors: %d/%d\n", errors, NUM_SENSORS);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2cClose(i2c_handles[i]);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

