#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360.0
#define LOG_FILE "encoder_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(double angular_position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Angular Position: %.2f degrees\n", timestamp, angular_position);
    } else {
        fprintf(fp, "(timestamp error), Angular Position: %.2f degrees\n", angular_position);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static int read_encoder_state(int a_pin, int b_pin) {
    int a = gpioRead(a_pin);
    int b = gpioRead(b_pin);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error reading GPIO pins: A=%d, B=%d\n", a, b);
        return -1;
    }

    if (a == 0 && b == 0) {
        return 0;
    }

    if (a == 0) {
        return 1;
    } else if (b == 0) {
        return 2;
    } else {
        return 3;
    }
}

static int update_encoder_state(int a_pin, int b_pin, int *prev_state, int *current_state) {
    int state = read_encoder_state(a_pin, b_pin);
    if (state < 0) {
        return -1;
    }

    if (*current_state != *prev_state) {
        *current_state = state;
        log_event(*current_state / 2.0 * PULSES_PER_REVOLUTION);
        *prev_state = state;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    int prev_state = -1;
    int current_state = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (update_encoder_state(SENSOR_A_PIN, SENSOR_B_PIN, &prev_state, &current_state) != 0) {
            fprintf(stderr, "Error updating encoder state\n");
            break;
        }
        gpioDelay(10000);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

