/*
 * ADPD144RI red/IR photometric sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO 2 (I2C bus 1 SDA)
 *   ADPD144RI SCL -> GPIO 3 (I2C bus 1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode    -> GPIO 17 (with ~330 ohm series resistor to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG  0x60
#define LED_PIN        17
#define IR_THRESHOLD   2000
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: got %zd bytes, expected 2: %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int adpd144ri_init(int fd)
{
    /* Power on and configure defaults. */
    if (i2c_write16(fd, 0x00, 0x0001) < 0) return -1;
    usleep(10000);
    if (i2c_write16(fd, 0x01, 0x0001) < 0) return -1;
    usleep(10000);
    if (i2c_write16(fd, 0x02, 0x0001) < 0) return -1;
    usleep(10000);
    if (i2c_write16(fd, 0x03, 0x0001) < 0) return -1;
    usleep(10000);
    return 0;
}

static int adpd144ri_read(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read16(fd, FIFO_DATA_REG, red) < 0) return -1;
    if (i2c_read16(fd, FIFO_DATA_REG + 2, ir) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- I2C setup --- */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Sensor presence check --- */
    uint16_t probe;
    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI init failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- GPIO setup via libgpiod --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led, "adpd144ri-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    FILE *log_fp = fopen("adpd144ri_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(adpd144ri_log.txt) failed: %s\n", strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t red, ir;
        if (adpd144ri_read(i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            printf("Red: %5u  IR: %5u\n", red, ir);
            if (ir > IR_THRESHOLD) {
                gpiod_line_set_value(led, 1);
                printf("IR threshold exceeded — LED ON\n");
            } else {
                gpiod_line_set_value(led, 0);
            }
            log_data(log_fp, red, ir);
        }
        usleep(SAMPLE_MS * 1000);
    }

    /* --- Cleanup --- */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

