#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_OUT 17
#define GPIO_GAIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_audio_event(FILE *fp, int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *out_line = NULL;
    struct gpiod_line *gain_line = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    out_line = gpiod_chip_get_line(chip, GPIO_OUT);
    if (out_line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_OUT, strerror(errno));
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GPIO_GAIN);
    if (gain_line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_GAIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(out_line, "max9814_out") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_OUT, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "max9814_gain", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_GAIN, strerror(errno));
        goto cleanup;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(out_line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_OUT, strerror(errno));
            break;
        }

        if (val == 1) {
            if (log_audio_event(fp, 1) < 0) {
                fprintf(stderr, "Error logging audio event.\n");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (out_line != NULL) {
        gpiod_line_release(out_line);
    }
    if (gain_line != NULL) {
        gpiod_line_release(gain_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fp != NULL) {
        fclose(fp);
    }

    printf("Audio sampling stopped.\n");
    return ret;
}

