#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define SLF3S_CMD_START 0x3608
#define SLF3S_READ_LEN 3
#define SLF3S_READ_DELAY_US 10000
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE_NAME "flow_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_slf3s(void) {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SLF3S_ADDR, i2c_handle);
        return -1;
    }

    uint8_t cmd[2] = {
        (uint8_t)((SLF3S_CMD_START >> 8) & 0xFF),
        (uint8_t)(SLF3S_CMD_START & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing start command to SLF3S\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    gpioDelay(10000);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[SLF3S_READ_LEN];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, SLF3S_READ_LEN);
    if (bytes_read != SLF3S_READ_LEN) {
        fprintf(stderr, "Error reading from SLF3S: expected %d bytes, got %d\n", SLF3S_READ_LEN, bytes_read);
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw_flow / 1000.0f;
    return 0;
}

static void log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    } else {
        fflush(log_file);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_slf3s() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Skipping log entry due to read error\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
