#define REG_STATE 0x00
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2) {
    char buf[7];
    int rc = i2cReadI2CBlockData(handle, REG_STATE, buf, 7);
    if (rc != 7) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }
    *tvoc = ((uint16_t)(buf[1] & 0xFF) << 8) | (uint8_t)buf[0];
    *eco2 = ((uint16_t)(buf[5] & 0xFF) << 8) | (uint8_t)buf[4];
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float tvoc_ppb = (float)tvoc;
    float eco2_ppm = (float)eco2;
    float iaq = 100.0f - (tvoc_ppb / 10.0f) - ((eco2_ppm - 400.0f) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static int log_data(FILE *fp, uint16_t tvoc, uint16_t eco2, float iaq) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%u,%u,%.2f\n", ts, tvoc, eco2, iaq) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,TVOC_ppb,eCO2_ppm,IAQ\n");
        fflush(log_file);
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t tvoc = 0, eco2 = 0;
        if (read_sensor_data(i2c_handle, &tvoc, &eco2) == 0) {
            float iaq = calculate_iaq(tvoc, eco2);
            if (log_data(log_file, tvoc, eco2, iaq) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f\n", tvoc, eco2, iaq);
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

