#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_intrusion_alert(void)
{
    printf("INTRUSION ALERT: Sensor on GPIO %d touched for more than %d seconds!\n",
           GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_SEC);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec start_time, current_time;
    int ret;

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s)...\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    fflush(stdout);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("clock_gettime");
            break;
        }

        if (value == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("clock_gettime (start)");
                break;
            }
        } else {
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("clock_gettime (start)");
                break;
            }
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                perror("clock_gettime (current)");
                break;
            }
        }

        if (value == 1) {
            double elapsed = (current_time.tv_sec - start_time.tv_sec)
                          + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
            if (elapsed >= INTRUSION_THRESHOLD_SEC) {
                print_intrusion_alert();
                if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                    perror("clock_gettime (start after alert)");
                    break;
                }
            }
        } else {
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("clock_gettime (start after release)");
                break;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

