#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LEFT_CHANNEL 17
#define SAMPLE_RATE 48000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 1
#define NUM_SAMPLES 1000000
#define LOG_FILE "audio_capture.pcm"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(void) {
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2S device");
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        perror("Failed to set DSP format");
        close(fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) == -1) {
        perror("Failed to set DSP channels");
        close(fd);
        return -1;
    }

    int speed = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &speed) == -1) {
        perror("Failed to set DSP speed");
        close(fd);
        return -1;
    }

    return fd;
}

static int init_gpio(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LEFT_CHANNEL);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "inmp441-left-select", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return chip;
}

static int select_left_channel(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO high");
