#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 50000
#define FLAME_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("flame_log.txt", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level < 0) {
        log_event("Error reading flame sensor");
        return -1;
    }
    return level;
}

static void control_fan(int flame_detected) {
    static int fan_on = 0;
    static uint32_t fan_start_tick = 0;
    static int flame_active = 0;

    if (flame_detected) {
        if (!fan_on) {
            if (gpioPWM(FAN_GPIO, 0) < 0) {
                log_event("Error setting fan PWM to 0");
            }
            fan_on = 1;
            flame_active = 1;
            log_event("Flame detected, fan activated");
        }
        uint32_t now = gpioTick();
        if (now - fan_start_tick > (DEBOUNCE_MS * 1000)) {
            int duty = 0;
            if (flame_active) {
                duty = (int)(((float)(now - fan_start_tick) / (DEBOUNCE_MS * 1000.0)) * 80.0);
                if (duty > PWM_RANGE) duty = PWM_RANGE;
                if (duty < 0) duty = 0;
                if (gpioPWM(FAN_GPIO, duty) < 0) {
                    log_event("Error setting fan PWM duty cycle");
                }
            } else {
                if (gpioPWM(FAN_GPIO, 0) < 0) {
                    log_event("Error setting fan PWM to 0");
                }
                fan_on = 0;
                flame_active = 0;
            }
            fan_start_tick = now;
        }
    } else {
        if (fan_on) {
            if (gpioPWM(FAN_GPIO, 0) < 0) {
                log_event("Error setting fan PWM to 0");
            }
            fan_on = 0;
            flame_active = 0;
            log_event("Flame cleared, fan deactivated");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");
    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame = read_flame_sensor();
        if (flame < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (flame == 0) {
            uint32_t start = gpioTick();
            while (program_running && (gpioTick() - start) < (DEBOUNCE_MS * 1000)) {
                gpioDelay(POLL_INTERVAL_US);
            }
            if (program_running) {
                control_fan(1);
            }
        } else {
            control_fan(0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    gpioPWM(FAN_GPIO, 0);
    gpioSetMode(FAN_GPIO, PI_INPUT);
    gpioTerminate();
    printf("System stopped.\n");
    return EXIT_SUCCESS;
}

