/* AWR1642 SPI protocol: 32-bit word, 8-bit subframe, 8-bit subframe, 8-bit subframe, 8-bit subframe */
#define SPI_WORD_SIZE 32

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_us;
} radar_config_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, int len) {
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: expected %d bytes, got %d\n", len, ret);
        return -1;
    }
    return 0;
}

static int log_header(FILE *f) {
    uint32_t magic[4] = {0x52444144, 0x52444144, 0x52444144, 0x52444144};
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    uint32_t ts_u = (uint32_t)now;
    uint32_t config[8];
    config[0] = 0x01; config[1] = 0x02; config[2] = 0x03; config[3] = 0x04;
    config[4] = 0x05; config[5] = 0x06; config[6] = 0x07; config[7] = 0x08;
    if (fwrite(magic, sizeof(magic), 4, f) != 4) return -1;
    if (fwrite(ts, sizeof(ts), 1, f) != 1) return -1;
    if (fwrite(config, sizeof(config), 8, f) != 8) return -1;
    return 0;
}

static int log_frame(FILE *f, uint32_t frame_num) {
    uint32_t ts_u = (uint32_t)time(NULL);
    uint32_t config[8];
    config[0] = 0x01; config[1] = 0x02; config[2] = 0x03; config[3] = 0x04;
    config[4] = 0x05; config[5] = 0x06; config[6] = 0x07; config[7] = 0x08;
    if (fwrite(&ts_u, sizeof(ts_u), 1, f) != 1) return -1;
    if (fwrite(config, sizeof(config), 8, f) != 8) return -1;
    if (fwrite(&frame_num, sizeof(frame_num), 1, f) != 1) return -1;
    return 0;
}

static int read_radar_data(uint8_t *data, int len) {
    if (spi_transfer((uint8_t[]){0x00, 0x00, 0x00, 0x00}, data, len) != 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(DATA_READY_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (log_header(log_file) != 0) {
        fprintf(stderr, "Failed to write header\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t frame_num = 0;
    uint8_t *data = malloc(FRAME_SIZE);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(1000); /* 1 ms */
        gpioWrite(TRIGGER_PIN, 0);

        int ready = 0;
        int timeout = 100;
        while (timeout-- > 0 && !running) {
            if (gpioRead(DATA_READY_PIN)) ready = 1;
            gpioDelay(1000);
        }
        if (!ready) {
            fprintf(stderr, "Data ready timeout\n");
            continue;
        }

        if (read_radar_data(data, FRAME_SIZE) != 0) {
            fprintf(stderr, "Failed to read radar data\n");
            continue;
        }

        if (log_frame(log_file, frame_num++) != 0) {
            fprintf(stderr, "Failed to log frame\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    free(data);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

