        fprintf(stderr, "[ERROR] Failed to read device ID register.\n");
        return -1;
    }

    /* OPT3001 manufacturer ID: 0x5449 (T.I.) */
    if ((manuf & 0xFF) != 0x54 || (manuf >> 8) != 0x49) {
        fprintf(stderr, "[ERROR] Manufacturer ID mismatch: got 0x%04X, expected 0x5449.\n", manuf);
        return -1;
    }

    /* Device ID: 0x3001 for OPT3001 */
    if ((id & 0xFF) != 0x30 || (id >> 8) != 0x01) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%04X, expected 0x3001.\n", id);
        return -1;
    }

    printf("[INFO] OPT3001 verified: manufacturer=0x%04X, device=0x%04X\n", manuf, id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the OPT3001 for continuous conversion mode                */
/* ------------------------------------------------------------------ */
static int opt3001_configure(int handle)
{
    /* Clear any latch bits by writing 0x0000, then set config bits */
    if (opt3001_write_reg(handle, REG_CONFIG, 0x0000) != 0)
        return -1;

    uint16_t config = CONFIG_CONTINUOUS |
                      CONFIG_CONV_TIME_100MS |
                      CONFIG_FS_AUTO;

    if (opt3001_write_reg(handle, REG_CONFIG, config) != 0)
        return -1;

    /* Allow first conversion to complete (100 ms) */
    gpioDelay(100000);

    printf("[INFO] OPT3001 configured: continuous mode, 100 ms conv, auto FS\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read lux value from the OPT3001                                  */
/* ------------------------------------------------------------------ */
static int opt3001_read_lux(int handle, float *lux_out)
{
    uint16_t raw;

    if (opt3001_read_reg(handle, REG_RESULT, &raw) != 0)
        return -1;

    /* 16-bit two's complement: exponent bits 15-12, mantissa bits 11-0 */
    int exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    *lux_out = 0.01f * (float)(1u << exponent) * (float)mantissa;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO-8601 timestamp                           */
/* ------------------------------------------------------------------ */
static void log_reading(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at OPT3001 address */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (opt3001_verify(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 not detected or wrong device.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (opt3001_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 configuration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Logging OPT3001 lux readings to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float lux;

        if (opt3001_read_lux(g_i2c_handle, &lux) == 0) {
            log_reading(lux);
            printf("[INFO] Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "[WARN] I2C read failed; will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

