/*
 * SainSmart IR Flame Detection Sensor Module - digital output reader
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Module (digital DOUT)
 * Wiring: DOUT -> GPIO17 (BCM 17, physical pin 11)
 *          VCC -> 3.3 V (physical pin 1)
 *          GND -> GND  (physical pin 9)
 *          (Adjust VCC if your module variant requires 5 V.)
 *
 * The module's DOUT line is active-low: it reads 0 when a flame is
 * detected, and 1 when no flame is present.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 * Run:    ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *request = NULL;
    int ret = EXIT_FAILURE;

    install_sigint_handler();

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* Configure the line as input with pull-up bias */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* Build the line config: offset 17, settings */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1,
                                            settings) != 0) {
        fprintf(stderr, "Failed to add line settings to config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request config: consumer label */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame-sensor");

    /* Request the line from the chip */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO line %u: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on GPIO %u (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (g_running) {
        int value = gpiod_line_request_get_value(request, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        /* Active-low: 0 => flame detected, 1 => no flame */
        printf("%s\n", value ? "Flame Detected: NO" : "Flame Detected: YES");
        fflush(stdout);

        /* Sleep 1 second, interruptible by signals */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

