#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LEFT_SENSOR 17
#define CENTER_SENSOR 18
#define RIGHT_SENSOR 27
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int left, center, right;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO modes to input */
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d to input\n", LEFT_SENSOR);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d to input\n", CENTER_SENSOR);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d to input\n", RIGHT_SENSOR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO %d, Center: GPIO %d, Right: GPIO %d\n", LEFT_SENSOR, CENTER_SENSOR, RIGHT_SENSOR);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        left = gpioRead(LEFT_SENSOR);
        center = gpioRead(CENTER_SENSOR);
        right = gpioRead(RIGHT_SENSOR);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: failed to read GPIOs\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

