                fprintf(stderr, "Failed to read GPIO line %u\n", gpio_pins[i]);
                goto cleanup;
            }
            printf("Channel %d: %d\n", i + 1, value);
        }
        fflush(stdout);
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

