/*
 * TMAG5110 Hall-Effect Latch Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio
 *
 * Wiring:
 *   TMAG5110 OUT1 -> BCM GPIO 4  (external pull-up to 3.3 V)
 *   TMAG5110 OUT2 -> BCM GPIO 5  (external pull-up to 3.3 V)
 *
 * The TMAG5110 digital OUT is open-drain: it pulls its output LOW
 * when a magnet is detected and releases the line (HIGH) when no
 * magnet is present.  External pull-ups keep the line HIGH when idle.
 *
 * Build:  gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:    sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with internal pull-ups disabled
     * (external pull-ups assumed).  The TMAG5110 OUT is open-drain,
     * so the line is HIGH when no magnet is present. */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-ups to settle */
    gpioDelay(10000); /* 10 ms */

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Pins: BCM GPIO %d (Sensor 1), BCM GPIO %d (Sensor 2)\n",
           SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        /* TMAG5110: LOW (0) = magnet detected, HIGH (1) = no magnet */
        printf("Sensor 1 (GPIO %d): %s | Sensor 2 (GPIO %d): %s\n",
               SENSOR_1_PIN, s1 ? "HIGH (no magnet)" : "LOW (magnet)",
               SENSOR_2_PIN, s2 ? "HIGH (no magnet)" : "LOW (magnet)");
        fflush(stdout);

        gpioDelay(500000); /* 500 ms */
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

