#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_DELAY_US    100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    int last_state = -1;   /* force initial log */

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up --- */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-up to settle */
    gpioDelay(10000);  /* 10 ms */

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    /* --- Main polling loop --- */
    while (running) {
        int current_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                    TILT_SENSOR_GPIO, current_state);
            break;
        }

        /* Log only on state change */
        if (current_state != last_state) {
            print_timestamp();
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

