    while (running) {
        int current_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                    TILT_SENSOR_GPIO, current_state);
            break;
        }

        /* Log only on state change */
        if (current_state != last_state) {
            print_timestamp();
            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

