    int part_id = read_register(handle, REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (write_register(handle, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_register(handle, REG_HW_KEY, HW_KEY_VAL) < 0) return -1;

    if (write_register(handle, REG_CHLIST, 0x03) < 0) return -1;

    if (write_register(handle, REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;
