    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

