    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting UV and ALS data logging...\n");

    while (running) {
        int uv_index = read_uv_index(i2c_handle);
        int als_visible = read_als_visible(i2c_handle);

        if (uv_index >= 0 && als_visible >= 0) {
            printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

