        cleanup();
        return 1;
    }

    i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (init_sensor(i2c_fd2) < 0) {
        fprintf(stderr, "Failed to init sensor 2\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }
    alarm_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = 0, ok2 = 0;

        if (read_flow_rate(i2c_fd1, &flow1) == 0) ok1 = 1;
        if (read_flow_rate(i2c_fd2, &flow2) == 0) ok2 = 1;

        if (ok1 && ok2) {
            float avg = (flow1 + flow2) / 2.0f;
            int alarm = (avg < FLOW_THRESHOLD) ? 1 : 0;
            gpiod_line_set_value(alarm_line, alarm);
            log_flow_rate(avg);
            printf("Avg flow: %.3f ml/min, Alarm: %s\n", avg, alarm ? "ON" : "OFF");
        } else {
            if (!ok1) fprintf(stderr, "Sensor 1 read failed\n");
            if (!ok2) fprintf(stderr, "Sensor 2 read failed\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

