#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

static SensorData circularBuffer[BUFFER_SIZE];
static int bufferIndex = 0;
static int bufferIsFull = 0;

static volatile sig_atomic_t running = 1;

static void signalHandler(int signum) {
    (void)signum;
    running = 0;
}

static void addData(time_t timestamp, int reading) {
    circularBuffer[bufferIndex].timestamp = timestamp;
    circularBuffer[bufferIndex].reading = reading;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
    if (bufferIndex == 0) {
        bufferIsFull = 1;
    }
}

static void printBuffer(void) {
    int start = (bufferIndex == 0) ? 0 : bufferIndex;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char timeStr[32];
        struct tm *tm_info = localtime(&circularBuffer[idx].timestamp);
        if (tm_info != NULL) {
            strftime(timeStr, sizeof(timeStr), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Reading: %d\n", timeStr, circularBuffer[idx].reading);
        } else {
            printf("[timestamp error] Reading: %d\n", circularBuffer[idx].reading);
        }
    }
    printf("\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

