    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Obstacle avoidance sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d\n", SENSOR_PIN);
            break;
        }

        if (reading == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
                break;
            }
            addData(now, reading);
            printf("Obstacle detected! Timestamp: %ld\n", (long)now);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printBuffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

