/*
 * fan_health.c — Omron D7S vibration monitor for Raspberry Pi 5
 *
 * Reads X/Y/Z acceleration (g) every 500 ms and logs CSV rows to
 * fan_health.csv.  If the D7S does not become active within 1 s after
 * MODE_CONTROL is written, the program exits with an error.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55          /* default 7-bit I2C address */
#define D7S_REG_MODE   0x1D          /* MODE_CONTROL */
#define D7S_REG_STATUS 0x1B          /* operating-status bits */
#define D7S_REG_X_LSB  0x2A          /* X-axis acceleration LSB */
#define D7S_REG_Y_LSB  0x2C          /* Y-axis acceleration LSB */
#define D7S_REG_Z_LSB  0x2E          /* Z-axis acceleration LSB */

#define SCALE_FACTOR   0.0009765625f /* g per LSB (16-bit signed, little-endian) */
#define MODE_ACTIVE    0x10          /* bit 0 of MODE_CONTROL enables active mode */
#define STATUS_ACTIVE  0x01          /* bit 0 of STATUS register indicates active */
#define INIT_TIMEOUT_S 1             /* max seconds to wait for D7S to become active */
#define SAMPLE_PERIOD_MS 500         /* sampling interval */
#define CSV_FILENAME   "fan_health.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s (wrote %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s (read %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_lsb, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &hi) < 0) return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor init                                                         */
/* ------------------------------------------------------------------ */

static int d7s_init(int fd)
{
    if (i2c_write_reg8(fd, D7S_REG_MODE, MODE_ACTIVE) < 0)
        return -1;

    /* Poll STATUS register until bit 0 (ACTIVE) is set or timeout. */
    for (int i = 0; i < INIT_TIMEOUT_S; ++i) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0)
            return -1;
        if (status & STATUS_ACTIVE)
            return 0;
        usleep(100000); /* 100 ms */
    }
    fprintf(stderr, "D7S did not become active within %d s\n", INIT_TIMEOUT_S);
    return -1;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */

static int log_data(FILE *fp, float xg, float yg, float zg)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, xg, yg, zg) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (d7s_init(fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        goto cleanup;
    }

    /* Open CSV file in append mode; write header if newly created */
    fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
        goto cleanup;
    }
    long sz = ftell(fp);
    if (sz < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sz == 0) {
        if (fprintf(fp, "timestamp,x_g,y_g,z_g\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("D7S vibration monitor started. Logging to %s every %d ms.\n",
           CSV_FILENAME, SAMPLE_PERIOD_MS);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x_raw = 0, y_raw = 0, z_raw = 0;
        float x_g = 0.0f, y_g = 0.0f, z_g = 0.0f;

        if (i2c_read_reg16_le(fd, D7S_REG_X_LSB, &x_raw) < 0 ||
            i2c_read_reg16_le(fd, D7S_REG_Y_LSB, &y_raw) < 0 ||
            i2c_read_reg16_le(fd, D7S_REG_Z_LSB, &z_raw) < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        x_g = x_raw * SCALE_FACTOR;
        y_g = y_raw * SCALE_FACTOR;
        z_g = z_raw * SCALE_FACTOR;

        if (log_data(fp, x_g, y_g, z_g) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    return rc;
}

