code:
/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 * Library: pigpio (I2C bus 1, address 0x0E)
 * Output: magnetic_log.csv (timestamp_ms,X_mT,Y_mT,Z_mT)
 *
 * Build: gcc -O2 -Wall -o mag_log mag_log.c -lpigpio -lrt
 * Run:   sudo ./mag_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170-Q1 constants (verified against TI datasheet) ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x0E          /* A0=A1=0  -> 0x0E */
#define REG_DEVICE_ID        0x00
#define REG_DEVICE_CONFIG    0x01
#define REG_X_MSB            0x04
#define REG_X_LSB            0x05
#define REG_Y_MSB            0x06
#define REG_Y_LSB            0x07
#define REG_Z_MSB            0x08
#define REG_Z_LSB            0x09
#define REG_STATUS           0x0F
#define REG_X_LSB_CFG        0x0A
#define REG_X_MSB_CFG        0x0B
#define REG_Y_LSB_CFG        0x0C
#define REG_Y_MSB_CFG        0x0D
#define REG_Z_LSB_CFG        0x0E
#define REG_Z_MSB_CFG        0x0F

#define EXPECTED_DEVICE_ID   0x8D
#define LOG_FILE             "magnetic_log.csv"
#define SAMPLE_PERIOD_US     100000        /* 100 ms */

/* 50 mT range: 1 LSB = 0.000244 mT (2.44 uT) */
#define LSB_TO_MT_50MT       0.000244f

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register (big-endian on bus).     */
/* ------------------------------------------------------------------ */
static int tmag_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)(value >> 8);
    buf[1] = (char)(value & 0xFF);
    if (i2cWriteI2CBlockData(handle, reg, buf, 2) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register (big-endian on bus).   */
/* ------------------------------------------------------------------ */
static int tmag_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TMAG5170 for continuous-conversion mode.              */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tmag_init(int handle)
{
    uint16_t dev_id = 0;

    /* Verify device identity */
    if (tmag_read_reg(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID register\n");
        return -1;
    }
    if (dev_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected device ID 0x%04X (expected 0x%04X)\n",
                dev_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    printf("[INFO] TMAG5170 detected (device ID 0x%04X)\n", dev_id);

    /* Configure for continuous-conversion mode, all axes enabled, 50 mT range */
    if (tmag_write_reg(handle, REG_X_MSB_CFG, 0x0000) != 0) return -1;
    if (tmag_write_reg(handle, REG_X_LSB_CFG, 0x0000) != 0) return -1;
    if (tmag_write_reg(handle, REG_Y_MSB_CFG, 0x0000) != 0) return -1;
    if (tmag_write_reg(handle, REG_Y_LSB_CFG, 0x0000) != 0) return -1;
    if (tmag_write_reg(handle, REG_Z_MSB_CFG, 0x0000) != 0) return -1;
    if (tmag_write_reg(handle, REG_Z_LSB_CFG, 0x0000) != 0) return -1;

    /* Enable continuous-conversion mode (bit 0 of device config) */
    if (tmag_write_reg(handle, REG_DEVICE_CONFIG, 0x0001) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetic field in mT. Returns 0 on success, -1 on error. */
/* ------------------------------------------------------------------ */
static int read_magnetic_field(int handle, float *x, float *y, float *z)
{
    uint16_t raw_x = 0, raw_y = 0, raw_z = 0;

    if (tmag_read_reg(handle, REG_X_MSB, &raw_x) != 0) return -1;
    if (tmag_read_reg(handle, REG_Y_MSB, &raw_y) != 0) return -1;
    if (tmag_read_reg(handle, REG_Z_MSB, &raw_z) != 0) return -1;

    *x = (float)raw_x * LSB_TO_MT_50MT;
    *y = (float)raw_y * LSB_TO_MT_50MT;
    *z = (float)raw_z * LSB_TO_MT_50MT;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (tmag_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,X_mT,Y_mT,Z_mT\n");
        fflush(g_log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float x, y, z;

        if (read_magnetic_field(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
