#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdatomic.h>

#define SENSOR_GPIO 4          /* BCM 4, physical pin 7 */
#define LOG_FILE    "rpm_log.txt"
#define SAMPLE_SEC  1          /* seconds between logged samples */

static atomic_int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleans up.        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of SENSOR_GPIO.         */
/* level == 1 means rising edge = one revolution captured.             */
/* ------------------------------------------------------------------ */
static void pulse_counter(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        atomic_fetch_add(&pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from the last SAMPLE_SEC seconds of pulses.             */
/* Returns 0 on success, -1 on invalid input.                           */
/* ------------------------------------------------------------------ */
static int calculate_rpm(int *pulses, int sample_seconds, double *rpm)
{
    if (pulses == NULL || rpm == NULL)
        return -1;

    if (sample_seconds <= 0 || *pulses <= 0)
        return 0;

    double pulses_per_second = ((double)*pulses / (double)sample_seconds) * 60.0;
    *rpm = pulses_per_second;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped RPM reading to the log file.                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioSetAlertFuncEx(SENSOR_GPIO, NULL, NULL);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pulses = 0;
    double rpm;
    int rc;

    /* ---- pigpio init ---- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin ---- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for BCM %d\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for BCM %d\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- register alert callback (rising-edge only) ---- */
    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for BCM %d\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start 1-second sampling timer ---- */
    if (gpioSetTimerFuncEx(0, SAMPLE_SEC, NULL, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    /* ---- main loop ---- */
    while (running) {
        gpioDelay(SAMPLE_SEC * 1000000);  /* pigpio microseconds */

        if (!running)
            break;

        /* Snapshot pulses and reset counter */
        rc = calculate_rpm(&pulses, SAMPLE_SEC, &rpm);
        if (rc != 0) {
            fprintf(stderr, "RPM calculation error — logging 0 RPM\n");
            rpm = 0.0;
        }

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        printf("RPM: %.2f\n", rpm);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

