        return EXIT_FAILURE;
    }

    /* ---- register alert callback (rising-edge only) ---- */
    if (gpioSetAlertFuncEx(SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for BCM %d\n", SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start 1-second sampling timer ---- */
    if (gpioSetTimerFuncEx(0, SAMPLE_SEC, NULL, NULL) != 0) {
        fprintf(stderr, "gpioSetTimerFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    /* ---- main loop ---- */
    while (running) {
        gpioDelay(SAMPLE_SEC * 1000000);  /* pigpio microseconds */

        if (!running)
            break;

        /* Snapshot pulses and reset counter */
        rc = calculate_rpm(&pulses, SAMPLE_SEC, &rpm);
        if (rc != 0) {
            fprintf(stderr, "RPM calculation error — logging 0 RPM\n");
            rpm = 0.0;
        }

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        printf("RPM: %.2f\n", rpm);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

