#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"
#define DEBOUNCE_US 10000

/* Quadrature state machine states */
typedef enum {
    Q_IDLE,
    Q_A_LOW,
    Q_A_HIGH,
    Q_B_LOW,
    Q_B_HIGH
} quadrature_state_t;

static volatile quadrature_state_t g_quadrature_state = Q_IDLE;
static volatile int g_previous_state = Q_IDLE;
static volatile int g_rotation_count = 0;
static pthread_mutex_t g_state_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_rotation(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ms, direction);
    fclose(fp);
}

static void sensor_a_alert(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    pthread_mutex_lock(&g_state_mutex);
    g_quadrature_state = (level == 0) ? Q_A_LOW : Q_A_HIGH;
    pthread_mutex_unlock(&g_state_mutex);
}

static void sensor_b_alert(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    pthread_mutex_lock(&g_state_mutex);
    g_quadrature_state = (level == 0) ? Q_B_LOW : Q_B_HIGH;
    pthread_mutex_unlock(&g_state_mutex);
}

static void process_quadrature(void) {
    pthread_mutex_lock(&g_state_mutex);
    int current = g_quadrature_state;
    int prev = g_previous_state;
    g_previous_state = current;
    g_rotation_count++;

    if (current == Q_IDLE) {
        return; /* No rotation yet */
    }

    /* Detect falling edge on A (A -> B transition) */
    if (prev == Q_A_HIGH && current == Q_B_LOW) {
        log_rotation("CW");
    } else if (prev == Q_B_HIGH && current == Q_A_LOW) {
        log_rotation("CCW");
    }
    pthread_mutex_unlock(&g_state_mutex);
}

