    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callbacks for both edges */
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_a_alert) != 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensor_b_alert) != 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        process_quadrature();
        usleep(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&g_state_mutex);
    return EXIT_SUCCESS;
}

