#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    openlog("touch_sensor_app", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_message(LOG_ERR, "Failed to register SIGINT handler: ");
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message(LOG_ERR, "Failed to register SIGTERM handler: ");
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip0: ");
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        log_message(LOG_ERR, "Failed to get touch sensor line (GPIO 23): ");
        perror("gpiod_chip_get_line (touch)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_message(LOG_ERR, "Failed to get LED line (GPIO 18): ");
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor_app") < 0) {
        log_message(LOG_ERR, "Failed to request touch sensor line as input: ");
        perror("gpiod_line_request_input (touch)");
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "touch_sensor_app", 0) < 0) {
        log_message(LOG_ERR, "Failed to request LED line as output: ");
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    log_message(LOG_INFO, "Touch sensor application started.");

    while (program_running) {
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            log_message(LOG_ERR, "Failed to read touch sensor value: ");
            perror("gpiod_line_get_value");
            break;
        }

        if (touch_value == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_message(LOG_ERR, "Failed to turn on LED: ");
                perror("gpiod_line_set_value (LED on)");
                break;
            }
            log_message(LOG_INFO, "Touch detected, LED turned on.");
        } else {
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_message(LOG_ERR, "Failed to turn off LED: ");
                perror("gpiod_line_set_value (LED off)");
                break;
            }
            log_message(LOG_INFO, "Touch released, LED turned off.");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_message(LOG_INFO, "Touch sensor application shutting down.");
    gpiod_line_set_value(led_line, 0);
    ret = EXIT_SUCCESS;

cleanup:
    if (touch_line) gpiod_line_release(touch_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

