#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TOUCH_GPIO 17
#define LED_GPIO 18
#define CONSUMER "touch-led-toggle"
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the touch sensor line */
    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", TOUCH_GPIO, strerror(errno));
        goto cleanup;
    }

    /* Request rising-edge events on the touch line */
    if (gpiod_line_request_rising_edge_events(touch_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO %d: %s\n",
                TOUCH_GPIO, strerror(errno));
        goto cleanup;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", LED_GPIO, strerror(errno));
        goto cleanup;
    }

    /* Request the LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor on GPIO %d, LED on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_GPIO, LED_GPIO);

    int led_state = 0;
    struct timespec last_event = {0, 0};

    while (running) {
        /* Block up to 1 second waiting for a rising edge */
        int rv = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
        if (rv < 0) {
            if (errno == EINTR) {
                continue;  /* interrupted by signal */
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (rv == 0) {
            continue;  /* timeout, no event */
        }

        /* Event detected — read it to confirm and clear the queue */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

