#include <gpiod.h>

#define TOUCH_GPIO 17
#define LED_GPIO 18
#define CONSUMER "touch-led-toggle"
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
