#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    uint32_t timestamp;
    int      sensor_pin;
    int      led_pin;
    int      state;
} LogEntry;

typedef struct {
    LogEntry buffer[BUFFER_SIZE];
    int      head;
    int      tail;
    int      count;
    int      overflow;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, LED_1_PIN, LED_2_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Warning: gpioSetPullUpDown failed for pin %d.\n", pins[i]);
        }
    }

    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d.\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d.\n", LED_2_PIN);
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for LED pin %d.\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for LED pin %d.\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void add_to_buffer(CircularBuffer *cb, int sensor_pin, int led_pin, int state)
{
    LogEntry *entry = &cb->buffer[cb->head];
    entry->timestamp   = (uint32_t)time(NULL);
    entry->sensor_pin  = sensor_pin;
    entry->led_pin     = led_pin;
    entry->state       = state;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
        cb->overflow++;
    } else {
        cb->count++;
    }
}

static void print_buffer(const CircularBuffer *cb)
{
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        int idx = (cb->tail + i) % BUFFER_SIZE;
        LogEntry *e = &cb->buffer[idx];
        printf("  [%d] %u  Sensor=%d  LED=%d  State=%d\n",
               i, e->timestamp, e->sensor_pin, e->led_pin, e->state);
    }
    if (cb->overflow > 0) {
        printf("  [Overflow] %d event(s) dropped when buffer wrapped.\n", cb->overflow);
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    CircularBuffer log_buf;
    memset(&log_buf, 0, sizeof(log_buf));
    log_buf.head  = 0;
    log_buf.tail  = 0;
    log_buf.count = 0;
    log_buf.overflow = 0;

    int prev_state_1 = -1;
    int prev_state_2 = -1;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        int new_state_1 = (s1 == 1) ? 1 : 0;
        int new_state_2 = (s2 == 1) ? 1 : 0;

        if (new_state_1 != prev_state_1) {
            add_to_buffer(&log_buf, SENSOR_1_PIN, LED_1_PIN, new_state_1);
            if (gpioWrite(LED_1_PIN, new_state_1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed for LED pin %d.\n", LED_1_PIN);
                break;
            }
            prev_state_1 = new_state_1;
        }

        if (new_state_2 != prev_state_2) {
            add_to_buffer(&log_buf, SENSOR_2_PIN, LED_2_PIN, new_state_2);
            if (gpioWrite(LED_2_PIN, new_state_2) != 0) {
                fprintf(stderr, "Error: gpioWrite failed for LED pin %d.\n", LED_2_PIN);
                break;
            }
            prev_state_2 = new_state_2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();

    print_buffer(&log_buf);
    return EXIT_SUCCESS;
}

