            }
        } else {
            armed = 1;
        }

        prev_s1 = v1;
        prev_s2 = v2;

        gpioDelay(10000);  // 10 ms loop delay
    }

    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

