#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define EXPECTED_PART_ID 0x82
#define LOG_FILE "biometric_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id = 0;
    if (read_register(handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID: 0x%02X)\n", part_id);

    if (write_register(handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to configure Si1182\n");
        return -1;
    }
    return 0;
}

static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t data = 0;
    if (read_register(handle, HEART_RATE_REG, &data) != 0) {
        return -1;
    }
    *heart_rate = (int)data;
    return 0;
}

static int read_spo2(int handle, int *spo2) {
    uint8_t data = 0;
    if (read_register(handle, SPO2_REG, &data) != 0) {
        return -1;
    }
    *spo2 = (int)data;
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Logging heart rate and SpO2 to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        int heart_rate = 0;
        int spo2 = 0;

        if (read_heart_rate(i2c_handle, &heart_rate) == 0 &&
            read_spo2(i2c_handle, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

