#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27
#define POLL_DELAY_US 100000  /* 100 ms */
#define TILT_THRESHOLD_SEC 2

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    if (!g_log) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");
    fprintf(g_log, "%s: %s\n", ts, msg);
    fflush(g_log);
}

static void activate_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) != 0)
        log_event("ERROR: failed to set alarm GPIO HIGH");
    else
        log_event("ALARM: tilt threshold exceeded");
}

static void deactivate_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 0) != 0)
        log_event("ERROR: failed to set alarm GPIO LOW");
    else
        log_event("ALARM: tilt threshold cleared");
}

static void cleanup(void)
{
    deactivate_alarm();
    if (g_log) {
        log_event("INFO: shutting down");
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize alarm GPIO LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen("bridge_integrity.log", "a");
    if (!g_log) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("INFO: Bridge integrity monitoring started");

    int prev_s1 = -1, prev_s2 = -1;
    int s1 = gpioRead(SENSOR_1_GPIO);
    int s2 = gpioRead(SENSOR_2_GPIO);
    if (s1 < 0 || s2 < 0) {
        fprintf(stderr, "Initial gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
        cleanup();
        return EXIT_FAILURE;
    }
    if (s1 == 1 || s2 == 1) {
        activate_alarm();
        log_event("INFO: tilt threshold exceeded at startup");
    }

    uint32_t tilt_start_tick = 0;
    int tilt_active = 0;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            log_event("ERROR: gpioRead failed");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 != prev_s1 || s2 != prev_s2) {
            if (s1 == 1 && s2 == 1) {
                if (!tilt_active) {
                    tilt_start_tick = gpioTick();
                    tilt_active = 1;
                    activate_alarm();
                    log_event("INFO: tilt threshold exceeded");
                }
            } else {
                if (tilt_active) {
                    uint32_t elapsed = gpioTick() - tilt_start_tick;
                    if (elapsed >= (uint32_t)(TILT_THRESHOLD_SEC * 1000000)) {
                        deactivate_alarm();
                        tilt_active = 0;
                        log_event("INFO: tilt threshold cleared");
                    }
                }
                tilt_active = 0;
            }
            prev_s1 = s1;
            prev_s2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

