/*
 * Raspberry Pi 3 Model B+ - Omron D7S-A0011 Seismic Sensor Monitor
 *
 * Wiring:
 *   D7S-A0011 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   D7S-A0011 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   D7S-A0011 VDD  -> 3.3 V
 *   D7S-A0011 GND  -> GND
 *   LED anode     -> GPIO 17 (with ~330 ohm series resistor)
 *   LED cathode   -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500           /* arbitrary vibration units */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_DURATION_US   1000000       /* 1 s */
#define LOG_FILE             "seismic_events.log"
#define MAX_RETRIES          3
#define SENSOR_REG_CTRL1     0x1F
#define SENSOR_REG_X_LSB     0x28
#define SENSOR_REG_X_MSB     0x29
#define SENSOR_REG_Y_LSB     0x2A
#define SENSOR_REG_Y_MSB     0x2B
#define SENSOR_REG_Z_LSB     0x2C
#define SENSOR_REG_Z_MSB     0x2D

/* CTRL1 register bits (D7S-A0011 datasheet) */
#define CTRL1_PD_BIT         0x80          /* power-down bit (clear to enable) */

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_sensor(void);
static int  read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
static double calculate_vibration(int16_t x, int16_t y, int16_t z);
static void log_event(double vibration);
static void cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- Sensor Init ------------------------------- */
static int init_sensor(void)
{
    int rc;

    /* Open I2C bus to the sensor */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(i2c_handle, SENSOR_REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X: %d\n",
                I2C_ADDR, ctrl1);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Clear power-down bit to enable sensor */
    rc = i2cWriteByteData(i2c_handle, SENSOR_REG_CTRL1, ctrl1 & ~CTRL1_PD_BIT);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to clear CTRL1 (0x%02X): %d\n",
                ctrl1, rc);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(100000); /* 100 ms */

    return 0;
}

/* ----------------------------- Read 6-byte acceleration block ---------------- */
static int read_sensor_data(int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];
    int  rc;

    rc = i2cReadI2CBlockData(i2c_handle, SENSOR_REG_X_LSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d (expected 6)\n", rc);
        return -1;
    }

    *x = (int16_t)((uint16_t)buffer[1] << 8 | (uint8_t)buffer[0]);
    *y = (int16_t)((uint16_t)buffer[3] << 8 | (uint8_t)buffer[2]);
    *z = (int16_t)((uint16_t)buffer[5] << 8 | (uint8_t)buffer[4]);

    return 0;
}

/* ----------------------------- Vibration magnitude ------------------------- */
static double calculate_vibration(int16_t x, int16_t y, int16_t z)
{
    double dx = (double)x;
    double dy = (double)y;
    double dz = (double)z;

    return sqrt(dx * dx + dy * dy + dz * dz);
}

/* ----------------------------- Log Event ----------------------------------- */
static void log_event(double vibration)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Vibration: %.2f\n", timestamp, vibration);
    fflush(log_file);
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main ---------------------------------------- */
int main(void)
{
    int16_t x, y, z;
    double   vibration;
    int      consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[FATAL] fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction SIGINT");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction SIGTERM");
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    printf("Threshold: %d | LED on GPIO %d | Log: %s\n",
           VIBRATION_THRESHOLD, LED_GPIO, LOG_FILE);

    /* Main polling loop */
    while (running) {
        int rc = read_sensor_data(&x, &y, &z);

        if (rc == 0) {
            consecutive_errors = 0;
            vibration = calculate_vibration(x, y, z);

            if (vibration > VIBRATION_THRESHOLD) {
                printf("Vibration exceeded threshold (%.2f > %d) - LED ON\n",
                       vibration, VIBRATION_THRESHOLD);
                gpioWrite(LED_GPIO, 1);
                log_event(vibration);

                /* Keep LED on for 1 s, checking running flag every 100 ms */
                uint32_t elapsed = 0;
                while (running && elapsed < LED_ON_DURATION_US) {
                    gpioDelay(100000);
                    elapsed += 100000;
                }
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Sensor read failed (%d consecutive)\n",
                    consecutive_errors);

            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "[ERROR] Max consecutive I2C failures "
                                "reached - attempting sensor re-init.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;

                if (init_sensor() != 0) {
                    fprintf(stderr, "[ERROR] Re-init failed - exiting.\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

