/*
 * flame_monitor.c - KY-026 flame sensor monitor using libgpiod
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   KY-026 DO  -> BCM GPIO 2 (physical pin 3)
 *   KY-026 DO  -> BCM GPIO 3 (physical pin 5)
 *   KY-026 DO  -> BCM GPIO 4 (physical pin 7)
 *   KY-026 DO  -> BCM GPIO17 (physical pin 11)
 *   KY-026 DO  -> BCM GPIO27 (physical pin 13)
 *   KY-026 VCC -> 3.3 V (physical pin 1)
 *   KY-026 GND -> GND   (physical pin 9)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
static const unsigned int sensor_gpios[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_names[NUM_SENSORS] = {"sensor1", "sensor2", "sensor3", "sensor4", "sensor5"};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(int sensor_id, int gpio_pin)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed: %s", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return;
    }

    FILE *fp = fopen("/var/log/flame_events.log", "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Cannot open log file: %s", strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %s (GPIO %u) - Flame Detected\n",
                timestamp, sensor_names[sensor_id], gpio_pin) < 0) {
        syslog(LOG_ERR, "fprintf to log failed: %s", strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose failed: %s", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int line_acquired[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_state, 0, sizeof(prev_state));

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_gpios[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_gpios[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u) failed: %s",
                   sensor_gpios[i], strerror(errno));
            goto cleanup;
        }

        line_acquired[i] = 1;
        prev_state[i] = gpiod_line_get_value(lines[i]);
        if (prev_state[i] < 0) {
            syslog(LOG_ERR, "Initial gpiod_line_get_value(%u) failed: %s",
                   sensor_gpios[i], strerror(errno));
            goto cleanup;
        }
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (GPIOs: %u, %u, %u, %u, %u)",
           sensor_gpios[0], sensor_gpios[1], sensor_gpios[2], sensor_gpios[3], sensor_gpios[4]);

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                       sensor_gpios[i], strerror(errno));
                continue;
            }

            if (val == 1 && prev_state[i] == 0) {
                log_event(i, sensor_gpios[i]);
            }
            prev_state[i] = val;
        }
        sleep(1);
    }

    syslog(LOG_INFO, "Flame sensor monitoring stopped");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (line_acquired[i] && lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

