/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod v1.x.
 *
 * Wiring (TTP226 OUT0-OUT7 -> BCM):
 *   OUT0 -> GPIO5 (pin 29)
 *   OUT1 -> GPIO6 (pin 31)
 *   OUT2 -> GPIO13 (pin 33)
 *   OUT3 -> GPIO19 (pin 35)
 *   OUT4 -> GPIO26 (pin 37)
 *   OUT5 -> GPIO12 (pin 32)
 *   OUT6 -> GPIO16 (pin 36)
 *   OUT7 -> GPIO20 (pin 38)
 *
 * Build: gcc -Wall -Wextra -O2 -o ttp226 ttp226.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
        printf("[%s] ", buffer);
    } else {
        printf("[unknown-time] ");
    }
}

static void log_touch_event(int sensor_index, unsigned int pin)
{
    print_timestamp();
    printf("Touch detected/lost on sensor %d (BCM pin %u)\n",
           sensor_index, pin);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line *lines_ptr = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default gpiochip (gpiochip0 on RPi 3B+) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Resolve all 8 lines into the bulk array --- */
    lines_count = NUM_CHANNELS;
    lines_ptr = gpiod_line_bulk_init(&lines);
    if (lines_ptr == NULL) {
        fprintf(stderr, "Failed to allocate line bulk array: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* --- Request all lines as inputs --- */
    if (gpiod_line_request_bulk_input(&lines, "ttp226-touch") < 0) {
        fprintf(stderr, "Failed to request lines as inputs: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (program_running) {
        int prev_values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            prev_values[i] = gpiod_line_get_value(lines_ptr, i);
            if (prev_values[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
        }

        if (read_ok) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                int cur = gpiod_line_get_value(lines_ptr, i);
                if (cur < 0) {
                    fprintf(stderr, "Failed to read GPIO %u: %s\n",
                            touch_pins[i], strerror(errno));
                    continue;
                }

                /* Log only on state change */
                if (cur != prev_values[i]) {
                    log_touch_event(i, touch_pins[i]);
                }
                prev_values[i] = cur;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (lines_ptr != NULL) {
        gpiod_line_bulk_free(lines_ptr);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

