    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Resolve all 8 lines into the bulk array --- */
    lines_count = NUM_CHANNELS;
    lines_ptr = gpiod_line_bulk_init(&lines);
    if (lines_ptr == NULL) {
        fprintf(stderr, "Failed to allocate line bulk array: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* --- Request all lines as inputs --- */
    if (gpiod_line_request_bulk_input(&lines, "ttp226-touch") < 0) {
        fprintf(stderr, "Failed to request lines as inputs: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (program_running) {
        int prev_values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            prev_values[i] = gpiod_line_get_value(lines_ptr, i);
            if (prev_values[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
        }

        if (read_ok) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                int cur = gpiod_line_get_value(lines_ptr, i);
                if (cur < 0) {
                    fprintf(stderr, "Failed to read GPIO %u: %s\n",
                            touch_pins[i], strerror(errno));
                    continue;
                }

                /* Log only on state change */
                if (cur != prev_values[i]) {
                    log_touch_event(i, touch_pins[i]);
                }
                prev_values[i] = cur;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (lines_ptr != NULL) {
        gpiod_line_bulk_free(lines_ptr);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

