#define VEML7700_ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_config(uint16_t config) {
    char buf[2];
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;
    if (i2cWriteI2CBlockData(i2c_handle, VEML7700_CONFIG_REG, buf, 2) < 0) {
        fprintf(stderr, "Error writing config to VEML7700: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_als(uint16_t *als) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, VEML7700_ALS_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading ALS from VEML7700: %s\n", strerror(errno));
        return -1;
    }
    *als = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int calculate_brightness(uint16_t lux) {
    if (lux < LUX_THRESHOLD_1) return 100;
    if (lux < LUX_THRESHOLD_2) return 75;
    if (lux < LUX_THRESHOLD_3) return 50;
    return 25;
}

static void log_data(uint16_t lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Lux: %u, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

