#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define DEBOUNCE_MS 50
#define POLL_DELAY_US 50000

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO %d\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void log_touch_event(int channel) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open touch_log.txt: %s\n", strerror(errno));
        return;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error: writing to touch_log.txt failed\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: closing touch_log.txt failed: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Security Keypad running. Press Ctrl+C to exit.\n");

    int prev_state = 0;
    int led_on = 0;

    while (running) {
        int touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(touch_pins[i]);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", touch_pins[i]);
                continue;
            }

            if (level == 1 && !prev_state) {
                log_touch_event(i + 1);
            }

            touched |= (level == 1) ? (1 << i) : 0;
        }

        if (touched && !led_on) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on\n");
            } else {
                led_on = 1;
            }
        } else if (!touched && led_on) {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off\n");
            } else {
                led_on = 0;
            }
        }

        prev_state = touched;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

