#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* OPT3001 I2C address (ADDR pin tied to GND) */
#define OPT3001_ADDR 0x44

/* OPT3001 register addresses */
#define OPT3001_RESULT_REG 0x00
#define OPT3001_CONFIG_REG 0x01

/* Configuration word: continuous conversion, auto-range, 100 ms CT */
#define OPT3001_CONFIG_VALUE 0xC810

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown (Ctrl+C) */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Byte-swap a 16-bit little-endian word to OPT3001 big-endian format */
static uint16_t swap_word(uint16_t word) {
    return (uint16_t)((word >> 8) | (word << 8));
}

/* Read 16-bit result from OPT3001; returns -1 on error */
static int read_result(int handle, uint16_t *result) {
    int word = i2cReadWordData(handle, OPT3001_RESULT_REG);
    if (word < 0) {
        fprintf(stderr, "Error reading result register: %s\n", strerror(errno));
        return -1;
    }
    *result = swap_word((uint16_t)word);
    return 0;
}

/* Write 16-bit configuration to OPT3001; returns -1 on error */
static int write_config(int handle, uint16_t config) {
    uint16_t swapped = swap_word(config);
    int rc = i2cWriteWordData(handle, OPT3001_CONFIG_REG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Convert raw result to lux; returns -1.0 on invalid exponent */
static double convert_to_lux(uint16_t raw) {
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    if (exponent == 0xFF) {
        fprintf(stderr, "Invalid exponent (0xFF) from sensor\n");
        return -1.0;
    }
    return (double)mantissa * 0.01 * (1 << exponent);
}

/* Log lux value to file and stdout; returns 0 on success, -1 on error */
static int log_data(double lux) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    FILE *fp = fopen("light_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

