#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int flame_detected) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame: %s\n", timestamp, flame_detected ? "DETECTED" : "NOT DETECTED");
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(1000000); /* 1 second in microseconds */
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
    }
}

int main(void) {
    int ret;

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialization failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure flame sensor pin as input */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alert pin as output, initially LOW */
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor pin: %d\n", sensor_value);
            log_event(0);
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        /* KY-026 DO is LOW (0) when flame is detected */
        int flame_detected = (sensor_value == 0);

        log_event(flame_detected);

        if (flame_detected) {
            trigger_alert();
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

