#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_DELAY_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_touch_event(FILE *log_file, int touch_detected) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, touch_detected ? "Touch Detected" : "Touch Released") < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input_flags(line, "ttp223-touch",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-down: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_line;
    }

    printf("Touch sensor logging started on %s line %d. Press Ctrl+C to exit.\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET);

    int last_state = gpiod_line_get_value(line);
    if (last_state < 0) {
        fprintf(stderr, "Initial read of GPIO line %d failed: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_log;
    }

    while (program_running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        if (current_state != last_state) {
            if (log_touch_event(log_file, current_state) != 0) {
                fprintf(stderr, "Failed to log touch event.\n");
            }
            last_state = current_state;
        }

        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

cleanup_log:
    if (log_file != NULL) {
        fclose(log_file);
    }

cleanup_line:
    gpiod_line_release(line);

cleanup_chip:
    gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }

    return ret;
}

