#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SLF3S_ADDR     0x08
#define START_MEAS_CMD  0x3608
#define FLOW_SCALE     90.0f
#define MIN_FLOW       0.0f
#define MAX_FLOW       100.0f
#define SAMPLE_US      1000000  /* 1 second */
#define MEAS_DELAY_US  2000     /* 2 ms after start command */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SLF3S_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = { (uint8_t)(START_MEAS_CMD >> 8), (uint8_t)(START_MEAS_CMD & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (start meas) failed: %d\n", rc);
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "i2cReadDevice failed: expected 3 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

static void log_data(float flow_rate, int status) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,%s\n", ts, flow_rate, status == 0 ? "OK" : "ERROR");
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void log_error(const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file) {
        fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open: %s\n", msg);
    }
}

static void log_out_of_range(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,OUT_OF_RANGE\n", ts, flow_rate);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open: %.2f ml/min out of range\n", flow_rate);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        perror("fopen(cooling_log.csv)");
        cleanup();
        return 1;
    }

    /* Write header only if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }

    printf("Cooling system monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (start_measurement() != 0) {
            log_error("Failed to start measurement");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float flow_rate;
        if (read_flow_rate(&flow_rate) != 0) {
            log_error("Failed to read flow rate");
            if (start_measurement() != 0) {
                log_error("Failed to re-start measurement");
            }
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (flow_rate < MIN_FLOW || flow_rate > MAX_FLOW) {
            log_out_of_range(flow_rate);
        } else {
            int status = 0;
            log_data(flow_rate, status);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

