{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        return -1;
    }
    return 0;
}

