        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO%u: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
