        int lr = gpiod_line_get_value(lines[2]);

        if (lv < 0 || lm < 0 || lr < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            break;
        }

        if (fprintf(log_fp, "%s,%d,%d,%d\n", ts, lv, lm, lr) < 0) {
            perror("fprintf");
            break;
        }
        if (fflush(log_fp) == EOF) {
            perror("fflush");
            break;
        }

        usleep(POLL_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        if (fclose(log_fp) == EOF) {
            perror("fclose");
        }
    }
    return rc;
}

