#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 4
#define LOG_FILE "flame_events.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_flame_event(FILE *log_file, const char *timestamp) {
    if (fprintf(log_file, "%s: Flame detected!\n", timestamp) < 0) {
        perror("Error writing to log file");
    }
    fflush(log_file);
}

static void print_alert(const char *timestamp) {
    printf("%s: Flame detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "flame_sensor") < 0) {
        perror("Failed to request falling edge events on GPIO line");
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    while (program_running) {
