    struct sigaction sa;
    int prev_flame = 1;  /* assume no flame at startup (active-low) */
    int ret = EXIT_FAILURE;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_GPIO);
    if (!flame_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", FLAME_GPIO, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", BUZZER_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (log_event("System started") < 0) {
        fprintf(stderr, "Failed to log startup event\n");
        goto cleanup;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            break;
        }

        if (val == 0 && prev_flame == 1) {
            printf("Flame detected!\n");
            if (log_event("Flame detected") < 0) {
                break;
            }
            if (activate_buzzer(BUZZER_DURATION_MS) < 0) {
                break;
            }
        }
        prev_flame = val;

        if (program_running) {
            usleep(POLL_INTERVAL_MS * 1000);
        }
    }

    if (log_event("System stopped") < 0) {
        fprintf(stderr, "Failed to log shutdown event\n");
    }
    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

