#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/*
 * TMAG5110A1 Hall-effect latch sensor.
 * The OUT pin is open-drain: it pulls low when a south pole is present
 * and releases high when the magnet is removed.  A logic low therefore
 * means "magnet present" and a logic high means "magnet removed".
 *
 * The internal pull-up resistor is enabled so that the pin reads HIGH
 * when the sensor is idle (no magnet) and LOW when a south pole is
 * present.
 */

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE    "magnet_log.txt"
#define POLL_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — just set the flag; async-signal-safe only          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin.  Returns 0 or 1 on success, -1 on error.         */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Log a state change with an ISO-8601 timestamp.                      */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s - Sensor %d: %s\n",
                ts, sensor_id, state ? "MAGNET_PRESENT" : "MAGNET_REMOVED") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure all three sensor pins.             */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    const char *names[] = {"SENSOR1", "SENSOR2", "SENSOR3"};

    for (int i = 0; i < 3; i++) {
        int pin = pins[i];
        if (gpioSetMode(pin, PI_INPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed for %s (pin %d): %s\n",
                    names[i], pin, pigpio_error(pin));
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
            fprintf(stderr, "gpioSetPullUpDown failed for %s (pin %d): %s\n",
                    names[i], pin, pigpio_error(pin));
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open log file in append mode */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return 1;
    }

    /* Initialize pigpio and configure sensor pins */
    if (initialize_gpio() != 0) {
        fclose(g_log);
        g_log = NULL;
        return 1;
    }

    int prev_state[3] = {1, 1, 1};   /* assume no magnet at startup */
    printf("Monitoring TMAG5110A1 sensors on GPIO4, GPIO17, GPIO27.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
            gpioDelay(POLL_US);
            continue;
        }

        /* Log initial state without falsely logging a transition */
        if (prev_state[0] != s1) {
            log_event(1, s1);
            prev_state[0] = s1;
        }
        if (prev_state[1] != s2) {
            log_event(2, s2);
            prev_state[1] = s2;
        }
        if (prev_state[2] != s3) {
            log_event(3, s3);
            prev_state[2] = s3;
        }

        gpioDelay(POLL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return 0;
}

