/*
 * TTP226 8-channel capacitive touch sensor -> 8-bit binary counter
 * Board:  Raspberry Pi Zero W
 * API:    libgpiod v2+ bulk/config (gpiod_chip_open, gpiod_line_request_bulk)
 * Sensor: TTP226 OUT1..OUT8 -> GPIO 5,6,7,8,9,10,11,12 (BCM)
 * Display: GPIO 17 (bit0) -> GPIO 17; GPIO 24 (bit7) -> GPIO 24
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define STABILIZE_MS  200
#define POLL_MS       10
#define LOG_FILE      "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int display_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_touch_event(int channel, int counter)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fclose(fp);
    } else {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *display_req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_config *display_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor lines as inputs ---- */
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int sensor_offsets[NUM_CHANNELS] = {0};
    if (gpiod_line_config_add_line_settings(line_cfg, sensor_offsets, NUM_CHANNELS, settings)) {
        fprintf(stderr, "gpiod_line_config_add_line_settings: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Configure display lines as outputs, default low ---- */
    display_cfg = gpiod_line_config_new();
    if (!display_cfg) {
        fprintf(stderr, "gpiod_line_config_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_config_reset(display_cfg);

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-touch-counter");

    /* ---- Request sensor lines ---- */
    sensor_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines(sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Request display lines ---- */
    display_req = gpiod_chip_request_lines(chip, req_cfg, display_cfg);
    if (!display_req) {
        fprintf(stderr, "gpiod_chip_request_lines(display): %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Stabilization delay ---- */
    usleep(STABILIZE_MS * 1000);

    int prev_state[NUM_CHANNELS] = {0};
    int counter = 0;

    while (program_running) {
        enum gpiod_line_value values[NUM_CHANNELS];
        int read_error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (values[i] == GPIOD_LINE_VALUE_ERROR) {
                fprintf(stderr, "gpiod_line_request_get_value(channel %d): %s\n",
                        i, strerror(errno));
                read_error = 1;
                break;
            }
        }

        if (read_error) {
            usleep(POLL_MS * 1000);
            continue;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current = values[i];
            if (current == GPIOD_LINE_VALUE_ACTIVE) {
                if (prev_state[i] == GPIOD_LINE_VALUE_INACTIVE) {
                    counter++;
                    if (counter > 255) counter = 0;
                    log_touch_event(i + 1, counter);
                }
            } else {
                prev_state[i] = current;
            }
        }

        /* ---- Update display ---- */
