            fprintf(stderr, "Failed to get GPIO line %u: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ky033-tracking") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

    printf("KY-033 4-Way IR Tracking started. Press Ctrl+C to stop.\n");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n", sensor_pins[i], strerror(errno));
                values[i] = -1;
            } else {
                values[i] = val;
            }
        }

        if (log_data(fp, values) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        struct timespec delay = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&delay, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nProgram terminated gracefully.\n");
    }
    return ret;
}

