#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO17 17
#define GPIO18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_MS 50

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (line17) {
        gpiod_line_release(line17);
        line17 = NULL;
    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(int sensor_id) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_id) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct timespec last_event_time[2] = {0, 0};
    int prev17 = 1, prev18 = 1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO17, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO18, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line17, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request line %d as input with pull-up: %s\n", GPIO17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line18, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request line %d as input with pull-up: %s\n", GPIO18, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring tilt sensors on GPIO17 and GPIO18. Press Ctrl+C to exit.\n");

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            fprintf(stderr, "Error reading GPIO17: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }
        if (val18 < 0) {
            fprintf(stderr, "Error reading GPIO18: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val17 == 0 && prev17 == 1) {
            clock_gettime(CLOCK_MONOTONIC, &last_event_time[0]);
        }
        if (val18 == 0 && prev18 == 1) {
            clock_gettime(CLOCK_MONOTONIC, &last_event_time[1]);
        }

        if (val17 == 0) {
            if (log_event(1) == 0) {
                printf("GPIO17 tilted\n");
            }
        }
        if (val18 == 0) {
            if (log_event(2) == 0) {
                printf("GPIO18 tilted\n");
            }
        }

        prev17 = val17;
        prev18 = val18;

        if (val17 == 0) {
            clock_gettime(CLOCK_MONOTONIC, &last_event_time[0]);
        }
        if (val18 == 0) {
            clock_gettime(CLOCK_MONOTONIC, &last_event_time[1]);
        }

