        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(s1, "tcrt5000-s1") < 0) {
        fprintf(stderr, "Request input on GPIO%d failed: %s\n", SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(s2, "tcrt5000-s2") < 0) {
        fprintf(stderr, "Request input on GPIO%d failed: %s\n", SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "led", 0) < 0) {
        fprintf(stderr, "Request output on GPIO%d failed: %s\n", LED_PIN, strerror(errno));
