#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x49
#define I2C_BUS "/dev/i2c-1"
#define ALS_VIS_DATA_LSB_REG 0x24
#define ALS_VIS_DATA_MSB_REG 0x25
#define READ_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, uint8_t reg_msb, uint16_t *val) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_msb, &msb) < 0) return -1;
    *val = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 Heart Rate Sensor Reader\n");
    printf("Bus: %s, Address: 0x%02X\n", I2C_BUS, SI1175_ADDR);
    printf("Reading ALS visible data every %d ms. Press Ctrl+C to exit.\n\n", READ_INTERVAL_MS);

    while (running) {
        uint16_t als_data = 0;
        if (i2c_read_reg16(fd, ALS_VIS_DATA_LSB_REG, ALS_VIS_DATA_MSB_REG, &als_data) < 0) {
            fprintf(stderr, "Error reading ALS data. Retrying in %d ms...\n", READ_INTERVAL_MS);
            usleep(READ_INTERVAL_MS * 1000);
            continue;
        }

        printf("ALS Visible Data: %u\n", als_data);
        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

