#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_DELAY_US 50000  /* 5 seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Convert hue (0-360) to RGB (0-255) using HSV-to-RGB with full saturation/value. */
static void hue_to_rgb(float hue, int *r, int *g, int *b)
{
    if (hue < 0.0f) hue = 0.0f;
    if (hue > 360.0f) hue = 360.0f;

    float h = hue / 360.0f;
    float s = 1.0f;
    float v = 1.0f;

    float c = (1.0f - fabsf(fmodf(h, 2.0f) - 1.0f) * 0.5f) * v;
    float m = (1.0f - fabsf(fmodf(h, 6.0f) - 2.0f) * 0.5f) * v;
    float r1 = c * (1.0f - fabsf(fmodf(h, 360.0f) - 120.0f) * 0.5f) * s;
    float g1 = c * (fabsf(fmodf(h, 360.0f) - 120.0f) * 0.5f) * s;
    float b1 = c * (1.0f + fabsf(fmodf(h, 360.0f) - 120.0f) * 0.5f) * s;

    float r2 = c * (1.0f - fabsf(fmodf(h, 360.0f) - 240.0f) * 0.5f) * s;
    float g2 = c * (fabsf(fmodf(h, 360.0f) - 240.0f) * 0.5f) * s;
    float b2 = c * (1.0f + fabsf(fmodf(h, 360.0f) - 240.0f) * 0.5f) * s;

    *r = (int)(r1 + r2);
    *g = (int)(g1 + g2);
    *b = (int)(b1 + b2);
}

static void set_led_color(int r, int g, int b)
{
    /* Common-anode: invert duty cycle (255 - value) and clamp to [0, 255]. */
    int r_val = 255 - r;
    int g_val = 255 - g;
    int b_val = 255 - b;

    if (r_val < 0) r_val = 0;
    if (r_val > 255) r_val = 255;
    if (g_val < 0) g_val = 0;
    if (g_val > 255) g_val = 255;
    if (b_val < 0) b_val = 0;
    if (b_val > 255) b_val = 255;

    if (gpioPWM(RED_PIN, r_val) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN");
    }
    if (gpioPWM(GREEN_PIN, g_val) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN");
    }
    if (gpioPWM(BLUE_PIN, b_val) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN");
    }
}

static void fade_color(int r, int g, int b, int steps, int delay_us)
{
    for (int i = 0; i < steps; i++) {
        float frac = (float)i / (float)steps;
        int r1 = (int)(r * frac);
        int r2 = (int)((1.0f - frac) * r);
        int g1 = (int)(g * frac);
        int g2 = (int)((1.0f - frac) * g);
        int b1 = (int)(b * frac);
        int b2 = (int)((1.0f - frac) * b);

        set_led_color(r1, g1, b1);
        gpioDelay(delay_us);
        set_led_color(r2, g2, b2);
        gpioDelay(delay_us);
    }
}

int main(void)
{
    srand((unsigned int)time(NULL));

    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure pins as outputs and set PWM frequency/range. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for RED_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GREEN_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for BLUE_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off (common-anode: duty=0 = fully off). */
    set_led_color(0, 0, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Mood lamp started. Press Ctrl+C to exit.");

    while (g_running) {
        int r, g, b;
        hue_to_rgb((float)rand() / RAND_MAX, &r, &g, &b);
        fade_color(r, g, b, FADE_STEPS, FADE_DELAY_US);
    }

    /* Graceful shutdown: turn off LED and release pigpio. */
    set_led_color(0, 0, 0);
    gpioTerminate();
    syslog(LOG_INFO, "Mood lamp stopped.");
    closelog();

    return EXIT_SUCCESS;
}

