/*
 * TCS34725 Color Sensor Reader with LED Threshold Indicator
 * Board:  Raspberry Pi 4 Model B
 * Library: libgpiod (modern Linux GPIO character-device API)
 * I2C:    /dev/i2c-1, TCS34725 fixed address 0x29
 * LED:    GPIO17 (BCM), active-HIGH
 *
 * Build:  gcc -O2 -Wall -o tcs34725 tcs34725.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_CMD   0x80
#define TCS34725_ID    0x12
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ENABLE_AEN_G 0x04

#define TCS34725_ID_VALUE   0x44

#define LED_PIN 17
#define RED_THRESHOLD 200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_CMD | reg), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_CMD | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_CMD | reg);
    uint8_t buf[2];
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_byte(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Cannot read sensor ID.\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x%02X).\n", id, TCS34725_ID_VALUE);
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) return -1;
    usleep(3000);

    if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) != 0) return -1;
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x00) != 0) return -1;

    if (i2c_write_byte(fd, TCS34725_ENABLE,
                      TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) return -1;

    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c)
{
    if (i2c_read_word(fd, TCS34725_CDATA, c) != 0) return -1;
    if (i2c_read_word(fd, TCS34725_RDATA, r) != 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATA, g) != 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATA, b) != 0) return -1;
    return 0;
}

static void calibrate(uint16_t raw_r, uint16_t raw_g, uint16_t raw_b,
                      uint16_t raw_c, float *cal_r, float *cal_g, float *cal_b, float *cal_c)
{
    const float gain = 0.0001f;
    const float offset = 0.0f;

    *cal_r = (float)raw_r * gain + offset;
    *cal_g = (float)raw_g * gain + offset;
    *cal_b = (float)raw_b * gain + offset;
    *cal_c = (float)raw_c * gain + offset;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip4: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 ready. Polling every 200 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_r, raw_g, raw_b, raw_c;
        if (tcs34725_read(i2c_fd, &raw_r, &raw_g, &raw_b, &raw_c) != 0) {
            fprintf(stderr, "Read error; re-initializing sensor.\n");
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; retrying in 1 s.\n");
                sleep(1);
                continue;
            }
            continue;
        }

        float cal_r, cal_g, cal_b, cal_c;
        calibrate(raw_r, raw_g, raw_b, raw_c, &cal_r, &cal_g, &cal_b, &cal_c);

        printf("R: %6.2f  G: %6.2f  B: %6.2f  C: %6.2f\n", cal_r, cal_g, cal_b, cal_c);

        int led_val = (cal_r > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_val) < 0) {
            fprintf(stderr, "GPIO write failed: %s\n", strerror(errno));
        }

        usleep(200000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

