#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_US 180000
#define NUM_LEDS 10
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PWM_DUTY_MAX 1000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(void) {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error writing BH1750 command\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(float *lux) {
    if (i2c_handle < 0) return -1;
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) return -1;
    gpioDelay(BH1750_CONV_TIME_US);

    char buf[2];
    int n = i2cReadDevice(i2c_handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error reading BH1750: %d\n", n);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int map_light_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 1000.0f) lux = 1000.0f;
    float norm = log10f(lux + 1.0f) / log10f(1000.0f + 1.0f);
    int brightness = (int)(norm * 100.0f);
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_DUTY_MAX) brightness = PWM_DUTY_MAX;
    return brightness;
}

static void ws2812b_set_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_DUTY_MAX) brightness = PWM_DUTY_MAX;
    uint32_t duty = (uint32_t)brightness;
    uint32_t period = 1000000 / PWM_FREQ;
    uint32_t on_us = (duty * period) / PWM_RANGE;
    uint32_t off_us = period - on_us;
    gpioPWM(18, on_us);
    gpioDelay(off_us);
}

static void ws2812b_write_leds(uint8_t r, uint8_t g, uint8_t b) {
    uint32_t on_us = (uint32_t)PWM_DUTY_MAX * period / 3;
    uint32_t off_us = period - on_us;
    gpioPWM(18, on_us);
    gpioDelay(1);
    uint32_t gr = (uint32_t)r | ((uint32_t)g << 8) | ((uint32)t)b;
    for (int i = 0; i < NUM_LEDS; i++) {
        gpioWrite(18, (gr >> (8 - i)) & 1);
        gpioDelay(1);
    }
    gpioPWM(18, off_us);
    gpioDelay(1);
}

static void ws2812b_clear(void) {
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_write_leds(0, 0, 0);
    }
}

static void cleanup(void) {
    ws2812b_clear();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (bh1750_init() != 0) {
        cleanup();
        return 1;
    }

    ws2812b_clear();

    while (running) {
        float lux;
        int retries = 3;
        int success = 0;
        while (retries-- > 0 && running) {
            if (bh1750_read_lux(&lux) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "BH1750 read failed, retries left: %d\n", retries);
            gpioDelay(100000);
        }
        if (!success) {
            fprintf(stderr, "BH1750 read failed after retries, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int brightness = map_light_to_brightness(lux);
        ws2812b_set_brightness(brightness);
        ws2812b_write_leds((uint8_t)(brightness / 10), (uint8_t)((brightness % 10) / 10), (uint8_t)((brightness % 10) % 10));

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

