/*
 * Raspberry Pi Zero W: BH1750 Ambient Light Sensor -> APA102 LED Strip
 *
 * Wiring:
 *   BH1750 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VCC 3.3V, GND
 *   APA102 DIN -> GPIO11 (pin 23, SPI0 SCLK), VCC 5V, GND
 *
 * Build: gcc -O2 -Wall -o light_led light_led.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR             0x23
#define BH1750_ONE_TIME_HRES    0x20   /* One-Time High-Resolution, ~120 ms */
#define BH1750_CONV_TIME_MS    120
#define BH1750_MAX_LUX         300.0f
#define MIN_LUX                10.0f
#define NUM_LEDS               10
#define SPI_DEVICE             "/dev/spidev0.0"
#define SPI_SPEED_HZ           1000000
#define SPI_BITS_PER_WORD      8
#define SPI_MODE               SPI_MODE_0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_spi_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/*
 * Read lux from BH1750. Returns 0 on success, -1 on error.
 */
static int read_bh1750(float *lux_out)
{
    uint8_t cmd = BH1750_ONE_TIME_HRES;
    ssize_t w = write(g_i2c_fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write failed: %s\n", strerror(errno));
        return -1;
    }

    sleep_ms(BH1750_CONV_TIME_MS);

    uint8_t buf[2];
    ssize_t r = read(g_i2c_fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/*
 * Map lux to APA102 5-bit global brightness (0-31).
 */
static uint8_t map_lux_to_brightness(float lux)
{
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > BH1750_MAX_LUX) lux = BH1750_MAX_LUX;
    return (uint8_t)((lux - MIN_LUX) / (BH1750_MAX_LUX - MIN_LUX) * 31.0f);
}

/*
 * Send one APA102 frame via SPI.
 * Frame layout (32 bits each):
 *   0x00 0x00 0x00 0x00  ... 0x00 0x00 0x00 0x00  ... 0x00 0x00 0x00 0x00
 *   0xE0 | brightness | blue | green | red
 *   0xFF 0xFF 0xFF 0xFF  ... 0xFF 0xFF 0xFF 0xFF  ... 0xFF 0xFF 0xFF 0xFF
 */
static int send_apa102_frame(uint8_t brightness)
{
    uint8_t frame[4 + 4 + 4 + 4 + 4 + 4 + 4 + 4 + 4 + 4];
    uint8_t *p = frame;

    /* Start frame: 32 zeros */
    for (int i = 0; i < 32; i++) {
        p[0] = 0x00;
        p++;
    }

    /* LED frames: one per LED */
    for (int i = 0; i < NUM_LEDS; i++) {
        uint8_t led_frame[4];
        led_frame[0] = 0xE0 | brightness;
        led_frame[1] = 0xFF;   /* blue   */
        led_frame[2] = 0xFF;   /* green  */
        led_frame[3] = 0xFF;   /* red    */
        memcpy(p, led_frame, 4);
        p += 4;
    }

    /* End frame: 32 ones */
    for (int i = 0; i < 32; i++) {
        p[0] = 0xFF;
        p++;
    }

    size_t total = sizeof(frame);
    ssize_t w = write(g_spi_fd, frame, total);
    if (w != total) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        /* Turn off all LEDs */
        uint8_t off = 0;
        while (send_apa102_frame(off) < 0) {
            /* Non-fatal: keep trying */
        }
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open " SPI_DEVICE);
        cleanup();
        return EXIT_FAILURE;
    }
    uint8_t spi_mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        cleanup();
        return EXIT_FAILURE;
    }
    uint8_t spi_bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return EXIT_FAILURE;
    }
    uint32_t spi_speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 -> APA102 running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux;
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Sensor read failed; skipping cycle.\n");
            sleep_ms(100);
            continue;
        }

        uint8_t brightness = map_lux_to_brightness(lux);
        if (send_apa102_frame(brightness) < 0) {
            fprintf(stderr, "SPI write failed; continuing.\n");
        }

        sleep_ms(100);
    }

