#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_LEDS 10
#define FADE_STEPS 500
#define FADE_DELAY_US 100000
#define LOOP_DELAY_US 100000

#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handles[NUM_SENSORS];
static int spi_handle;
static int led_pins[NUM_LEDS];
static int num_leds = NUM_LEDS;
static int num_sensors = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HRES2) < 0) {
        fprintf(stderr, "Error: Failed to write One-Time High-Resolution Mode 2 command to BH1750 at 0x%02X\n", handle);
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    return 0;
}

static int read_bh1750(int handle) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 at 0x%02X (got %d)\n", handle, bytes);
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    return (int)raw;
}

static int map_lux_to_brightness(int lux) {
    if (lux < 0) lux = 0;
    if (lux > 65535) lux = 65535;
    int brightness = 31 - (int)((lux / 65535.0) * 31.0);
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    return brightness;
}

static void set_led_brightness(int led, int brightness) {
    if (led < 0 || led >= num_leds) return;
    int idx = led;
    for (int i = 0; i < NUM_LEDS; i++) {
        if (i == idx) {
            gpioWrite(led_pins[i], (brightness > 0) ? 1 : 0);
        }
    }
}

static void fade_strip(int brightness) {
    for (int i = 0; i < FADE_STEPS; i++) {
        int idx = (i * brightness) / FADE_STEPS;
        if (idx < 0) idx = 0;
        if (idx > 31) idx = 31;
        set_led_brightness(idx, 1);
        gpioDelay(FADE_DELAY_US / FADE_STEPS);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioWrite(led_pins[0], 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        led_pins[i] = 17 + i;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: Could not open BH1750 at 0x%02X, skipping sensor %d\n", BH1750_ADDR_LOW, i);
            continue;
        }
        if (init_bh1750(i2c_handles[i]) < 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X init failed, skipping sensor %d\n", BH1750_ADDR_LOW, i);
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
            continue;
        }
        num_sensors++;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int total_lux = 0;
        int valid = 0;

        for (int i = 0; i < num_sensors; i++) {
            int handle = i2c_handles[i];
            if (handle < 0) continue;
            int lux = read_bh1750(handle);
            if (lux >= 0) {
                total_lux += lux;
                valid++;
            }
        }

        if (valid == 0) {
            fprintf(stderr, "Error: No valid BH1750 readings, keeping previous brightness\n");
            continue;
        }

        int avg_lux = total_lux / valid;
        int brightness = map_lux_to_brightness(avg_lux);

        printf("Avg Lux: %d, Brightness: %d\n", avg_lux, brightness);

        fade_strip(brightness);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

