#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 18
#define MAX_LUX 120000.0
#define MAX_BRIGHTNESS 255
#define NUM_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile int keep_running = 1;
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *chip = NULL;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int veml7700_init(int fd) {
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

int veml7700_read_lux(int fd, float *lux) {
    uint16_t raw;
    for (int retry = 0; retry < NUM_RETRIES; retry++) {
        if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) == 0) {
            *lux = (float)raw * 0.0036f * (1.0f / 8.0f) * (100.0f / 100.0f);
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d)\n", retry + 1, NUM_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    fprintf(stderr, "Failed to read VEML7700 after %d retries\n", NUM_RETRIES);
    return -1;
