    if (lux <= 0.0f) return 0;
    float norm = lux / MAX_LUX;
    float gamma = powf(norm, 1.0f / 2.2f);
    int brightness = (int)(gamma * MAX_BRIGHTNESS);
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    if (brightness < 0) brightness = 0;
    return brightness;
}

