#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define CONSUMER "flame_monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int self_test(void) {
    struct gpiod_line *led = NULL;
    struct gpiod_line *buzzer = NULL;
    struct gpiod_line *flame = NULL;
    int ret = 0;

    led = gpiod_line_get_line(CONSUMER, LED_PIN);
    buzzer = gpiod_line_get_line(CONSUMER, BUZZER_PIN);
    flame = gpiod_line_get_line(CONSUMER, FLAME_SENSOR_PIN);

    if (!led || !buzzer || !flame) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return -1;
    }

    if (gpiod_line_request_output(led, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(buzzer, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request LED/buzzer output\n");
        ret = -1;
        goto cleanup;
    }

    if (gpiod_line_request_input(flame, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request flame sensor input\n");
        ret = -1;
        goto cleanup;
    }

    log_event("Starting self-test: LED blink");

    for (int i = 0; i < 2 && program_running; i++) {
        gpiod_line_set_value(led, 1);
        usleep(500000);
        gpiod_line_set_value(led, 0);
        usleep(500000);
    }

    if (!program_running) {
        log_event("Self-test interrupted by signal");
        ret = -1;
        goto cleanup;
    }

    log_event("Self-test LED blink complete");

    for (int i = 0; i < 5 && program_running; i++) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "Failed to read flame sensor during self-test\n");
            ret = -1;
            goto cleanup;
        }
        if (val == 0) {
            fprintf(stderr, "Flame sensor fault: consistently LOW during self-test\n");
            ret = -1;
            goto cleanup;
        }
        usleep(100000);
    }

    if (!program_running) {
        log_event("Self-test interrupted by signal");
        ret = -1;
        goto cleanup;
    }

    if (ret == 0) {
        log_event("Self-test passed");
    } else {
        log_event("Self-test failed");
    }

    log_event("Starting error pattern");

    for (int i = 0; i < 5 && program_running; i++) {
        gpiod_line_set_value(led, 1);
        usleep(100000);
        gpiod_line_set_value(led, 0);
        usleep(100000);
    }

    for (int i = 0; i < 3 && program_running; i++) {
        gpiod_line_set_value(buzzer, 1);
        usleep(200000);
        gpiod_line_set_value(buzzer, 0);
        usleep(200000);
        gpiod_line_set_value(buzzer, 1);
        usleep(600000);
        gpiod_line_set_value(buzzer, 0);
        usleep(200000);
    }

    log_event("Error pattern complete");

cleanup:
    if (led) gpiod_line_release(led);
    if (buzzer) gpiod_line_release(buzzer);
    if (flame) gpiod_line_release(flame);
    return ret;
}

static void activate_alarm(void) {
    struct gpiod_line *led = NULL;
    struct gpiod_line *buzzer = NULL;
    struct gpiod_line *flame = NULL;

    led = gpiod_line_get_line(CONSUMER, LED_PIN);
    buzzer = gpiod_line_get_line(CONSUMER, BUZZER_PIN);
    flame = gpiod_line_get_line(CONSUMER, FLAME_SENSOR_PIN);

    if (!led || !buzzer || !flame) {
        fprintf(stderr, "Failed to get GPIO lines for alarm\n");
        return;
    }

    if (gpiod_line_request_output(led, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(buzzer, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request alarm output\n");
        return;
    }

    log_event("Flame detected! Activating alarm");

    while (program_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "Failed to read flame sensor during alarm\n");
            break;
        }
        if (val == 1) {
            break;
        }
        usleep(50000);
    }

    if (gpiod_line_set_value(led, 0) < 0 ||
        gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to deactivate alarm\n");
    }

    log_event("Alarm deactivated");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_event("Flame sensor monitoring started");

    if (self_test() != 0) {
        log_event("Self-test failed, exiting");
        return 1;
    }

    while (program_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            log_event("Error reading flame sensor");
            break;
        }
        if (val == 0) {
            activate_alarm();
        }
        usleep(50000);
    }

    log_event("Flame sensor monitoring stopped");
    gpiod_line_release(led);
    gpiod_line_release(buzzer);
    gpiod_line_release(flame);
    return 0;
}

