#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <math.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define LUX_THRESHOLD 1000.0f
#define MIN_BLINK_RATE 0.5f
#define MAX_BLINK_RATE 5.0f
#define BLINK_PERIOD_MS 200
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_exported = 0;

static float lux_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static float read_bh1750(int fd) {
    uint8_t data[2];
    if (i2c_write_cmd(fd, 0x10) < 0) return -1.0f;
    usleep(180000); // Wait for measurement (max 180ms)
    if (i2c_read_data(fd, data, 2) < 0) return -1.0f;
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    return (float)raw / 1.2f;
}

static float calculate_average_lux(void) {
    float sum = 0.0f;
    int count = (buffer_count < BUFFER_SIZE) ? buffer_count : BUFFER_SIZE;
    for (int i = 0; i < count; i++) {
        sum += lux_buffer[i];
    }
    return (count > 0) ? (sum / count) : 0.0f;
}

static float map_lux_to_rate(float lux) {
    if (lux <= 0.0f) return MIN_BLINK_RATE;
    if (lux >= LUX_THRESHOLD) return MAX_BLINK_RATE;
    return MIN_BLINK_RATE + (lux / LUX_THRESHOLD) * (MAX_BLINK_RATE - MIN_BLINK_RATE);
}

static void set_gpio_value(int value) {
    char buf[4];
    if (gpio_exported) {
        snprintf(buf, sizeof(buf), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
        FILE *fp = fopen(buf, "w");
        if (fp) {
            fprintf(fp, "%d", value);
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to write to GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        }
    }
}

static void blink_led(float rate) {
    float half_period = 500000.0f / rate;
    int on_time_ms = (int)(half_period / 2.0f);
    int off_time_ms = (int)(half_period / 2.0f);
    int direction = 1;
    while (running) {
        set_gpio_value(1);
        usleep(on_time_ms * 1000);
        if (!running) break;
        set_gpio_value(0);
        usleep(off_time_ms * 1000);
        if (!running) break;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
