#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_exported = 0;

static float lux_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static float read_bh1750(int fd) {
    uint8_t data[2];
    if (i2c_write_cmd(fd, 0x10) < 0) return -1.0f;
    usleep(180000); // Wait for measurement (max 180ms)
    if (i2c_read_data(fd, data, 2) < 0) return -1.0f;
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    return (float)raw / 1.2f;
}

static float calculate_average_lux(void) {
