#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define CHIP_NAME "gpiochip0"

// Segment patterns for digits 0-9 (common cathode, active high)
// Order: a, b, c, d, e, f, g, dp (dp unused)
const unsigned char digits[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (data_line) {
        gpiod_line_release(data_line);
        data_line = NULL;
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
        clock_line = NULL;
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
        latch_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        release_resources();
        return -1;
    }

    if (gpiod_line_request_output(data_line, "seven_seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven_seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven_seg", 0) < 0) {
        perror("Failed to request GPIO lines as outputs");
        release_resources();
        return -1;
    }

    return 0;
}

void shift_out_data(unsigned char data) {
    // Send 8 bits MSB-first
    for (int i = 0; i < 8; i++) {
        int bit = (data >> (7 - i)) & 0x01;
        if (gpiod_line_set_value(data_line, bit) < 0) {
            perror("Failed to set data line");
            release_resources();
            exit(EXIT_FAILURE);
        }
        // Pulse clock: low, high, low (standard timing)
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            perror("Failed to set clock low");
            release_resources();
            exit(EXIT_FAILURE);
        }
        usleep(1);
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            perror("Failed to set clock high");
            release_resources();
            exit(EXIT_FAILURE);
        }
        usleep(1);
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            perror("Failed to set clock low");
            release_resources();
            exit(EXIT_FAILURE);
        }
        usleep(1);
    }
}

void display_digit(int index) {
    if (index < 0 || index > 9) return;
    unsigned char pattern = digits[index];
    shift_out_data(pattern);
    // Pulse latch to output the data
    if (gpiod_line_set_value(latch_line, 1) < 0) {
        perror("Failed to set latch high");
        release_resources();
        exit(EXIT_FAILURE);
    }
    usleep(1);
    if (gpiod_line_set_value(latch_line, 0) < 0) {
        perror("Failed to set latch low");
        release_resources();
        exit(EXIT_FAILURE);
    }
    usleep(10000); // 10 ms blanking
}

int main(void) {
    // Set up signal handler for clean exit
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        display_digit(5);
        usleep(500000); // 500 ms on
        if (!keep_running) break;
        display_digit(0); // blank
        usleep(500000);   // 500 ms off
    }

    release_resources();
    return EXIT_SUCCESS;
}

