#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000  // 10 ms = 100 Hz
#define PWM_STEPS 100           // 100 steps per period

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    srand(time(NULL));

    // Open GPIO chip 0 (Raspberry Pi 5 uses gpiochip0)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        cleanup_and_exit(0);
    }

    // Request lines as outputs, initially low
    struct gpiod_line_request_config config = {
        .consumer = "rgb-pwm",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };
    if (gpiod_line_request(red_line, &config, 0) < 0 ||
        gpiod_line_request(green_line, &config, 0) < 0 ||
        gpiod_line_request(blue_line, &config, 0) < 0) {
        perror("Failed to request GPIO lines as outputs");
        cleanup_and_exit(0);
    }

    // Set up signal handler for clean exit
    signal(SIGINT, cleanup_and_exit);

    printf("RGB LED PWM started. Press Ctrl+C to exit.\n");

    while (1) {
        // Generate random RGB values (0-100)
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        // Calculate duty cycles (0-100)
        int red_duty = red * 100 / 101;
        int green_duty = green * 100 / 101;
        int blue_duty = blue * 100 / 101;

        // Set PWM values (0-100)
        gpiod_line_set_value(red_line, red_duty);
        gpiod_line_set_value(green_line, green_duty);
        gpiod_line_set_value(blue_line, blue_duty);

        // Wait for PWM period using clock_nanosleep
        struct timespec ts = {
            .tv_sec = 0,
            .tv_nsec = PWM_PERIOD_NS
        };
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

    // Unreachable, but for completeness:
    cleanup_and_exit(0);
    return 0;
}

