#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C address (SA0 tied to GND) */
#define LSM303_I2C_ADDR 0x19

/* LSM303DLHC register addresses */
#define CTRL_REG1_A   0x20
#define CTRL_REG4_A   0x23
#define OUT_X_L_A     0x28
#define OUT_X_H_A     0x29
#define OUT_Y_L_A     0x2A
#define OUT_Y_H_A     0x2B
#define OUT_Z_L_A     0x2C
#define OUT_Z_H_A     0x2D

/* GPIO pin for impact indicator */
#define IMPACT_GPIO 17

/* Default impact threshold in G */
#define DEFAULT_THRESHOLD 2.0f

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;
static float impact_threshold = DEFAULT_THRESHOLD;

/* Function prototypes */
static int initialize_lsm303(void);
static int read_accelerometer_data(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void trigger_impact(void);
static void log_impact_data(float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(IMPACT_GPIO, 0);
    gpioTerminate();
}

/* Initialize the LSM303DLHC accelerometer */
static int initialize_lsm303(void) {
    /* CTRL_REG1_A: Enable X, Y, Z axes; ODR = 100 Hz (0x27) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1_A\n");
        return -1;
    }

    /* CTRL_REG4_A: Full-scale = 2G (0x00) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data using multi-byte read with auto-increment */
static int read_accelerometer_data(float *x, float *y, float *z) {
    char buffer[6];

    /* Read 6 bytes starting at OUT_X_L_A with auto-increment (0x80) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (returned %d)\n", bytes_read);
        return -1;
    }

    /* Combine little-endian bytes */
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Sensitivity for 2G full-scale: 16384 LSB/G */
    *x = (float)x_raw / 16384.0f;
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;

    return 0;
}

/* Calculate the magnitude of the acceleration vector */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Trigger the impact indicator */
static void trigger_impact(void) {
    gpioWrite(IMPACT_GPIO, 1);
    gpioDelay(50000); /* 50 ms pulse */
    gpioWrite(IMPACT_GPIO, 0);
}

/* Log impact data to file */
static void log_impact_data(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open impact_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f G, Y: %.3f G, Z: %.3f G\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
}

int main(int argc, char *argv[]) {
    float x, y, z;
    float magnitude;

    /* Parse command-line arguments */
    if (argc > 1) {
        char *endptr;
        impact_threshold = strtof(argv[1], &endptr);
        if (*endptr != '\0' || impact_threshold < 0.0f) {
            fprintf(stderr, "Error: Invalid threshold value. Using default: %.2f G\n", DEFAULT_THRESHOLD);
            impact_threshold = DEFAULT_THRESHOLD;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at LSM303DLHC address */
    i2c_handle = i2cOpen(1, LSM303_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X\n", LSM303_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Initialize LSM303DLHC */
    if (initialize_lsm303() < 0) {
        fprintf(stderr, "Error: LSM303DLHC initialization failed\n");
        cleanup();
        return 1;
    }

    /* Configure GPIO17 as output and ensure it starts LOW */
    gpioSetMode(IMPACT_GPIO, PI_OUTPUT);
    gpioWrite(IMPACT_GPIO, 0);

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n", impact_threshold);

    /* Main loop */
    while (program_running) {
        if (read_accelerometer_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > impact_threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                trigger_impact();
                log_impact_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data\n");
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz polling) */
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

