    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Read a single byte from an FXOS8700CQ register */
static int fxos_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Write a single byte to an FXOS8700CQ register */
static int fxos_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* Read 6 bytes of acceleration data (14-bit left-justified) */
static int fxos_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration block: %d\n", rc);
        return -1;
    }

    /* 14-bit left-justified data: shift right by 2 to get 16-bit value */
    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    *y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;
    return 0;
}

/* Compute acceleration magnitude in m/s^2 */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_magnitude = (float)x * FXOS8700_SENSITIVITY_2G * 9.81f;
    float y_magnitude = (float)y * FXOS8700_SENSITIVITY_2G * 9.81f;
    float z_magnitude = (float)z * FXOS8700_SENSITIVITY_2G * 9.81f;
    return sqrtf(x_magnitude * x_magnitude + y_magnitude * y_magnitude + z_magnitude * z_magnitude);
}

/* Log impact data to file */
static void log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at address 0x1F */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify sensor identity */
    uint8_t who_am_i = 0;
    if (fxos_read_byte(g_i2c_handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure sensor: standby mode first, then ±2g, then active */
    if (fxos_write_byte(g_i2c_handle, FXOS8700_CTRL_REG1, 0x00) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (fxos_write_byte(g_i2c_handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (fxos_write_byte(g_i2c_handle, FXOS8700_CTRL_REG1, 0x01) != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Allow sensor to settle into active mode */
    gpioDelay(100000); /* 100 ms */

    /* Set up signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    int16_t x, y, z;
    float magnitude;

    while (1) {
        if (fxos_read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Unreachable, but kept for completeness */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

