#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GYRO_ADDRESS        0x69
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0xD3
#define CTRL_REG1           0x20
#define CTRL_REG4           0x23
#define OUT_X_L             0x28
#define NUM_CAL_SAMPLES     100
#define SAMPLE_PERIOD_US    50000
#define THRESHOLD_DPS       50.0f
#define SENSITIVITY_DPS_LSB 0.00875f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read %zu bytes failed (got %zd): %s\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int gyro_init(int fd) {
    uint8_t who;
    if (i2c_read_block(fd, WHO_AM_I, &who, 1) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z) {
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_L, raw, 6) < 0) return -1;
    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);
    *x = (float)x_raw * SENSITIVITY_DPS_LSB;
    *y = (float)y_raw * SENSITIVITY_DPS_LSB;
    *z = (float)z_raw * SENSITIVITY_DPS_LSB;
    return 0;
}

static void calibrate_gyro(int fd, float *x0, float *y0, float *z0) {
    float x = 0, y = 0, z = 0;
    for (int i = 0; i < NUM_CAL_SAMPLES; i++) {
        if (!g_running) break;
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            continue;
        }
        x0[i] += x; y0[i] += y; z0[i] += z;
        usleep(10000);
    }
    *x0 = (*x0 / NUM_CAL_SAMPLES) - 0.5f;
    *y0 = (*y0 / NUM_CAL_SAMPLES) - 0.5f;
    *z0 = (*z0 / NUM_CAL_SAMPLES) - 0.5f;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS || fabsf(z) > THRESHOLD_DPS) {
        fprintf(stderr, "Threshold exceeded: X=%.2f Y=%.2f Z=%.2f\n", x, y, z);
        fprintf(g_log_fp, "ALERT: Threshold exceeded X=%.2f Y=%.2f Z=%.2f\n", x, y, z);
        fflush(g_log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                GYRO_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (gyro_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    float x0[NUM_CAL_SAMPLES], y0[NUM_CAL_SAMPLES], z0[NUM_CAL_SAMPLES];
    calibrate_gyro(g_i2c_fd, x0, y0, z0);

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen gyro_log.txt failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Gyroscope logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_gyro(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        float cx = x - x0[0];
        float cy = y - y0[0];
        float cz = z - z0[0];
        log_data(g_log_fp, cx, cy, cz);
        check_threshold(cx, cy, cz);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

