#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0   0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_THRESH_FF 0x28
#define ADXL345_TIME_FF 0x29
#define ADXL345_TAP_AXES 0x2A
#define ADXL345_DATA_FORMAT_VAL 0x0B
#define ADXL345_POWER_CTL_VAL 0x08
#define ADXL345_BW_RATE_VAL 0x0F
#define ADXL345_TAP_AXES_VAL 0x00
#define ADXL345_THRESH_FF_VAL 0x20
#define ADXL345_TIME_FF_VAL 0x00
#define ADXL345_I2C_BUS 1
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "accel_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_init(int handle) {
    uint8_t devid = 0;
    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 DEVID mismatch: got 0x%02X, expected 0xE5\n", devid);
        return -1;
    }

    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, ADXL345_POWER_CTL_VAL) != 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT, ADXL345_DATA_FORMAT_VAL) != 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_BW_RATE, ADXL345_BW_RATE_VAL) != 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_THRESH_FF, ADXL345_THRESH_FF_VAL) != 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_TIME_FF, ADXL345_TIME_FF_VAL) != 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_TAP_AXES, ADXL345_TAP_AXES_VAL) != 0) return -1;
    return 0;
}

static int read_accel(int handle, float *x, float *y, float *z) {
    uint8_t data[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, (char *)data, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: rc=%d\n", rc);
        return -1;
    }
    int16_t x_raw = (int16_t)((data[1] << 8) | data[0]);
    int16_t y_raw = (int16_t)((data[3] << 8) | data[2]);
    int16_t z_raw = (int16_t)((data[5] << 8) | data[4]);
    *x = (float)x_raw / 256.0f;
