#define ADXL345_DATAX0   0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_THRESH_FF 0x28
#define ADXL345_TIME_FF 0x29
#define ADXL345_TAP_AXES 0x2A
#define ADXL345_DATA_FORMAT_VAL 0x0B
#define ADXL345_POWER_CTL_VAL 0x08
#define ADXL345_BW_RATE_VAL 0x0F
#define ADXL345_TAP_AXES_VAL 0x00
#define ADXL345_THRESH_FF_VAL 0x20
#define ADXL345_TIME_FF_VAL 0x00
#define ADXL345_I2C_BUS 1
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "accel_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
