#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define ACCEL_ADDR 0x19
#define MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A   0x28
#define MR_REG_M    0x02
#define OUT_X_H_M   0x03

/* Sensitivities (LSB/gauss) */
#define ACCEL_SENSITIVITY 0.000244f
#define MAG_SENSITIVITY   0.00014f

static volatile sig_atomic_t running = 1;
static int accel_handle = -1;
static int mag_handle   = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, char *buf, uint32_t len) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: reg=0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, len) != (int)len) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, len=%u\n", reg, len);
        return -1;
    }
    return 0;
}

static int init_accelerometer(void) {
    if (i2c_write_reg(accel_handle, CTRL_REG1_A, 0x27) != 0) return -1;
    if (i2c_write_reg(accel_handle, CTRL_REG4_A, 0x38) != 0) return -1;
    return 0;
}

static int init_magnetometer(void) {
    if (i2c_write_reg(mag_handle, MR_REG_M, 0x00) != 0) return -1;
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buf[6];
    if (i2c_read_block(accel_handle, OUT_X_L_A | 0x80, buf, 6) != 0) return -1;
    int16_t x_raw = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    *x = (float)x_raw * ACCEL_SENSITIVITY;
    *y = (float)y_raw * ACCEL_SENSITIVITY;
    *z = (float)z_raw * ACCEL_SENSITIVITY;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char buf[6];
    if (i2c_read_block(mag_handle, OUT_X_H_M, buf, 6) != 0) return -1;
    int16_t x_raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t y_raw = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t z_raw = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    *x = (float)x_raw * MAG_SENSITIVITY;
    *y = (float)y_raw * MAG_SENSITIVITY;
    *z = (float)z_raw * MAG_SENSITIVITY;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float heading = atan2f(-my * cosf(pitch) - mz * sinf(pitch),
                          mx * sinf(roll) + my * cosf(roll) * cosf(pitch) - mz * sinf(pitch) * sinf(roll));
    heading = fmodf(heading, 2.0f * M_PI);
    if (heading < 0) heading += 2.0f * M_PI;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    if (sz == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X(g),Accel_Y(g),Accel_Z(g),Mag_X(g),Mag_Y(g),Mag_Z(g)\n");
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f\n", ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open accelerometer I2C: %d\n", accel_handle);
        gpioTerminate();
        return 1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open magnetometer I2C: %d\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    if (init_accelerometer() != 0 || init_magnetometer() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accelerometer(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accelerometer read error\n");
        } else if (read_magnetometer(&mx, &my, &mz) != 0) {
            fprintf(stderr, "Magnetometer read error\n");
        } else {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
            printf("Heading: %.2f deg\n", heading);
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(mag_handle);
    i2cClose(accel_handle);
    gpioTerminate();
    return 0;
}

