#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_VALUE 0x80
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    int status = i2cWriteByteData(handle, CTRL_REG, CTRL_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing control register to sensor 0x%02X: %s\n",
                handle, pigpio_error(status));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, int16_t *out) {
    char buf[2];
    int status = i2cReadI2CBlockData(handle, DATA_REG, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading data from sensor 0x%02X: %s\n",
                handle, pigpio_error(status));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_tdoa(int16_t s1, int16_t s2) {
    return (double)(s1 - s2);
}

static void log_data(double tdoa) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld, Sensor1: %d, Sensor2: %d, TDOA: %.6f\n",
            time_buf, ts.tv_nsec / 1000000, ts.tv_sec, ts.tv_nsec % 1000000000, tdoa);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n",
                SENSOR1_ADDR, pigpio_error(i2c_handle1));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n",
                SENSOR2_ADDR, pigpio_error(i2c_handle2));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) != 0 || init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed. Check wiring and I2C addresses.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Bat echolocation analysis started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t s1 = 0, s2 = 0;
        int status1 = read_sensor_data(i2c_handle1, &s1);
        int status2 = read_sensor_data(i2c_handle2, &s2);

        if (status1 == 0 && status2 == 0) {
            double tdoa = calculate_tdoa(s1, s2);
            log_data(tdoa);
        } else {
            fprintf(stderr, "Sensor read error. Skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

