#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A Register Addresses */
#define X_GYRO_REG   0x04
#define Y_GYRO_REG   0x06
#define Z_GYRO_REG   0x08
#define X_ACCEL_REG  0x0A
#define Y_ACCEL_REG  0x0C
#define Z_ACCEL_REG  0x0E

/* Sensitivities (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000   /* 1 MHz */
#define SPI_FLAGS      0b11000000000 /* CPOL=1, CPHA=1, aux SPI off */

/* Timing */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define STALL_DELAY_US   40       /* >40 us stall between request and data read */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_csv_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — registered with atexit()                                */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_csv_file != NULL) {
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                          */
/* Returns 0 on success, -1 on SPI transfer error.                    */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  status;

    /* Request phase: send MSB=0, LSB=register address */
    tx[0] = 0x00;
    tx[1] = (char)reg;

    status = spiXfer(g_spi_handle, tx, rx, 2);
    if (status < 0) {
        fprintf(stderr, "spiXfer (request) failed: %d\n", status);
        return -1;
    }

    /* Stall ~40 us so the device can prepare the response */
    gpioDelay(STALL_DELAY_US);

    /* Data phase: send MSB=0 again, receive 2 data bytes */
    tx[0] = 0x00;
    tx[1] = 0x00;

    status = spiXfer(g_spi_handle, tx, rx, 2);
    if (status < 0) {
        fprintf(stderr, "spiXfer (data) failed: %d\n", status);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register and convert to physical units                */
/* ------------------------------------------------------------------ */
static int read_register_and_convert(uint8_t reg, float *out)
{
    int16_t raw;
    if (read_register(reg, &raw) != 0)
        return -1;
    *out = (float)raw * (GYRO_SENSITIVITY  /* gyro  */
                      + ACCEL_SENSITIVITY /* accel */
                      + 0.0f);          /* temp  */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file                                     */
/* ------------------------------------------------------------------ */
static void log_sample(float gx, float gy, float gz,
                       float ax, float ay, float az)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_csv_file, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec / 1000000L,
            gx, gy, gz, ax, ay, az);
    fflush(g_csv_file);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_csv_file = fopen("imu_data.csv", "w");
    if (g_csv_file == NULL) {
        perror("fopen(imu_data.csv)");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(g_csv_file);

    printf("ADIS16488A logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_register_and_convert(X_GYRO_REG, &gx) != 0 ||
            read_register_and_convert(Y_GYRO_REG, &gy) != 0 ||
            read_register_and_convert(Z_GYRO_REG, &gz) != 0 ||
            read_register_and_convert(X_ACCEL_REG, &ax) != 0 ||
            read_register_and_convert(Y_ACCEL_REG, &ay) != 0 ||
            read_register_and_convert(Z_ACCEL_REG, &az) != 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
        } else {
            log_sample(gx, gy, gz, ax, ay, az);
        }

        /* Non-blocking delay so SIGINT/SIGTERM respond promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(10000);  /* 10 ms chunks */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

