#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* SPI Mode 0 (CPOL=0, CPHA=0) */

/* Scaling factors */
#define GYRO_SCALE 0.05f   /* deg/sec/LSB */
#define ACCL_SCALE 0.00025f /* g/LSB */

/* Stall time for ADIS16448 two-cycle read */
#define STALL_US 40

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit register from the ADIS16448.
 * The ADIS16448 requires a two-cycle SPI read:
 *   1. Send the register address (bit 15 set) in the first transfer.
 *   2. Send a dummy 0x0000 in the second transfer to clock out the data.
 *   The data is valid after the second transfer.
 */
static int adis16448_read_register(uint8_t reg, int16_t *value) {
    char tx[2], rx[2];
    int  ret;

    /* First transfer: send register address */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read (phase 1) failed for reg 0x%02X: ret=%d\n", reg, ret);
        return -1;
    }

    gpioDelay(STALL_US); /* Wait for conversion */

    /* Second transfer: dummy read to clock out data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read (phase 2) failed for reg 0x%02X: ret=%d\n", reg, ret);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro(int16_t *x, int16_t *y, int16_t *z) {
    if (adis16448_read_register(X_GYRO_OUT, x) != 0) return -1;
    if (adis16448_read_register(Y_GYRO_OUT, y) != 0) return -1;
    if (adis16448_read_register(Z_GYRO_OUT, z) != 0) return -1;
    return 0;
}

static int read_accel(int16_t *x, int16_t *y, int16_t *z) {
    if (adis16448_read_register(X_ACCL_OUT, x) != 0) return -1;
    if (adis16448_read_register(Y_ACCL_OUT, y) != 0) return -1;
    if (adis16448_read_register(Z_ACCL_OUT, z) != 0) return -1;
    return 0;
}

static void convert_data(int16_t raw_g, int16_t raw_a,
                         float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az) {
    *gx = raw_g * GYRO_SCALE;
    *gy = raw_g * GYRO_SCALE;
    *gz = raw_g * GYRO_SCALE;
    *ax = raw_a * ACCL_SCALE;
    *ay = raw_a * ACCL_SCALE;
    *az = raw_a * ACCL_SCALE;
}

int main(void) {
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;
    float gx, gy, gz, ax, ay, az;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0/GPIO8) at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_gyro(&raw_gx, &raw_gy, &raw_gz) != 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }
        if (read_accel(&raw_ax, &raw_ay, &raw_az) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            gpioDelay(100000);
            continue;
        }

        convert_data(raw_gx, raw_gy, raw_gz, &gx, &gy, &gz,
                     raw_ax, raw_ay, raw_az);
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gx, gy, gz, ax, ay, az);

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

