#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0   0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_I2C_ADDRESS 0x53
#define ADXL345_DEVID_VAL 0xE5
#define IMPACT_THRESHOLD 2.5f
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_write_register(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int adxl345_init(int handle) {
    uint8_t devid = 0;
    if (adxl345_read_register(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Error: failed to read DEVID register.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Error: ADXL345 not found (DEVID=0x%02X, expected 0x%02X).\n", devid, ADXL345_DEVID_VAL);
        return -1;
    }
    if (adxl345_write_register(handle, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error: failed to enable measurement mode.\n");
        return -1;
    }
    if (adxl345_write_register(handle, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Error: failed to set full-resolution mode.\n");
        return -1;
    }
    if (adxl345_write_register(handle, ADXL345_BW_RATE, 0x0A) != 0) {
        fprintf(stderr, "Error: failed to set 100 Hz BW rate.\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read failed (rc=%d).\n", rc);
        return -1;
    }
    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float magnitude, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s - Impact: Magnitude=%.3fg, X=%.3fg, Y=%.3fg, Z=%.3fg\n",
            timestamp, magnitude, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X (rc=%d).\n", ADXL345_I2C_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3fg\n", magnitude);
                gpioWrite(LED_GPIO, 1);
                gpioDelay(500000);
                gpioWrite(LED_GPIO, 0);
                log_impact(magnitude, x, y, z);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

