#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VAL 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_L 0x01
#define OUT_X_H 0x02
#define OUT_Y_L 0x03
#define OUT_Y_H 0x04
#define OUT_Z_L 0x05
#define OUT_Z_H 0x06
#define LED_PIN 17
#define ACCEL_THRESHOLD 2.0f
#define ACCEL_SCALE 1024.0f
#define LOG_FILE "impact_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_mma8451q(int fd) {
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accel data: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static float calc_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Impact: X=%.2fg, Y=%.2fg, Z=%.2fg\n", ts, x, y, z);
    fclose(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Error: Cannot set I2C slave 0x%02X: %s\n", MMA8451Q_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_mma8451q(i2c_fd) < 0) {
        fprintf(stderr, "Error: MMA8451Q initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Cannot open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error: Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "mma8451q-led", 0) < 0) {
        fprintf(stderr, "Error: Cannot request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8451Q impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) == 0) {
            float mag = calc_magnitude(x, y, z);
            if (mag > ACCEL_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2fg\n", mag);
                gpiod_line_set_value(led_line, 1);
                log_impact(x, y, z);
                usleep(500000);
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Warning: Read error, retrying...\n");
        }
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

