#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x53
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define LOG_FILE        "freefall_log.csv"

#define REG_DEVID       0x00
#define REG_THRESH_FF   0x0A
#define REG_TIME_FF     0x20
#define REG_INT_MAP     0x2F
#define REG_INT_ENABLE  0x2E
#define REG_POWER_CTL   0x2D
#define REG_DATAX0      0x32

#define EXPECTED_DEVID  0xE5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid;
    if (i2c_read_reg8(fd, REG_DEVID, &devid) < 0) return -1;
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, EXPECTED_DEVID);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_POWER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_THRESH_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, REG_TIME_FF, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INT_MAP, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, REG_INT_ENABLE, 0x04) < 0) return -1;
    if (i2c_write_reg8(fd, REG_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

static void freefall_cb(struct gpiod_line *line, int16_t *x, int16_t *y, int16_t *z) {
    (void)line;
    uint8_t int_src;
    if (i2c_read_reg8(i2c_fd, REG_INT_SOURCE, &int_src) < 0) return;
    if (!(int_src & 0x04)) return;
    int16_t x_raw, y_raw, z_raw;
    if (read_accel(i2c_fd, &x_raw, &y_raw, &z_raw) < 0) return;
    log_data(log_fp, x_raw, y_raw, z_raw);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "freefall") < 0) {
        fprintf(stderr, "Cannot request falling edge events on GPIO %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
        fflush(log_fp);
    }

    printf("Freefall detection running. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec ts = {1, 0};
        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod event read error: %s\n", strerror(errno));
            continue;
        }
        if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            freefall_cb(line, NULL, NULL, NULL);
        }
    }

    printf("\nShutting down...\n");
    i2c_write_reg8(i2c_fd, REG_INT_ENABLE, 0x00);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

