#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22
#define OUTX_L_XL    0x28

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6A

/* Sensitivities for +-2g and +-250 dps */
#define ACCEL_SENSITIVITY 0.061f
#define GYRO_SENSITIVITY  0.00875f

#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD   2.5f
#define IMPACT_WINDOW_SEC  1.0

#define I2C_BUS 1
#define LOG_FILE "motion_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int read_accel(int handle, sensor_data_t *d) {
    uint8_t buf[6];
    if (read_block(handle, OUTX_L_XL, buf, 6) < 0) return -1;
    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);
    d->x = (float)x * ACCEL_SENSITIVITY;
    d->y = (float)y * ACCEL_SENSITIVITY;
    d->z = (float)z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_gyro(int handle, sensor_data_t *d) {
    uint8_t buf[6];
    if (read_block(handle, OUTX_L_G, buf, 6) < 0) return -1;
    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);
    d->x = (float)x * GYRO_SENSITIVITY;
    d->y = (float)y * GYRO_SENSITIVITY;
    d->z = (float)z * GYRO_SENSITIVITY;
    return 0;
}

static void log_data(const sensor_data_t *a, const sensor_data_t *g) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, a->x, a->y, a->z, g->x, g->y, g->z);
    fflush(log_file);
}

static int init_lsm6dsr(void) {
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, LSM6DSR_ADDR, i2c_handle);
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %d\n", who);
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* CTRL1_XL: ODR=104 Hz (0x60), FS=00 (+-2g) */
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error writing CTRL1_XL\n");
        return -1;
    }
    /* CTRL2_G: ODR=104 Hz (0x60), FS=00 (+-250 dps) */
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error writing CTRL2_G\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM6DSR logging started. Press Ctrl+C to stop.\n");

    int freefall_state = 0;
    int impact_state = 0;
    time_t impact_start = 0;

    while (!terminate) {
        sensor_data_t accel, gyro;

        if (read_accel(i2c_handle, &accel) < 0) {
            fprintf(stderr, "Error reading accelerometer\n");
            break;
        }
        if (read_gyro(i2c_handle, &gyro) < 0) {
            fprintf(stderr, "Error reading gyroscope\n");
            break;
        }

        log_data(&accel, &gyro);

        float ax = (float)accel.x;
        float ay = (float)accel.y;
        float az = (float)accel.z;
        float gx = (float)gyro.x;
        float gy = (float)gyro.y;
        float gz = (float)gyro.z;

        float mag = sqrtf(ax * ax + ay * ay + az * az);
        float mag_g = mag * 0.061f;

        if (mag_g < FREEFALL_THRESHOLD) {
            if (!freefall_state) {
                freefall_state = 1;
                impact_start = time(NULL);
                printf("Freefall detected!\n");
            }
        } else if (mag_g > IMPACT_THRESHOLD) {
            if (impact_state == 0 && freefall_state) {
                impact_state = 1;
                printf("Impact detected!\n");
            }
        } else {
            if (impact_state) {
                impact_state = 0;
                printf("Impact ended.\n");
            }
        }

        time_sleep(0.01);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

