    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint16_t *value) {
    char tx[2], rx[2];
    tx[0] = (char)(reg | 0x80);  /* MSB=1 for read */
    tx[1] = 0x00;                 /* dummy for 16-bit read */

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

static int spi_write_register(uint8_t reg, uint16_t value) {
    char tx[2], rx[2];
    tx[0] = (char)(reg & 0x7F);  /* MSB=0 for write */
    tx[1] = (char)value;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    uint16_t raw_x;
    if (spi_read_register(ADIS16266_REG_X_GYRO_OUT, &raw_x) != 0) {
        data->x = 0.0f;
        data->y = 0.0f;
        data->z = 0.0f;
        return -1;
    }
    data->x = (float)raw_x * GYRO_SCALE;
    return 0;
}

static void log_data(FILE *fp, gyro_data_t data) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.4f,%.4f,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.x, data.y, data.z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return 1;
    }

    uint16_t who_am_i = 0;
    if (spi_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        goto cleanup;
    }
    if (who_am_i != 0x3F5A && who_am_i != 0x3F5B) {
        fprintf(stderr, "Unexpected WHO_AM_I: 0x%04X (expected 0x3F5A or 0x3F5B)\n", who_am_i);
        goto cleanup;
    }
    printf("ADIS16266 detected (WHO_AM_I=0x%04X)\n", who_am_i);

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("fopen gyro_log.csv");
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_deg_s, y_deg_s, z_deg_s\n");
        fflush(log_file);
    }

    printf("Logging gyro data to gyro_log.csv. Press Ctrl+C to stop.\n");

    while (!terminate) {
        gyro_data_t gyro_data;
        if (read_gyro_data(&gyro_data) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
        } else {
            log_data(log_file, gyro_data);
        }
        gpioDelay(10000);  /* 10 ms */
    }

cleanup:
    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

