#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* L3G4200D I2C address (SA0 tied to GND) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I       0x0F
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

/* Expected device ID */
#define L3G4200D_WHO_AM_I 0xD3

/* Sensitivity for +-250 dps full-scale range: 8.75 mdps/LSB */
#define SENSITIVITY_250DPS 8.75f / 1000.0f

/* Retry configuration */
#define I2C_RETRIES 3
#define SAMPLE_PERIOD_US 10000  /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                             */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        gpioDelay(1000);  /* 1 ms backoff */
    }
    return -1;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, I2C_RETRIES, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Gyroscope initialization                                             */
/* ------------------------------------------------------------------ */
static int init_gyroscope(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != L3G4200D_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, L3G4200D_WHO_AM_I);
        return -1;
    }
    printf("L3G4200D detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    /* CTRL_REG1: normal mode, all axes enabled (0x0F) */
    if (i2c_write_reg(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: +-250 dps full-scale range (0x00) */
    if (i2c_write_reg(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data                                                 */
/* ------------------------------------------------------------------ */
static int read_gyroscope_data(int handle, float *x, float *y, float *z)
{
    char buffer[6];

    /* Read 6 bytes starting at OUT_X_L (0x28) in a single block */
    int rc = i2cReadI2CBlockData(handle, OUT_X_L, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Failed to read gyroscope data block (rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint8_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)(((uint8_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)(((uint8_t)buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x * SENSITIVITY_250DPS;
    *y = (float)raw_y * SENSITIVITY_250DPS;
    *z = (float)raw_z * SENSITIVITY_250DPS;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    fprintf(fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the L3G4200D address */
    g_i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                L3G4200D_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (init_gyroscope(g_i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("gyro_log.csv", "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(g_log_file, "Timestamp,X,Y,Z\n");
    fflush(g_log_file);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_gyroscope_data(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

