#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_file, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[64];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s.%03ld - Sensor1: %d, Sensor2: %d\n",
                timestamp, ts.tv_nsec / 1000000L, sensor1_state, sensor2_state) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) == EOF) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(SENSOR_1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(SENSOR_2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line1, "conveyor_monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line2, "conveyor_monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(line2)");
        goto cleanup;
    }

    printf("Conveyor belt safety monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = gpiod_line_get_value(line1);
        int sensor2_value = gpiod_line_get_value(line2);

        if (sensor1_value < 0) {
            perror("gpiod_line_get_value(sensor1)");
            break;
        }
        if (sensor2_value < 0) {
            perror("gpiod_line_get_value(sensor2)");
            break;
        }

        if (log_event(log_file, sensor1_value, sensor2_value) < 0) {
            fprintf(stderr, "Error logging event.\n");
            break;
        }

        if (sensor1_value == 1 && sensor2_value == 1) {
            printf("Conveyor halted!\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    printf("Conveyor belt safety monitoring stopped.\n");
    return ret;
}

