#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_L        0x01
#define LOG_FILE       "fall_log.txt"
#define TILT_THRESHOLD 45.0f
#define POLL_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_log_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine_msb_lsb(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 4) | (lsb >> 4));
}

static int init_mma8452q(int fd) {
    uint8_t who;
    if (i2c_read_block(fd, WHO_AM_I, &who, 1) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0A) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t raw[6];
    if (i2c_read_block(fd, OUT_X_L, raw, 6) < 0) return -1;
    *x = combine_msb_lsb(raw[0], raw[1]);
    *y = combine_msb_lsb(raw[2], raw[3]);
    *z = combine_msb_lsb(raw[4], raw[5]);
    return 0;
}

static float calc_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float xg = (float)x / 8192.0f;
    float yg = (float)y / 8192.0f;
    float zg = (float)z / 8192.0f;
