#define SAMPLE_DELAY_S 1.0 / SAMPLE_HZ
#define METAL_THRESHOLD 800.0f
#define CALIB_OFFSET_X  0
#define CALIB_OFFSET_Y  0
#define CALIB_OFFSET_Z  0
#define CALIB_SCALE_X   1.0f
#define CALIB_SCALE_Y   1.0f
#define CALIB_SCALE_Z   1.0f
#define SENSITIVITY_MG  0.146f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x70) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetic_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Failed to read 6 bytes from 0x%02X: %s\n", OUT_X_L, strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *x_mg, float *y_mg, float *z_mg) {
    *x_mg = ((float)raw_x - CALIB_OFFSET_X) * CALIB_SCALE_X * SENSITIVITY_MG;
    *y_mg = ((float)raw_y - CALIB_OFFSET_Y) * CALIB_SCALE_Y * SENSITIVITY_MG;
    *z_mg = ((float)raw_z - CALIB_OFFSET_Z) * CALIB_SCALE_Z * SENSITIVITY_MG;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.3f,%.3f,%.3f\n", x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Field magnitude: %.2f mG\n", mag);
    }
}

