    int init_ok = 0;
    while (retries > 0 && !init_ok) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
        } else {
            retries--;
            if (retries > 0) {
                fprintf(stderr, "Init failed, retrying in 1 s...\n");
                sleep(1);
            }
        }
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after %d retries.\n", retries);
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open magnetic_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at %.1f Hz. Press Ctrl+C to stop.\n", SAMPLE_HZ);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetic_data(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Read error, retrying in 1 s...\n");
            sleep(1);
            continue;
        }
        float x_mg, y_mg, z_mg;
        calibrate_data(raw_x, raw_y, raw_z, &x_mg, &y_mg, &z_mg);
        log_data(g_log_fp, x_mg, y_mg, z_mg);
        check_threshold(x_mg, y_mg, z_mg);
        sleep(SAMPLE_DELAY_S);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

