#define ADXL354_REG_STATUS       0x04
#define ADXL354_REG_POWER_CTL    0x2D
#define ADXL354_REG_RESET        0x1F

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x0000   /* Mode 0, active-low CE */

/* ADXL354B Constants */
#define ADXL354_DEVID_ADXL354 0x1D
#define ADXL354_SENSITIVITY   0.0000039f  /* g/LSB (+/- 2g range) */
#define ADXL354_RESET_CMD     0x52
#define ADXL354_STATUS_STABLE  0x01
#define ADXL354_STATUS_DR      0x02
#define ADXL354_STATUS_ERROR   0x04

#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define RESET_DELAY_US      1000    /* 1 ms */
#define MAX_RETRIES         3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} accel_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg | 0x80), (char)value };
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed (ret=%d)\n", reg, ret);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read from reg 0x%02X failed (ret=%d)\n", reg, ret);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int spi_read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    char tx[32] = {0};
    char rx[32] = {0};
    tx[0] = (char)(reg | 0xC0);  /* read + multi-byte */
    for (uint32_t i = 0; i < len; i++) {
        tx[1 + i] = 0x00;
    }
    int ret = spiXfer(spi_handle, tx, rx, len + 1);
    if (ret != (int)(len + 1)) {
        fprintf(stderr, "SPI burst read from reg 0x%02X failed (ret=%d)\n", reg, ret);
        return -1;
    }
    memcpy(buf, &rx[1], len);
    return 0;
}

static int adxl354_reset(void) {
    if (spi_write_reg(ADXL354_REG_RESET, ADXL354_RESET_CMD) != 0) {
        fprintf(stderr, "Failed to reset ADXL354\n");
        return -1;
    }
    gpioDelay(RESET_DELAY_US);
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (spi_read_reg(ADXL354_REG_STATUS, &status) != 0) return -1;
        if ((status & ADXL354_STATUS_STABLE) == ADXL354_STATUS_STABLE) {
            return 0;
        }
        gpioDelay(1000);
    }
    fprintf(stderr, "ADXL354 reset timeout\n");
    return -1;
}

static int adxl354_init(void) {
    uint8_t partid = 0;
    if (spi_read_reg(ADXL354_REG_PARTID, &partid) != 0) return -1;
    if (partid != ADXL354_DEVID_ADXL354) {
        fprintf(stderr, "ADXL354 not detected (PARTID=0x%02X, expected 0x%02X)\n",
                partid, ADXL354_DEVID_ADXL354);
        return -1;
    }
    if (adxl354_reset() != 0) return -1;
    /* Clear RUN bit to enter standby */
    if (spi_write_reg(ADXL354_REG_POWER_CTL, 0x00) != 0) return -1;
    /* Wait for STABLE bit */
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (spi_read_reg(ADXL354_REG_STATUS, &status) != 0) return -1;
        if ((status & ADXL354_STATUS_STABLE) == ADXL354_STATUS_STABLE) {
            break;
        }
        gpioDelay(1000);
    }
    if (!(status & ADXL354_STATUS_STABLE)) {
        fprintf(stderr, "ADXL354 not ready after reset\n");
        return -1;
    }
    /* Set RUN bit to start measurement */
    if (spi_write_reg(ADXL354_REG_POWER_CTL, 0x02) != 0) return -1;
    return 0;
}

static int read_accel_data(accel_data_t *data) {
    uint8_t x_lsb = 0, x_msb = 0, x_err = 0;
    uint8_t y_lsb = 0, y_msb = 0, y_err = 0;
    uint8_t z_lsb = 0, z_msb = 0, z_err = 0;

    if (spi_read_burst(ADXL354_REG_XDATA_L, &x_lsb, 1) != 0) return -1;
    if (spi_read_burst(ADXL354_REG_XDATA_H, &x_msb, 1) != 0) return -1;
    if (spi_read_burst(ADXL354_REG_YDATA_L, &y_lsb, 1) != 0) return -1;
    if (spi_read_burst(ADXL354_REG_YDATA_H, &y_msb, 1) != 0) return -1;
    if (spi_read_burst(ADXL354_REG_ZDATA_L, &z_lsb, 1) != 0) return -1;
    if (spi_read_burst(ADXL354_REG_ZDATA_H, &z_msb, 1) != 0) return -1;

    /* Check error bits (bits 7 of each axis) */
    if ((x_lsb & 0x80) || (x_msb & 0x80) ||
        (y_lsb & 0x80) || (y_msb & 0x80) ||
        (z_lsb & 0x80) || (z_msb & 0x80)) {
        fprintf(stderr, "ADXL354 error bits set\n");
        return -1;
    }

    int32_t x_raw = ((int32_t)x_msb << 8) | x_lsb;
    int32_t y_raw = ((int32_t)y_msb << 8) | y_lsb;
    int32_t z_raw = ((int32_t)z_msb << 8) | z_lsb;

    /* Sign-extend 20-bit to 32-bit */
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    data->x = (float)x_raw * ADXL354_SENSITIVITY;
    data->y = (float)y_raw * ADXL354_SENSITIVITY;
    data->z = (float)z_raw * ADXL354_SENSITIVITY;
    return 0;
}

static void log_data(const accel_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.4f g, Y: %.4f g, Z: %.4f g\n",
            timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl354_init() != 0) {
        fprintf(stderr, "ADXL354 initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL354B logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        accel_data_t data;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (read_accel_data(&data) == 0) {
                success = 1;
                break;
            }
            retries++;
            gpioDelay(10000);  /* 10 ms backoff */
        }

        if (success) {
            log_data(&data);
        } else {
            fprintf(stderr, "Failed to read acceleration data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

