#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_REG   0x04
#define Y_GYRO_REG   0x06
#define Z_GYRO_REG   0x08
#define X_ACCL_REG   0x0A
#define Y_ACCL_REG   0x0C
#define Z_ACCL_REG   0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.0025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL  0       /* CE0 (GPIO8) */
#define SPI_BAUD     1000000 /* 1 MHz */
#define SPI_FLAGS    3       /* Mode 3: CPOL=1, CPHA=1, active-high, sampled trailing edge */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from ADIS16362 via SPI.
 * Protocol: send address with MSB set, then dummy byte, then read 2 bytes.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[3];
    char rx[3];
    int ret;

    /* Build command: [reg | 0x80, 0x00, 0x00] */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    tx[2] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Small delay to allow conversion to complete */
    gpioDelay(100); /* 100 us */

    /* Read the 2 data bytes */
    tx[0] = 0x00;
    tx[1] = 0x00;
    tx[2] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI read failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    return 0;
}

/* Read a 16-bit register and convert to physical units */
static int read_axis(uint8_t reg, float *out) {
    int16_t raw;
    if (read_register(reg, &raw) != 0) {
        return -1;
    }
    *out = (float)raw * (GYRO_SCALE for gyro, ACCL_SCALE for accel);
    return 0;
}

/* Log one sample line to CSV */
static int log_sample(float gx, float gy, float gz, float ax, float ay, float az) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                timestamp, ts.tv_nsec, gx, gy, gz, ax, ay, az) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, baud=%d, flags=%d): %d\n",
                SPI_CHANNEL, SPI_BAUD, SPI_FLAGS, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float gx, gy, gz, ax, ay, az;

        if (read_axis(X_GYRO_REG, &gx) != 0 ||
            read_axis(Y_GYRO_REG, &gy) != 0 ||
            read_axis(Z_GYRO_REG, &gz) != 0 ||
            read_axis(X_ACCL_REG, &ax) != 0 ||
            read_axis(Y_ACCL_REG, &ay) != 0 ||
            read_axis(Z_ACCL_REG, &az) != 0) {
