            continue;
        }

        if (log_sample(gx, gy, gz, ax, ay, az) != 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        gpioDelay(10000); /* 10 ms -> ~100 Hz */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

