/*
 * KY-032 IR Obstacle Avoidance System (libgpiod v2 API)
 * Board: Raspberry Pi 3 Model B+
 * Sensors: 2 x Keyes KY-032 on GPIO17 (BCM) and GPIO27 (BCM)
 *          (physical pins 11 and 13)
 * Logic:  Active-low output — 0 = obstacle detected, 1 = clear
 * Build:  gcc -Wall -Wextra -O2 -o ky032_avoid ky032_avoid.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_PIN_17      17
#define GPIO_PIN_27      27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct timespec poll_ts = { 0, POLL_INTERVAL_MS * 1000000L };
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* --- Open the gpiochip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error: failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    unsigned int offsets[2] = { GPIO_PIN_17, GPIO_PIN_27 };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2,
                                            GPIOD_LINE_SETTINGS_FLAG_NONE,
                                            settings) != 0) {
        fprintf(stderr, "Error: failed to configure line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Request both lines together --- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoid");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "Error: failed to request GPIO lines %u and %u: %s\n",
                GPIO_PIN_17, GPIO_PIN_27, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance started. Press Ctrl+C to exit.\n");
    printf("Sensors on GPIO17 and GPIO27 (BCM). Active-low: 0 = obstacle.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value vals[2];
        int rc = gpiod_line_request_get_values(req, vals);

        if (rc != 0) {
            fprintf(stderr, "Error: failed to read GPIO values: %s\n",
                    strerror(errno));
            break;
        }

        print_timestamp();
        printf("GPIO17=%d  GPIO27=%d  ", vals[0], vals[1]);
        if (vals[0] == GPIOD_LINE_VALUE_ACTIVE) {
            printf("OBSTACLE  ");
        } else {
            printf("CLEAR    ");
        }
        printf("\n");

        nanosleep(&poll_ts, NULL);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (req != NULL) {
        gpiod_line_request_release(req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

