#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I      0x0F
#define CTRL1_XL      0x10
#define CTRL2_G       0x11
#define OUTX_L_G      0x22
#define OUTX_L_XL     0x28

/* Expected chip ID */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities (from datasheet) */
#define GYRO_SENSITIVITY 0.00875f  /* dps/LSB */
#define ACCEL_SENSITIVITY 0.000061f /* g/LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block from reg 0x%02X (got %d, expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify chip identity */
    if (read_block(handle, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Gyro: 104 Hz, +-250 dps */
    if (write_reg(handle, CTRL2_G, 0x42) != 0) return -1;

    /* Accel: 104 Hz, +-2g */
    if (write_reg(handle, CTRL1_XL, 0x42) != 0) return -1;

    return 0;
}

static int read_sensor_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z)
{
    uint8_t buf[12];

    if (read_block(handle, OUTX_L_G, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Failed to read sensor data block\n");
        return -1;
    }

    /* Gyro X/Y/Z (buf[0..2]) then Accel X/Y/Z (buf[3..6]) */
    int16_t raw_gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_ax = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_ay = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_az = (int16_t)((buf[11] << 8) | buf[10]);

    *gyro_x = (float)raw_gx * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gy * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gz * GYRO_SENSITIVITY;
    *accel_x = (float)raw_ax * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_ay * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_az * ACCEL_SENSITIVITY;

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X (rc=%d)\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("LSM6DSR initialized. Reading every 100 ms (Ctrl+C to stop)...\n");

    while (g_running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_sensor_data(g_i2c_handle, &gyro_x, &gyro_y, &gyro_z,
                             &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro X: %7.2f dps, Gyro Y: %7.2f dps, Gyro Z: %7.2f dps\n",
                   gyro_x, gyro_y, gyro_z);
            printf("Accel X: %7.2f g, Accel Y: %7.2f g, Accel Z: %7.2f g\n",
                   accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }

        /* Sleep 100 ms in 10 ms increments so we can exit promptly on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

