                   accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }

        /* Sleep 100 ms in 10 ms increments so we can exit promptly on signal */
        for (int i = 0; i < 10 && g_running; i++) {
