#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FXOS8700_ADDR 0x1D
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_fxos8700(void) {
    uint8_t who_am_i = 0;
    if (read_reg(FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    if (write_reg(FXOS8700_CTRL_REG1, 0x00) != 0) return -1;
    if (write_reg(FXOS8700_CTRL_REG2, 0x00) != 0) return -1;
    if (write_reg(FXOS8700_M_CTRL_REG1, 0x00) != 0) return -1;
    if (write_reg(FXOS8700_M_CTRL_REG2, 0x00) != 0) return -1;

    /* Hybrid mode: accel 14-bit, mag 16-bit, 100 Hz ODR */
    if (write_reg(FXOS8700_CTRL_REG1, 0x0C) != 0) return -1;
    if (write_reg(FXOS8700_M_CTRL_REG1, 0x20) != 0) return -1;
    if (write_reg(FXOS8700_M_CTRL_REG2, 0x00) != 0) return -1;

    return 0;
}

static int read_sensor_data(int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t buf[12];
    int rc = i2cReadI2CBlockData(i2c_handle, FXOS8700_OUT_X_MSB, (char *)buf, 12);
    if (rc != 12) {
        fprintf(stderr, "I2C block read failed: rc=%d\n", rc);
        return -1;
    }

    /* 14-bit left-aligned accelerometer, 16-bit magnetometer */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging every 100 ms (Ctrl+C to stop)...\n");

    while (running) {
        int16_t ax, ay, az, mx, my, mz;
        if (read_sensor_data(&ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel X: %6d  Y: %6d  Z: %6d  Mag X: %6d  Y: %6d  Z: %6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; retrying next cycle.\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

