#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define ADXL345_ADDRESS 0x53
#define I2C_BUS "/dev/i2c-1"
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, 0x32, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

double calculate_tilt_angle(int16_t x, int16_t y) {
    double x_deg = atan2((double)x, sqrt((double)y * y + (double)z * z)) * 180.0 / M_PI;
    double y_deg = atan2((double)y, sqrt((double)x * x + (double)z * z)) * 180.0 / M_PI;
    return (x_deg > y_deg) ? x_deg : y_deg;
}

void log_event(double tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt Angle: %.2f degrees\n", s, tilt_angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence by reading WHO_AM_I register (0x00)
    uint8_t who_am_i = 0;
    if (i2c_read_bytes(i2c_fd, 0x00, &who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (who_am_i != 0xE5) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0xE5, got 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized successfully.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            break;
        }

        double tilt_angle = calculate_tilt_angle(x, y);
        if (tilt_angle > TILT_THRESHOLD) {
            log_event(tilt_angle);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

