#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms between samples */
#define MONITORING_WINDOW_US 5000000 /* 5 seconds */
#define PAUSE_BETWEEN_WINDOWS_US 1000000 /* 1 second */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum high-readings per 5-second window\n");
        return EXIT_FAILURE;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input */
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring ambient noise on GPIO%d for %ld high-readings every %d seconds.\n",
           SOUND_SENSOR_GPIO, threshold, MONITORING_WINDOW_US / 1000000);

    while (program_running) {
        int high_count = 0;
        uint32_t elapsed = 0;

        /* Sample GPIO17 for the 5-second monitoring window */
        while (elapsed < MONITORING_WINDOW_US && program_running) {
            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_GPIO);
                gpioDelay(SAMPLE_INTERVAL_US);
                elapsed += SAMPLE_INTERVAL_US;
                continue;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            elapsed += SAMPLE_INTERVAL_US;
        }

        print_timestamp();

        if (high_count > threshold) {
            printf("ALERT: %ld high-readings detected in %d seconds\n",
                   high_count, MONITORING_WINDOW_US / 1000000);
        } else {
            printf("Status: %ld high-readings in %d seconds\n",
                   high_count, MONITORING_WINDOW_US / 1000000);
        }
        fflush(stdout);

        /* Pause between monitoring windows */
        if (program_running) {
            gpioDelay(PAUSE_BETWEEN_WINDOWS_US);
        }
    }

    /* Clean up pigpio resources */
    gpioTerminate();
