/*
 * door_access.c - Raspberry Pi 4 Model B door access control
 *
 * Uses libgpiod (modern GPIO API) instead of deprecated wiringPi.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO bank on Pi 4 */
#define GPIO_DOOR_A     17
#define GPIO_DOOR_B     27
#define CODE_LENGTH    6
#define UNLOCK_DURATION 5           /* seconds */
#define LOG_FILE       "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, code[0]);
    } else {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

static void unlock_door(struct gpiod_line *line, int duration)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH: %s\n",
                GPIO_DOOR_A, strerror(errno));
        return;
    }

    printf("Door unlocked for %d seconds.\n", duration);

    for (int i = 0; i < duration && g_running; i++)
        sleep(1);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW: %s\n",
                GPIO_DOOR_A, strerror(errno));
        return;
    }

    printf("Door re-locked.\n");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get lines --- */
    line_a = gpiod_chip_get_line(chip, GPIO_DOOR_A);
    if (!line_a) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_DOOR_A, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_DOOR_B);
    if (!line_b) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_DOOR_B, strerror(errno));
        goto cleanup;
    }

    /* --- Request lines as outputs, default LOW (locked) --- */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_DOOR_A, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_DOOR_B, strerror(errno));
        goto cleanup;
    }

    /* --- Generate initial 6-digit code --- */
    srand((unsigned int)time(NULL));
    char code[CODE_LENGTH];
    for (int i = 0; i < CODE_LENGTH; i++)
        code[i] = '0' + rand() % 10;
    printf("Security code: %s\n", code);

    /* --- Main access loop --- */
    while (g_running) {
        printf("Enter the security code: ");
        fflush(stdout);

        char input[CODE_LENGTH];
        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin))
                fprintf(stderr, "EOF on stdin; exiting.\n");
            else
                fprintf(stderr, "stdin read error: %s\n", strerror(errno));
            break;
        }

        /* Strip trailing newline */
        input[strcspn(input, "\n")] = '\0';

        /* Validate: exactly 6 digits, no non-digit characters */
        if (strlen(input) != CODE_LENGTH) {
            fprintf(stderr, "Invalid input: %s\n", input);
            continue;
        }

        for (int i = 0; i < CODE_LENGTH; i++) {
            if (input[i] < '0' || input[i] > '9') {
                fprintf(stderr, "Invalid input: %s\n", input);
                continue;
            }
        }

        if (strcmp(code, input) == 0) {
            printf("Access granted.\n");
            unlock_door(line_a, UNLOCK_DURATION);
            log_access(code);
            srand((unsigned int)time(NULL));
            for (int i = 0; i < CODE_LENGTH; i++)
                code[i] = '0' + rand() % 10;
            printf("New security code: %s\n", code);
        } else {
            printf("Access denied.\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Ensure both lines are LOW (locked) on exit --- */
    if (line_a) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

