#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_DELAY_MS 180
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("I2C read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read incomplete: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    uint8_t data[2];

    if (i2c_write_cmd(fd, 0x21) < 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux_out = (float)raw * 5.0f / 6.0f;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float lux;
        if (read_bh1750(fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        log_data(lux);
        printf("Lux: %.2f\n", lux);

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

