#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* HMC5883L I2C address (SA0 tied to GND) */
#define HMC5883L_ADDR 0x1E

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_X_MSB 0x03

/* Configuration values */
#define HMC5883L_CONFIG_A_VAL 0x70  /* 8-average, 15 Hz, gain 1.3 Gauss */
#define HMC5883L_CONFIG_B_VAL 0x20  /* 8-average, 15 Hz, gain 1.3 Gauss */
#define HMC5883L_MODE_VAL    0x00  /* Continuous measurement mode */

/* Hard-iron offset storage */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} hard_iron_offsets_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an HMC5883L register; returns 0 on success, -1 on error */
static int hmc5883l_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive registers; returns 0 on success, -1 on error */
static int hmc5883l_read_reg16(int handle, uint8_t reg_msb, int16_t *out) {
    int msb = i2cReadByteData(handle, reg_msb);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from register 0x%02X (pigpio rc=%d)\n", reg_msb, msb);
        return -1;
    }
    int lsb = i2cReadByteData(handle, reg_msb + 1);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from register 0x%02X (pigpio rc=%d)\n", reg_msb + 1, lsb);
        return -1;
    }
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* Initialize the HMC5883L; returns 0 on success, -1 on error */
static int hmc5883l_init(int handle) {
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VAL) != 0) {
        fprintf(stderr, "Failed to write Configuration Register A\n");
        return -1;
    }
    if (hmc5883l_write_reg(handle, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VAL) != 0) {
        fprintf(stderr, "Failed to write Configuration Register B\n");
        return -1;
    }
    if (hmc5883l_write_reg(handle, HMC5883L_MODE, HMC5883L_MODE_VAL) != 0) {
        fprintf(stderr, "Failed to write Mode Register\n");
        return -1;
    }
    return 0;
}

/* Read raw magnetometer data; returns 0 on success, -1 on error */
static int hmc5883l_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z) {
    if (hmc5883l_read_reg16(handle, HMC5883L_DATA_X_MSB, x) != 0) {
        return -1;
    }
    if (hmc5883l_read_reg16(handle, HMC5883L_DATA_X_MSB + 2, y) != 0) {
        return -1;
    }
    if (hmc5883l_read_reg16(handle, HMC5883L_DATA_X_MSB + 4, z) != 0) {
        return -1;
    }
    return 0;
}

/* Compute hard-iron offsets as a running average over the last N samples */
static void compute_hard_iron_offsets(int16_t x, int16_t y, int16_t z,
                                       hard_iron_offsets_t *offsets,
                                       int *offset_index, int *offset_window_size) {
    *offset_index = (*offset_index + 1) % 100;
    if (*offset_window_size < 100) {
        *offset_window_size = 100;
    }
    offsets[*offset_index].x = (int16_t)(x - offsets[*offset_index].x);
    offsets[*offset_index].y = (int16_t)(y - offsets[*offset_index].y);
    offsets[*offset_index].z = (int16_t)(z - offsets[*offset_index].z);
}

/* Apply hard-iron offsets to raw data; returns 0 on success, -1 on error */
static int apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z,
                                    hard_iron_offsets_t offsets,
                                    int16_t *x_out, int16_t *y_out, int16_t *z_out) {
    *x_out = x - offsets.x;
    *y_out = y - offsets.y;
    *z_out = z - offsets.z;
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    g_i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (pigpio rc=%d)\n",
                HMC5883L_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the HMC5883L */
    if (hmc5883l_init(g_i2c_handle) != 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Hard-iron offset storage */
    hard_iron_offsets_t offsets = {0, 0, 0};
    int offset_index = 0;
    int offset_window_size = 0;

    printf("HMC5883L magnetometer reading (hard-iron offsets running average)\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;

        if (hmc5883l_read_raw(g_i2c_handle, &x, &y, &z) == 0) {
            compute_hard_iron_offsets(x, y, z, &offsets, &offset_index, &offset_window_size);
            if (apply_hard_iron_offsets(x, y, z, offsets, &x, &y, &z) != 0) {
                fprintf(stderr, "Error applying hard-iron offsets\n");
            } else {
                printf("X: %6d  Y: %6d  Z: %6d\n", x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        gpioDelay(500000); /* 500 ms delay (microseconds) */
    }

    /* Clean resource release on exit */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

