/*
 * LSM303D tri-axial accelerometer monitor for Raspberry Pi Zero W.
 *
 * I2C bus : /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * I2C addr: 0x1D  (SA0 tied high)
 * INT1    : GPIO23 (BCM 23, physical pin 16)
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D register definitions ---- */
#define LSM303D_ADDR        0x1D
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_INT1_CFG   0x5B
#define LSM303D_INT1_THS   0x5C
#define LSM303D_INT1_DURATION 0x5D

/* ---- Configuration constants ---- */
#define I2C_BUS             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip0"
#define GPIO_INT_LINE       23          /* BCM 23, physical pin 16 */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000       /* 10 ms */
#define SAMPLES_TO_DUMP     10
#define ACCEL_THRESHOLD_MG  2000.0f
#define ACCEL_SENSITIVITY   0.061f      /* mg/LSB at +/-2g */

/* ---- Data structures ---- */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- GPIO helpers ---- */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    g_int_line = gpiod_chip_get_line(g_chip, GPIO_INT_LINE);
    if (!g_int_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_INT_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    if (gpiod_line_request_rising_edge_events(g_int_line, "lsm303d-int1") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO %d: %s\n",
                GPIO_INT_LINE, strerror(errno));
        g_int_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void)
{
    if (g_int_line) {
        gpiod_line_release(g_int_line);
        g_int_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf)
{
    memset(buf, 0, sizeof(*buf));
}

static void buffer_add(circular_buffer_t *buf, accel_sample_t s)
{
    buf->samples[buf->head] = s;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_dump(const circular_buffer_t *buf, int n)
{
    if (n > buf->count) n = buf->count;
    int start = (buf->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    printf("--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%2d] x=%.3f  y=%.3f  z=%.3f mg\n",
               i, buf->samples[idx].x, buf->samples[idx].y, buf->samples[idx].z);
    }
    printf("\n");
}

/* ---- LSM303D operations ---- */
static int lsm303d_init(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    uint8_t who = 0;
    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I; sensor absent or bus error.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Accelerometer: 50 Hz ODR, all axes enabled */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0)
        return -1;

    /* Full-scale +/-2g */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG4, 0x00) < 0)
        return -1;

    /* INT1 threshold = 2000 mg / 16 = 125 */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_THS, 125) < 0)
        return -1;

    /* INT1 duration = 0 (immediate) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_DURATION, 0x00) < 0)
        return -1;

    /* Enable accelerometer */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) < 0)
        return -1;

    return 0;
}

static void lsm303d_shutdown(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer */
        if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00) < 0)
            fprintf(stderr, "Warning: failed to disable accel during shutdown.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    circular_buffer_t accel_buf;
    buffer_init(&accel_buf);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (lsm303d_init() < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D ready. Sampling at ~10 ms. Ctrl-C to exit.\n");

    while (g_running) {
        accel_sample_t sample;
        memset(&sample, 0, sizeof(sample));

        if (i2c_read_block(g_i2c_fd, LSM303D_OUT_X_L_A | 0x80, (uint8_t *)&sample, 6) < 0) {
            /* I2C read error: warn and skip this sample */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw to mg (sensitivity = 0.061 mg/LSB at +/-2g) */
        sample.x = (float)sample.x * ACCEL_SENSITIVITY;
        sample.y = (float)sample.y * ACCEL_SENSITIVITY;
        sample.z = (float)sample.z * ACCEL_SENSITIVITY;

        buffer_add(&accel_buf, sample);

        /* Dump on rising edge of INT1 */
        if (gpiod_line_event_read(g_int_line, NULL) < 0) {
            /* Event queue full or transient error; continue sampling */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        if (gpiod_line_event_get_event_type(g_int_line) == GPIOD_LINE_EVENT_RISING_EDGE) {
            buffer_dump(&accel_buf, SAMPLES_TO_DUMP);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    lsm303d_shutdown();
    gpio_cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

