/*
 * Reciprocating linear actuator simulator for Raspberry Pi 3 Model B+
 * Uses libgpiod (modern GPIO character-device API) — no wiringPi.
 *
 * Wiring:
 *   Solenoid 1 (via TIP120) -> GPIO17 (BCM)
 *   Solenoid 2 (via TIP120) -> GPIO27 (BCM)
 *   Flyback diodes on each solenoid coil.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o actuator actuator.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define SOLENOID_1_PIN  17
#define SOLENOID_2_PIN  27
#define CONSUMER        "solenoid-actuator"
#define DELAY_MS        500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
