#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define SERIAL_PORT1 "/dev/serial0"
#define SERIAL_PORT2 "/dev/serial1"
#define BAUD_RATE B9600
#define CODE_LENGTH 6
#define CODE_TO_OPEN "123456"
#define UNLOCK_DURATION_MS 2000
#define POLL_INTERVAL_US 10000
#define SERIAL_TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static int serial1_fd = -1;
static int serial2_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    return 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = SERIAL_TIMEOUT_SEC * 10;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_serial_digit(int fd, char *buffer, int *index) {
    fd_set readfds;
    struct timeval tv;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);
    tv.tv_sec = SERIAL_TIMEOUT_SEC;
    tv.tv_usec = 0;
    int retval = select(fd + 1, &readfds, NULL, NULL, &tv);
    if (retval < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select() error on serial fd %d: %s\n", fd, strerror(errno));
        return -1;
    }
    if (retval == 0) {
        *index = 0;
        return 0;
    }
    char c;
    ssize_t n = read(fd, &c, 1);
    if (n < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "read() error on serial fd %d: %s\n", fd, strerror(errno));
        return -1;
    }
    if (n == 0) {
        *index = 0;
        return 0;
    }
    if (c < '0' || c > '9') {
        *index = 0;
        return 0;
    }
    *buffer = c;
    (*index)++;
    return 1;
}

static int is_digit(const char *s, int len) {
    for (int i = 0; i < len; i++) {
        if (s[i] < '0' || s[i] > '9') return 0;
    }
    return 1;
}

static int compare_codes(const char *a, const char *b, int len) {
    for (int i = 0; i < len; i++) {
        if (a[i] != b[i]) return 0;
    }
    return 1;
}

static void unlock_doors(void) {
    gpioWrite(LOCK1_GPIO, 1);
    gpioWrite(LOCK2_GPIO, 1);
    printf("Doors unlocked\n");
}

static void relock_doors(void) {
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    printf("Doors locked\n");
}

static void cleanup(void) {
    relock_doors();
    if (serial1_fd >= 0) close(serial1_fd);
    if (serial2_fd >= 0) close(serial2_fd);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }
    if (init_gpio() != 0) return 1;
    serial1_fd = init_serial(SERIAL_PORT1);
    if (serial1_fd < 0) { cleanup(); return 1; }
    serial2_fd = init_serial(SERIAL_PORT2);
    if (serial2_fd < 0) { close(serial1_fd); cleanup(); return 1; }
    printf("Dual-factor authentication system started. Waiting for codes...\n");
    char code1_buf[CODE_LENGTH] = {0};
    char code2_buf[CODE_LENGTH] = {0};
    int code1_index = 0;
    int code2_index = 0;
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (running) {
        int rc1 = read_serial_digit(serial1_fd, code1_buf, &code1_index);
        int rc2 = read_serial_digit(serial2_fd, code2_buf, &code2_index);
        if (rc1 < 0) {
            fprintf(stderr, "Error reading from serial port 1\n");
            code1_index = 0;
            code1_buf[0] = '\0';
        }
        if (rc2 < 0) {
            fprintf(stderr, "Error reading from serial port 2\n");
            code2_index = 0;
            code2_buf[0] = '\0';
        }
        if (code1_index >= CODE_LENGTH && code2_index >= CODE_LENGTH) {
            if (compare_codes(code1_buf, code2_buf, CODE_LENGTH) == 1) {
                if (compare_codes(code1_buf, CODE_TO_OPEN, CODE_LENGTH) == 1) {
                    unlock_doors();
                    gpioDelay(UNLOCK_DURATION_MS * 1000);
                    relock_doors();
                    printf("Codes matched and opened doors\n");
                } else {
                    printf("Codes matched but wrong code\n");
                }
            } else {
                printf("Codes do not match\n");
            }
            code1_index = 0;
            code2_index = 0;
        }
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L +
                          (now.tv_nsec - start.tv_nsec) / 1000000L;
        if (elapsed_ms > SERIAL_TIMEOUT_SEC * 1000L) {
            printf("Timeout: no codes received within %d seconds\n", SERIAL_TIMEOUT_SEC);
            code1_index = 0;
            code2_index = 0;
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("Shutting down...\n");
    cleanup();
    return 0;
}

