#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define GPIO_CHIP_NAME "gpiochip0"
#define STRIKE_DURATION_SEC 1
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_SEC 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "[%s] %s", timestamp, message);
}

static void log_error(const char *message) {
    log_event(LOG_ERR, message);
}

static void log_info(const char *message) {
    log_event(LOG_INFO, message);
}

static void log_warning(const char *message) {
    log_event(LOG_WARNING, message);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_error("Failed to register SIGINT handler");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to register SIGTERM handler");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_error("Failed to open gpiochip0");
        goto cleanup;
    }

