#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22
#define NUM_RELAYS 4
#define ACTIVATION_DURATION 300  /* seconds */
#define PAUSE_DURATION 60        /* seconds */
#define TIMER_INTERVAL 60       /* seconds */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t timer_fired = 0;

static const int relay_gpios[NUM_RELAYS] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to syslog                              */
/* ------------------------------------------------------------------ */
static void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
    }

    syslog(LOG_INFO, "%s: %s", ts, message);
}

/* ------------------------------------------------------------------ */
/* Activate a single relay for ACTIVATION_DURATION seconds              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int activate_relay(int gpio)
{
    if (gpioWrite(gpio, 0) != 0) {   /* active-LOW: LOW = ON */
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", gpio);
        return -1;
    }
    log_message("Relay activated");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate a single relay (HIGH = OFF)                            */
/* ------------------------------------------------------------------ */
static int deactivate_relay(int gpio)
{
    if (gpioWrite(gpio, 1) != 0) {   /* active-LOW: HIGH = OFF */
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", gpio);
        return -1;
    }
    log_message("Relay deactivated");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timer callback — fires every TIMER_INTERVAL seconds                  */
/* State machine: 0 = pause, 1 = activation, 2 = deactivation          */
/* ------------------------------------------------------------------ */
static void timer_callback(void *user_data)
{
    (void)user_data;

    if (timer_fired) {
        timer_fired = 0;
        return;
    }

    timer_fired = 1;

    int current_relay = 0;
    int next_relay = (current_relay + 1) % NUM_RELAYS;

    if (current_relay == 0) {
        /* Activation phase */
        if (activate_relay(relay_gpios[current_relay]) != 0) {
            syslog(LOG_ERR, "Activation failed for relay %d", current_relay + 1);
            return;
        }
        /* Wait for activation duration, checking for shutdown */
        for (int i = 0; i < ACTIVATION_DURATION && running; i++) {
            gpioDelay(1000000); /* 1 second */
        }
        if (!running) {
            syslog(LOG_INFO, "Shutdown requested during activation of relay %d", current_relay + 1);
            return;
        }
        if (deactivate_relay(relay_gpios[current_relay]) != 0) {
            syslog(LOG_ERR, "Deactivation failed for relay %d", current_relay + 1);
            return;
        }
        /* Pause between relays */
        for (int i = 0; i < PAUSE_DURATION && running; i++) {
            gpioDelay(1000000);
        }
    } else if (current_relay == 1) {
        /* Deactivation phase */
        if (deactivate_relay(relay_gpios[current_relay]) != 0) {
            syslog(LOG_ERR, "Deactivation failed for relay %d", current_relay + 1);
            return;
        }
        /* Pause between activations */
        for (int i = 0; i < PAUSE_DURATION && running; i++) {
            gpioDelay(1000000);
        }
    } else if (current_relay == 2) {
        /* Pause phase */
        for (int i = 0; i < PAUSE_DURATION && running; i++) {
            gpioDelay(1000000);
        }
    } else {
        syslog(LOG_ERR, "Invalid relay index %d in timer callback", current_relay);
        return;
    }
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure all relay GPIOs                     */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
        /* Start with all relays OFF (HIGH) */
        if (gpioWrite(relay_gpios[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to initialise GPIO %d to HIGH", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — deactivate all relays and terminate pigpio               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_gpios[i], 1); /* ensure OFF */
    }
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    /* Start single timer 0 with 60-second interval */
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started. Activating relays in sequence.");

    while (running) {
        /* Sleep loop — timer callback handles the 60-second interval */
        gpioDelay(100000); /* 100 ms */
    }

    syslog(LOG_INFO, "Shutting down irrigation system.");
    cleanup();
    return EXIT_SUCCESS;
}

