#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "smart-lighting"

static const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int intervals[NUM_RELAYS] = {2, 3, 5, 7};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relay_lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!running) break;

            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed = (current_time.tv_sec - start_time.tv_sec) +
                             (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed >= intervals[i]) {
                if (set_relay(relay_lines[i], 1) == 0) {
                    start_time = current_time;
                } else {
                    fprintf(stderr, "Failed to turn on relay %d\n", i + 1);
                }
            } else {
                if (set_relay(relay_lines[i], 0) == 0) {
                    start_time = current_time;
                } else {
                    fprintf(stderr, "Failed to turn off relay %d\n", i + 1);
                }
            }
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

