#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define ALARM_DURATION_MS 3000
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_alarm(void) {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening alarm_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Alarm triggered\n", ts);
    } else {
        fprintf(fp, "(unknown time) - Alarm triggered\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing alarm_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void trigger_alarm(void) {
    printf("Alarm triggered!\n");
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to turn on relay\n");
        return;
    }
    gpioDelay(ALARM_DURATION_MS * 1000);
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to turn off relay\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sound sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring sound sensor on GPIO%d. Relay on GPIO%d. Press Ctrl+C to exit.\n",
           SOUND_SENSOR_GPIO, RELAY_GPIO);

    int last_state = gpioRead(SOUND_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Failed to read initial sound sensor state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(SOUND_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read sound sensor\n");
            break;
        }

        if (current_state == 1 && last_state == 0) {
            trigger_alarm();
            if (log_alarm() != 0) {
                fprintf(stderr, "Logging failed; continuing monitoring.\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

