#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Sensitivity scale factor for default +-250 dps range
#define GYRO_SCALE 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold
#define THRESHOLD 50.0f

// I2C device path
#define I2C_DEV "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static float gyro_x_buffer[BUFFER_SIZE];
static float gyro_y_buffer[BUFFER_SIZE];
static float gyro_z_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int i2c_init(void);
int i2c_write_byte(uint8_t reg, uint8_t value);
int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len);
int mpu6050_init(void);
int read_gyro_data(gyro_data_t *data);
float calculate_magnitude(gyro_data_t data);
void add_to_buffer(gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize I2C communication
int i2c_init(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Write a single byte to an I2C register
int i2c_write_byte(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read multiple bytes from an I2C register
int i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X for read: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the MPU-6050 sensor
int mpu6050_init(void) {
    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    if (i2c_write_byte(PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        return -1;
    }
    usleep(100000); // Wait 100ms for sensor to stabilize

    // Verify device identity by reading WHO_AM_I register
    uint8_t who_am_i = 0;
    if (i2c_read_bytes(WHO_AM_I, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x68, got 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_bytes(GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    // Combine high and low bytes (little-endian)
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert raw data to degrees per second
    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_x_buffer[buffer_index] = data.x;
    gyro_y_buffer[buffer_index] = data.y;
    gyro_z_buffer[buffer_index] = data.z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if the angular velocity exceeds the threshold
void check_threshold(gyro_data_t data) {
    if (calculate_magnitude(data) > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f\n", calculate_magnitude(data));
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C
    if (i2c_init() < 0) {
        return EXIT_FAILURE;
    }

    // Initialize MPU-6050
    if (mpu6050_init() < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized successfully. Reading gyroscope data...\n");

    // Main loop
    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(&gyro_data) < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        add_to_buffer(gyro_data);
        check_threshold(gyro_data);

        usleep(10000); // Sample rate: 10ms
    }

    // Cleanup
    printf("\nCleaning up and exiting...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

