/*
 * MH-Z19B CO2 Monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 @ 9600 baud (GPIO14 TXD, GPIO15 RXD)
 * Library: pigpio
 *
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 * Run:   sudo ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_INTERVAL_S  5
#define READ_TIMEOUT_MS  1000
#define READ_CMD_LEN     9
#define READ_RESP_LEN    9
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_log_fp      = NULL;
static FILE *g_err_fp      = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_err_fp, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                         */
/* ------------------------------------------------------------------ */
static int init_uart(void)
{
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        log_error("serOpen failed");
        return -1;
    }
    return 0;
}

static void close_uart(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
}

/*
 * Send the 9-byte read command.
 * Returns 0 on success, -1 on write failure.
 */
static int send_read_command(void)
{
    char cmd[READ_CMD_LEN];
    memset(cmd, 0, sizeof(cmd));

    for (int i = 0; i < READ_CMD_LEN; i++) {
        int rc = serWrite(g_uart_handle, &cmd[i], 1);
        if (rc < 0) {
            log_error("serWrite failed");
            return -1;
        }
    }

    /* Datasheet: wait ~100 ms after command */
    gpioDelay(100000); /* microseconds */
    return 0;
}

/*
 * Read exactly 9 bytes of response.
 * Returns 0 on success, -1 on timeout or partial read.
 */
static int read_response(uint8_t response[READ_RESP_LEN])
{
    int total = 0;
    int elapsed = 0;

    while (total < READ_RESP_LEN) {
        int avail = serDataAvailable(g_uart_handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail == 0) {
            gpioDelay(1000); /* 1 ms */
            elapsed++;
            if (elapsed >= READ_TIMEOUT_MS) {
                log_error("UART read timeout");
                return -1;
            }
            continue;
        }

        int n = serRead(g_uart_handle, (char *)(response + total), avail);
        if (n < 0) {
            log_error("serRead failed");
            return -1;
        }
        if (n == 0) {
            gpioDelay(1000);
            elapsed++;
            continue;
        }

        total += n;
        elapsed = 0;
    }
    return 0;
}

/*
 * Validate checksum: sum of bytes 1-7, inverted, must equal byte 8.
 * Returns 0 on success, -1 on mismatch.
 */
static int validate_checksum(const uint8_t response[READ_RESP_LEN])
{
    uint8_t sum = 0;
    for (int i = 1; i <= 7; i++)
        sum += response[i];

    uint8_t calc = (uint8_t)((~sum + 1) & 0xFF);
    if (calc != response[8]) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Checksum mismatch: calc=0x%02X recv=0x%02X",
                 calc, response[8]);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int read_co2_ppm(uint16_t *ppm_out)
{
    uint8_t response[READ_RESP_LEN];

    if (send_read_command() != 0)
        return -1;

    if (read_response(response) != 0)
        return -1;

    if (validate_checksum(response) != 0)
        return -1;

    *ppm_out = (uint16_t)(response[2] << 8) | response[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t ppm, int error_flag)
{
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&tv.tv_sec, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    char json[256];
    snprintf(json, sizeof(json),
             "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %u, "
             "\"error\": %d}",
             ts, (unsigned long)tv.tv_usec, ppm, error_flag);

    if (fprintf(g_log_fp, "%s\n", json) < 0) {
        log_error("fprintf to log file failed");
    } else {
        fflush(g_log_fp);
    }

    printf("%s\n", json);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    close_uart();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", ERROR_LOG_FILE, strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_uart() != 0) {
        log_error("UART initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 Monitor started. UART=%s @ %d baud\n",
           UART_DEVICE, BAUD_RATE);
    printf("Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, READ_INTERVAL_S);

    while (g_running) {
        uint16_t ppm = 0;
        int err = 0;

        if (read_co2_ppm(&ppm) == 0) {
            err = 0;
        } else {
            err = 1;
        }

        log_data(ppm, err);
        sleep(READ_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

