#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* HMC5883L I2C address (SA0 tied to GND) */
#define HMC5883L_ADDR 0x1E

/* Register addresses */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_X_MSB 0x03

/* GPIO pin for indicator */
#define ALERT_GPIO 17

/* Target heading in degrees */
#define TARGET_HEADING 90.0

/* Hard-iron offsets (replace with calibrated values) */
#define X_OFFSET 100
#define Y_OFFSET (-50)

/* Circular buffer size */
#define BUFFER_SIZE 100

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sample interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Circular buffer */
typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Initialize HMC5883L                                               */
/* ------------------------------------------------------------------ */
static int init_hmc5883l(void) {
    /* CONFIG_A: 8-average, 15 Hz, normal measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    /* CONFIG_B: 1.3 Gauss gain */
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    /* MODE: continuous measurement */
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw magnetometer data                                          */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compensate for hard-iron distortion                                 */
/* ------------------------------------------------------------------ */
static void compensate_hard_iron(int16_t raw_x, int16_t raw_y,
                                  float *comp_x, float *comp_y) {
    *comp_x = (float)raw_x - X_OFFSET;
    *comp_y = (float)raw_y - Y_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Calculate heading in degrees                                        */
/* ------------------------------------------------------------------ */
static float calculate_heading(float comp_x, float comp_y) {
    float heading = atan2f(comp_y, comp_x) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

/* ------------------------------------------------------------------ */
/* Add heading to circular buffer                                      */
/* ------------------------------------------------------------------ */
static void add_heading_to_buffer(float heading) {
    heading_buffer.data[heading_buffer.head] = heading;
    heading_buffer.head = (heading_buffer.head + 1) % BUFFER_SIZE;
    if (heading_buffer.count < BUFFER_SIZE) {
        heading_buffer.count++;
    }
}

/* ------------------------------------------------------------------ */
/* Check if heading deviates from target                               */
/* ------------------------------------------------------------------ */
static bool heading_deviates(float heading, float target) {
    float deviation = fabsf(heading - target);
    return deviation > 10.0f;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize HMC5883L */
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d mode\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Initialize circular buffer */
    heading_buffer.head = 0;
    heading_buffer.count = 0;

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HMC5883L heading monitor started. Target: %.1f deg\n", TARGET_HEADING);

    /* Main loop */
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;

        if (read_magnetometer(&raw_x, &raw_y, &raw_z) == 0) {
            float comp_x, comp_y;
            compensate_hard_iron(raw_x, raw_y, &comp_x, &comp_y);
            float heading = calculate_heading(comp_x, comp_y);

            add_heading_to_buffer(heading);
            bool deviates = heading_deviates(heading, TARGET_HEADING);
            gpioWrite(ALERT_GPIO, deviates ? 1 : 0);

            printf("Heading: %.2f deg  (deviates: %s)\n",
                   heading, deviates ? "YES" : "no");
        } else {
            fprintf(stderr, "Read error; retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

