#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define DISTANCE_MIN 10.0
#define DISTANCE_MAX 100.0
#define DISTANCE_THRESHOLD 50.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int in1, int in2, int duty) {
    if (gpioPWM(in2, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", in2);
        return -1;
    }
    if (gpioWrite(in1, 1) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", in1);
        return -1;
    }
    if (gpioWrite(in3, 1) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", in3);
        return -1;
    }
    if (gpioPWM(in4, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", in4);
        return -1;
    }
    return 0;
}

static int map_distance_to_duty(double distance) {
    if (distance < DISTANCE_MIN) distance = DISTANCE_MIN;
    if (distance > DISTANCE_MAX) distance = DISTANCE_MAX;
    double normalized = (distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN);
    int duty = (int)(normalized * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        double distance_a = 45.0;
        double distance_b = 65.0;

        int duty_a = map_distance_to_duty(distance_a);
        int duty_b = map_distance_to_duty(distance_b);

        if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, duty_a) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, duty_b) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        gpioDelay(100000);
    }

    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

