#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23

#define STEPS_PER_REVOLUTION 512
#define STEP_DELAY_US 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static int safe_set_output(unsigned gpio) {
    return safe_set_mode(gpio, PI_OUTPUT);
}

static int safe_set_input(unsigned gpio) {
    return safe_set_mode(gpio, PI_INPUT);
}

static int safe_set_input_pull(unsigned gpio, unsigned pud) {
    return safe_set_pull(gpio, pud);
}

static int rotate_steps(int direction, int steps) {
    if (direction < 0 || direction > 1) {
        fprintf(stderr, "Error: invalid direction %d\n", direction);
        return -1;
    }

    int sequence[4][4] = {
        {1, 0, 0, 0},
        {1, 1, 0, 0},
        {0, 1, 0, 0},
        {0, 1, 1, 0}
    };

    for (int i = 0; i < steps; i++) {
        if (!running) {
            fprintf(stderr, "Interrupted before step %d\n", i);
            return -1;
        }
        if (safe_write(IN1, sequence[direction][i % 4][0]) < 0) return -1;
        if (safe_write(IN2, sequence[direction][i % 4][1]) < 0) return -1;
        if (safe_write(IN3, sequence[direction][i % 4][2]) < 0) return -1;
        if (safe_write(IN4, sequence[direction][i % 4][3]) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static void deenergize(void) {
    safe_write(IN1, 0);
    safe_write(IN2, 0);
    safe_write(IN3, 0);
    safe_write(IN4, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_output(IN1) < 0 || safe_set_output(IN2) < 0 ||
        safe_set_output(IN3) < 0 || safe_set_output(IN4) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_input(BUTTON_LOCK) < 0 || safe_set_input(BUTTON_UNLOCK) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_pull(BUTTON_LOCK, PI_PUD_UP) < 0 || safe_set_pull(BUTTON_UNLOCK, PI_PUD_UP) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic door lock system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(BUTTON_LOCK) == 0) {
            printf("Locking door...\n");
            if (rotate_steps(1, STEPS_PER_REVOLUTION) < 0) break;
            deenergize();
            printf("Door locked.\n");
            gpioDelay(500000);
        } else if (gpioRead(BUTTON_UNLOCK) == 0) {
            printf("Unlocking door...\n");
            if (rotate_steps(-1, STEPS_PER_REVOLUTION) < 0) break;
            deenergize();
            printf("Door unlocked.\n");
            gpioDelay(500000);
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("System shut down cleanly.\n");
    return EXIT_SUCCESS;
}

