static void deenergize(void) {
    safe_write(IN1, 0);
    safe_write(IN2, 0);
    safe_write(IN3, 0);
    safe_write(IN4, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_output(IN1) < 0 || safe_set_output(IN2) < 0 ||
        safe_set_output(IN3) < 0 || safe_set_output(IN4) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_input(BUTTON_LOCK) < 0 || safe_set_input(BUTTON_UNLOCK) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_pull(BUTTON_LOCK, PI_PUD_UP) < 0 || safe_set_pull(BUTTON_UNLOCK, PI_PUD_UP) < 0) {
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic door lock system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(BUTTON_LOCK) == 0) {
            printf("Locking door...\n");
            if (rotate_steps(1, STEPS_PER_REVOLUTION) < 0) break;
            deenergize();
            printf("Door locked.\n");
            gpioDelay(500000);
        } else if (gpioRead(BUTTON_UNLOCK) == 0) {
            printf("Unlocking door...\n");
            if (rotate_steps(-1, STEPS_PER_REVOLUTION) < 0) break;
            deenergize();
            printf("Door unlocked.\n");
            gpioDelay(500000);
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("System shut down cleanly.\n");
    return EXIT_SUCCESS;
}

