#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define SCHEDULE_FILE "lighting_schedule.txt"
#define FADE_DURATION_SEC 1800
#define FADE_STEP_SEC 1
#define FADE_STEP_DUTY 1
#define PWM_FREQ 100
#define PWM_RANGE 100

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int *relays, int *on_off) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int line_num = 0;
    int num_entries = 0;
    int last_time[24] = {0};

    while (fgets(line, sizeof(line), fp) && line_num < 100) {
        line_num++;
        char *t = strtok(line, ":\n");
        if (!t) continue;

        char *h = strtok(NULL, ":\n");
        char *m = strtok(NULL, ":\n");
        char *s = strtok(NULL, ":\n");

        if (!h || !m || !s) continue;

        int hour, minute, second;
        if (sscanf(t, "%d:%d:%d", &hour, &minute, &second) != 3) continue;

        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) continue;

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (i == relays[i]) continue;

            if (hour == last_time[i] && minute == last_time[i] + 1 && second == last_time[i] + 2) {
                if (on_off[i] != 0) {
                    int duty = (on_off[i] == 1) ? PWM_RANGE : 0;
                    gpioPWM(relay_pins[i], duty);
                }
                num_entries++;
            }
        }

        last_time[i] = hour * 3600 + minute * 60 + second;
    }

    fclose(fp);
    return num_entries;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_relay(int pin, int target_state, int duration_sec) {
    int current_duty = (target_state == 1) ? PWM_RANGE : 0;
    int current_duty_step = (target_state == 1) ? 0 : PWM_RANGE;

    for (int i = 0; i <= duration_sec && running; i++) {
        current_duty += FADE_STEP_DUTY;
        if (current_duty > PWM_RANGE) current_duty = PWM_RANGE;
        if (current_duty < 0) current_duty = 0;

        gpioPWM(pin, current_duty);
        current_duty_step += FADE_STEP_DUTY;
        if (current_duty_step > PWM_RANGE) current_duty_step = PWM_RANGE;
        if (current_duty_step < 0) current_duty_step = 0;

        sleep(FADE_STEP_SEC);
    }

    if (gpioWrite(pin, target_state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (set_relay(relay_pins[i], 0) != 0) {
            gpioTerminate();
            return 1;
        }
    }

    int relays[NUM_RELAYS];
    int on_off[NUM_RELAYS];
    int num_entries = read_schedule(SCHEDULE_FILE, relays, on_off);

    if (num_entries == 0) {
        fprintf(stderr, "No schedule entries found. Exiting.\n");
        for (int i = 0; i < NUM_RELAYS; i++) {
            set_relay(relay_pins[i], 0);
        }
        gpioTerminate();
        return 0;
    }

    printf("Smart home lighting system started. %d entries in schedule.\n", num_entries);

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (on_off[i] == 1) {
                if (fade_relay(relay_pins[i], 1, FADE_DURATION_SEC) != 0) {
                    fprintf(stderr, "Fade failed for relay %d\n", i);
                }
            } else {
                if (fade_relay(relay_pins[i], 0, FADE_DURATION_SEC) != 0) {
                    fprintf(stderr, "Fade failed for relay %d\n", i);
                }
            }
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (on_off[i] == 1) {
                if (set_relay(relay_pins[i], 1) != 0) {
                    fprintf(stderr, "Failed to turn on relay %d\n", i);
                }
            } else {
                if (set_relay(relay_pins[i], 0) != 0) {
                    fprintf(stderr, "Failed to turn off relay %d\n", i);
                }
            }
        }

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

