/*
 * Raspberry Pi Zero W - HC-SR04 Theremin
 * Library: pigpio
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (output)
 *   HC-SR04 ECHO -> GPIO24 (input, 1 kΩ pull-down recommended)
 *   Buzzer +     -> GPIO18 (PWM-capable)
 *
 * Build: gcc -Wall -Wextra -O2 -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY    200
#define MAX_FREQUENCY    2000
#define LOOP_DELAY_US    50000   /* 50 Hz loop cadence */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms timeout for echo */
#define MEASURE_GAP_US   60000   /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres using the HC-SR04.
 * Returns distance on success, or -1.0f on timeout / error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Issue a 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIG high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object / sensor absent) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* distance = (pulse_us * 34300 cm/s) / 2 / 1e6 */
    return (float)pulse_us * MIN_DISTANCE_CM / 1000000.0f / 2.0f;
}

static int map_distance_to_frequency(float distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float ratio = (distance_cm - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    int freq = (int)(MIN_FREQUENCY + ratio * (MAX_FREQUENCY - MIN_FREQUENCY));

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    return freq;
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency < 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Warning: gpioSetPWMfrequency(%d) failed\n", frequency);
        gpioPWM(BUZZER_PIN, 0);
        return;
    }
    gpioPWM(BUZZER_PIN, 128); /* 50% duty cycle */
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: distance measurement failed, keeping previous frequency\n");
        } else {
            int frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

