#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_SENSITIVITY 131.0f
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 init: failed to wake sensor\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_gyro(int fd, float *gx, float *gy, float *gz) {
    uint8_t buf[6];
    if (i2c_read_block(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SENSITIVITY;
    *gy = (float)raw_y / GYRO_SENSITIVITY;
    *gz = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

static void log_data(float gx, float gy, float gz) {
    FILE *fp = fopen("gyro_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "log_data: failed to open file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, gx, gy, gz);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        close(fd);
        return 1;
    }

    printf("MPU-6050 gyro logging to gyro_log.txt (Ctrl+C to stop)\n");

    while (g_running) {
        float gx, gy, gz;
        if (read_gyro(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "read_gyro failed; continuing\n");
        } else {
            log_data(gx, gy, gz);
            printf("X: %.2f, Y: %.2f, Z: %.2f deg/s\n", gx, gy, gz);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return 0;
}

