#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_DUTY 500000    /* 50% of 1,000,000 range */

/* Melody: frequency in Hz, duration in milliseconds */
static const int melody[] = {
    262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 783, 880, 987, 0
};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t melody_playing = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 0) {  /* active-low */
        melody_playing = 1;
    }
}

static int play_tone(int freq, int duration_ms) {
    if (gpioHardwarePWM(BUZZER_PIN, freq, PWM_DUTY) < 0) {
        fprintf(stderr, "gpioHardwarePWM failed for freq %d\n", freq);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
        fprintf(stderr, "gpioHardwarePWM stop failed\n");
        return -1;
    }
    return 0;
}

static void play_melody(void) {
    for (int i = 0; i < melody_len && melody_playing; i++) {
        if (play_tone(melody[i], 100) < 0) {
            melody_playing = 0;
            return;
        }
        gpioDelay(10000);  /* 10 ms between notes */
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
        fprintf(stderr, "gpioHardwarePWM init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell ready. Press button on GPIO%d to play melody.\n", BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (melody_playing) {
            play_melody();
            melody_playing = 0;
        }
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Cleanup */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

