#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

static void log_event(FILE *log_file, int value) {
    char timestamp[32];
    get_timestamp(timestamp, sizeof(timestamp));
    if (fprintf(log_file, "%s - Vibration detected, value: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

static void check_for_earthquake(FILE *log_file, int *window[WINDOW_SIZE], int *index, int *count) {
    if (*index >= WINDOW_SIZE) {
        *index = 0;
    }
    if (log_file) {
        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));
        fprintf(log_file, "%s - Earthquake Alert!\n", timestamp);
        fflush(log_file);
    }
    printf("Earthquake Alert!\n");
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default: %d ms\n", DEFAULT_POLL_TIMEOUT_MS);
            poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;
        }
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int window_count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring vibration sensor on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = poll_timeout_ms / 1000;
        ts.tv_nsec = (poll_timeout_ms % 1000) * 1000000L;

        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        log_event(log_file, event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0);
        check_for_earthquake(log_file, window, &window_index, &window_count);
    }

    printf("\nCleaning up...\n");
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

