#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer I2C address (SA0 tied high) */
#define LSM303_ADDRESS 0x1E

/* LSM303DLHC magnetometer registers */
#define CRA_REG_M   0x00
#define MR_REG_M    0x02
#define OUT_X_MSB   0x03
#define OUT_X_LSB   0x04
#define OUT_Z_MSB   0x05
#define OUT_Z_LSB   0x06
#define OUT_Y_MSB   0x07
#define OUT_Y_LSB   0x08

/* Calibration offsets (replace with your own calibrated values) */
#define X_OFFSET 10
#define Y_OFFSET (-5)
#define Z_OFFSET 20

/* Compass directions */
typedef enum {
    NORTH = 0,
    NE = 45,
    EAST = 90,
    SE = 135,
    SOUTH = 180,
    SW = 225,
    WEST = 270,
    NW = 315
} compass_direction_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Failed to set CRA_REG_M\n");
        return -1;
    }
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to set MR_REG_M\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calibrate_magnetometer_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                         int16_t *cal_x, int16_t *cal_y, int16_t *cal_z) {
    *cal_x = raw_x - X_OFFSET;
    *cal_y = raw_y - Y_OFFSET;
    *cal_z = raw_z - Z_OFFSET;
}

static compass_direction_t calculate_compass_heading(int16_t cal_x, int16_t cal_y) {
    float heading = atan2f((float)cal_x, (float)cal_y) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    float heading_rad = heading;
    compass_direction_t direction;
    if (heading_rad >= 135.0f && heading_rad < 225.0f) {
        direction = NE;
    } else if (heading_rad >= 225.0f && heading_rad < 315.0f) {
        direction = E;
    } else if (heading_rad >= 315.0f && heading_rad < 45.0f) {
        direction = SE;
    } else if (heading_rad >= 45.0f && heading_rad < 135.0f) {
        direction = S;
    } else if (heading_rad >= 135.0f && heading_rad < 225.0f) {
        direction = SW;
    } else if (heading_rad >= 225.0f && heading_rad < 315.0f) {
        direction = W;
    } else if (heading_rad >= 315.0f && heading_rad < 45.0f) {
        direction = NW;
    } else {
        direction = NORTH;
    }
    return direction;
}

static void log_data(FILE *fp, int16_t cal_x, int16_t cal_y, int16_t cal_z,
                     compass_direction_t heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, cal_x, cal_y, cal_z, heading);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                LSM303_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("mag_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open mag_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        fflush(g_log_file);
    }

    printf("Magnetometer data logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer_data(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
            sleep(1);
            continue;
        }

        int16_t cal_x, cal_y, cal_z;
        calibrate_magnetometer_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);

        compass_direction_t heading = calculate_compass_heading(cal_x, cal_y);

        log_data(g_log_file, cal_x, cal_y, cal_z, heading);

        printf("Calibrated X: %d, Calibrated Y: %d, Calibrated Z: %d, Heading: %s\n",
               cal_x, cal_y, cal_z, compass_directions[heading]);
        fflush(stdout);

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

