#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_touch_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void touch_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 1) return; /* Only act on touch (HIGH) */

    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    if (diff < (uint32_t)(DEBOUNCE_MS * 1000)) return;
    last_tick = tick;

    last_touch_tick = tick;

    int relay_state = gpioRead(RELAY_GPIO);
    if (gpioWrite(RELAY_GPIO, !relay_state) != 0) {
        fprintf(stderr, "Warning: failed to write relay GPIO\n");
        return;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed\n");
        return;
    }

    struct tm timeinfo;
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Warning: strftime() failed\n");
        return;
    }

    char json_string[256];
    int len = snprintf(json_string, sizeof(json_string),
                       "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}",
                       timestamp, relay_state ? "ON" : "OFF");
    if (len < 0 || (size_t)len >= sizeof(json_string)) {
        fprintf(stderr, "Warning: JSON buffer too small\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s for append\n", LOG_FILE);
        return;
    }
    if (fputs(json_string, fp) == EOF) {
        fprintf(stderr, "Warning: fputs() failed\n");
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose() failed\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set touch sensor GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: cannot set pull-down on touch sensor GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(TOUCH_SENSOR_GPIO, touch_callback) != 0) {
        fprintf(stderr, "Error: cannot register alert callback on GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Relay control started. Touch GPIO%d to toggle relay on GPIO%d.\n", TOUCH_SENSOR_GPIO, RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    gpioSetAlertFunc(TOUCH_SENSOR_GPIO, NULL);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

