#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define GAP_BETWEEN_RELAYS 1
#define LOOP_DELAY 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_irrigation(int relay_num, int moisture_level) {
    FILE *fp = fopen("irrigation_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }
    fprintf(fp, "%s - Relay %d activated (Moisture: %d%%)\n", timestamp, relay_num, moisture_level);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_lines[4];
    int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int i;
    int ret;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    for (i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_output(relay_lines[i], "irrigation", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture_level = rand() % 101;
        printf("Simulated moisture level: %d%%\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating relays.\n");

            for (i = 0; i < 4; i++) {
                if (!program_running) break;

                ret = gpiod_line_set_value(relay_lines[i], 0);
                if (ret < 0) {
                    fprintf(stderr, "Failed to activate relay %d: %s\n", i + 1, strerror(errno));
                    goto cleanup;
                }
                log_irrigation(i + 1, moisture_level);

                for (int j = 0; j < IRRIGATION_DURATION && program_running; j++) {
                    sleep(GAP_BETWEEN_RELAYS);
                }

                ret = gpiod_line_set_value(relay_lines[i], 1);
                if (ret < 0) {
                    fprintf(stderr, "Failed to deactivate relay %d: %s\n", i + 1, strerror(errno));
                    goto cleanup;
                }
            }
        } else {
            printf("Moisture level above threshold. No irrigation needed.\n");
        }

        for (int j = 0; j < LOOP_DELAY && program_running; j++) {
            sleep(1);
        }
    }

cleanup:
    printf("\nShutting down...\n");
    for (i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

