/*
 * Automated Plant Watering System - Raspberry Pi Zero W
 * Library: pigpio
 *
 * Servos:
 *   GPIO17 (physical pin 11) - water valve (closed at 0 deg, open at 90 deg)
 *   GPIO18 (physical pin 12) - directional nozzle (sweeps 0, 45, 90, 135, 180 deg)
 *
 * Moisture cycle (1 s period):
 *   20, 40, 60, 80, 100 -> if < 50, open valve -> sweep nozzle -> hold 5 s -> close valve
 *   else skip -> wait 5 s -> next reading
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO      17
#define NOZZLE_GPIO     18

#define VALVE_OPEN_DEG   90
#define VALVE_CLOSED_DEG 0
#define NOZZLE_MIN_DEG   0
#define NOZZLE_MAX_DEG   180
#define NOZZLE_STEP_DEG  45

#define MOISTURE_THRESHOLD 50
#define MOISTURE_VALUES    {20, 40, 60, 80, 100}
#define MOISTURE_CYCLE_US  1000000
#define NOZZLE_STEP_US     2000000
#define HOLD_US            5000000
#define LOOP_DELAY_US      5000000

#define SERVO_RETRY_COUNT 3
#define SERVO_RETRY_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int gpio, int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: angle %d out of range [0, 180] on GPIO %d\n", angle, gpio);
        return -1;
    }

    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        int pw = gpioServo(gpio, angle);
        if (pw >= 0) {
            return 0;
        }
        fprintf(stderr, "Warning: gpioServo failed on GPIO %d (attempt %d/%d, rc=%d)\n",
                gpio, attempt + 1, SERVO_RETRY_COUNT, pw);
        if (attempt < SERVO_RETRY_COUNT - 1) {
            gpioDelay(SERVO_RETRY_DELAY_US);
        }
    }
    return -1;
}

static int open_valve(int gpio)
{
    return set_servo_angle(gpio, VALVE_OPEN_DEG);
}

static int close_valve(int gpio)
{
    return set_servo_angle(gpio, VALVE_CLOSED_DEG);
}

static int set_nozzle_angle(int gpio, int angle)
{
    if (angle < NOZZLE_MIN_DEG || angle > NOZZLE_MAX_DEG) {
        fprintf(stderr, "Error: nozzle angle %d out of range [%d, %d] on GPIO %d\n",
                angle, NOZZLE_MIN_DEG, NOZZLE_MAX_DEG, gpio);
        return -1;
    }
    return set_servo_angle(gpio, angle);
}

static int read_moisture(void)
{
    return (int)(MOISTURE_VALUES[0] + (rand() % (int)(MOISTURE_VALUES[1] - MOISTURE_VALUES[0])));
}

static void water_plant(int valve_gpio, int nozzle_gpio)
{
    int moisture = read_moisture();
    printf("Moisture level: %d\n", moisture);

    if (moisture < MOISTURE_THRESHOLD) {
        printf("Watering needed!\n");

        if (open_valve(valve_gpio) != 0) {
            fprintf(stderr, "Error: failed to open valve on GPIO %d\n", valve_gpio);
            return;
        }

        for (int angle = NOZZLE_MIN_DEG; angle <= NOZZLE_MAX_DEG && g_running; angle += NOZZLE_STEP_DEG) {
            if (set_nozzle_angle(nozzle_gpio, angle) != 0) {
                fprintf(stderr, "Error: failed to set nozzle angle %d on GPIO %d\n",
                        angle, nozzle_gpio);
                close_valve(valve_gpio);
                return;
            }
            printf("Nozzle at %d deg\n", angle);
            gpioDelay(NOZZLE_STEP_US);
        }

        if (close_valve(valve_gpio) != 0) {
            fprintf(stderr, "Error: failed to close valve on GPIO %d\n", valve_gpio);
        } else {
            printf("Valve closed.\n");
        }

        printf("Watering complete.\n");
    } else {
        printf("Moisture sufficient.\n");
    }

    gpioDelay(HOLD_US);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(NOZZLE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with valve closed and nozzle at 0 */
    if (close_valve(VALVE_GPIO) != 0 || set_nozzle_angle(NOZZLE_GPIO, NOZZLE_MIN_DEG) != 0) {
        fprintf(stderr, "Error: failed to initialise servo positions\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        water_plant(VALVE_GPIO, NOZZLE_GPIO);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

