/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi 4 Model B.
 * Uses libgpiod v2.x (gpiod.h) — no wiringPi.
 *
 * Wiring (BCM numbering):
 *   TRIGGER -> GPIO17 (output)
 *   ECHO    -> GPIO18 (input, active-high, 3.3 V compatible)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lgpiod
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TRIGGER_LINE_OFFSET  17   /* BCM GPIO17 */
#define ECHO_LINE_OFFSET     18   /* BCM GPIO18 */

#define SPEED_OF_SOUND_CM_PER_US  0.01715   /* 343 m/s round-trip */
#define TIMEOUT_US               50000     /* 50 ms edge timeout */
#define MEASURE_INTERVAL_US      1000000   /* 1 s between measurements */
#define GUARD_INTERVAL_US        60000     /* 60 ms guard to avoid false echoes */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms)
{
    sleep_us(ms * 1000U);
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout or error.
 */
static long measure_echo(struct gpiod_line *echo_line)
{
    struct timespec t_start, t_now;
    long elapsed_us = 0;

    /* Wait for echo rising edge */
    while (1) {
        if (gpiod_line_get_value(echo_line) == 1)
            break;
        if (clock_gettime(CLOCK_MONOTONIC, &t_now) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        if (t_now.tv_sec > t_start.tv_sec ||
            (t_now.tv_sec == t_start.tv_sec && t_now.tv_nsec >= t_start.tv_nsec))
            return -1;          /* timeout */
        sleep_us(10);
    }

    clock_gettime(CLOCK_MONOTONIC, &t_start);

    /* Wait for echo falling edge */
    while (1) {
        if (gpiod_line_get_value(echo_line) == 0)
            break;
        if (clock_gettime(CLOCK_MONOTONIC, &t_now) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        if (t_now.tv_sec > t_start.tv_sec ||
            (t_now.tv_sec == t_start.tv_sec && t_now.tv_nsec >= t_start.tv_nsec))
            return -1;          /* timeout */
        sleep_us(10);
    }

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    return (long)(t_now.tv_sec - t_start.tv_sec) * 1000000L +
           (long)(t_now.tv_nsec - t_start.tv_nsec) / 1000L;
}

static float calculate_distance_cm(long pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US;
}

static void log_distance(FILE *fp, float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance_cm < 0.0f)
        fprintf(fp, "%s, -1.0\n", timestamp);
    else
        fprintf(fp, "%s, %.2f\n", timestamp, distance_cm);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file once */
    fp = fopen("distance_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open distance_log.txt: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open default gpiochip (gpiochip4 on Pi 4 Bookworm) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_LINE_OFFSET);
    if (!trigger_line) {
        fprintf(stderr, "gpiod_chip_get_line(trigger) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_LINE_OFFSET);
    if (!echo_line) {
        fprintf(stderr, "gpiod_chip_get_line(echo) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value 0 */
    if (gpiod_line_request_output(trigger_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(trigger) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input with rising-edge event detection */
    if (gpiod_line_request_rising_edge_events(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events(echo) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        long pulse_us = measure_echo(echo_line);
        float distance_cm = -1.0f;

        if (pulse_us >= 0) {
            distance_cm = calculate_distance_cm(pulse_us);
            if (distance_cm < 0.0f || distance_cm > 400.0f) {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
            }
        }

        log_distance(fp, distance_cm);

        /* Guard interval to avoid false echoes */
        sleep_ms(GUARD_INTERVAL_US);

        /* Measurement interval */
        sleep_ms(MEASURE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (echo_line)
        gpiod_line_release(echo_line);
    if (chip)
        gpiod_chip_close(chip);
    if (fp)
        fclose(fp);

    return ret;
}

