#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GPIO_RELAY     18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US   100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x0080
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_DISTANCE_MSB     0x0096
#define REG_RESULT_DISTANCE_LSB     0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
