#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_DURATION_SEC  5
#define POLL_INTERVAL_SEC     60
#define LOG_FILE            "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_watering_event(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int i;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire all four relay lines --- */
    for (i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- Request all lines as outputs, initially HIGH (inactive) --- */
    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "plant-watering",
                                       1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started. Relay pins: %u, %u, %u, %u\n",
           relay_pins[0], relay_pins[1], relay_pins[2], relay_pins[3]);
    printf("Watering every %d seconds for %d seconds. Press Ctrl+C to exit.\n",
           WATERING_DURATION_SEC, POLL_INTERVAL_SEC);

    /* --- Main loop: water each relay sequentially --- */
    while (g_running) {
        for (i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }

            printf("Watering plant on GPIO %u...\n", relay_pins[i]);

            /* Sleep in 1-second increments so signals are caught promptly */
            for (int s = 0; s < WATERING_DURATION_SEC && g_running; s++) {
                sleep(1);
            }

            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u HIGH: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }

            printf("Watering complete on GPIO %u.\n", relay_pins[i]);

            if (log_watering_event(LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to log watering event.\n");
            }
        }

        if (g_running) {
            /* Sleep in 1-second increments so signals are caught promptly */
            for (int s = 0; s < POLL_INTERVAL_SEC && g_running; s++) {
                sleep(1);
            }
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release all lines and close chip --- */
    for (i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

