#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800  /* 30 minutes in seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
}

static void sunrise_simulation(void) {
    for (int i = 0; i < SUNRISE_DURATION && running; ++i) {
        int duty = (i * 255) / SUNRISE_DURATION;
        for (int j = 0; j < 4; ++j) {
            if (gpioPWM(RELAY1_PIN, duty) != 0 ||
                gpioPWM(RELAY2_PIN, duty) != 0 ||
                gpioPWM(RELAY3_PIN, duty) != 0 ||
                gpioPWM(RELAY4_PIN, duty) != 0) {
                fprintf(stderr, "PWM write failed on one or more relays\n");
                log_event("Error: PWM write failed during sunrise simulation");
                break;
            }
        }
        log_event("Sunrise simulation: duty cycle = 255");
        gpioDelay(1000000); /* 1 second */
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Smart lighting sunrise simulation started");

    sunrise_simulation();

    cleanup_gpio();
    log_event("Smart lighting sunrise simulation stopped");
    return EXIT_SUCCESS;
}

