#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Maximum consecutive read failures before giving up */
#define MAX_READ_FAILURES 3

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(gyro_data_t data);
static void check_threshold(float x, float y, float z);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize the MPU-6050 */
static int init_mpu6050(void) {
    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, MPU6050_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms startup delay */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Set gyro full-scale range to +/- 250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data from the MPU-6050 */
static int read_gyro_data(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, raw_data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (returned %d)\n", bytes_read);
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    raw_x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    raw_y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    raw_z = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    /* Convert to degrees/second (131 LSB/deg/s for +/- 250 deg/s) */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static void check_threshold(float x, float y, float z) {
    int led_state = (fabsf(x) > 250.0f) || (fabsf(y) > 250.0f) || (fabsf(z) > 250.0f);
    if (gpioWrite(LED_PIN, led_state) < 0) {
        fprintf(stderr, "Warning: Failed to write LED pin\n");
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set LED pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    /* Set up signal handling */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    int consecutive_failures = 0;

    /* Main loop */
    while (running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            consecutive_failures = 0;

            gyro_data_t data;
            data.timestamp = clock_gettime(CLOCK_REALTIME);
            data.x = x;
            data.y = y;
            data.z = z;
            add_to_buffer(data);

            check_threshold(x, y, z);
        } else {
            consecutive_failures++;
            fprintf(stderr, "Error: Failed to read gyro data (attempt %d/%d)\n",
                    consecutive_failures, MAX_READ_FAILURES);

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max consecutive read failures reached. Exiting.\n");
                break;
            }

            /* Attempt to re-initialise the sensor */
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            gpioDelay(100000); /* 100 ms delay before retry */

            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: Re-initialisation failed. Exiting.\n");
                break;
            }
            consecutive_failures = 0;
        }

        gpioDelay(50000); /* 50 ms delay for 20 Hz sampling */
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return 0;
}

