#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define GYRO_REG_XOUT_H 0x43
#define GYRO_REG_ZOUT_L 0x48
#define GYRO_SCALE      131.0f
#define SAMPLE_PERIOD_US 10000
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250_cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_cs_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS LOW failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS HIGH failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro_raw(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t tx[6] = { (uint8_t)(GYRO_REG_XOUT_H | 0x80),
                      (uint8_t)(GYRO_REG_XOUT_H & 0x7F),
                      (uint8_t)(GYRO_REG_XOUT_H & 0x7F),
                      (uint8_t)(GYRO_REG_XOUT_H & 0x7F),
                      (uint8_t)(GYRO_REG_ZOUT_L | 0x80),
                      (uint8_t)(GYRO_REG_ZOUT_L & 0xFF) };
    uint8_t rx[6] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, sizeof(tx)) == 0) {
            *x = (int16_t)((rx[0] << 8) | rx[1]);
            *y = (int16_t)((rx[2] << 8) | rx[3]);
            *z = (int16_t)((rx[4] << 8) | rx[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int log_data(float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, sizeof(timestamp) - len, ".%09ld", ts.tv_nsec);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(gyro_log.txt): %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-9250 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_gyro_raw(&raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Gyroscope read failed after %d retries.\n", MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float x_rate = (float)raw_x / GYRO_SCALE;
        float y_rate = (float)raw_y / GYRO_SCALE;
        float z_rate = (float)raw_z / GYRO_SCALE;

        if (log_data(x_rate, y_rate, z_rate) < 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

