#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define LED_PIN         17
#define BUFFER_SIZE     64
#define SAMPLE_DELAY_US 100000
#define BLINK_INTERVAL_US 500000
#define SPI_SPEED_HZ    3900000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define GYRO_SENSITIVITY 131.0f
#define THRESHOLD       200.0f

#define REG_GYRO_X_H    0x43
#define REG_GYRO_Y_H    0x45
#define REG_GYRO_Z_H    0x47

typedef struct {
    time_t timestamp;
    float  x;
    float  y;
    float  z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, 8); /* GPIO8 = CE0 */
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip); chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip); chip = NULL; cs_line = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
