#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt thresholds (degrees) */
#define TILT_THRESHOLD 45.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_mpu6050(int handle);
static int read_raw_accel(int handle, int16_t *x, int16_t *y, int16_t *z);
static double calculate_roll(int16_t x, int16_t y, int16_t z);
static double calculate_pitch(int16_t x, int16_t y, int16_t z);
static void control_led(double roll, double pitch);
static void log_data(double roll, double pitch);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize MPU-6050: wake up and set accelerometer range to ±2g */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear SLEEP bit in PWR_MGMT_1) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settling time after wake-up */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ACCEL_CONFIG register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settling time for config change */
    return 0;
}

/* Read raw accelerometer data (6 bytes from 0x3B-0x40) */
static int read_raw_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int bytes_read = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes, got %d)\n", bytes_read);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Calculate roll angle in degrees */
static double calculate_roll(int16_t x, int16_t y, int16_t z) {
    double roll = atan2((double)y, (double)z) * 180.0 / M_PI;
    return roll;
}

/* Calculate pitch angle in degrees */
static double calculate_pitch(int16_t x, int16_t y, int16_t z) {
    double pitch = atan2(-(double)x, sqrt((double)y * y + (double)z * z)) * 180.0 / M_PI;
    return pitch;
}

/* Control LED based on tilt thresholds */
static void control_led(double roll, double pitch) {
    if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* Log data to file and console */
static void log_data(double roll, double pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);

    printf("%s, Roll: %.2f, Pitch: %.2f\n", timestamp, roll, pitch);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_raw_accel(i2c_handle, &x, &y, &z) == 0) {
            double roll = calculate_roll(x, y, z);
            double pitch = calculate_pitch(x, y, z);

            log_data(roll, pitch);
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping this cycle\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    cleanup();
    return 0;
}

