#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x5A
#define REG_ALS        0x20
#define REG_PS         0x22
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       17
#define THRESHOLD       100
#define LOG_FILE        "biometric_log.txt"
#define RETRY_COUNT     3
#define RETRY_DELAY_MS  10
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t reg_buf = reg;
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write(fd, &reg_buf, 1) == 1) {
            uint8_t data[2];
            if (read(fd, data, 2) == 2) {
                *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
                return 0;
            }
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    if (i2c_read_reg16(fd, REG_ALS, ambient_light) != 0) return -1;
    if (i2c_read_reg16(fd, REG_PS, proximity) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        fclose(log_fp);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "si1145_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        close(i2c_fd);
        return 1;
    }

    printf("Si1145 biometric sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient_light, proximity;
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_fp, ambient_light, proximity);
            if (proximity > THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Sensor read error after retries.\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(i2c_fd);
    printf("Cleanup complete.\n");
    return 0;
}

