#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_XGYRO_OUT  0x02
#define ADXRS290_REG_YGYRO_OUT  0x04

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

/* Sampling interval: 10 ms -> ~100 Hz */
#define SAMPLE_INTERVAL_US 10000

/* Retry configuration */
#define MAX_RETRIES 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADXRS290                              */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2], rx[2];
    int  ret;

    /* Build transaction: [reg | 0x80] [0x00] */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* Response is the second byte */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI                                                      */
/* ------------------------------------------------------------------ */
static int init_spi(void) {
    /* spiOpen flags: bits 0-1 = mode, bit 2 = active-low CE (pigpio default) */
    unsigned flags = (SPI_MODE & 0x03) | 0x04;
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, flags);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s (handle=%d)\n", pigpio_error(spi_handle), spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise file pointer                                              */
/* ------------------------------------------------------------------ */
static int init_file(void) {
    fp = fopen("gyro_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp_s,rate_x_deg_s,rate_y_deg_s\n");
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (fp) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (init_file() != 0) {
        cleanup();
        return 1;
    }

    printf("ADXRS290 gyro logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        gyro_data_t data;
        int16_t raw_x, raw_y;

        if (read_register(ADXRS290_REG_XGYRO_OUT, &raw_x) != 0) {
            fprintf(stderr, "Failed to read X gyro; reinitialising SPI...\n");
            for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
                if (init_spi() == 0) break;
                gpioDelay(100000); /* 100 ms back-off */
            }
            if (terminate) break;
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed after %d attempts; exiting.\n", MAX_RETRIES);
                break;
            }
            continue;
        }

        if (read_register(ADXRS290_REG_YGYRO_OUT, &raw_y) != 0) {
            fprintf(stderr, "Failed to read Y gyro; reinitialising SPI...\n");
            for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
                if (init_spi() == 0) break;
                gpioDelay(100000);
            }
            if (terminate) break;
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed after %d attempts; exiting.\n", MAX_RETRIES);
                break;
            }
            continue;
        }

        data.x_rate = raw_x;
        data.y_rate = raw_y;

        /* Timestamp: seconds since epoch, microsecond precision */
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp_s = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

        fprintf(fp, "%.6f,%.6f,%.6f\n", timestamp_s, data.x_rate, data.y_rate);
        fflush(fp);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

