#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define EVENT_DURATION_MS 500
#define ALERT_DURATION_MS 2000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        if (gpio == SENSOR_1_PIN && gpio == SENSOR_2_PIN) {
            uint32_t start_tick = tick;
            uint32_t elapsed = 0;
            while (running && elapsed < EVENT_DURATION_MS * 1000) {
                gpioDelay(1000);
                elapsed += 1000;
                if (gpioRead(SENSOR_1_PIN) == 1 && gpioRead(SENSOR_2_PIN) == 1) {
                    start_tick = tick;
                }
            }
            if (gpio == SENSOR_1_PIN && gpio == SENSOR_2_PIN) {
                if (elapsed >= EVENT_DURATION_MS * 1000) {
                    if (gpioWrite(ALERT_PIN, 1) == 0) {
                        uint32_t alert_start = tick;
                        while (running && elapsed < ALERT_DURATION_MS * 1000) {
                            gpioDelay(1000);
                            elapsed += 1000;
                        }
                        if (gpioWrite(ALERT_PIN, 0) == 0) {
                            time_t rawtime;
                            struct tm *timeinfo;
                            char timestamp[32];
                            time(&rawtime);
                            timeinfo = localtime(&rawtime);
                            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                            if (log_file) {
                                fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
                                fflush(log_file);
                            }
                        }
                    }
                }
            }
        }
    }
}

int main(void) {
