#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

#define ADXRS290_SENSITIVITY 200.0

typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    if (pthread_mutex_init(&buffer->mutex, NULL) != 0) {
        fprintf(stderr, "Error: Failed to initialize mutex for circular buffer.\n");
        return -1;
    }
    return 0;
}

static void add_to_circular_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

static int read_gyro_data(int spi_handle, float *angular_velocity) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADXRS290 requires MSB=1 for read */
    tx_buf[0] = (char)(ADXRS290_REG_RATE_XL | 0x80);
    tx_buf[1] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", result);
        return -1;
    }

    int16_t raw_data = (int16_t)(((uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    *angular_velocity = (float)raw_data / ADXRS290_SENSITIVITY;
    return 0;
}

static void control_led(float angular_velocity) {
    if (angular_velocity > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d).\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_circular_buffer(&gyro_buffer) != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float angular_velocity;
    struct timespec ts;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_US * 1000};

    while (program_running) {
        if (read_gyro_data(spi_handle, &angular_velocity) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_circular_buffer(&gyro_buffer, (gyro_data_t){ts, angular_velocity});
            control_led(angular_velocity);
        } else {
            fprintf(stderr, "Warning: Skipping sample due to read error.\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

