#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define FADE_DURATION_ARG 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range for GPIO%d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency for GPIO%d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM for GPIO%d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void fade_lamp(int pin, int duration_seconds) {
    if (duration_seconds <= 0) {
        gpioPWM(pin, 0);
        return;
    }

    int elapsed = 0;
    while (running && elapsed < duration_seconds) {
        int duty = (PWM_RANGE - 1) * elapsed / (PWM_RANGE * duration_seconds);
        if (gpioPWM(pin, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on pin %d.\n", pin);
        }
        elapsed += 1;
    }

    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on pin %d during shutdown.\n", pin);
    }
}

static void cleanup_all_lamps(void) {
    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  fade_duration_seconds: integer, 1-3600\n");
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: fade duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fading lamps for %d seconds.\n", duration);
    printf("Press Ctrl+C to stop early.\n");

    for (int i = 0; i < 3 && running; ++i) {
        fade_lamp(LAMP1_PIN, duration);
        fade_lamp(LAMP2_PIN, duration);
        fade_lamp(LAMP3_PIN, duration);
    }

    cleanup_all_lamps();
    printf("Smart Sunset Simulator finished.\n");
    return EXIT_SUCCESS;
}

