#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LOG_FILE "touch_relay.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated cleanly.");
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, val, rc);
        log_message(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(0x80, 0x63) < 0) return -1;  /* reset */
    gpioDelay(10000);
    if (mpr121_write(0x5E, 0x00) < 0) return -1;  /* stop mode */
    if (mpr121_write(0x5D, 0x01) < 0) return -1;  /* enable electrode 0 */
    if (mpr121_write(0x41, 0x0A) < 0) return -1;  /* touch threshold */
    if (mpr121_write(0x42, 0x08) < 0) return -1;  /* release threshold */
    if (mpr121_write(0x5B, 0x21) < 0) return -1;  /* debounce */
    if (mpr121_write(0x5C, 0x0D) < 0) return -1;  /* charge time */
    if (mpr121_write(0x5E, 0x0D) < 0) return -1;  /* run mode */
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lsb = i2cReadByteData(i2c_handle, 0x00);
    if (lsb < 0) return -1;
    int msb = i2cReadByteData(i2c_handle, 0x01);
    if (msb < 0) return -1;
    *status = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    uint16_t touch_status;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x0001) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                    log_message("Failed to write relay GPIO");
                } else {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                    log_message(msg);
                }
            }
        } else {
            log_message("Failed to read touch status");
        }
        gpioDelay(100000);  /* 100 ms debounce */
    }

    cleanup();
    return 0;
}

