#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening flame_log.txt");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = 0;
        int read_errors = 0;

        for (int i = 0; i < DEBOUNCE_READS; i++) {
            int val = gpiod_line_get_value(flame_line);
            if (val < 0) {
                perror("gpiod_line_get_value(flame)");
                read_errors = 1;
                break;
            }
            if (val == 0) {
                flame_detected = 1;
                break;
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        if (read_errors) {
            log_event(log_file, "Error reading flame sensor");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (flame_detected) {
            log_event(log_file, "Flame Detected");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                perror("gpiod_line_set_value(buzzer ON)");
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led ON)");
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                perror("gpiod_line_set_value(buzzer OFF)");
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led OFF)");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (flame_line) gpiod_line_release(flame_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    printf("Fire alarm system stopped.\n");
    return ret;
}

