#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor A pins */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B pins */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* Enable pins */
#define ENA 24
#define ENB 25

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* PWM range */
#define PWM_RANGE 255

/* PID parameters */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Log file path */
#define LOG_FILE "balance_log.txt"

/* Global state */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Function prototypes */
static int init_gpio(void);
static int set_motor_speed(int motor, int speed);
static float pid_control(float tilt_error, float *integral, float *previous_error);
static float simulate_distance_sensor(void);
static void obstacle_avoidance(float distance);
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
static void signal_handler(int signal);
static void cleanup(void);

int main(void) {
    float tilt_error = 0.0;
    float integral = 0.0;
    float previous_error = 0.0;
    float distance = 0.0;
    int motor_a_speed = 0;
    int motor_b_speed = 0;

    /* Initialize pigpio */
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Simulate distance sensor */
    distance = simulate_distance_sensor();

    /* Main control loop */
    while (running) {
        /* Simulate tilt error (random between -10 and 10 degrees) */
        tilt_error = (rand() % 21) - 10.0;

        /* PID control */
        motor_a_speed = pid_control(tilt_error, &integral, &previous_error);
        motor_b_speed = pid_control(tilt_error, &integral, &previous_error);

        /* Obstacle avoidance if distance is below threshold */
        obstacle_avoidance(distance);

        /* Set motor speeds */
        set_motor_speed(MOTOR_A_FORWARD, motor_a_speed);
        set_motor_speed(MOTOR_A_BACKWARD, 0);
        set_motor_speed(MOTOR_B_FORWARD, motor_b_speed);
        set_motor_speed(MOTOR_B_BACKWARD, 0);

        /* Log data */
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        /* Delay 50 ms */
        gpioDelay(50000);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

/* Initialize pigpio and configure GPIO pins */
static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set motor control pins as outputs */
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    /* Set enable pins as outputs and HIGH (motors enabled) */
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    /* Set PWM range */
    gpioSetPWMrange(MOTOR_A_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_A_BACKWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_BACKWARD, PWM_RANGE);

    /* Ensure motors are stopped initially */
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);

    return 0;
}

/* Set motor speed using PWM (0-255) */
static int set_motor_speed(int motor, int speed) {
    if (motor == MOTOR_A_FORWARD) {
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_FORWARD, speed);
    } else if (motor == MOTOR_A_BACKWARD) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioPWM(MOTOR_A_BACKWARD, speed);
    } else if (motor == MOTOR_B_FORWARD) {
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_FORWARD, speed);
    } else if (motor == MOTOR_B_BACKWARD) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioPWM(MOTOR_B_BACKWARD, speed);
    } else {
        fprintf(stderr, "Invalid motor: %c\n", motor);
        return -1;
    }
    return 0;
}

/* PID controller: returns motor speed (0-255) */
static float pid_control(float tilt_error, float *integral, float *previous_error) {
    float error = tilt_error;
    *integral += error;
    float derivative = error - *previous_error;
    float output = KP * error + KI * (*integral) + KD * derivative;

    if (output < 0) output = 0;
    if (output > 255) output = 255;
    *previous_error = error;
    return (int)output;
}

/* Simulate distance sensor returning a random value between 2.0 and 400.0 cm */
static float simulate_distance_sensor(void) {
    return (rand() % 399) + 2.0;
}

/* Obstacle avoidance: reverse both motors at 50% speed if distance < OBSTACLE_THRESHOLD */
static void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        motor_a_speed = 128;
        motor_b_speed = 128;
    }
}

/* Log data to file */
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Cleanup: stop motors, close log file, terminate pigpio */
static void cleanup(void) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

