#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ID 0x12
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME_154MS 0xD5
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int tcs34725_write_reg(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n", value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_read_reg(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int tcs34725_init(void) {
    uint8_t id;
    if (tcs34725_read_reg(TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (tcs34725_write_reg(TCS34725_ENABLE, 0x00) < 0) return -1;
    if (tcs34725_write_reg(TCS34725_ATIME, TCS34725_ATIME_154MS) < 0) return -1;
    if (tcs34725_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_crgb(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t c_low, c_high, r_low, r_high, g_low, g_high, b_low, b_high;
    if (tcs34725_read_reg(TCS34725_CDATA, &c_low) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_CDATA + 1, &c_high) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_RDATA, &r_low) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_RDATA + 1, &r_high) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_GDATA, &g_low) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_GDATA + 1, &g_high) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_BDATA, &b_low) < 0) return -1;
    if (tcs34725_read_reg(TCS34725_BDATA + 1, &b_high) < 0) return -1;
    *clear = (uint16_t)((c_high << 8) | c_low);
    *red   = (uint16_t)((r_high << 8) | r_low);
    *green = (uint16_t)((g_high << 8) | g_low);
    *blue  = (uint16_t)((b_high << 8) | b_low);
    return 0;
}

static void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    time(&rawtime);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)rawtime, clear, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        tcs34725_write_reg(TCS34725_ENABLE, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, TCS34725_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        cleanup();
        return 1;
    }
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(fp, "timestamp,clear,red,green,blue\n");
    fflush(fp);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    uint16_t clear, red, green, blue;
    while (!terminate) {
        if (tcs34725_read_crgb(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data. Setting to 0.\n");
            clear = red = green = blue = 0;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

