#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"
#define CONSUMER "sunrise_simulator"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM pin %u\n", relay_pins[i]);
            return -1;
        }

        int ret = gpiod_line_request_output(relay_lines[i], CONSUMER, 1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for BCM pin %u\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void set_all_relays(int value) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], value);
        }
    }
}

static void all_off(void) {
    set_all_relays(1);
}

static void all_on(void) {
    set_all_relays(0);
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_hours(unsigned int hours) {
    sleep_ms(hours * 60 * 1000);
}

static void simulate_sunrise(void) {
    for (int i = 0; i < 3600 && keep_running; i++) {
        for (int j = 0; j < 60 && keep_running; j++) {
            for (int k = 0; k < NUM_RELAYS; k++) {
                gpiod_line_set_value(relay_lines[k], 0);
                sleep_ms(20);
                gpiod_line_set_value(relay_lines[k], 1);
                sleep_ms(20);
            }
        }
    }
}

static void simulate_daytime(void) {
    for (int i = 0; i < 3600 && keep_running; i++) {
        for (int j = 0; j < 60 && keep_running; j++) {
            for (int k = 0; k < NUM_RELAYS; k++) {
                gpiod_line_set_value(relay_lines[k], 1);
            }
        }
    }
}

static void simulate_sunset(void) {
    for (int i = 0; i < 3600 && keep_running; i++) {
        for (int j = 0; j < 60 && keep_running; j++) {
            for (int k = 0; k < NUM_RELAYS; k++) {
                gpiod_line_set_value(relay_lines[k], 1);
                sleep_ms(20);
                gpiod_line_set_value(relay_lines[k], 0);
                sleep_ms(20);
            }
        }
    }
}

static void simulate_nighttime(void) {
    for (int i = 0; i < 86400 && keep_running; i++) {
        for (int j = 0; j < 60 && keep_running; j++) {
            for (int k = 0; k < NUM_RELAYS; k++) {
                gpiod_line_set_value(relay_lines[k], 1);
            }
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Sunrise simulator started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        simulate_sunrise();
        if (!keep_running) break;

        simulate_daytime();
        if (!keep_running) break;

        simulate_sunset();
        if (!keep_running) break;

        simulate_nighttime();
    }

    all_off();
    cleanup_gpio();
    printf("Sunrise simulator stopped.\n");
    return EXIT_SUCCESS;
}

