#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DIR "/home/pi/videos"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DURATION_SEC 5
#define DEBOUNCE_MS 200

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo);
}

static int ensure_video_dir(void) {
    struct stat st;
    if (stat(VIDEO_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", VIDEO_DIR);
        return -1;
    }
    if (mkdir(VIDEO_DIR, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int ensure_log_file(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return -1;
    }
    return 0;
}

static int record_video(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspivid -t %d -o %s", VIDEO_DURATION_SEC, filename);
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static void log_motion(const char *filename) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file) {
        fprintf(log_file, "%s: Motion detected, video recorded: %s\n", ts, filename);
        fflush(log_file);
    }
    printf("%s: Motion detected, video recorded: %s\n", ts, filename);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (ensure_video_dir() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    uint32_t last_trigger_ms = 0;
    while (running) {
        int level = gpioRead(MOTION_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", MOTION_SENSOR_GPIO);
            break;
        }

        if (level == 0) {
            uint32_t now_ms = gpioTick() / 1000;
            if (now_ms - last_trigger_ms >= DEBOUNCE_MS) {
                last_trigger_ms = now_ms;
                char filename[64];
                get_timestamp(filename, sizeof(filename));

                if (record_video(filename) == 0) {
                    log_motion(filename);
                } else {
                    fprintf(stderr, "Failed to record video for %s\n", filename);
                }
            }
        }

        gpioDelay(10000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

