#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x19
#define GYRO_FS_SEL  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

/* Sensitivity for ±250 °/s range: 131 LSB per °/s */
#define GYRO_SENSITIVITY 131.0f

/* Sample interval in microseconds (10 ms = 100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Log file path */
#define LOG_FILE "gyro_log.csv"

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global state for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the MPU-6050: wake it up and configure gyroscope */
static int init_mpu6050(void) {
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1 (wake up): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake */

    /* Set sample rate divider to 125 Hz (register 0x19: 0x07 = 1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope full-scale range to ±250 °/s (register 0x1B: 0x00 = ±250 °/s) */
    if (i2cWriteByteData(i2c_handle, GYRO_FS_SEL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write GYRO_FS_SEL: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read raw 16-bit gyroscope values from consecutive registers */
static int read_gyro_raw(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting at GYRO_XOUT_H (0x43) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes, expected 6): %s\n",
                bytes_read, strerror(errno));
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    *x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    return 0;
}

/* Convert raw gyroscope value to degrees per second */
static float convert_to_dps(int16_t raw) {
    return (float)raw / GYRO_SENSITIVITY;
}

/* Log a single data record to the CSV file */
static void log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

/* Attempt to re-initialize the MPU-6050 after a failure */
static int reinit_mpu6050(void) {
    fprintf(stderr, "Attempting to re-initialize MPU-6050...\n");
    for (int attempt = 0; attempt < 3; attempt++) {
        if (init_mpu6050() == 0) {
            fprintf(stderr, "Re-initialization successful (attempt %d).\n", attempt + 1);
            return 0;
        }
        fprintf(stderr, "Re-initialization attempt %d failed.\n", attempt + 1);
        gpioDelay(100000); /* 100 ms before retry */
    }
    fprintf(stderr, "Re-initialization failed after 3 attempts.\n");
    return -1;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d): %s\n", i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,degrees_per_s\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "MPU-6050 vibration monitoring started. Logging to %s\n", LOG_FILE);
    fprintf(stderr, "Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;

        if (read_gyro_raw(&raw_x, &raw_y, &raw_z) == 0) {
            float dps_x = convert_to_dps(raw_x);
            float dps_y = convert_to_dps(raw_y);
            float dps_z = convert_to_dps(raw_z);
            log_data(dps_x, dps_y, dps_z);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Attempting re-initialization...\n");
            if (reinit_mpu6050() != 0) {
                fprintf(stderr, "Error: Failed to re-initialize sensor after 3 attempts.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    fprintf(stderr, "\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    fprintf(stderr, "Cleanup complete.\n");
    return EXIT_SUCCESS;
}

