#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define NUM_RELAYS 4
#define SLEEP_SECONDS 5

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Failed to write HIGH to GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(int pin) {
    return rand() % 101;
}

static int control_relay(int pin, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write %d to GPIO %d\n", state, pin);
        return -1;
    }
    return 0;
}

static void log_data(int moisture_level, int relay_state, time_t timestamp) {
    struct tm *timeinfo;
    char timestamp_str[20];
    timeinfo = localtime(&timestamp);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s - Moisture Level: %d, Relay State: %d\n", timestamp_str, moisture_level, relay_state);
    fflush(log_file);
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    srand(time(NULL));

    while (running) {
        time_t current_time = time(NULL);
        int moisture_level = read_moisture_sensor(RELAY1_PIN);
        int relay_state = 0;

        for (int i = 0; i < NUM_RELAYS; i++) {
            relay_state |= control_relay(relay_pins[i], moisture_level);
        }

        log_data(moisture_level, relay_state, current_time);
        sleep(SLEEP_SECONDS);
    }

    cleanup();
    return 0;
}

