#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define SAMPLE_INTERVAL_MS 100
#define ALARM_HOLD_MS 5000
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ADXL345_ADDRESS, i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening freefall.log for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

static void trigger_alarm(void) {
    gpioWrite(ALARM_GPIO, 1);
    gpioDelay(ALARM_HOLD_MS * 1000);
    gpioWrite(ALARM_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    if (adxl345_init() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    int freefall_active = 0;
    int freefall_count = 0;

    while (!terminate) {
        if (read_accelerometer(&x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                if (!freefall_active) {
                    freefall_active = 1;
                    freefall_count = 0;
                } else {
                    freefall_count++;
                }

                if (freefall_count >= FREEFALL_DURATION_MS / SAMPLE_INTERVAL_MS) {
                    log_freefall(x, y, z);
                    trigger_alarm();
                    freefall_active = 0;
                    freefall_count = 0;
                }
            } else {
                freefall_active = 0;
                freefall_count = 0;
            }
        } else {
            gpioDelay(100000);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();

    return 0;
}

