#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TIMEOUT_US 100000  /* 100 ms timeout for echo */
#define MAX_DISTANCE_CM 4000.0
#define LOG_FILE "distance_log.txt"

/* Shared state between callback and main thread */
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_timeout = 0;
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo interrupt callback (rising edge)                                */
/* ------------------------------------------------------------------ */
static void echo_rising(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&data_mutex);
        start_tick = tick;
        echo_received = 0;
        echo_timeout = 0;
        pthread_mutex_unlock(&data_mutex);
    }
}

/* ------------------------------------------------------------------ */
/* Echo interrupt callback (falling edge)                              */
/* ------------------------------------------------------------------ */
static void echo_falling(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        pthread_mutex_lock(&data_mutex);
        end_tick = tick;
        echo_received = 1;
        echo_timeout = 0;
        pthread_mutex_unlock(&data_mutex);
    }
}

/* ------------------------------------------------------------------ */
/* Trigger pulse generation                                           */
/* ------------------------------------------------------------------ */
static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);  /* 10 µs */
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute distance from pulse width in microseconds                   */
/* ------------------------------------------------------------------ */
static double calculate_distance_cm(uint32_t pulse_width_us)
{
    /* Speed of sound: 343 m/s = 0.0343 cm/µs */
    return (double)pulse_width_us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
/* Log a distance reading with nanosecond timestamp                     */
/* ------------------------------------------------------------------ */
static void log_distance(double distance_cm)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%ld.%09ld,%.2f\n",
            (long)ts.tv_sec, ts.tv_nsec, distance_cm);
