#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LIS3DH I2C address (SA0 tied to GND) */
#define LIS3DH_ADDR 0x18

/* LIS3DH register addresses */
#define CTRL_REG1   0x20
#define CTRL_REG4   0x23
#define OUT_X_L     0x28

/* Buzzer GPIO pin */
#define BUZZER_PIN 17

/* Default thresholds */
#define DEFAULT_FREEFALL_THRESHOLD  0.2f
#define DEFAULT_IMPACT_THRESHOLD   1.5f

/* Sensitivity for ±2g full scale: 16384 LSB/g */
#define LIS3DH_SENSITIVITY 16384.0f

/* I2C bus on Raspberry Pi 5 */
#define I2C_BUS 1

/* Retry configuration */
#define I2C_RETRIES 3
#define RETRY_DELAY_US 1000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize pigpio and I2C bus */
static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Configure LIS3DH: 100 Hz data rate, ±2g full scale */
static int configure_lis3dh(void) {
    /* CTRL_REG1: ODR=100Hz (0x77), all axes enabled, normal mode */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: Full scale ±2g (0x00) */
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read 16-bit signed acceleration value from OUT_X_L */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from OUT_X_L: X_L, X_H, Y_L, Y_H, Z_L, Z_H */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: I2C block read failed (returned %d)\n", bytes_read);
        return -1;
    }

    /* Combine little-endian bytes into signed 16-bit values */
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Convert raw acceleration to g */
static float convert_to_g(int16_t raw) {
    return (float)raw / LIS3DH_SENSITIVITY;
}

/* Calculate acceleration magnitude in g */
static float calculate_magnitude_g(int16_t x, int16_t y, int16_t z) {
    float fx = convert_to_g(x);
    float fy = convert_to_g(y);
    float fz = convert_to_g(z);
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

/* Activate buzzer for 1 second */
static void activate_buzzer(void) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(1000000); /* 1 second in microseconds */
    gpioWrite(BUZZER_PIN, 0);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold   = DEFAULT_IMPACT_THRESHOLD;

    /* Parse command-line arguments */
    if (argc > 1) {
        freefall_threshold = (float)atof(argv[1]);
        if (freefall_threshold <= 0.0f) {
            fprintf(stderr, "Warning: Freefall threshold must be positive\n");
            freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
        }
    }
    if (argc > 2) {
        impact_threshold = (float)atof(argv[2]);
        if (impact_threshold <= 0.0f) {
            fprintf(stderr, "Warning: Impact threshold must be positive\n");
            impact_threshold = DEFAULT_IMPACT_THRESHOLD;
        }
    }

    printf("Freefall threshold: %.3f g\n", freefall_threshold);
    printf("Impact threshold: %.3f g\n", impact_threshold);

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Initialize pigpio and I2C */
    if (initialize_i2c() < 0) {
        return EXIT_FAILURE;
    }

    /* Configure LIS3DH */
    if (configure_lis3dh() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin */
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    printf("Starting data acquisition (100 Hz, ±2g)...\n");

    int consecutive_errors = 0;

    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;

        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            consecutive_errors = 0;

            float magnitude = calculate_magnitude_g(raw_x, raw_y, raw_z);

            printf("X: %6d, Y: %6d, Z: %6d, Mag: %6.3f g\n",
                   raw_x, raw_y, raw_z, magnitude);

            if (magnitude < freefall_threshold) {
                printf("Freefall detected!\n");
                activate_buzzer();
            } else if (magnitude > impact_threshold) {
                printf("Impact detected!\n");
                activate_buzzer();
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (attempt %d/%d)\n",
                    consecutive_errors, I2C_RETRIES);
            if (consecutive_errors >= I2C_RETRIES) {
                fprintf(stderr, "Fatal: Max I2C errors reached. Exiting.\n");
                break;
            }
            gpioDelay(RETRY_DELAY_US);
        }

        gpioDelay(10000); /* 10 ms delay (~100 Hz polling) */
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

