#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LIS3DH I2C address (SA0 tied to GND) */
#define LIS3DH_ADDR 0x18

/* LIS3DH register addresses */
#define CTRL_REG1   0x20
#define CTRL_REG4   0x23
#define OUT_X_L     0x28
#define OUT_X_H     0x29
#define OUT_Y_L     0x2A
#define OUT_Y_H     0x2B
#define OUT_Z_L     0x2C
#define OUT_Z_H     0x2D

/* ±2g, high-resolution mode: 12-bit left-justified, 100 Hz ODR */
#define CTRL_REG1_VAL 0x57
/* ODR = 100 Hz, all axes enabled, little-endian */
#define CTRL_REG4_VAL 0x88

/* ±2g sensitivity: 1 mg/LSB = 0.001 g/LSB */
#define SENSITIVITY 0.001f

#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms = 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", val, reg, rc);
        return -1;
    }
    return 0;
}

static int init_lis3dh(int addr)
{
    if (addr < 0x08 || addr > 0x77) {
        fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x08-0x77)\n", addr);
        return -1;
    }

    g_i2c_handle = i2cOpen(1, addr, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X (rc=%d)\n", addr, g_i2c_handle);
        return -1;
    }

    if (write_reg(CTRL_REG1, CTRL_REG1_VAL) != 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    if (write_reg(CTRL_REG4, CTRL_REG4_VAL) != 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_acceleration(int *x, int *y, int *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(g_i2c_handle, OUT_X_L, buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration block (rc=%d)\n", i2cReadI2CBlockData(g_i2c_handle, OUT_X_L, buf, 6));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    return 0;
}

static float calculate_g(int16_t raw)
{
    return (float)raw * SENSITIVITY;
}

static void log_event(float x, float y, float z, float threshold)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - High acceleration detected: X=%.3f g, Y=%.3f g, Z=%.3f g (threshold=%.3f g)\n",
            ts, x, y, z, threshold);
    fclose(fp);
}

static void shutdown_system(float x, float y, float z, float threshold)
{
    printf("High acceleration detected! Shutting down system...\n");
    fflush(stdout);

    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        perror("system() failed");
    }
}

int main(int argc, char *argv[])
{
    int i2c_addr = LIS3DH_ADDR;
    float threshold = 2.0f;

    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 0);
        if (*endptr != '\0' || val < 0x08 || val > 0x77) {
            fprintf(stderr, "Invalid I2C address: %s\n", argv[1]);
            return 1;
        }
        i2c_addr = (int)val;
    }

    if (argc > 2) {
        char *endptr;
        float val = strtof(argv[2], &endptr);
        if (*endptr != '\0' || val <= 0.0f) {
            fprintf(stderr, "Invalid threshold: %s\n", argv[2]);
            return 1;
        }
        threshold = val;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed (run as root?)\n");
        return 1;
    }

    if (init_lis3dh(i2c_addr) != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring acceleration at 0x%02X (threshold %.2f g)...\n", i2c_addr, threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            float x = calculate_g(raw_x);
            float y = calculate_g(raw_y);
            float z = calculate_g(raw_z);

            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z, threshold);
                shutdown_system(x, y, z, threshold);
                break;
            }
        } else {
            fprintf(stderr, "Sensor read error; continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

