#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN  4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define POLL_INTERVAL_US 10000
#define ALERT_DURATION_US 2000000

#define LINE_FOLLOW_FORWARD  0
#define LINE_FOLLOW_TURN_LEFT 1
#define LINE_FOLLOW_TURN_RIGHT 2
#define LINE_FOLLOW_STOP     3

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static volatile sig_atomic_t program_running = 1;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
    }
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open gpio chip: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line_follower_left") < 0) {
        fprintf(stderr, "Failed to request left line as input: %s\n", strerror(errno));
        cleanup();
        return -1;
    }
    if (gpiod_line_request_input(center_line, "line_follower_center") < 0) {
        fprintf(stderr, "Failed to request center line as input: %s\n", strerror(errno));
        cleanup();
