#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7210_ADDR    0x30
#define RELAY_GPIO      17
#define FIELD_THRESHOLD 5.0f
#define SAMPLE_US      100000   /* 100 ms */
#define CONV_TIMEOUT   50       /* 50 * 2 ms = 100 ms max conversion time */
#define LOG_FILE       "magnetic_events.txt"

/* Si7210 register addresses */
#define SI7210_REG_CONV_STATUS   0xC1
#define SI7210_REG_FIELD_LSB    0xC0
#define SI7210_REG_MEAS_CONFIG   0xC1  /* 0x01 one-shot measurement */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    } else {
        fprintf(fp, "<unknown-time> %s\n", msg);
    }
    fclose(fp);
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X val=0x%02X rc=%d", reg, val, rc);
        log_event(buf);
    }
    return rc;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read failed: reg=0x%02X rc=%d", reg, rc);
        log_event(buf);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg(handle, reg, &lo) < 0) return -1;
    if (i2c_read_reg(handle, reg + 1, &hi) < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int read_field_mT(int handle, float *field_mT)
{
    uint8_t status = 0xFF;

    /* Trigger one-shot measurement */
    if (i2c_write_reg(handle, SI7210_REG_MEAS_CONFIG, 0x01) < 0)
        return -1;

    /* Poll conversion status until it reads 0x00 (conversion complete) */
    for (int i = 0; i < CONV_TIMEOUT; i++) {
        if (i2c_read_reg(handle, SI7210_REG_CONV_STATUS, &status) < 0)
            return -1;
        if (status == 0x00)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if (status != 0x00) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Field conversion timeout (status=0x%02X)", status);
        log_event(buf);
        return -1;
    }

    int16_t raw;
    if (i2c_read_reg16(handle, SI7210_REG_FIELD_LSB, &raw) < 0)
        return -1;

    /* Convert raw to milliTesla: 0.01 mT per LSB */
    *field_mT = (float)raw * 25.0f / 1000.0f;
    return 0;
}

static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to %s relay", state ? "activate" : "deactivate");
        log_event(buf);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, SI7210_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Si7210 monitoring started");

    while (g_running) {
        float field_mT = 0.0f;
        int rc = read_field_mT(g_i2c_handle, &field_mT);

        if (rc == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Field strength: %.2f mT", field_mT);
            log_event(msg);

            if (field_mT > FIELD_THRESHOLD * 100.0f) {
                control_relay(1);
                log_event("Relay activated");
            } else {
                control_relay(0);
                log_event("Relay deactivated");
            }
        } else if (rc < 0) {
            /* Error already logged in helper functions */
        }

        gpioDelay(SAMPLE_US);
    }

    /* Graceful shutdown */
    log_event("Shutting down");
    control_relay(0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

