#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define I2C_BUS 1
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0f
#define SCALE_FACTOR 1500.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_out) {
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read error: handle=%d, n=%d\n", handle, n);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / SCALE_FACTOR;
    return 0;
}

static void log_flow_rates(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000, f1, f2);
    fclose(fp);
}

static void cleanup(void) {
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (0x%02X): %d\n",
                SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (0x%02X): %d\n",
                SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    if (i2cWriteDevice(g_i2c_handle1, (char *)"36 08") < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 1\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteDevice(g_i2c_handle2, (char *)"36 08") < 0) {
        fprintf(stderr, "Failed to start measurement on sensor 2\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow_rate(g_i2c_handle1, &f1);
        int r2 = read_flow_rate(g_i2c_handle2, &f2);

        if (r1 == 0 && r2 == 0) {
            int relay_on = (f1 < FLOW_THRESHOLD) || (f2 < FLOW_THRESHOLD);
            gpioWrite(RELAY_GPIO, relay_on ? 1 : 0);
            log_flow_rates(f1, f2);
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

