#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_STABILIZE_US  600000   /* 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on pin %u (level %u): %s",
               pin, level, pigpio_error(0));
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENA_PIN, 0);
    rc |= safe_write(MOTOR_IN1_PIN, 0);
    rc |= safe_write(MOTOR_IN2_PIN, 0);
    return rc;
}

static int motor_run(void)
{
    if (safe_write(MOTOR_ENA_PIN, 1) < 0) return -1;
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return -1;
    return 0;
}

static int close_window(void)
{
    syslog(LOG_INFO, "Closing window...");
    if (motor_run() < 0) {
        syslog(LOG_ERR, "Motor start failed");
        return -1;
    }
    gpioDelay(MOTOR_RUN_US);
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Motor stop failed");
        return -1;
    }
    syslog(LOG_INFO, "Window closed.");
    return 0;
}

static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised.");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin %d as input", RAIN_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
