#define SERVO_PIN      18
#define BUTTON_LOCK    21
#define BUTTON_UNLOCK  22
#define SERVO_LOCK     2000   /* microseconds: locked position */
#define SERVO_UNLOCK   1000   /* microseconds: unlocked position */
#define DEBOUNCE_US    50000  /* 50 ms debounce */
#define POLL_US        10000  /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int safe_gpio_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(pin=%u, level=%u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "gpioServo(pin=%d, %d us) failed\n", SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure servo pin as output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SERVO_PIN=%d, OUTPUT) failed\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) != 0 ||
        gpioSetMode(BUTTON_UNLOCK, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(BUTTON_PIN=%d/%d, INPUT) failed\n",
                BUTTON_LOCK, BUTTON_UNLOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo is in a known state at startup */
    if (set_servo(SERVO_UNLOCK) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Door-lock servo initialised at unlocked position (1000 us).\n");
    fflush(stdout);

    int last_lock_state = 1;   /* 1 = released, 0 = pressed */
    int last_unlock_state = 1;

    while (g_running) {
        int lock_state = gpioRead(BUTTON_LOCK);
        int unlock_state = gpioRead(BUTTON_UNLOCK);

        if (lock_state < 0 || unlock_state < 0) {
            fprintf(stderr, "gpioRead failed (LOCK=%d, UNLOCK=%d)\n",
                    lock_state, unlock_state);
            break;
        }

        /* Lock button: pressed when LOW (pulled up) */
        if (lock_state == 0 && last_lock_state == 1) {
            if (set_servo(SERVO_LOCK) == 0) {
                printf("Locking door (2000 us pulse).\n");
                fflush(stdout);
            }
            last_lock_state = lock_state;
        }

        /* Unlock button: pressed when LOW */
        if (unlock_state == 0 && last_unlock_state == 1) {
            if (set_servo(SERVO_UNLOCK) == 0) {
                printf("Unlocking door (1000 us pulse).\n");
                fflush(stdout);
            }
            last_unlock_state = unlock_state;
        }

        /* Debounce: wait for release, then add debounce delay */
        if (lock_state == 1) {
            gpioDelay(DEBOUNCE_US);
        }
        if (unlock_state == 1) {
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: stop servo pulses and release pigpio */
    set_servo(0);
    gpioTerminate();
    printf("\nDoor-lock servo stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

