#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define FLOODLIGHT_DURATION 60
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type, int duration) {
    FILE *fp = fopen("security_log.txt", "a");
    if (!fp) {
        perror("fopen security_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s, duration: %d seconds\n", timestamp, event_type, duration) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(FLOODLIGHT_PIN, 1) failed\n");
        return -1;
    }
    return 0;
}

static int deactivate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(FLOODLIGHT_PIN, 0) failed\n");
        return -1;
    }
    return 0;
}

static int measure_floodlight_duration(void) {
    time_t start = time(NULL);
    if (start == (time_t)-1) {
        perror("time");
        return -1;
    }

    if (activate_floodlight() != 0) {
        return -1;
    }

    for (int i = 0; i < 100 && running; i++) {
        gpioDelay(POLL_DELAY_US);
    }

    if (!running) {
        return -1;
    }

    time_t end = time(NULL);
    if (end == (time_t)-1) {
        perror("time");
        deactivate_floodlight();
        return -1;
    }

    if (deactivate_floodlight() != 0) {
        return -1;
    }

    return difftime(end, start);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(FLOODLIGHT_PIN) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(FLOODLIGHT_PIN, 0) initial failed\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(PIR_PIN) == 1) {
            printf("Motion detected!\n");

            if (activate_floodlight() != 0) {
                fprintf(stderr, "Failed to activate floodlight\n");
            } else {
                int duration = measure_floodlight_duration();
                if (duration < 0) {
                    fprintf(stderr, "Measurement failed or interrupted\n");
                } else {
                    if (log_event("Motion", duration) != 0) {
                        fprintf(stderr, "Failed to log event\n");
                    }
                }
            }

            if (deactivate_floodlight() != 0) {
                fprintf(stderr, "Failed to deactivate floodlight\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    deactivate_floodlight();
    gpioTerminate();
    printf("Smart Security Light stopped.\n");
    return 0;
}

