#include <pigpio.h>

#define RELAY_GPIO        17
#define I2C_BUS           1
#define MPR121_ADDR       0x5A

/* MPR121 register addresses */
#define MHD_R           0x2B
#define NHD_R           0x2C
#define NCL_R           0x2D
#define FDL_R           0x2E
#define DEBOUNCE        0x5B
#define CONFIG1         0x5C
#define CONFIG2         0x5D
#define ELE0_T_THRESH   0x41
#define ELE0_R_THRESH   0x42
#define ELEPROX         0x7B
#define AUTO_CONFIG0    0x7B
#define AUTO_CONFIG1    0x7C
#define AUTO_CONFIG2    0x7D
#define SOFTRESET       0x80
#define TOUCH_STATUS_L  0x00
#define TOUCH_STATUS_H  0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write(handle, SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Baseline filtering */
    if (mpr121_write(handle, MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(handle, NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(handle, FDL_R, 0x00) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (mpr121_write(handle, DEBOUNCE, 0x33) < 0) return -1;

    /* Filtering / charge settings */
    if (mpr121_write(handle, CONFIG1, 0x10) < 0) return -1; /* FFI=6, CDC=16 */
    if (mpr121_write(handle, CONFIG2, 0x20) < 0) return -1; /* CDT=0.5us, SFI=4 */

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write(handle, ELE0_T_THRESH, 0x0F) < 0) return -1;
    if (mpr121_write(handle, ELE0_R_THRESH, 0x0A) < 0) return -1;

    /* Auto-config: 12 electrodes, 0.5us CDT, 4 samples */
    if (mpr121_write(handle, AUTO_CONFIG0, 0x0C) < 0) return -1;
    if (mpr121_write(handle, AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(handle, AUTO_CONFIG2, 0x00) < 0) return -1;

    /* Enable 12 electrodes (0x0C = 12) */
    if (mpr121_write(handle, 0x5E, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle) {
