    if (lo < 0) {
        fprintf(stderr, "I2C read failed (touch status low): %d\n", lo);
        return -1;
    }
    int hi = i2cReadByteData(handle, TOUCH_STATUS_H);
    if (hi < 0) {
        fprintf(stderr, "I2C read failed (touch status high): %d\n", hi);
        return -1;
    }
    return (hi << 8) | lo;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

