    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    printf("MPR121 relay control started. Touch electrode 0 to toggle relay.\n");
    printf("Press Ctrl+C to exit.\n");

    int last_touch = 0;

    while (g_running) {
        int touch = read_touch_status(g_i2c_handle);
        if (touch < 0) {
            /* Sensor read error: ensure relay is off and retry */
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(100000);
            continue;
        }

        /* Rising-edge detection: only toggle on fresh touch */
        if (touch && !last_touch) {
            gpioWrite(RELAY_GPIO, 1);
            printf("Relay ON\n");
        } else if (!touch && last_touch) {
            gpioWrite(RELAY_GPIO, 0);
            printf("Relay OFF\n");
        }
        last_touch = touch;

        gpioDelay(50000); /* 50 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

