#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define PORT 5000
#define PIR_PIN 4
#define SERVO_PIN 17
#define LOG_FILE "security.log"
#define GPIO_CHIP "gpiochip4"
#define PWM_PERIOD_US 20000  /* 50 Hz */
#define PWM_MIN_PULSE_US 1000  /* 1 ms -> 0° */
#define PWM_MAX_PULSE_US 2000  /* 2 ms -> 180° */

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *servo_line = NULL;

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    if (log_fp) {
        fprintf(log_fp, "%s: %s\n", timestamp, message);
        fflush(log_fp);
    }
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (servo_line) {
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    closelog();
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip");
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message("Failed to get PIR line");
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "security-pir") < 0) {
        log_message("Failed to request PIR line as input");
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message("Failed to get servo line");
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "security-servo", 0) < 0) {
        log_message("Failed to request servo line as output");
        return -1;
    }
    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_us = PWM_MIN_PULSE_US + (angle * (PWM_MAX_PULSE_US - PWM_MIN_PULSE_US) / 180);
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message("Failed to set servo high");
        return;
    }
    usleep(pulse_us);
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message("Failed to set servo low");
        return;
    }
    usleep(PWM_PERIOD_US - pulse_us);
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        if (n < 0) log_message("recv error");
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    char *cmd = strtok(buffer, " \r\n");
    while (cmd) {
        char *arg = strtok(NULL, " \r\n");
        if (!arg) break;
        if (strcmp(cmd, "SERVO") == 0) {
            int angle = atoi(arg);
            if (angle >= 0 && angle <= 180) {
                set_servo_angle(angle);
                char resp[64];
                snprintf(resp, sizeof(resp), "SERVO: %d", angle);
                send(client_fd, resp, strlen(resp), 0);
            } else {
                send(client_fd, "ERROR: Invalid angle\n", 18, 0);
            }
        } else if (strcmp(cmd, "PIR") == 0) {
            int pir = gpiod_line_get_value(pir_line);
            if (pir < 0) {
                send(client_fd, "ERROR: PIR read failed\n", 20, 0);
            } else {
                char resp[64];
                snprintf(resp, sizeof(resp), "PIR:%d", pir);
                send(client_fd, resp, strlen(resp), 0);
            }
        } else {
            send(client_fd, "ERROR: Unknown command\n", 20, 0);
        }
        cmd = strtok(NULL, " \r\n");
    }
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set signal handlers");
        return 1;
    }
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_message("Failed to open log file");
        return 1;
    }
    openlog("security_app", LOG_PID | LOG_CONS, LOG_USER);
    if (init_gpio() < 0) {
        log_message("GPIO initialization failed");
        cleanup();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Socket creation failed");
        cleanup();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("setsockopt failed");
        cleanup();
        return 1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message("Bind failed");
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message("Listen failed");
        cleanup();
        return 1;
    }
    log_message("Listening on port 5000");
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_message("Accept failed");
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf), "Client connected: %s", ip);
        log_message(log_buf);
        handle_client(client_fd);
    }
    log_message("Shutting down");
    cleanup();
    return 0;
}

