int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set signal handlers");
        return 1;
    }
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_message("Failed to open log file");
        return 1;
    }
    openlog("security_app", LOG_PID | LOG_CONS, LOG_USER);
    if (init_gpio() < 0) {
        log_message("GPIO initialization failed");
        cleanup();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Socket creation failed");
        cleanup();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("setsockopt failed");
        cleanup();
        return 1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message("Bind failed");
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message("Listen failed");
        cleanup();
        return 1;
    }
    log_message("Listening on port 5000");
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_message("Accept failed");
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf), "Client connected: %s", ip);
        log_message(log_buf);
        handle_client(client_fd);
    }
    log_message("Shutting down");
    cleanup();
    return 0;
}

