#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define I2C_BUS 1
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_SEC 2
#define BH1750_CONV_MS 120

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_read_lux(int handle, float *lux_out) {
    char buf[2];
    int rc;

    /* One-Time High-Resolution mode (command 0x20) */
    rc = i2cWriteByte(handle, 0x20);
    if (rc < 0) {
        fprintf(stderr, "BH1750: failed to send mode command (rc=%d)\n", rc);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);

    /* Read 2 bytes of result */
    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "BH1750: failed to read data (rc=%d)\n", rc);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    float lux;
    int relay_state = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (running) {
        if (bh1750_read_lux(i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                if (gpioWrite(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                    printf("Grow light ON\n");
                } else {
                    fprintf(stderr, "Failed to activate relay\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                if (gpioWrite(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                    printf("Grow light OFF\n");
                } else {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
            }

            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

