#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>

#define DOUT_PIN      23
#define SCK_PIN       24
#define SOLENOID_PIN  25

#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US  10000
#define HX711_READ_US    100
#define HX711_AVG_READS  5
#define HX711_TARE_READS 10
#define SOLENOID_PULSE_US 200000
#define POLL_INTERVAL_US  500000
#define MAX_RETRIES       3

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int wait_low(struct gpiod_line *line, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpiod_line_get_value(line) == 1) {
        if (elapsed >= timeout_us) return -1;
        sleep_us(10);
        elapsed += 10;
    }
    return 0;
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck, long *out) {
    if (wait_low(dout, HX711_TIMEOUT_US) < 0) {
        syslog(LOG_ERR, "HX711: DOUT timeout waiting for LOW");
        return -1;
    }

    long count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "HX711: SCK high write failed");
            return -1;
        }
        sleep_us(HX711_READ_US);
        count <<= 1;
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "HX711: SCK low write failed");
            return -1;
        }
        sleep_us(HX711_READ_US);
        if (gpiod_line_get_value(dout, 0) < 0) {
            syslog(LOG_ERR, "HX711: DOUT read failed");
            return -1;
        }
        if (count & 0x800000) count |= 0xFF000000L;
    }

    /* 25th pulse: Channel A / Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "HX711: 25th SCK high failed");
        return -1;
    }
    sleep_us(HX711_READ_US);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "HX711: 25th SCK low failed");
        return -1;
    }
    sleep_us(HX711_READ_US);

    *out = count;
    return 0;
}

static long average_readings(struct gpiod_line *dout, struct gpiod_line *sck, int avg_reads) {
    long sum = 0;
    for (int i = 0; i < avg_reads; i++) {
        long r;
        if (read_hx711(dout, sck, &r) < 0) return -1;
        sum += r;
        sleep_us(100);
    }
    return sum / avg_reads;
}

static long tare_hx711(struct gpiod_line *dout, struct gpiod_line *sck) {
    long sum = 0;
    for (int i = 0; i < HX711_TARE_READS; i++) {
        long r = read_hx711(dout, sck, &sum);
        if (r < 0) return -1;
        sleep_us(100);
    }
    return sum / HX711_TARE_READS;
}

static float calculate_weight(long raw, long tare, float scale) {
    return ((float)(raw - tare)) / scale;
}

static void trigger_solenoid(struct gpiod_line *sol, int duration_us) {
    if (gpiod_line_set_value(sol, 1) < 0) {
        syslog(LOG_ERR, "Solenoid: failed to set HIGH");
        return;
    }
    sleep_us(duration_us);
    if (gpiod_line_set_value(sol, 0) < 0) {
        syslog(LOG_ERR, "Solenoid: failed to set LOW");
    }
}

int main(int argc, char *argv[]) {
    int threshold = 1000;
    float scale = 1.0f;
    int duration = 200;
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 's': scale = (float)atof(optarg); break;
            case 'd': duration = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g] [-s scale_factor] [-d duration_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting load cell monitor (threshold=%d g, scale=%.2f, duration=%d ms)",
           threshold, scale, duration);

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, DOUT_PIN);
    struct gpiod_line *sck  = gpiod_chip_get_line(chip, SCK_PIN);
    struct gpiod_line *sol  = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines: dout=%p sck=%p sol=%p", dout, sck, sol);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "GPIO initialized: dout=%d sck=%d sol=%d", DOUT_PIN, SCK_PIN, SOLENOID_PIN);

    long tare_raw = tare_hx711(dout, sck);
    if (tare_raw < 0) {
        syslog(LOG_ERR, "Tare failed: %s", strerror(errno));
        goto cleanup;
    }
    syslog(LOG_INFO, "Tare complete: raw=%ld", tare_raw);

    while (program_running) {
        long avg_raw = average_readings(dout, sck, HX711_AVG_READS);
        if (avg_raw < 0) {
            syslog(LOG_ERR, "Read failed, retrying in 1 s");
            sleep(1);
            continue;
        }

        long raw = avg_raw - tare_raw;
        float weight = calculate_weight(raw, tare_raw, scale);

        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded, triggering solenoid");
            trigger_solenoid(sol, SOLENOID_PULSE_US);
        }

        sleep(POLL_INTERVAL_US);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down: solenoid LOW");
    gpiod_line_set_value(sol, 0);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(sol);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

