/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control on an MQTT broker at localhost:1883,
 * drives a relay module on GPIO17 (BCM 17, physical pin 11) using pigpio,
 * and logs every connection, subscription, disconnection, and error
 * event to syslog.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *                 -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER        "localhost"
#define MQTT_PORT          1883
#define MQTT_CLIENT_ID     "relay_controller_1"
#define MQTT_TOPIC         "home/lights/control"
#define GPIO_PIN           17          /* BCM 17, physical pin 11 */
#define KEEPALIVE_SEC      60
#define RECONNECT_DELAY_S  5
#define LOOP_DELAY_US      100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_msg(const char *msg)
{
    syslog(LOG_INFO, "%s", msg);
}

static void log_err(const char *msg)
{
    syslog(LOG_ERR, "%s", msg);
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int gpio_setup(void)
{
    if (gpioInitialise() < 0) {
        log_err("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_err("gpioSetMode failed for GPIO17");
        gpioTerminate();
        return -1;
    }

    /* Relay OFF at startup */
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        log_err("gpioWrite failed to initialise GPIO17 LOW");
        gpioTerminate();
        return -1;
    }

    log_msg("GPIO17 configured as output, relay OFF");
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT setup                                                          */
/* ------------------------------------------------------------------ */
static int mqtt_setup(void)
{
    int rc;

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        log_err("mosquitto_new failed");
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);
    mosquitto_reconnect_callback_set(g_mosq, on_reconnect);

    rc = mosquitto_connect(g_mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "mosquitto_connect failed: %s",
                 mosquitto_strerror(rc));
        log_err(buf);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    rc = mosquitto_subscribe(g_mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf), "mosquitto_subscribe failed: %s",
                 mosquitto_strerror(rc));
        log_err(buf);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        return -1;
    }

    log_msg("MQTT connected to broker");
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *m, void *ud, int rc)
{
    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        log_msg("MQTT connected successfully");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "MQTT connect failed: %s",
                 mosquitto_strerror(rc));
        log_err(buf);
    }
}

static void on_disconnect(struct mosquitto *m, void *ud, int rc)
{
    (void)m; (void)ud;
    if (rc == 0) {
        log_msg("MQTT disconnected cleanly");
    } else {
        log_err("MQTT unexpected disconnect");
    }
}

static void on_reconnect(struct mosquitto *m, void *ud, int rc)
{
    (void)m; (void)ud;
    if (rc != MOSQ_ERR_SUCCESS) {
        log_err("MQTT reconnect failed");
    } else {
        log_msg("MQTT reconnected successfully");
    }
}

static void on_message(struct mosquitto *m, void *ud,
                        const struct mosquitto_message *msg)
{
    (void)m; (void)ud;

    if (!msg || !msg->payload || msg->payloadlen <= 0) {
        log_err("Received empty MQTT message");
        return;
    }

    /* NUL-terminate the payload buffer for safe string operations */
    char payload[256];
    int len = msg->payloadlen;
    if (len >= (int)sizeof(payload)) {
        snprintf(payload, sizeof(payload), "Payload too long (%d bytes)", len);
        log_err(payload);
        return;
    }
    memcpy(payload, msg->payload, len);
    payload[len] = '\0';

    /* Strip trailing newline if present */
    size_t plen = strlen(payload);
    if (plen > 0 && payload[plen - 1] == '\n') {
        payload[plen - 1] = '\0';
    }

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) < 0) {
            log_err("gpioWrite failed to set GPIO17 HIGH");
        } else {
            log_msg("Relay ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) < 0) {
            log_err("gpioWrite failed to set GPIO17 LOW");
        } else {
            log_msg("Relay OFF");
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "Invalid command: '%s'", payload);
        log_err(buf);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();

    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog(MQTT_CLIENT_ID, LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_err("sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_setup() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_setup() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_msg("Relay controller started");

    while (g_running) {
        if (mosquitto_loop(g_mosq, LOOP_DELAY_US, 1) != MOSQ_ERR_SUCCESS) {
            log_err("mosquitto_loop returned error");
            break;
        }
        if (!g_running) {
            break;
        }
        /* If the broker unexpectedly disconnects, loop() returns -1 */
        if (mosquitto_reconnect(g_mosq, RECONNECT_DELAY_S, 1) != MOSQ_ERR_SUCCESS) {
            log_err("Reconnect attempt failed, will retry");
        }
    }

    log_msg("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

