#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_POSITION 1000
#define SERVO2_POSITION 1500
#define SERVO3_POSITION 2000
#define SERVO4_POSITION 500
#define SERVO5_POSITION 2500

#define PWM_RANGE 2500
#define PWM_FREQ 50
#define HOLD_TIME 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_position(int pin, int position) {
    if (position < 500 || position > PWM_RANGE) {
        fprintf(stderr, "Error: Position %d out of range for pin %d\n", position, pin);
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on pin %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on pin %d\n", pin);
        return -1;
    }
    if (gpioPWM(pin, position) < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int positions[] = {SERVO1_POSITION, SERVO2_POSITION, SERVO3_POSITION, SERVO4_POSITION, SERVO5_POSITION};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && running; i++) {
        if (set_servo_position(pins[i], positions[i]) != 0) {
            fprintf(stderr, "Error: Failed to set position on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (!running) {
        fprintf(stderr, "Interrupted before all servos reached position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < HOLD_TIME && running; i++) {
        gpioDelay(1000000);
    }

    for (int i = 0; i < num_pins && running; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

