        fprintf(stderr, "Error: Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int positions[] = {SERVO1_POSITION, SERVO2_POSITION, SERVO3_POSITION, SERVO4_POSITION, SERVO5_POSITION};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && running; i++) {
        if (set_servo_position(pins[i], positions[i]) != 0) {
            fprintf(stderr, "Error: Failed to set position on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (!running) {
        fprintf(stderr, "Interrupted before all servos reached position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < HOLD_TIME && running; i++) {
        gpioDelay(1000000);
    }

    for (int i = 0; i < num_pins && running; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

