#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdbool.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

#define TARGET_SPEED 50.0
#define KP 0.5
#define KI 0.05
#define PWM_FREQ 10000
#define PWM_RANGE 255
#define PWM_DUTY_MAX 255
#define PWM_DUTY_MIN 0
#define LOOP_PERIOD_US 100000
#define STALL_TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;
static atomic_int encoder_a_ticks = 0;
static atomic_int encoder_b_ticks = 0;
static atomic_int encoder_a_last = 0;
static atomic_int encoder_b_last = 0;

static double integral_a = 0.0;
static double integral_b = 0.0;
static double target_a = 0.0;
static double target_b = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    if (tick >= 0) {
        atomic_store(&encoder_a_ticks, atomic_load(&encoder_a_ticks) + 1);
        atomic_store(&encoder_a_last, atomic_load(&encoder_a_last) + 1);
    }
    if (tick >= 0) {
        atomic_store(&encoder_b_ticks, atomic_load(&encoder_b_ticks) + 1);
        atomic_store(&encoder_b_last, atomic_load(&encoder_b_last) + 1);
    }
}

static void set_motor_direction(int in1, int in2, int direction) {
    if (direction == 1) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    } else if (direction == -1) {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    } else {
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }
}

static void motor_forward(int in1, int in2) {
    set_motor_direction(in1, in2, 1);
}

static void motor_backward(int in1, int in2) {
    set_motor_direction(in1, in2, -1);
}

static void motor_stop(int in1, int in2) {
    set_motor_direction(in1, in2, 0);
}

static void calculate_target(double integral, double error, double kp, double ki, double *target) {
    *target = kp * error + ki * integral;
}

static void control_motor(int in1, int in2, double integral, double error, double kp, double ki, double *target) {
    double target_val = *target;
    if (target_val < 0.0) target_val = 0.0;
    if (target_val > PWM_DUTY_MAX) target_val = PWM_DUTY_MAX;
    double duty = (target_val - PWM_DUTY_MIN) / (PWM_DUTY_MAX - PWM_DUTY_MIN);
    if (duty < 0.0) duty = 0.0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    gpioPWM(in1, (int)duty);
    integral += error;
    if (integral > 1.0) integral = 1.0;
    if (integral < -1.0) integral = -1.0;
}

static void cleanup(void) {
    motor_stop(MOTOR_A_IN1, MOTOR_A_IN2);
    motor_stop(MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ENCODER_A_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set encoder GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set encoder pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_IN3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set encoder ISRs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double integral_a = 0.0;
    double integral_b = 0.0;
    double target_a = 0.0;
    double target_b = 0.0;

    struct timespec last_print = {0, 0};

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_print.tv_sec) +
                         (now.tv_nsec - last_print.tv_nsec) / 1e9;

        if (elapsed >= 1.0) {
            last_print = now;

            int a_ticks = atomic_load(&encoder_a_ticks);
            int b_ticks = atomic_load(&encoder_b_ticks);

            double a_rpm = (a_ticks - a_last) / (64.0 * 2.0) * 60.0;
            double b_rpm = (b_ticks - b_last) / (64.0 * 2.0) * 60.0;

            printf("Motor A: RPM=%.2f, PWM=%.2f\n", a_rpm, (double)gpioGetPWMdutycycle(MOTOR_A_IN1));
            printf("Motor B: RPM=%.2f, PWM=%.2f\n", b_rpm, (double)gpioGetPWMdutycycle(MOTOR_B_IN3));

            if (a_rpm < 0.0) {
                printf("WARNING: Encoder A stall detected (ticks unchanged for %.1f s)\n",
                       (double)elapsed);
            }
            if (b_rpm < 0.0) {
                printf("WARNING: Encoder B stall detected (ticks unchanged for %.1f s)\n",
                       (double)elapsed);
            }

            if (a_rpm < 0.0 || b_rpm < 0.0) {
                integral_a = 0.0;
                integral_b = 0.0;
            }

            calculate_target(integral_a, a_rpm - TARGET_SPEED, KP, KI, &target_a);
            calculate_target(integral_b, b_rpm - TARGET_SPEED, KP, KI, &target_b);

            control_motor(MOTOR_A_IN1, MOTOR_A_IN2, integral_a, a_rpm - TARGET_SPEED, KP, KI, &target_a);
            control_motor(MOTOR_B_IN3, MOTOR_B_IN4, integral_b, b_rpm - TARGET_SPEED, KP, KI, &target_b);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

