#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux) {
    char cmd = 0x21; // One-Time High-Resolution Mode 2
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_MS * 1000);

    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: Lux = %.2f, Relay = %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            lux, relay_state ? "ON" : "OFF");
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X\n", BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int consecutive_errors = 0;

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Error reading BH1750 (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many consecutive errors, turning off relay for safety\n");
                gpioWrite(RELAY_GPIO, 0);
                consecutive_errors = 0;
            }
            log_data(log_file, -1.0f, relay_state);
        } else {
            consecutive_errors = 0;
            if (lux < LUX_THRESHOLD_DUSK && !relay_state) {
                if (gpioWrite(RELAY_GPIO, 1) == 0) {
                    relay_state = 1;
                    log_data(log_file, lux, relay_state);
                }
            } else if (lux > LUX_THRESHOLD_DAWN && relay_state) {
                if (gpioWrite(RELAY_GPIO, 0) == 0) {
                    relay_state = 0;
                    log_data(log_file, lux, relay_state);
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

