#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US 10000       /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_timestamp(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    localtime_r(&now, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info);
    printf("[%s] %s\n", buf, msg);
    fflush(stdout);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void toggle_relay(void) {
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "Error: failed to read relay state\n");
        return;
    }
    if (gpioWrite(RELAY_PIN, current ? 0 : 1) != 0) {
        fprintf(stderr, "Error: failed to write relay state\n");
        return;
    }
    log_timestamp(current ? "OFF" : "ON");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: failed to read touch sensor\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Detect touch-release edge (LOW) */
        if (touch == 0 && last_touch == 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm < 0) {
                fprintf(stderr, "Error: failed to read touch sensor after debounce\n");
                continue;
            }
            if (confirm == 0) {
                toggle_relay();
                last_touch = 0;
            }
        }

        /* Detect touch (HIGH) */
        if (touch == 1 && last_touch == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirm = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm < 0) {
                fprintf(stderr, "Error: failed to read touch sensor after debounce\n");
                continue;
            }
            if (confirm == 1) {
                toggle_relay();
                last_touch = 1;
            }
        }

        last_touch = touch;
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    log_timestamp("Program terminated gracefully");
    return EXIT_SUCCESS;
}

