#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define SAMPLE_INTERVAL_US 1000000
#define DEBOUNCE_US 1000000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int solenoid_state = 1; /* 1 = open, 0 = closed */
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void cleanup(void) {
    if (solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0);
        solenoid_state = 0;
    }
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, EITHER_EDGE, DEBOUNCE_US, NULL, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    if (log_file) {
        log_event("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, solenoid_state ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to initialize solenoid state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, EITHER_EDGE, DEBOUNCE_US, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int pulses = 0;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (double)pulses / PULSES_PER_LITER * 60.0;

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", lpm);
        log_event(msg);

        if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
            solenoid_state = 0;
            gpioWrite(SOLENOID_PIN, 0);
            log_event("Solenoid valve closed (flow rate exceeded threshold).");
        } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
            solenoid_state = 1;
            gpioWrite(SOLENOID_PIN, 1);
            log_event("Solenoid valve opened (flow rate below threshold).");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

