#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_HX711_DATA_PIN 23
#define DEFAULT_HX711_CLOCK_PIN 24
#define DEFAULT_STABILIZE_DELAY_US 1000000
#define DEFAULT_TIMEOUT_ATTEMPTS 1000
#define DEFAULT_TIMEOUT_US 1000
#define DEFAULT_SERVO_MIN_US 1000
#define DEFAULT_SERVO_MAX_US 2000
#define DEFAULT_SERVO_OPEN_US 500000
#define DEFAULT_SERVO_CLOSE_US 150000
#define DEFAULT_LOG_FILE "dispensing_log.json"

#define HX711_READY_TIMEOUT_US 1000000
#define HX711_READY_TIMEOUT_ATTEMPTS 100

#define MAX_MESSAGE_LENGTH 256

typedef struct {
    char *ip_address;
    int port;
    double calibration_factor;
    int servo_pin;
    int hx711_data_pin;
    int hx711_clock_pin;
    char log_file[256];
} Config;

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int pigpio_initialized = 0;
static int servo_open = 0;
static int hx711_ready = 0;
static int hx711_data_ready = 0;
static int hx711_timeout_counter = 0;
static int hx711_timeout_attempts = 0;
static int hx711_pulse_counter = 0;
static int hx711_pulse_width = 0;
static int hx711_pulse_start_tick = 0;
static int hx711_pulse_end_tick = 0;
static int hx711_data_value = 0;
static int hx711_data_ready_flag = 0;
static Config config;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

void log_error(const char *message) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"date\": \"%d-%02d-%02d %02d:%02d:%02d\", \"time\": \"%d-%02d-%02d %02d:%02d:%02d\", \"error\": \"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

void log_dispensing(const char *message) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"date\": \"%d-%02d-%02d %02d:%02d:%02d\", \"time\": \"%d-%02d-%02d %02d:%02d:%02d\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"dispensing\": \"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            config.calibration_factor, message);
    fclose(fp);
}

int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open config file %s. Using defaults.\n", filename);
        config->ip_address = DEFAULT_SERVER_IP;
        config->port = DEFAULT_SERVER_PORT;
        config->calibration_factor = DEFAULT_CALIBRATION_FACTOR;
        config->servo_pin = DEFAULT_SERVO_PIN;
        config->hx711_data_pin = DEFAULT_HX711_DATA_PIN;
        config->hx711_clock_pin = DEFAULT_HX711_CLOCK_PIN;
        strncpy(config->log_file, DEFAULT_LOG_FILE, sizeof(config->log_file) - 1);
        config->log_file[sizeof(config->log_file) - 1] = '\0';
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
