        config->log_file[sizeof(config->log_file) - 1] = '\0';
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key == NULL || value == NULL) continue;
        if (strcmp(key, "server_ip") == 0) config->ip_address = value;
        else if (strcmp(key, "server_port") == 0) config->port = atoi(value);
        else if (strcmp(key, "calibration_factor") == 0) config->calibration_factor = atof(value);
        else if (strcmp(key, "servo_pin") == 0) config->servo_pin = atoi(value);
        else if (strcmp(key, "hx711_data_pin") == 0) config->hx711_data_pin = atoi(value);
        else if (strcmp(key, "hx711_clock_pin") == 0) config->hx711_clock_pin = atoi(value);
        else if (strcmp(key, "log_file") == 0) {
            strncpy(config->log_file, value, sizeof(config->log_file) - 1);
            config->log_file[sizeof(config->log_file) - 1] = '\0';
        }
    }
    fclose(fp);
    return 0;
}

