#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay to OFF\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;

    if (argc > 1) {
        long val = strtol(argv[1], NULL, 10);
        if (val <= 0) {
            fprintf(stderr, "Error: debounce time must be a positive integer\n");
            return EXIT_FAILURE;
        }
        debounce_ms = (int)val;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int last_touch_state = 0;
    int relay_state = 0;
    uint32_t last_change_tick = 0;

