                    fprintf(stderr, "Error: gpioWrite failed on GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
                last_change_tick = now;
            }
        }

        last_touch_state = touch_state;
        usleep(POLL_DELAY_US);
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

