#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define START_ANGLE 90
#define ANGLE_STEP 10
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int save_termios(int fd) {
    struct termios old;
    if (tcgetattr(fd, &old) != 0) {
        perror("tcgetattr");
        return -1;
    }
    if (tcsetattr(fd, TCSANOW, &old) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_termios(int fd, const struct termios *saved) {
    if (tcsetattr(fd, TCSANOW, saved) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int set_raw_mode(int fd) {
    struct termios old;
    if (tcgetattr(fd, &old) != 0) {
        perror("tcgetattr");
        return -1;
    }
    cfsetospeed(&old, B9600);
    cfsetispeed(&old, B9600);
    old.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    old.c_cc[VMIN] = 0;
    old.c_cc[VTIME] = 0;
    if (tcsetattr(fd, TCSANOW, &old) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioServo(SERVO_PIN, START_ANGLE * 1000 / PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to start servo on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int angle_to_pulse_us(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return MIN_PULSE_US + (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / 180);
}

static void cleanup_gpio(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int fd = fileno(stdin);
    if (fd < 0) {
        perror("fileno");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Servo control started on GPIO%d. Press '+' to increase, '-' to decrease, 'q' to quit.\n", SERVO_PIN);
    printf("Angle: %d°\n", START_ANGLE);
    fflush(stdout);

    while (g_running) {
        int c = getchar();
        if (c == 'q' || c == 'Q') {
            break;
        }
        if (c == '\n') {
            continue;
        }
        if (c == '+' || c == '-') {
            int new_angle = START_ANGLE + (c == '+' ? ANGLE_STEP : -ANGLE_STEP);
            if (new_angle < 0) new_angle = 0;
            if (new_angle > 180) new_angle = 180;
            int pulse = angle_to_pulse_us(new_angle);
            if (pulse < MIN_PULSE_US || pulse > MAX_PULSE_US) {
                fprintf(stderr, "Invalid pulse width %d µs (clamped to %d-%d)\n", pulse, MIN_PULSE_US, MAX_PULSE_US);
            } else {
                if (gpioServo(SERVO_PIN, pulse) != 0) {
                    fprintf(stderr, "gpioServo failed for pulse %d µs\n", pulse);
                } else {
                    printf("Angle: %d° (pulse %d µs)\n", new_angle, pulse);
                    fflush(stdout);
                }
            }
        }
    }

    cleanup_gpio();
    restore_termios(fd, &old);
    return EXIT_SUCCESS;
}

