#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "motor_rpm.log"
#define DEBOUNCE_DELAY_MS 2
#define SAMPLE_INTERVAL_S 5
#define NUM_SAMPLES (SAMPLE_INTERVAL_S * 1000 / DEBOUNCE_DELAY_MS)

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_log_file(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,rpm_value\n");
        fflush(log_file);
    }
    return 0;
}

static void close_log_file(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int open_gpio_chip(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        return -1;
    }
    return 0;
}

static int open_gpio_line(void) {
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }
    return 0;
}

static int request_gpio_line(void) {
    struct gpiod_line_request_config config = {
        .consumer = "conveyor-belt-monitor",
        .request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("gpiod_line_request");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    close_log_file();
}

int main(void) {
    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (open_gpio_chip() != 0) {
        return EXIT_FAILURE;
    }

    if (open_gpio_line() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (request_gpio_line() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int pulse_count = 0;
    struct timespec last_pulse_time = {0, 0};
    struct timespec current_time;
    int ret;

    while (program_running) {
        ret = gpiod_line_event_wait(line, &(struct timespec){0, 1000000000});
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - last_pulse_time.tv_sec) * 1000L +
