        return EXIT_FAILURE;
    }

    if (open_gpio_chip() != 0) {
        return EXIT_FAILURE;
    }

    if (open_gpio_line() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (request_gpio_line() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int pulse_count = 0;
    struct timespec last_pulse_time = {0, 0};
    struct timespec current_time;
    int ret;

    while (program_running) {
        ret = gpiod_line_event_wait(line, &(struct timespec){0, 1000000000});
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - last_pulse_time.tv_sec) * 1000L +
                          (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000000L;

        if (elapsed_ms >= DEBOUNCE_DELAY_MS) {
            pulse_count++;
            last_pulse_time = current_time;
        }
    }

    if (!program_running) {
        cleanup();
        return EXIT_SUCCESS;
    }

    double rpm = (double)pulse_count / (double)NUM_SAMPLES * 60.0;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);

    printf("RPM: %.2f\n", rpm);
    fflush(stdout);

    cleanup();
    return EXIT_SUCCESS;
}

