#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000   /* 50 ms */
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

static void cleanup(void)
{
    /* Force relay OFF (active-HIGH module) */
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    time_t touch_start = 0;
    int touch_active = 0;

    printf("Touch sensor on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);

    while (running) {
        int sensor_value = safe_read(TOUCH_SENSOR_PIN);
        if (sensor_value < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        /* Rising edge: touch detected */
        if (sensor_value == 1 && !touch_active) {
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0) {
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            touch_active = 1;
            touch_start = time(NULL);
        } else if (sensor_value == 1 && touch_active) {
            /* Check failsafe: sensor stuck HIGH for FAILSAFE_TIMEOUT_S seconds */
            if (difftime(time(NULL), touch_start) >= FAILSAFE_TIMEOUT_S) {
                /* Force relay OFF and reset failsafe */
                safe_write(RELAY_PIN, 0);
                relay_state = 0;
                touch_active = 0;
                printf("Failsafe triggered: relay OFF\n");
            }
        } else {
            touch_active = 0;
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

