#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO        18
#define VALVE_ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO  24
#define PWM_FREQUENCY     1000
#define PWM_RANGE         255
#define PULSES_PER_LITER  450.0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE_NAME     "flow_log.csv"

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static double calculate_flow_rate(int pulses, double dt) {
    return (double)pulses / PULSES_PER_LITER * 60.0 / dt;
}

static int set_valve_position(int pwm_duty) {
    if (pwm_duty < 0) pwm_duty = 0;
    if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;
    if (gpioPWM(VALVE_GPIO, pwm_duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty %d\n", pwm_duty);
        return -1;
    }
    return 0;
}

static int log_data(double flow_rate, int valve_position) {
    if (!log_file) return -1;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long long timestamp_ms = (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
    if (fprintf(log_file, "%lld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioWrite(VALVE_ENABLE_GPIO, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t target_flow_rate_L_min\n", argv[0]);
        return EXIT_FAILURE;
    }

    double target_flow = atof(argv[1]);
    if (target_flow <= 0.0) {
        fprintf(stderr, "Error: target flow rate must be positive\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_ENABLE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_ENABLE_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to enable valve\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to set ISR for flow sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control system started. Target: %.2f L/min. Press Ctrl+C to exit.\n", target_flow);

    while (running) {
        int pulses = pulse_count;
        pulse_count = 0;

        double dt = (double)SAMPLE_INTERVAL_US / 1000000.0;
        double flow_rate = calculate_flow_rate(pulses, dt);

        int pwm_duty = (int)(target_flow - flow_rate);
        if (pwm_duty < 0) pwm_duty = 0;
        if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

        if (set_valve_position(pwm_duty) != 0) {
            fprintf(stderr, "Warning: valve position update failed\n");
        }

        if (log_data(flow_rate, pwm_duty) != 0) {
            fprintf(stderr, "Warning: log write failed\n");
        }

        printf("Flow: %.2f L/min, Valve: %d/255\n", flow_rate, pwm_duty);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

