    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to set ISR for flow sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control system started. Target: %.2f L/min. Press Ctrl+C to exit.\n", target_flow);

    while (running) {
        int pulses = pulse_count;
        pulse_count = 0;

        double dt = (double)SAMPLE_INTERVAL_US / 1000000.0;
        double flow_rate = calculate_flow_rate(pulses, dt);

        int pwm_duty = (int)(target_flow - flow_rate);
        if (pwm_duty < 0) pwm_duty = 0;
        if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

        if (set_valve_position(pwm_duty) != 0) {
            fprintf(stderr, "Warning: valve position update failed\n");
        }

        if (log_data(flow_rate, pwm_duty) != 0) {
            fprintf(stderr, "Warning: log write failed\n");
        }

        printf("Flow: %.2f L/min, Valve: %d/255\n", flow_rate, pwm_duty);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

