#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_US 50000
#define UNLOCK_DURATION_US 5000000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s %s\n", ts, msg);
    fflush(log_fp);
}

static int unlock_lock(int gpio) {
    if (gpioWrite(gpio, 0) < 0) {
        log_event("ERROR: failed to write lock LOW");
        return -1;
    }
    log_event("Lock disengaged");
    gpioDelay(DEBOUNCE_US);
    if (gpioWrite(gpio, 1) < 0) {
        log_event("ERROR: failed to write lock HIGH");
        return -1;
    }
    log_event("Lock re-engaged");
    return 0;
}

static int read_rfid_tag(char *buf, int len) {
    if (spiXfer(SPI_CHANNEL, buf, buf, len) < 0) {
        log_event("ERROR: SPI transfer failed");
        return -1;
    }
    if (buf[0] == 0 && buf[1] == 0 && buf[2] == 0 && buf[3] == 0 &&
        buf[4] == 0 && buf[5] == 0 && buf[6] == 0 && buf[7] == 0 &&
        buf[8] == 0 && buf[9] == 0) {
        log_event("INFO: RFID tag absent");
        return -1;
    }
    log_event("INFO: RFID tag read OK");
    return 0;
}

static int verify_tag(const char *buf, int len) {
    if (len != 10) return 0;
    for (int i = 0; i < 10; i++) {
        if (buf[i] != (char)(i + 1)) return 0;
    }
    return 1;
}

static int button_pressed(void) {
    if (gpioRead(BUTTON_GPIO) == 0) return 1;
    gpioDelay(DEBOUNCE_US);
    if (gpioRead(BUTTON_GPIO) == 0) return 1;
    return 0;
}

static void cleanup(void) {
    unlock_lock(LOCK1_GPIO);
    unlock_lock(LOCK2_GPIO);
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_GPIO, PI_INPUT) < 0) {
        log_event("ERROR: gpioSetMode failed");
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP) < 0) {
        log_event("ERROR: gpioSetPullUpDown failed");
        cleanup();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        log_event("ERROR: spiOpen failed");
        cleanup();
        return 1;
    }

    log_event("System started");

    while (running) {
        char buf[10];
        int rfid_ok = read_rfid_tag(buf, sizeof(buf));
        int tag_verified = 0;
        int button_pressed = 0;

        if (rfid_ok == 0) {
            if (verify_tag(buf, sizeof(buf))) {
                tag_verified = 1;
            } else {
                log_event("ACCESS DENIED: invalid RFID tag");
            }
        } else {
            log_event("ACCESS DENIED: RFID read failure");
        }

        if (button_pressed) {
            log_event("ACCESS DENIED: button pressed without valid tag");
        }

        if (tag_verified && button_pressed) {
            log_event("ACCESS GRANTED: two-factor authentication successful");
            if (unlock_lock(LOCK1_GPIO) < 0 ||
                unlock_lock(LOCK2_GPIO) < 0) {
                log_event("ERROR: unlock failed");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

