}

static void cleanup(void) {
    for (int i = 0; i < 2; i++) {
        pthread_mutex_lock(&encoder_mutex[i]);
        pthread_mutex_unlock(&encoder_mutex[i]);
    }
    for (int i = 0; i < 2; i++) {
        pthread_mutex_destroy(&encoder_mutex[i]);
    }
    for (int i = 0; i < 2; i++) {
        pthread_mutex_lock(&encoder_mutex[i]);
    }
    for (int i = 0; i < 2; i++) {
        pthread_mutex_destroy(&encoder_mutex[i]);
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_release(motor_lines[i]);
            motor_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

