#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Filtering configuration */
    if (mpr121_write(handle, MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_FALL, 0x00) < 0) return -1;

