#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"
#define CONSUMER "solenoid_valve"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_v1 = NULL;
static struct gpiod_line *line_v2 = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open: %s\n", message);
    }
}

static int set_valve(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        char err_msg[128];
        snprintf(err_msg, sizeof(err_msg), "Failed to set GPIO value: %s", strerror(errno));
        log_event(err_msg);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (line_v1) {
        gpiod_line_set_value(line_v1, 0);
        gpiod_line_release(line_v1);
        line_v1 = NULL;
    }
    if (line_v2) {
        gpiod_line_set_value(line_v2, 0);
        gpiod_line_release(line_v2);
        line_v2 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        log_event("Error: Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    line_v1 = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!line_v1) {
        perror("gpiod_chip_get_line (valve1)");
        log_event("Error: Failed to get GPIO 17");
        cleanup();
        return EXIT_FAILURE;
    }

    line_v2 = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!line_v2) {
        perror("gpiod_chip_get_line (valve2)");
        log_event("Error: Failed to get GPIO 18");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_v1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (valve1)");
        log_event("Error: Failed to request GPIO 17 as output");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_v2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (valve2)");
        log_event("Error: Failed to request GPIO 18 as output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Solenoid valve control started");

    while (program_running) {
        if (set_valve(line_v1, 1) < 0) {
            log_event("Error: Failed to activate Valve 1");
        } else {
            log_event("Valve 1 activated");
        }
        usleep(500000);

        if (!program_running) break;

        if (set_valve(line_v1, 0) < 0) {
            log_event("Error: Failed to deactivate Valve 1");
        } else {
            log_event("Valve 1 deactivated");
        }
        usleep(5000000);

        if (!program_running) break;

        if (set_valve(line_v2, 1) < 0) {
            log_event("Error: Failed to activate Valve 2");
        } else {
            log_event("Valve 2 activated");
        }
        usleep(1000000);

        if (!program_running) break;

        if (set_valve(line_v2, 0) < 0) {
            log_event("Error: Failed to deactivate Valve 2");
        } else {
            log_event("Valve 2 deactivated");
        }
        usleep(10000000);
    }

    log_event("Solenoid valve control stopped");
    cleanup();
    return EXIT_SUCCESS;
}

