#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, event_type);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d high\n", RELAY_GPIO);
        log_event("ERROR: relay activation failed");
        return;
    }
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d low\n", RELAY_GPIO);
        log_event("ERROR: relay deactivation failed");
    }
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR GPIO %d as input\n", PIR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on PIR GPIO %d\n", PIR_GPIO);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    log_event("System started");
    printf("Door access control system started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    uint32_t last_motion_tick = 0;
    uint32_t unlock_start_tick = 0;

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: failed to read PIR GPIO %d\n", PIR_GPIO);
            log_event("ERROR: GPIO read failure");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_motion_tick > RATE_LIMIT_MS * 1000) {
                log_event("Motion detected");
                unlock_door();
                last_motion_tick = now;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

