#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PWM_RANGE 255
#define MIN_DUTY 0
#define MAX_DUTY PWM_RANGE
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15
#define STEP_DELAY_US 10000  /* 10 ms between steps */

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int set_motor_speed(int pin, int duty) {
    if (duty < MIN_DUTY || duty > MAX_DUTY) {
        fprintf(stderr, "Error: Invalid duty cycle %d for pin %d (must be %d-%d)\n",
                duty, pin, MIN_DUTY, MAX_DUTY);
        return -1;
    }
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int generate_step(int *motor1_duty, int *motor2_duty) {
    *motor1_duty = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
    *motor2_duty = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
    return 0;
}

static void play_pattern(int motor1_pin, int motor2_pin, int num_steps,
                         int *motor1_duty, int *motor2_duty) {
    for (int i = 0; i < num_steps; i++) {
        if (shutdown_flag) break;

        if (set_motor_speed(motor1_pin, motor1_duty[i]) != 0) {
            fprintf(stderr, "Error: Failed to set motor 1 speed\n");
            return;
        }
        if (set_motor_speed(motor2_pin, motor2_duty[i]) != 0) {
            fprintf(stderr, "Error: Failed to set motor 2 speed\n");
            return;
        }
        gpioDelay(STEP_DELAY_US);
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {MOTOR1_PIN, MOTOR2_PIN};
    for (int i = 0; i < 2; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM range for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: Failed to initialize PWM for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n",
                strerror(errno));
    }

    int motor1_duty = 0;
    int motor2_duty = 0;
    int num_steps = 0;

    while (!shutdown_flag) {
        num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

        int *duty1 = malloc((size_t)num_steps * sizeof(int));
        int *duty2 = malloc((size_t)num_steps * sizeof(int));
        if (!duty1 || !duty2) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            free(duty1);
            free(duty2);
            break;
        }

        for (int i = 0; i < num_steps; i++) {
            if (generate_step(&duty1[i], &duty2[i]) != 0) {
                fprintf(stderr, "Error: Failed to generate step %d\n", i);
                free(duty1);
                free(duty2);
                break;
            }
        }

        play_pattern(MOTOR1_PIN, MOTOR2_PIN, num_steps, duty1, duty2);

        free(duty1);
        free(duty2);
    }

    /* Graceful shutdown: stop motors and release pigpio */
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

