        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: Failed to set PWM range for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: Failed to initialize PWM for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n",
                strerror(errno));
    }

    int motor1_duty = 0;
    int motor2_duty = 0;
    int num_steps = 0;

    while (!shutdown_flag) {
        num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

        int *duty1 = malloc((size_t)num_steps * sizeof(int));
        int *duty2 = malloc((size_t)num_steps * sizeof(int));
        if (!duty1 || !duty2) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            free(duty1);
            free(duty2);
            break;
        }

        for (int i = 0; i < num_steps; i++) {
            if (generate_step(&duty1[i], &duty2[i]) != 0) {
                fprintf(stderr, "Error: Failed to generate step %d\n", i);
                free(duty1);
                free(duty2);
                break;
            }
        }

        play_pattern(MOTOR1_PIN, MOTOR2_PIN, num_steps, duty1, duty2);

        free(duty1);
        free(duty2);
    }

    /* Graceful shutdown: stop motors and release pigpio */
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

