#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define THRESHOLD 10.0
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s for reading; using defaults.\n", CALIBRATION_FILE);
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = line;
        char *val = eq + 1;
        if (strcmp(key, "scale_factor") == 0) scale_factor = atof(val);
        else if (strcmp(key, "offset") == 0) offset = atof(val);
    }
    fclose(fp);
    return 0;
}

static int load_calibration_data(void) {
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Warning: could not read calibration file; using defaults.\n");
    }
    return 0;
}

static double calibrate_solenoid(void) {
    double sum = 0.0;
    int valid = 0;
    printf("Calibrating solenoid (zero load)...\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        if (gpioWrite(SOLENOID_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set solenoid high during calibration.\n");
            return -1.0;
        }
        gpioDelay(100000);
        int raw = gpioRead(HX711_DATA_PIN);
        if (raw < 0) {
            fprintf(stderr, "Error: failed to read HX711 during calibration.\n");
            return -1.0;
        }
        sum += raw;
        valid++;
        gpioDelay(100000);
        if (gpioWrite(SOLENOID_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set solenoid low during calibration.\n");
            return -1.0;
        }
    }
    if (valid == 0) {
        fprintf(stderr, "Error: no valid calibration readings.\n");
        return -1.0;
    }
    double avg = sum / valid;
    printf("Calibration complete. Average raw: %.2f\n", avg);
    return (avg - (double)offset) / scale_factor;
}

static double read_hx711(void) {
    int raw = 0;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 0) {
        gpioDelay(100);
        timeout++;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout waiting for data pin.\n");
            return -1.0;
        }
    }
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set clock high.\n");
            return -1.0;
        }
        gpioDelay(1);
        raw <<= 1;
        int bit = gpioRead(HX711_DATA_PIN);
        if (bit < 0) {
            fprintf(stderr, "Error: failed to read data pin.\n");
            return -1.0;
        }
        if (bit) raw |= 1;
        if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set clock low.\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    if (gpioWrite(HX711_CLOCK_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set clock high for gain bit.\n");
        return -1.0;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set clock low for gain bit.\n");
        return -1.0;
    }
    gpioDelay(1);
    if (raw & 0x800000) raw |= 0xFF000000;
    return (double)raw;
}

static double convert_to_weight(int raw) {
    return (raw - offset) / scale_factor;
}

static void control_solenoid(double weight) {
    if (weight > THRESHOLD) {
        if (gpioWrite(SOLENOID_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to engage solenoid lock.\n");
        } else {
            printf("Lock engaged (weight: %.2f kg)\n", weight);
        }
    } else {
        if (gpioWrite(SOLENOID_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to release solenoid lock.\n");
        } else {
            printf("Lock released (weight: %.2f kg)\n", weight);
        }
    }
}

static void log_weight(double weight) {
    FILE *fp = fopen(WEIGHT_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for writing.\n", WEIGHT_LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f kg\n", ts, weight);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set HX711 data pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set HX711 clock pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set solenoid pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (load_calibration_data() != 0) {
        fprintf(stderr, "Error: could not load calibration data.\n");
        gpioTerminate();
        return 1;
    }
    scale_factor = load_calibration_solenoid();
    if (scale_factor < 0) {
        fprintf(stderr, "Error: solenoid calibration failed.\n");
        gpioTerminate();
        return 1;
    }
    printf("System initialised. Scale factor: %.2f, Offset: %.2f\n", scale_factor, offset);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    while (running) {
        double raw = read_hx711();
        if (raw < 0) {
            fprintf(stderr, "Error: HX711 read failed, skipping iteration.\n");
            gpioDelay(500000);
            continue;
        }
        double weight = convert_to_weight(raw);
        control_solenoid(weight);
        log_weight(weight);
        gpioDelay(500000);
    }
    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

