#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define MOTOR_RUN_TIME 5
#define CHECK_INTERVAL 60
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 50000
#define LOG_FILE "/var/log/window_control.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) low_count++;
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= 3) ? 1 : 0;
}

static int close_window(void) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        gpioWrite(MOTOR_IN1_PIN, 0);
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 150) < 0) {
        syslog(LOG_ERR, "Failed to start PWM");
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        return -1;
    }
    syslog(LOG_INFO, "Motor running to close window for %d seconds", MOTOR_RUN_TIME);
    for (int i = 0; i < MOTOR_RUN_TIME && running; i++) {
        gpioDelay(1000000);
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop motor");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop motor");
    }
    syslog(LOG_INFO, "Window closed");
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting window control program");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_rain_sensor()) {
            syslog(LOG_INFO, "Rain detected!");
            if (close_window() < 0) {
                syslog(LOG_ERR, "Failed to close window");
            }
            log_event("Rain detected and window closed");
        }
        for (int i = 0; i < CHECK_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

