#define SOLENOID_DURATION 5
#define SAMPLE_INTERVAL 1.0
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out_value) {
    if (gpioSetMode(HX711_DT, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK, PI_OUTPUT) < 0) return -1;

    /* Wait for DT to go low (data ready) with timeout */
    uint32_t waited = 0;
    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(100);
        waited += 100;
        if (waited >= HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: DT stuck high\n");
            return -1;
        }
    }

    /* Read 24 bits */
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(HX711_SETTLE_US);
        value <<= 1;
        if (gpioRead(HX711_DT)) value |= 1;
        gpioWrite(HX711_SCK, 0);
        gpioDelay(HX711_SETTLE_US);
    }

    /* 25th pulse for gain 128 */
    gpioWrite(HX711_SCK, 1);
    gpioDelay(HX711_SETTLE_US);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(HX711_SETTLE_US);

    /* Convert two's complement */
    if (value & 0x800000) value |= 0xFF000000;

    *out_value = value;
    return 0;
}

