                if (gpioWrite(SOLENOID_PIN, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate solenoid\n");
                } else {
                    log_event("Solenoid deactivated");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return 0;
}

