#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_LOCK_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_LOCK_DURATION 5
#define HX711_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711_raw(int data_pin, int clock_pin, long *raw_value) {
    int i;
    int data = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(data_pin)) {
            data |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    *raw_value = data;
    return 0;
}

static double calculate_weight(long raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

static int log_event(const char *filename, double weight) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", timestamp, weight);
    fclose(fp);
    return 0;
}

static int control_solenoid(int pin, int duration_seconds) {
    gpioWrite(pin, 1);
    gpioDelay(duration_seconds * 1000000);
    gpioWrite(pin, 0);
    return 0;
}

static int calibrate_hx711(double known_weight) {
    long raw_value;
    if (read_hx711_raw(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
        fprintf(stderr, "Failed to read raw value during calibration\n");
        return -1;
    }

    double weight = calculate_weight(raw_value, calibration_factor);
    if (weight != known_weight) {
        fprintf(stderr, "Calibration failed: expected %.2f kg, got %.2f kg\n", known_weight, weight);
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error opening calibration file");
        return -1;
    }
    fprintf(fp, "%.6f\n", calibration_factor);
    fclose(fp);
    printf("Calibration complete. Calibration factor: %.6f\n", calibration_factor);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_LOCK_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_LOCK_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (calibrate_hx711(5.0) != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioWrite(SOLENOID_LOCK_PIN, 0);
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value;
        if (read_hx711_raw(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "Error reading HX711. Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        double weight = calculate_weight(raw_value, calibration_factor);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Unlocking solenoid.\n");
            if (log_event(SECURITY_LOG_FILE, weight) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            control_solenoid(SOLENOID_LOCK_PIN, SOLENOID_LOCK_DURATION);
            printf("Solenoid locked for %d seconds.\n", SOLENOID_LOCK_DURATION);
        }

        gpioDelay(100000);
    }

    printf("\nShutting down gracefully...\n");
    gpioWrite(SOLENOID_LOCK_PIN, 0);
    gpioTerminate();
    return 0;
}

