#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define VALVE_GPIO_LINE 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define DEFAULT_DURATION 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading config file '%s': %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline */
    line[strcspn(line, "\r\n")] = '\0';

    if (strncmp(line, "duration=", 8) != 0) {
        fprintf(stderr, "Config file missing 'duration=' line\n");
        return -1;
    }

    char *endptr;
    long val = strtol(line + 8, &endptr, 10);
    if (endptr == line + 8 || *endptr != '\0' || val <= 0 || val > MAX_DURATION) {
        fprintf(stderr, "Invalid duration '%s' (must be 1-%d)\n", line + 8, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static int set_valve(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void sleep_interruptible(unsigned int seconds) {
    struct timespec req = {
        .tv_sec = seconds,
        .tv_nsec = 0
    };
    struct timespec rem;
    while (nanosleep(&req, &rem) < 0 && errno == EINTR) {
        if (!program_running) break;
        req = rem;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = DEFAULT_DURATION;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, VALVE_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", VALVE_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Watering system started. Duration: %d seconds\n", duration);
    fflush(stdout);

    if (set_valve(line, 0) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Valve OFF\n");
    fflush(stdout);

    if (read_config(CONFIG_FILE, &duration) < 0) {
        set_valve(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Configured duration: %d seconds\n", duration);
    fflush(stdout);

    if (set_valve(line, 1) < 0) {
        set_valve(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    printf("Valve ON\n");
    fflush(stdout);

    sleep_interruptible(duration);

    if (!program_running) {
        printf("Interrupted by signal. Valve OFF\n");
        fflush(stdout);
        set_valve(line, 0);
    } else {
        printf("Valve OFF\n");
        fflush(stdout);
        set_valve(line, 0);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Watering system stopped.\n");
    return EXIT_SUCCESS;
}

