        printf("Valve OFF\n");
        fflush(stdout);
        set_valve(line, 0);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Watering system stopped.\n");
    return EXIT_SUCCESS;
}

