    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (gpioWrite(gpio, 1) < 0) return -1;
    if (gpioPWM(gpio, speed) < 0) return -1;
    return 0;
}

static int read_sensor(int gpio) {
    int v = gpioRead(gpio);
    if (v < 0) return -1;
    return v;
}

static void stop_motors(void) {
    gpioWrite(MOTOR_LEFT_DIR, 0);
    gpioWrite(MOTOR_RIGHT_DIR, 0);
    gpioPWM(MOTOR_LEFT_PWM, 0);
    gpioPWM(MOTOR_RIGHT_PWM, 0);
}

static void cleanup(void) {
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_MIDDLE, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_DIR, PI_OUTPUT) < 0 ||
