        gpioSetPullUpDown(SENSOR_MIDDLE, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(SENSOR_RIGHT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-ups\n");
        cleanup();
        return EXIT_FAILURE;
