#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = 0x10; /* Continuous High-Resolution Mode */
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        log_event("Error: Failed to write measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_event("Error: Failed to read BH1750 data");
        return -1;
    }
    unsigned int raw = ((unsigned int)(buf[0] & 0xFF) << 8) | (unsigned int)(buf[1] & 0xFF);
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    control_relay(RELAY_GPIO, 0);

    int relay_state = 0;
    float lux;

    while (running) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Lux: %.2f", lux);
            log_event(log_msg);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
                log_event("Relay activated");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
                log_event("Relay deactivated");
            }
        } else {
            log_event("Sensor read failed; continuing");
        }
        gpioDelay(500 * 1000); /* 500 ms */
    }

    control_relay(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

