#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_LOCK_PULSE_WIDTH 1000
#define SERVO_UNLOCK_PULSE_WIDTH 2000
#define DEBOUNCE_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_servo_set(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    return gpioServo(SERVO_PIN, pulse_width);
}

static int lock_door(void) {
    if (safe_servo_set(SERVO_LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: failed to set servo to locked position\n");
        return -1;
    }
    printf("Door locked (servo pulse width: %d us)\n", SERVO_LOCK_PULSE_WIDTH);
    return 0;
}

static int unlock_door(void) {
    if (safe_servo_set(SERVO_UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error: failed to set servo to unlocked position\n");
        return -1;
    }
    printf("Door unlocked (servo pulse width: %d us)\n", SERVO_UNLOCK_PULSE_WIDTH);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set lock button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set unlock button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on lock button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on unlock button\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_pressed = gpioRead(LOCK_BUTTON_PIN);
        int unlock_pressed = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_pressed == 0) {
            printf("Lock button pressed\n");
            if (lock_door() != 0) {
                fprintf(stderr, "Error: failed to lock door\n");
            }
        }

        if (unlock_pressed == 0) {
            printf("Unlock button pressed\n");
            if (unlock_door() != 0) {
                fprintf(stderr, "Error: failed to unlock door\n");
            }
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

