#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PULSE_DURATION_MS 200
#define OTHER_PULSE_DURATION_MS 300
#define CONSUMER "haptic_feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines for the two motors */
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low (motor off) */
    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR1_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR2_PIN)");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    /* Main loop: pulse motors sequentially */
    while (running) {
        /* Pulse motor 1 for PULSE_DURATION_MS */
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            perror("gpiod_line_set_value(MOTOR1_PIN, 1)");
            goto cleanup;
        }
        usleep(PULSE_DURATION_MS * 1000);
        if (gpiod_line_set_value(motor1_line, 0) < 0) {
            perror("gpiod_line_set_value(MOTOR1_PIN, 0)");
            goto cleanup;
        }

        /* Pulse motor 2 for OTHER_PULSE_DURATION_MS */
        if (gpiod_line_set_value(motor2_line, 1) < 0) {
            perror("gpiod_line_set_value(MOTOR2_PIN, 1)");
            goto cleanup;
        }
        usleep(OTHER_PULSE_DURATION_MS * 1000);
        if (gpiod_line_set_value(motor2_line, 0) < 0) {
            perror("gpiod_line_set_value(MOTOR2_PIN, 0)");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure motors are off on exit */
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nHaptic feedback system stopped.\n");
    }
    return ret;
}

