#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_SERVER_ADDRESS "tcp://*:5555"
#define ZMQ_CLIENT_ADDRESS "tcp://localhost:5555"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }

    struct gpiod_line *sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line(sensor)");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int init_zmq(void) {
    int rc = zmq_init(NULL);
    if (rc == -1) {
        perror("zmq_init");
        return -1;
    }

    zmq_context_t *context = zmq_ctx_new();
    if (!context) {
        perror("zmq_ctx_new");
        zmq_term(rc);
        return -1;
    }

    zmq_socket_t *server_socket = zmq_socket(context, ZMQ_PUB);
    if (!server_socket) {
        perror("zmq_socket(server)");
        zmq_term(context);
        return -1;
    }

    int opt = 1;
    if (zmq_setsockopt(server_socket, ZMQ_PUB, ZMQ_LINGER, &opt, sizeof(opt)) < 0) {
        perror("zmq_setsockopt(ZMQ_LINGER)");
        zmq_close(server_socket);
        zmq_term(context);
        return -1;
    }

    zmq_connect(server_socket, ZMQ_SERVER_ADDRESS);
    zmq_setsockopt(server_socket, ZMQ_ID, "sound_alarm_server", 5);

    zmq_socket_t *client_socket = zmq_socket(context, ZMQ_SUB);
    if (!client_socket) {
        perror("zmq_socket(client)");
        zmq_close(server_socket);
        zmq_term(context);
        return -1;
    }

    int opt2 = 0;
    if (zmq_setsockopt(client_socket, ZMQ_SUB, ZMQ_ID, "sound_alarm_client", 5) < 0) {
        perror("zmq_setsockopt(ZMQ_ID)");
        zmq_close(client_socket);
        zmq_close(server_socket);
        zmq_term(context);
        return -1;
    }

    if (zmq_connect(client_socket, ZMQ_CLIENT_ADDRESS) == -1) {
        perror("zmq_connect(client)");
        zmq_close(client_socket);
        zmq_close(server_socket);
        zmq_term(context);
        return -1;
    }

    return 0;
}

static void publish_alert(int sound_detected) {
    char buffer[64];
    if (sound_detected) {
        snprintf(buffer, sizeof(buffer), "Sound detected!");
    } else {
        snprintf(buffer, sizeof(buffer), "No sound detected.");
    }

    size_t len = strlen(buffer);
    zmq_msg_t msg;
    if (zmq_msg_init_size(&msg, len) != 0) {
        perror("zmq_msg_init_size");
        return;
    }
    memcpy(zmq_msg_data(&msg), buffer, len);

    zmq_msg_t *more = NULL;
    int sent = zmq_send(server_socket, &msg, 1, 0);
    if (sent == -1) {
        perror("zmq_send");
    } else if (sent < 1) {
        fprintf(stderr, "Short send: %zd bytes\n", sent);
    }

    if (more) zmq_msg_close(more);
    if (zmq_msg_close(&msg) == -1) {
        perror("zmq_msg_close");
    }
}

static void process_alert(const char *message) {
    printf("Received alert: %s\n", message);
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("gpiod_line_set_value(led, 1)");
    }
    usleep(ALARM_DURATION_MS * 1000);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value(led, 0)");
    }
}

static void cleanup_zmq(void) {
    if (server_socket) {
        zmq_close(server_socket);
        server_socket = NULL;
    }
    if (client_socket) {
        zmq_close(client_socket);
        client_socket = NULL;
    }
    if (context) {
        zmq_term(context);
        context = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_zmq() < 0) {
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor mode (GPIO17, active-low)\n");
    printf("Alarm node mode (GPIO27, 1s pulse)\n");
    printf("Press Ctrl+C to exit.\n");

    int exit_code = EXIT_SUCCESS;

    while (running) {
        if (strcmp(mode, "sound_sensor") == 0) {
            int val = gpiod_line_get_value(sensor_line);
            if (val < 0) {
                perror("gpiod_line_get_value(sensor)");
                exit_code = EXIT_FAILURE;
                break;
            }
            publish_alert(val == 0);
        } else {
            char buffer[256];
            int rc = zmq_recv(client_socket, buffer, sizeof(buffer), 0);
            if (rc == -1) {
                if (errno == EINTR) {
                    continue;
                }
                perror("zmq_recv");
                exit_code = EXIT_FAILURE;
                break;
            }
            if (rc == 0) {
                printf("Received empty message\n");
            } else {
                process_alert(buffer);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_zmq();
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    if (exit_code == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    }
    return exit_code;
}

