#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOLERANCE 300

static volatile uint32_t pulse_lengths[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static volatile int frame_ready = 0;
static volatile int running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0) return;
    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (pulse_count < MAX_PULSES) {
        pulse_lengths[pulse_count++] = diff;
    } else {
        fprintf(stderr, "Warning: pulse buffer overflow, resetting\n");
        pulse_count = 0;
    }
}

static int decode_nec(const uint32_t *p, int n, uint32_t *addr, uint32_t *cmd) {
    if (n < 34) return -1;
    if (p[0] != NEC_HEADER_MARK || p[1] != NEC_HEADER_SPACE) return -1;
    uint32_t addr_raw = 0, cmd_raw = 0;
    for (int i = 0; i < 32; i++) {
        if (p[2 + i*2] == NEC_BIT_MARK && p[2 + i*2 + 1] > NEC_BIT_MARK - NEC_TOLERANCE &&
            p[2 + i*2 + 1] < NEC_BIT_MARK + NEC_TOLERANCE) {
            if (p[2 + i*2 + 1] == NEC_ONE_SPACE) {
                addr_raw |= (1u << i);
                cmd_raw |= (1u << i);
            } else if (p[2 + i*2 + 1] == NEC_ZERO_SPACE) {
                addr_raw |= (1u << i);
            }
        }
    }
    *addr = addr_raw;
    *cmd = cmd_raw;
    return 0;
}

static int validate_nec(const uint32_t *addr, const uint32_t *cmd) {
    uint32_t addr_inv = ~addr;
    if ((addr[0] ^ addr[1] ^ addr[2] ^ addr[3]) != 0xFFFF) return -1;
    if ((cmd[0] ^ cmd[1] ^ cmd[2] ^ cmd[3]) != 0xFFFF) return -1;
    if ((addr_inv[0] ^ addr_inv[1] ^ addr_inv[2] ^ addr_inv[3]) != 0xFFFF) return -1;
    if ((cmd_inv[0] ^ cmd_inv[1] ^ cmd_inv[2] ^ cmd_inv[3]) != 0xFFFF) return -1;
    return 0;
}

static void publish_mqtt(const uint32_t *addr, const uint32_t *cmd) {
    char json[256];
    snprintf(json, sizeof(json),
             "{\"address\":0x%08X,\"command\":0x%08X}",
             addr[0], addr[1]);
    MQTTClient_message pubmsg;
    pubmsg.payload = (void *)json;
    pubmsg.payloadlen = (int)strlen(json);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = client.publish(MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "IR decoder starting on GPIO%d", IR_GPIO);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);
    gpioSetAlertFunc(IR_GPIO, ir_callback);

    if (client == NULL) {
        client = MQTTClient_connect(NULL, MQTT_HOST, MQTT_PORT, 60, NULL);
        if (client == NULL) {
            syslog(LOG_ERR, "MQTT connect failed");
            gpioTerminate();
            closelog();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t addr = 0, cmd = 0;
    while (running) {
        if (frame_ready) {
            if (decode_nec(pulse_lengths, pulse_count, &addr, &cmd) == 0 &&
                validate_nec(&addr, &cmd) == 0) {
                syslog(LOG_INFO, "Decoded NEC: addr=0x%02X cmd=0x%02X", addr, cmd);
                publish_mqtt(&addr, &cmd);
                frame_ready = 0;
            }
            pulse_count = 0;
        }
        gpioDelay(1000);
    }

    syslog(LOG_INFO, "Shutting down");
    if (client) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

