#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "read failed: %s\n", r < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int udp_send(int sockfd, const char *data) {
    size_t len = strlen(data);
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(sockfd, data + sent, len - sent, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "send failed: %s\n", strerror(errno));
            return -1;
        }
        sent += (size_t)n;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(I2C_BUS, (uint8_t)i);
        if (i2c_fds[i] < 0) {
            for (int j = 0; j < i; j++) close(i2c_fds[j]);
            return 1;
        }
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
        return 1;
    }

    struct sockaddr_in mcast;
    memset(&mcast, 0, sizeof(mcast));
    mcast.sin_family = AF_INET;
    mcast.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    mcast.sin_port = htons(MULTICAST_PORT);

    while (g_running) {
        char data[256 * NUM_SENSORS];
        int all_ok = 1;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux;
            if (bh1750_read(i2c_fds[i], &lux) < 0) {
                lux = NAN;
                all_ok = 0;
            } else {
                snprintf(data + i * 64, 64, "%d,%.2f", i + 1, lux);
            }
        }

        if (all_ok) {
            snprintf(data + NUM_SENSORS * 64, 64 - NUM_SENSORS * 64, ";");
        }

        if (udp_send(sockfd, data) < 0) {
            fprintf(stderr, "UDP send failed\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    for (int i = 0; i < NUM_SENSORS; i++) close(i2c_fds[i]);
    close(sockfd);
    return 0;
}

