/*
 * AS7341 10-Channel Light/Color Sensor Logger for Raspberry Pi 3 Model B+
 * Uses Linux i2c-dev kernel interface (no wiringPi).
 *
 * Wiring:
 *   AS7341 SDA -> GPIO2 (Pin 3)
 *   AS7341 SCL -> GPIO3 (Pin 5)
 *   AS7341 VDD -> 3.3V
 *   AS7341 GND -> GND
 *
 * Build: gcc -O2 -Wall -o spectral_logger spectral_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"

#define AS7341_WHO_AM_I 0x24
#define AS7341_WHO_AM_I_VAL 0x19
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_SP_EN 0x80
#define AS7341_CH_LIST 0x60

#define NUM_CHANNELS 10
#define LOG_FILE "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_as7341(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, AS7341_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != AS7341_WHO_AM_I_VAL) {
        fprintf(stderr, "AS7341 not detected (WHO_AM_I=0x%02X, expected 0x%02X)\n", who_am_i, AS7341_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_ENABLE, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_SP_EN, 0x01) < 0) return -1;

    return 0;
}

static int read_spectral_data(int fd, uint16_t *data) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        uint8_t reg = AS7341_CH_LIST + (uint8_t)(i * 2);
        uint8_t val = 0;
        if (i2c_read_reg8(fd, reg, &val) < 0) return -1;
        data[i] = (uint16_t)((val & 0x3F) << 8) | val;
    }
    return 0;
}

static float calculate_lux(uint16_t *data) {
    float sum = 0.0f;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sum += (float)data[i];
    }
    return (float)sum;
}

static int log_data(FILE *fp, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AS7341_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_as7341(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Lux\n");
    }

    printf("AS7341 spectral logger started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t spectral_data[NUM_CHANNELS];
        if (read_spectral_data(i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Failed to read spectral data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float lux = calculate_lux(spectral_data);
        if (log_data(log_fp, lux) < 0) {
            fprintf(stderr, "Logging failed. Continuing.\n");
        }

        printf("Lux: %.2f\n", lux);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

