#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL    1
#define DEFAULT_FILENAME    "seismic_data.csv"
#define I2C_BUS             "/dev/i2c-1"
#define NUM_AXES             3
#define RETRY_COUNT          3
#define RETRY_DELAY_US       10000
#define SCALE_FACTOR         0.000244f  /* ±8 g range */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

typedef struct {
    float x, y, z;
} accel_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    if (!g_err_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(g_err_fp, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
    } else {
        fprintf(g_err_fp, "(unknown time): %s (errno=%d: %s)\n", msg, errno, strerror(errno));
    }
    fflush(g_err_fp);
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) return -1;
        if (n == 0) return -1;  /* sensor absent or bus error */
        total += (size_t)n;
    }
    return 0;
}

static int read_acceleration(int fd, accel_t *out) {
    uint8_t buf[NUM_AXES * 2];
    for (int i = 0; i < NUM_AXES; i++) {
        if (i2c_write_byte(fd, 0x28 + i * 2) < 0) return -1;
        if (i2c_read_bytes(fd, buf + i * 2, 2) < 0) return -1;
        int16_t raw = (int16_t)((buf[i * 2 + 1] << 8) | buf[i * 2]);
        out->x = (float)raw * SCALE_FACTOR;
        out->y = (float)raw * SCALE_FACTOR;
        out->z = (float)raw * SCALE_FACTOR;
    }
    return 0;
}

static int log_data(const char *filename, const accel_t *data) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return -1;
    char ts[32];
