#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL 1
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (bh1750_write(fd, 0x01) < 0) return -1; /* Power on */
    usleep(10000); /* 10 ms power-on delay */
    if (bh1750_write(fd, 0x10) < 0) return -1; /* Continuous high-res mode */
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error reading BH1750: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &MULTICAST_TTL, sizeof(MULTICAST_TTL)) < 0) {
        perror("setsockopt TTL");
        close(sockfd);
        return -1;
    }
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            if (send_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750.\n");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    close(i2c_fd);
    return 0;
}

