#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define READ_BUF_SIZE 256
#define LINE_BUF_SIZE 512
#define POLL_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = INTER_BYTE_TIMEOUT_MS / 100; /* 0.5 s */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void log_line(const char *timestamp, float range)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("Timestamp: %s, Range: %.2f meters\n", ts, range);
    } else {
        printf("Timestamp: unknown, Range: %.2f meters\n", range);
    }
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[READ_BUF_SIZE];
    ssize_t bytes_read;
    fd_set readfds;
    struct timeval timeout;

    while (g_running) {
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        timeout.tv_sec = POLL_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        bytes_read = select(g_uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            continue; /* timeout, loop and check g_running */
        }

        if (FD_ISSET(g_uart_fd, &readfds)) {
            ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
            if (n < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
                fprintf(stderr, "read() error: %s\n", strerror(errno));
                break;
            }
            if (n == 0) continue;

            for (ssize_t i = 0; i < n && g_running; i++) {
                char c = read_buf[i];
                if (c == '\n') {
                    line_buf[line_len] = '\0';
                    if (line_len > 0) {
                        log_line(line_buf, 0.0f);
                    }
                    line_len = 0;
                } else if (c != '\r') {
                    if (line_len < LINE_BUF_SIZE - 1) {
                        line_buf[line_len++] = c;
                    } else {
                        fprintf(stderr, "Line exceeded buffer, discarding\n");
                        line_len = 0;
                    }
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        tcflush(g_uart_fd, TCIOFLUSH);
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

