#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define POLL_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %d\n", pin, v);
        return -1;
    }
    return v;
}

static void log_sensor_states(int left, int middle, int right)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    }

    printf("[%s] Left: %d, Middle: %d, Right: %d\n",
           ts, left, middle, right);
    fflush(stdout);
}

static void emergency_stop(void)
{
    if (g_serial_fd < 0) {
        fprintf(stderr, "Serial port not open; cannot send emergency stop.\n");
        return;
    }

    char msg[64];
    int len = snprintf(msg, sizeof(msg), "EMERGENCY STOP!\n");
    if (len < 0 || (size_t)len >= sizeof(msg)) {
        fprintf(stderr, "Emergency stop message truncated.\n");
        return;
    }

    ssize_t written = write(g_serial_fd, msg, (size_t)len);
    if (written < 0) {
        fprintf(stderr, "Serial write error during emergency stop: %s\n",
                strerror(errno));
    } else {
        printf("Sent emergency stop message.\n");
    }
}

int main(void)
{
    /* --- Install signal handlers early --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs with pull-ups --- */
    int pins[] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "gpioSetPullUpDown failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Open serial port --- */
    g_serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port %s: %d\n",
                SERIAL_PORT, g_serial_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor\n");
    printf("Pins: Left=GPIO%d, Middle=GPIO%d, Right=GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Serial port: %s @ %d baud\n", SERIAL_PORT, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int left  = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            /* Sensor read error: log and continue rather than aborting */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_sensor_states(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            emergency_stop();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_serial_fd >= 0) {
        serClose(g_serial_fd);
        g_serial_fd = -1;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

